-- Pack one ASCII bitmap (w x h) into the binary string gfx.sprite wants.
-- Validates the art so a typo fails loudly at load instead of drawing garbage.
local function pack_bitmap(name, rows, w, h)
    assert(#rows == h, name .. ": bitmap needs " .. h .. " rows, got " .. #rows)
    local bytes_per_row = (w + 7) // 8
    local out = {}
    for y, row in ipairs(rows) do
        assert(#row == w, name .. ": row " .. y .. " is " .. #row .. " chars, need " .. w)
        for b = 0, bytes_per_row - 1 do
            local value = 0
            for bit = 0, 7 do
                local x = b * 8 + bit
                if x < w and row:sub(x + 1, x + 1) == "#" then
                    value = value | (1 << bit)
                end
            end
            out[#out + 1] = string.char(value)
        end
    end
    local packed = table.concat(out)
    assert(#packed == bytes_per_row * h and #packed <= 128, name .. ": bad packed size")
    return packed
end

-- The Churn's new items: their own art (09_art_churn), or a look-alike's
-- (ITEM_DB[..].look, resolved below, after the ragged clothes: a look may
-- itself borrow, so in passes).
for id, rows in pairs(CHURN.art) do SPRITE_ART[id] = rows end

-- Makeshift clothes borrow the real thing's sprite, full of holes.
for item_id, def in pairs(ITEM_DB) do
    local base = def.ragged_of and SPRITE_ART[def.ragged_of]
    if base and not SPRITE_ART[item_id] then
        local rows = {}
        for y, row in ipairs(base) do
            local out = {}
            for x = 1, #row do
                local c = row:sub(x, x)
                out[x] = (c == "#" and (x + 2 * y) % 5 == 0) and "." or c
            end
            rows[y] = table.concat(out)
        end
        SPRITE_ART[item_id] = rows
    end
end

for _ = 1, 3 do
    for item_id, def in pairs(ITEM_DB) do
        if def.look and not SPRITE_ART[item_id] then SPRITE_ART[item_id] = SPRITE_ART[def.look] end
    end
end

local SPRITES = {}
for item_id, rows in pairs(SPRITE_ART) do
    SPRITES[item_id] = pack_bitmap(item_id, rows, SPRITE_W, SPRITE_H)
end
-- The packed sprites are all the game draws: let the source rows go (they'd
-- live as long as the main loop otherwise). sprite_test keeps them.
CHURN.art = nil
if not KEEP_SPRITE_ART then SPRITE_ART = nil end

-- gfx.sprite is documented as an alias of gfx.bitmap; use whichever exists
-- so an older firmware without the alias still gets icons.
local draw_sprite = gfx.sprite or gfx.bitmap

