-- Weather over the map (Game:draw_weather): one 32x29 tile per kind and
-- phase (8 rows of 29 fill the map's 232 px), built the first time it's
-- needed. Rain and storms: diagonal streaks; snow: 2x2 flakes; fog: a dot
-- veil. The phase (the hour) moves the streaks and flakes along.
GLYPHS.WEATHER = {Rain = {n = 6, len = 3}, Storm = {n = 14, len = 5}, Snow = {n = 9, flake = true},
                  Fog = {veil = true}, w = 32, h = 29}
function GLYPHS.weather(kind, phase)
    local spec, W = GLYPHS.WEATHER[kind], GLYPHS.WEATHER
    if not spec then return nil end
    local key = kind .. (phase % 4)
    if GLYPHS[key] then return GLYPHS[key] end
    local grid = {}
    for y = 1, W.h do grid[y] = {} for x = 1, W.w do grid[y][x] = "." end end
    local function dot(x, y) grid[(y - 1) % W.h + 1][(x - 1) % W.w + 1] = "#" end
    if spec.veil then
        for y = 1 + phase % 4, W.h, 4 do
            for x = 1 + (y // 4) % 2 * 2, W.w, 4 do dot(x, y) end
        end
    else
        local seed = 977
        for _ = 1, spec.n do
            seed = (seed * 1103 + 12345) % 65536
            local x, y = seed % W.w + 1, (seed // W.w) % W.h + 1 + (phase % 4) * 7
            if spec.flake then
                dot(x, y); dot(x + 1, y); dot(x, y + 1); dot(x + 1, y + 1)
            else
                for i = 0, spec.len - 1 do dot(x - i, y + i) end
            end
        end
    end
    local rows = {}
    for y = 1, W.h do rows[y] = table.concat(grid[y]) end
    GLYPHS[key] = pack_bitmap("weather:" .. key, rows, W.w, W.h)
    return GLYPHS[key]
end

-- ---------------------------------------------------------------------
-- Small deterministic RNG (avoids depending on math.randomseed behaving
-- a particular way on-device - same approach as the bundled Snake demo)
-- ---------------------------------------------------------------------

local function rand_next(seed)
    return (seed * 109 + 1021) % 32768
end

local function weighted_pick(seed, weights)
    seed = rand_next(seed)
    local total = 0
    for _, w in ipairs(weights) do total = total + w[2] end
    local roll = seed * total // 32768   -- high bits; the LCG's low bits cycle fast
    local acc = 0
    for _, w in ipairs(weights) do
        acc = acc + w[2]
        if roll < acc then return seed, w[1] end
    end
    return seed, weights[#weights][1]
end

-- ---------------------------------------------------------------------
-- Hex math (axial coordinates, pointy-top, flat 2D - no isometric squash)
-- ---------------------------------------------------------------------

local SQRT3 = math.sqrt(3)

local function axial_to_pixel(q, r, size)
    local x = size * (SQRT3 * q + SQRT3 / 2 * r)
    local y = size * (3 / 2 * r)
    return x, y
end

local function axial_round(qf, rf)
    local xf, zf = qf, rf
    local yf = -xf - zf
    local rx, ry, rz = math.floor(xf + 0.5), math.floor(yf + 0.5), math.floor(zf + 0.5)
    local dx, dy, dz = math.abs(rx - xf), math.abs(ry - yf), math.abs(rz - zf)
    if dx > dy and dx > dz then
        rx = -ry - rz
    elseif dy > dz then
        ry = -rx - rz
    else
        rz = -rx - ry
    end
    return rx, rz
end

local function axial_distance(aq, ar, bq, br)
    local ax, az = aq, ar
    local ay = -ax - az
    local bx, bz = bq, br
    local by = -bx - bz
    return math.max(math.abs(ax - bx), math.abs(ay - by), math.abs(az - bz))
end

local AXIAL_DIRS = {{1, 0}, {1, -1}, {0, -1}, {-1, 0}, {-1, 1}, {0, 1}}

local function hex_key(q, r) return q .. "," .. r end

local function neighbors(tiles, q, r)
    local result = {}
    for _, d in ipairs(AXIAL_DIRS) do
        local nq, nr = q + d[1], r + d[2]
        if tiles[hex_key(nq, nr)] then
            result[#result + 1] = {nq, nr}
        end
    end
    return result
end

-- ---------------------------------------------------------------------
-- World / player state
-- ---------------------------------------------------------------------

local function generate_world(seed)
    local tiles = {}
    for q = -GRID_RADIUS, GRID_RADIUS do
        for r = -GRID_RADIUS, GRID_RADIUS do
            if -GRID_RADIUS <= -q - r and -q - r <= GRID_RADIUS then
                local terrain
                seed, terrain = weighted_pick(seed, TERRAIN_WEIGHTS)
                tiles[hex_key(q, r)] = terrain
            end
        end
    end

    -- rivers: random walks from one edge toward the opposite one, each with
    -- two fords where it can be waded
    local R = GRID_RADIUS
    for _ = 1, WORLD.rivers do
        seed = rand_next(seed)
        local d = AXIAL_DIRS[seed % 6 + 1]
        local q, r = d[1] * R, d[2] * R
        local tq, tr = -q, -r
        local path = {}
        for _ = 1, 4 * R do
            if not tiles[hex_key(q, r)] then break end
            tiles[hex_key(q, r)] = "water"
            path[#path + 1] = {q, r}
            if q == tq and r == tr then break end
            -- step to a neighbor closer to the far edge, now and then sideways
            local best, options = axial_distance(q, r, tq, tr), {}
            for _, n in ipairs(AXIAL_DIRS) do
                local nq, nr = q + n[1], r + n[2]
                if tiles[hex_key(nq, nr)] and axial_distance(nq, nr, tq, tr) < best then
                    options[#options + 1] = {nq, nr}
                end
            end
            seed = rand_next(seed)
            if #options == 0 or seed % 7 == 0 then
                local n = AXIAL_DIRS[(seed // 7) % 6 + 1]
                if tiles[hex_key(q + n[1], r + n[2])] then options = {{q + n[1], r + n[2]}} end
            end
            if #options == 0 then break end
            local pick = options[(seed // 3) % #options + 1]
            q, r = pick[1], pick[2]
        end
        for _, f in ipairs({1 / 3, 2 / 3}) do
            local at = path[math.max(1, math.floor(#path * f))]
            if at then tiles[hex_key(at[1], at[2])] = "ford" end
        end
    end

    -- ruins: a town (a tight cluster) somewhere 5-9 hexes out, and wrecks
    local keys = {}
    for key in pairs(tiles) do keys[#keys + 1] = key end
    table.sort(keys)
    local function parse(key)
        local q, r = key:match("(-?%d+),(-?%d+)")
        return tonumber(q), tonumber(r)
    end
    local town
    for _ = 1, 200 do
        seed = rand_next(seed)
        local q, r = parse(keys[seed % #keys + 1])
        local dist = axial_distance(0, 0, q, r)
        if dist >= 5 and dist <= 9 then town = {q, r}; break end
    end
    if town then
        local placed = 0
        for ring = 0, 2 do
            for _, key in ipairs(keys) do
                local q, r = parse(key)
                if placed < WORLD.town_ruins and axial_distance(q, r, town[1], town[2]) == ring then
                    seed = rand_next(seed)
                    if ring < 2 or seed % 3 == 0 then
                        tiles[key] = "ruins"
                        placed = placed + 1
                    end
                end
            end
        end
    end
    for _ = 1, WORLD.lone_ruins do
        seed = rand_next(seed)
        local key = keys[seed % #keys + 1]
        local q, r = parse(key)
        if tiles[key] ~= "water" and axial_distance(0, 0, q, r) >= 3 then tiles[key] = "ruins" end
    end
    tiles[hex_key(0, 0)] = "plains"

    -- sites: the trader on the town's center, and the Checkpoint on the map's
    -- edge, at the edge hex farthest from the trader (the long way round)
    local sites = {}
    local trader = town and hex_key(town[1], town[2])
    for _, key in ipairs(keys) do
        if trader then break end
        if tiles[key] == "ruins" then trader = key end
    end
    trader = trader or hex_key(3, 0)
    tiles[trader] = "ruins"
    sites.trader = trader
    local tq, tr = parse(trader)
    local exit, exit_d
    for _, key in ipairs(keys) do
        local q, r = parse(key)
        if axial_distance(0, 0, q, r) == GRID_RADIUS and tiles[key] ~= "water" then
            local d = axial_distance(q, r, tq, tr)
            if not exit or d > exit_d then exit, exit_d = key, d end
        end
    end
    exit = exit or hex_key(GRID_RADIUS, 0)
    if tiles[exit] == "water" then tiles[exit] = "plains" end
    sites.checkpoint = exit

    -- every walkable hex must be reachable from the start: where water cuts
    -- some off, wade a line of fords from them back toward the start
    local function reachable()
        local seen, queue = {[hex_key(0, 0)] = true}, {{0, 0}}
        local i = 1
        while queue[i] do
            local cur = queue[i]; i = i + 1
            for _, n in ipairs(AXIAL_DIRS) do
                local nq, nr = cur[1] + n[1], cur[2] + n[2]
                local k = hex_key(nq, nr)
                if tiles[k] and not seen[k] and TERRAIN[tiles[k]].passable then
                    seen[k] = true
                    queue[#queue + 1] = {nq, nr}
                end
            end
        end
        return seen
    end
    for _ = 1, 50 do
        local seen, cut_off = reachable(), nil
        for _, key in ipairs(keys) do
            if TERRAIN[tiles[key]].passable and not seen[key] then cut_off = key; break end
        end
        if not cut_off then break end
        local q, r = parse(cut_off)
        local n = axial_distance(q, r, 0, 0)
        for step = 1, n do
            local lq, lr = axial_round(q + (0 - q) * step / n, r + (0 - r) * step / n)
            if tiles[hex_key(lq, lr)] == "water" then tiles[hex_key(lq, lr)] = "ford" end
        end
    end

    local ground = {}
    -- (you wake with nothing: enough here for a rag shirt, a bindle and
    -- foot wraps, and a fire for the first night)
    ground[hex_key(0, 0)] = {
        {item = "rock", qty = 1},
        {item = "stick", qty = 4},
        {item = "cloth_scrap", qty = 6},
        {item = "canned_beans", qty = 1},
        {item = "water_bottle", qty = 2},
        {item = "matches", qty = 1},
    }

    -- Scatter loot on other passable tiles: every wearable once, plus a few
    -- food/water caches. Keys are sorted so a seed always gives the same map.
    local spots = {}
    for key, terrain in pairs(tiles) do
        if TERRAIN[terrain].passable and key ~= hex_key(0, 0) then
            spots[#spots + 1] = key
        end
    end
    table.sort(spots)
    local function drop(item, qty)
        seed = rand_next(seed)
        local key = spots[seed % #spots + 1]
        ground[key] = ground[key] or {}
        for _, s in ipairs(ground[key]) do
            if s.item == item then s.qty = s.qty + qty; return end
        end
        table.insert(ground[key], {item = item, qty = qty})
    end
    for _, item in ipairs(WORLD_WEARABLES) do drop(item, 1) end
    for _ = 1, 2 do   -- food/water caches (loot is meant to be scarce)
        for _, item in ipairs({"canned_beans", "canned_beans", "water_bottle",
                               "water_bottle", "water_bottle", "cloth_scrap"}) do
            drop(item, 1)
        end
    end
    for _, item in ipairs(RAD.world_items) do drop(item, 1) end
    for _, item in ipairs(TECH.world_items) do drop(item, 1) end

    -- anomaly fields: hot spots of radiation, an artifact at each center.
    -- rad[key] = level 1-3 (see RAD); not saved, rebuilt from the seed.
    local rad = {}
    local fields = 0
    for _ = 1, 300 do
        if fields >= RAD.fields then break end
        seed = rand_next(seed)
        local center = spots[seed % #spots + 1]
        local cq, cr = parse(center)
        local clear = axial_distance(0, 0, cq, cr) >= RAD.min_dist and not rad[center]
        for _, site in pairs(sites) do
            local sq, sr = parse(site)
            if axial_distance(cq, cr, sq, sr) < RAD.min_dist then clear = false end
        end
        if clear then
            seed = rand_next(seed)
            local radius = 1 + seed % 2
            for _, key in ipairs(keys) do
                local q, r = parse(key)
                local d = axial_distance(q, r, cq, cr)
                if d <= radius then rad[key] = math.max(rad[key] or 0, 3 - d) end
            end
            seed = rand_next(seed)
            ground[center] = ground[center] or {}
            table.insert(ground[center], {item = ARTIFACTS[seed % #ARTIFACTS + 1], qty = 1})
            fields = fields + 1
        end
    end
    return tiles, ground, seed, rad, sites
end

-- ---------------------------------------------------------------------
-- Character: attributes (NEO Scavenger-style point buy) and traits (Project
-- Zomboid-style budget: positive traits cost points, negative ones give them
-- back, and you can only start with the balance at 0 or above). Only traits
-- that actually change something are offered.
-- ---------------------------------------------------------------------

local ATTRIBUTES = {"Strength", "Speed", "Perception", "Endurance"}
local ATTR_MIN, ATTR_MAX, ATTR_DEFAULT, ATTR_POINTS = 1, 6, 3, 12
local ATTR_DESC = {
    Strength   = "Strength: +1 bag cell per point over 3",
    Speed      = "Speed: +1 MP per 2 points over 3",
    Perception = "Perception: sight, finds, fewer duds",
    Endurance  = "Endurance: 10% slower tiring per point",
}

-- cost > 0 spends trait points, cost < 0 gives them. fx keys: mp, sight,
-- scav (finds per search), bag (cells), hunger / rest_gain (multipliers)
local TRAITS = {
    {name = "Quick",        cost = 3,  desc = "+1 movement point",        fx = {mp = 1}},
    {name = "Hawk-Eyed",    cost = 3,  desc = "+1 sight",                 fx = {sight = 1}},
    {name = "Scrounger",    cost = 2,  desc = "+1 find per search",       fx = {scav = 1}},
    {name = "Light Eater",  cost = 2,  desc = "Hunger drains 25% slower", fx = {hunger = 0.75}},
    {name = "Pack Mule",    cost = 2,  desc = "+2 bag cells",             fx = {bag = 2}},
    {name = "Asthmatic",    cost = -3, desc = "-1 movement point",        fx = {mp = -1}},
    {name = "Near-Sighted", cost = -3, desc = "-1 sight",                 fx = {sight = -1}},
    {name = "Careless",     cost = -2, desc = "-1 find per search",       fx = {scav = -1}},
    {name = "Big Eater",    cost = -2, desc = "Hunger drains 25% faster", fx = {hunger = 1.25}},
    {name = "Insomniac",    cost = -2, desc = "Resting restores 25% less", fx = {rest_gain = 0.75}},
}

local function default_attrs()
    local a = {}
    for _, name in ipairs(ATTRIBUTES) do a[name] = ATTR_DEFAULT end
    return a
end

local function attr_points_left(attrs)
    local used = 0
    for _, name in ipairs(ATTRIBUTES) do used = used + attrs[name] end
    return ATTR_POINTS - used
end

-- trait points left: everyone gets TRAIT_START_POINTS, negatives add more,
-- positives spend; must be >= 0 to start
local TRAIT_START_POINTS = 5
local function trait_points_left(traits)
    local left = TRAIT_START_POINTS
    for _, t in ipairs(TRAITS) do
        if traits[t.name] then left = left - t.cost end
    end
    return left
end

-- Derived stats from attributes + traits, stored on the player.
local FX_MULT = {hunger = true, rest_gain = true, thirst = true, rest_drain = true,
                 encounter = true}
local function recompute_stats(player)
    local a = player.attrs
    local fx = {mp = 0, sight = 0, scav = 0, bag = 0, heal = 0, scav_hurt = 0,
                hunger = 1, rest_gain = 1, thirst = 1, rest_drain = 1, encounter = 1}
    local function add(effects)
        for k, v in pairs(effects) do
            if FX_MULT[k] then fx[k] = fx[k] * v else fx[k] = fx[k] + v end
        end
    end
    for _, t in ipairs(TRAITS) do
        if player.traits[t.name] then add(t.fx) end
    end
    -- worn things with fx (a travois slows you, a charm thins the meetings)
    for slot, item in pairs(player.equipped) do
        if not HOLD_SLOTS[slot] and ITEM_DB[item].fx then add(ITEM_DB[item].fx) end
    end
    -- artifacts work while held
    for _, slot in ipairs({"lhand", "rhand"}) do
        local item = player.equipped[slot]
        if item and ITEM_DB[item].artifact then add(ITEM_DB[item].artifact) end
    end
    player.max_mp = math.max(1, BASE_MAX_MP + (a.Speed - 3) // 2 + fx.mp)
    player.sight = math.max(1, BASE_SIGHT + (a.Perception - 3) // 2 + fx.sight)
    player.scav_rolls = math.max(1, SCAVENGE_ROLLS + (a.Perception - 3) // 2 + fx.scav)
    player.bag_bonus = math.max(0, a.Strength - 3) + fx.bag   -- (weak arms never cost you cells)
    player.hunger_mult = fx.hunger * (player.diff_drain or 1)
    player.rest_gain_mult = fx.rest_gain
    player.rest_drain_mult = (1 - 0.1 * (a.Endurance - 3)) * fx.rest_drain
    player.thirst_mult = fx.thirst * (player.diff_drain or 1)
    player.heal_per_hour = fx.heal
    player.encounter_mult = fx.encounter
    player.scav_hurt = fx.scav_hurt
    if player.mp and player.mp > player.max_mp then player.mp = player.max_mp end
end

-- Perception scales how often a search roll comes up empty: 100% at 3,
-- 25% at 6, 150% at 1.
local function dud_percent(perception)
    return 100 * (7 - perception) // 4
end

local function new_player()
    return {
        q = 0, r = 0,
        max_mp = BASE_MAX_MP,
        mp = BASE_MAX_MP,
        sight = BASE_SIGHT,
        hours = 0,
        needs = {hunger = 100, thirst = 100, rest = 100},
        health = MAX_HEALTH,
        injuries = {bleeding = false, wounded_hours = 0},
        equipped = {},    -- you wake up with nothing: no clothes, no shoes, no bag
        inventory = {},
        explored = {},
        visible = {},
        attrs = default_attrs(),
        traits = {},
    }
end

-- Only the hexes within sight are visited (the world has hundreds).
-- view_sight is sight after night/light (Game:refresh_view); sight otherwise.
local function update_visibility(player, tiles)
    player.visible = {}
    local s = player.view_sight or player.sight
    for dq = -s, s do
        for dr = math.max(-s, -dq - s), math.min(s, -dq + s) do
            local key = hex_key(player.q + dq, player.r + dr)
            if tiles[key] then
                player.visible[key] = true
                player.explored[key] = true
            end
        end
    end
end

local function clamp(v) return math.max(0, math.min(100, v)) end

-- Split text into lines of at most cols characters, breaking at spaces.
local function wrap(text, cols)
    local lines, line = {}, ""
    for word in text:gmatch("%S+") do
        if line == "" then
            line = word
        elseif #line + 1 + #word <= cols then
            line = line .. " " .. word
        else
            lines[#lines + 1] = line
            line = word
        end
    end
    if line ~= "" then lines[#lines + 1] = line end
    return lines
end

local function apply_awake_hours(player, hours)
    player.needs.hunger = clamp(player.needs.hunger - hours * (100 / 72) * player.hunger_mult)
    player.needs.thirst = clamp(player.needs.thirst - hours * (100 / 48) * player.thirst_mult)
    player.needs.rest = clamp(player.needs.rest - hours * (100 / 18) * player.rest_drain_mult)
    player.health = clamp(player.health + hours * player.heal_per_hour)
    if player.injuries.bleeding then
        player.health = clamp(player.health - hours * BLEED_PER_HOUR)
    end
end

local function apply_rest_hours(player, hours)
    player.needs.hunger = clamp(player.needs.hunger - hours * (100 / 72) * 0.5 * player.hunger_mult)
    player.needs.thirst = clamp(player.needs.thirst - hours * (100 / 48) * 0.5 * player.thirst_mult)
    player.needs.rest = clamp(player.needs.rest + hours * (100 / 6) * player.rest_gain_mult)
    local inj = player.injuries
    if inj.bleeding then
        player.health = clamp(player.health - hours * BLEED_PER_HOUR)
    elseif player.needs.hunger <= 0 or player.needs.thirst <= 0 then
        -- a starving or parched body doesn't mend
        inj.wounded_hours = math.max(0, inj.wounded_hours - hours)
    else
        local heal = REST_HEAL_PER_HOUR * (1 + 0.1 * (player.attrs.Endurance - 3))
        player.health = clamp(player.health + hours * heal)
        inj.wounded_hours = math.max(0, inj.wounded_hours - hours)
    end
end

local function effective_max_mp(player)
    local penalty = 0
    if player.needs.hunger <= 0 then penalty = penalty + 1 end
    if player.needs.thirst <= 0 then penalty = penalty + 1 end
    if player.needs.rest <= 0 then penalty = penalty + 1 end
    if player.injuries.wounded_hours > 0 then penalty = penalty + 1 end
    return math.max(1, player.max_mp - penalty)
end

-- ---------------------------------------------------------------------
-- Game object (holds everything one screen/session needs)
-- ---------------------------------------------------------------------

local Game = {}
Game.__index = Game

-- "q,r" (a tile key, hex_key) back to two numbers.
function Game.key_qr(key)
    local q, r = key:match("(-?%d+),(-?%d+)")
    return tonumber(q), tonumber(r)
end

function Game.new()
    local self = setmetatable({}, Game)
    -- The SolarOS Lua runtime does not load the `os` library, so seed from
    -- uptime instead; the constant is only a fallback for other hosts.
    local seed = 12345
    local clock = solaros.time and solaros.time.uptime_ms
    if clock then
        seed = math.floor(clock()) % 32768
    elseif os and os.time then
        seed = os.time() % 32768
    end
    self.world_seed = seed       -- the map is rebuilt from this when a save is loaded
    -- this run, for the records (two runs can share a world seed)
    self.run_id = seed .. "-" .. math.random(1, 1000000000)
    self.tiles, self.ground, seed, self.rad, self.sites = generate_world(seed)
    self.extras = Game.place_extras(self.tiles, self.sites, self.rad, self.world_seed)
    for _, d in ipairs(self.extras.drops) do
        self.ground[d.key] = self.ground[d.key] or {}
        table.insert(self.ground[d.key], {item = d.item, qty = 1})
    end
    self.ferry_trader = Game.starting_stock("ferry")
    self.peddler = Game.starting_stock("peddler")
    self.little = Game.new_little()
    self.story = Game.new_story()
    self.trader = {stock = {}, restocked = 0}   -- what the trader has now (it changes as you trade)
    for _, st in ipairs(TRADE.stock) do
        self.trader.stock[#self.trader.stock + 1] = {item = st[1], qty = st[2]}
    end
    self.sites_known = {}        -- site name -> true once you know where it is
    self.stashes = {}            -- tile key -> true: a stash a note told you about
    self.snares = {}             -- tile key -> {set = hour}: snares you've set
    self.next_emission = RAD.emission.first
    self.rad_known = {}          -- tile key -> rad level you've measured or felt there
    self.skills = {}             -- skill -> XP (src/55_skills.lua)
    self.stats = {}              -- this run's counts (src/56_records.lua)
    self.seed = seed             -- RNG state for scavenging
    self.weather_seed = seed     -- fixed per world: weather is rolled from it (Game:weather)
    self.scavenged = {}          -- tile key -> searches used
    self.camps = {}              -- tile key -> {until_hour} while a campfire burns
    self.known = {}              -- recipe id -> true once you know how to make it
    for _, r in ipairs(RECIPES) do
        if r.known then self.known[r.id] = true end
    end
    self.craft_ui = {cursor = 1, back = "map"}   -- crafting screen state (not "craft": that is the method)
    self.player = new_player()
    self.difficulty = "normal"
    self.player.diff_drain = DIFFICULTY.normal.drain   -- (set_difficulty changes it)
    recompute_stats(self.player)
    self:refresh_view()
    self.screen = "creator"      -- "creator", then "map" or "inventory"
    self.creator_cursor = 1      -- rows: attributes, then traits
    self.creator_msg = nil
    self.log = {"You wake with nothing. Not even shoes."}
    self.inv_cursor = 1
    self.inv_selected = nil      -- {"ground"|"inventory"|"equip", key}
    self.quit = false
    return self
end

-- A difficulty multiplier (DIFFICULTY in 05_data_world); Normal is all 1.
function Game:diff(key)
    return DIFFICULTY[self.difficulty or "normal"][key]
end

function Game:set_difficulty(id)
    self.difficulty = id
    self.player.diff_drain = DIFFICULTY[id].drain
    recompute_stats(self.player)
end

-- Leave the creator: apply the chosen stats and start on the map.
function Game:start_game()
    if trait_points_left(self.player.traits) < 0 then
        self.creator_msg = "Too many trait points spent."
        return false
    end
    local p = self.player
    Game.ART_TILES = {}   -- (the title screens' pictures, cut into tiles: not needed in play)
    recompute_stats(p)
    p.mp = p.max_mp
    p.explored = {}
    self:refresh_view()
    self.screen = "map"
    self:queue_scene("wake")
    self:place_legacy()
    return true
end

-- Health at 0 ends the run: the death screen, then a new character.
function Game:check_death(cause)
    if self.player.health > 0 then return false end
    self.screen = "dead"
    self:sfx("death")
    Game.delete_save()           -- one life: a dead survivor can't be continued
    self.death_cause = cause
    self:save_legacy(cause)      -- (what you carried waits in the next world: 64_legacy)
    self:record_run(nil, cause)
    return true
end

function Game:push_log(text)
    table.insert(self.log, text)
    while #self.log > 3 do table.remove(self.log, 1) end
end

-- -- movement / rest --------------------------------------------------

function Game:try_move(q, r)
    local p = self.player
    local key = hex_key(q, r)
    local terrain_id = self.tiles[key]
    if not terrain_id then return end
    local found = false
    for _, n in ipairs(neighbors(self.tiles, p.q, p.r)) do
        if n[1] == q and n[2] == r then found = true end
    end
    if not found then return end
    local terrain = TERRAIN[terrain_id]
    if not terrain.passable then
        self:push_log("Can't cross " .. terrain.name .. ".")
        return
    end
    if p.mp <= 0 then
        self:push_log("Out of movement. Rest first.")
        return
    end
    p.mp = p.mp - terrain.cost
    p.q, p.r = q, r
    p.hours = p.hours + terrain.cost
    apply_awake_hours(p, terrain.cost)
    self:refresh_view()
    self:push_log("Moved to " .. terrain.name .. " (" .. terrain.cost .. " MP)")
    local pile = self.ground[key]
    if pile and #pile > 0 then self:push_log("Something is here. (I to look)") end
    if p.needs.hunger <= 0 then self:push_log("You are starving!") end
    if p.needs.thirst <= 0 then self:push_log("You are dehydrated!") end
    self:find_stash()
    self:check_snare()
    self:camp_arrive()
    self:scan_arrive()
    if not self:check_death("You bled out.") and not self:arrive_site() and not self:quest_arrive()
        and not self:little_arrive() and not self:legacy_arrive() then
        self:maybe_encounter(terrain_id)
    end
    if self.screen == "map" then self:dread_move() end
end

-- The map's movement keys. Hexes have six neighbors and there are four
-- arrows, so Up/Down only lean (self.move_lean = -1 up, 1 down) and the next
-- Left/Right steps that way: Up then Left = up-left, Down then Right =
-- down-right; Left/Right alone go west/east. True if the key was used; any
-- other key drops the lean (the caller handles it).
function Game:map_dir_key(key)
    if key == gfx.KEY_UP or key == KEY.W then
        self.move_lean = -1
        return true
    elseif key == gfx.KEY_DOWN or key == KEY.S then
        self.move_lean = 1
        return true
    end
    local dx = (key == gfx.KEY_LEFT or key == KEY.A) and -1
        or (key == gfx.KEY_RIGHT or key == KEY.D) and 1 or nil
    local lean = self.move_lean
    self.move_lean = nil
    if not dx then return false end
    self:move_dir(dx, lean or 0)
    return true
end

function Game:move_dir(dq, dr)
    local p = self.player
    -- pick the neighbor whose pixel-space direction best matches (dq,dr)
    local px, py = axial_to_pixel(p.q, p.r, HEX_SIZE)
    local best, best_dot = nil, -math.huge
    for _, n in ipairs(neighbors(self.tiles, p.q, p.r)) do
        local nx, ny = axial_to_pixel(n[1], n[2], HEX_SIZE)
        local vx, vy = nx - px, ny - py
        local len = math.sqrt(vx * vx + vy * vy)
        if len == 0 then len = 1 end
        local dot = (vx / len) * dq + (vy / len) * dr
        if dot > best_dot then best_dot, best = dot, n end
    end
    if best then self:try_move(best[1], best[2]) end
end

function Game:scavenge_left()
    local key = hex_key(self.player.q, self.player.r)
    return SCAVENGE_TRIES - (self.scavenged[key] or 0)
end

-- Search the current tile: costs MP and hours like moving, rolls the
-- terrain's loot table, and drops what turns up on the ground here.
function Game:scavenge()
    local p = self.player
    local key = hex_key(p.q, p.r)
    local loot = SCAVENGE_LOOT[self.tiles[key]]
    if not loot then
        self:push_log("Nothing to search here.")
        return
    end
    if self:scavenge_left() <= 0 then
        self:push_log("This area is picked clean.")
        return
    end
    if p.mp <= 0 then
        self:push_log("Too tired to search. Rest first.")
        return
    end
    p.mp = p.mp - SCAVENGE_HOURS
    p.hours = p.hours + SCAVENGE_HOURS
    apply_awake_hours(p, SCAVENGE_HOURS)
    self.scavenged[key] = (self.scavenged[key] or 0) + 1
    if p.scav_hurt > 0 then
        p.health = clamp(p.health - p.scav_hurt)
        self:push_log("The star in your hand drinks from you. (-" .. p.scav_hurt .. " HP)")
    end

    -- Perception: fewer dud rolls (and, via scav_rolls, more of them)
    local table_ = {}
    for i, entry in ipairs(loot) do
        local w = entry[2]
        if entry[1] == "nothing" then
            w = math.max(1, w * (7 - p.attrs.Perception) // 4)
            w = math.max(1, w * (100 - self:skill_bonus("scav")) // 100)
        end
        local food = ITEM_DB[entry[1]] and ITEM_DB[entry[1]].consumable
        if food and food.hunger and food.hunger > 0 then
            w = math.max(1, math.floor(w * self:diff("food") * self:season().food + 0.5))
        end
        table_[i] = {entry[1], w}
    end
    local found = {}
    for _ = 1, p.scav_rolls do
        local item
        self.seed, item = weighted_pick(self.seed, table_)
        if item ~= "nothing" then found[#found + 1] = self:drop_found(item) end
    end
    self:skill_xp("scav", SKILLS.xp.search + SKILLS.xp.find * #found)
    self:stat("searches")
    if #found == 0 then
        self:push_log("Searched " .. SCAVENGE_HOURS .. "h. Found nothing.")
    else
        self:push_log("Found: " .. table.concat(found, ", ") .. ".")
        self:push_log("Press I to pick it up.")
    end
    self:scavenge_field()
    self:pick_crate(key)
    self:find_corpse(key)
    if p.needs.hunger <= 0 then self:push_log("You are starving!") end
    if p.needs.thirst <= 0 then self:push_log("You are dehydrated!") end
    self:check_death(p.scav_hurt > 0 and "The Hollow Star emptied you." or "You bled out.")
end

function Game:rest()
    local p = self.player
    local cap = effective_max_mp(p)
    if p.mp >= cap then
        self:push_log("Already rested.")
        return
    end
    local fire, bed = self:fire_here(), self:bed_here()
    local terror, rest0 = (p.dread or 0) >= CHURN.dread.tiers[3][1], p.needs.rest
    p.hours = p.hours + REST_HOURS
    apply_rest_hours(p, REST_HOURS)
    if terror then p.needs.rest = rest0 + (p.needs.rest - rest0) * CHURN.dread.sleep end   -- (you can't sleep)
    if bed then self:dread(CHURN.dread.bed_rest) elseif fire then self:dread(CHURN.dread.fire_rest) end
    if fire then   -- a campfire: warm, and better sleep
        p.needs.rest = clamp(p.needs.rest + REST_HOURS * (100 / 6) * WORLD.fire_rest_bonus)
    end
    if bed then    -- your own bedroll at camp (and a pelt on it: better still)
        local bonus = BASE.bed_rest_bonus + (self:camp_stack("bed") and BASE.bed_pelt_bonus or 0)
        p.needs.rest = clamp(p.needs.rest + REST_HOURS * (100 / 6) * bonus)
    end
    p.mp = effective_max_mp(p)
    self:refresh_view()
    self:push_log("Rested " .. REST_HOURS .. "h" .. (bed and " in your bedroll." or fire and " by the fire." or "."))
    if self:weather() == "Rain" then self:rain_fill() end
    if p.injuries.bleeding then self:push_log("You're still bleeding. Bandage it (E on cloth).") end
    if not self:check_death("You bled out in your sleep.") then self:camp_night() end
end

-- -- inventory transfer -------------------------------------------------

function Game:ground_list()
    local key = hex_key(self.player.q, self.player.r)
    self.ground[key] = self.ground[key] or {}
    return self.ground[key]
end

function Game:get_stack(kind, k)
    if kind == "ground" then
        return self:ground_list()[k]
    elseif kind == "inventory" then
        return self.player.inventory[k]
    elseif kind == "equip" then
        local item = self.player.equipped[k]
        return item and {item = item, qty = 1, cond = self:stack_cond(k)} or nil
    elseif kind == "camp" then
        return self:camp_stack(k)
    end
end

-- What the worn piece's condition becomes on a stack (nil when as new).
function Game:stack_cond(slot)
    local c = (self.player.wear or {})[slot]
    if c and c < 100 then return c end
    return nil
end

function Game:remove_stack(kind, k)
    if kind == "ground" then
        return table.remove(self:ground_list(), k)
    elseif kind == "inventory" then
        return table.remove(self.player.inventory, k)
    elseif kind == "equip" then
        local item = self.player.equipped[k]
        local cond = self:stack_cond(k)
        self.player.equipped[k] = nil
        if self.player.wear then self.player.wear[k] = nil end
        return item and {item = item, qty = 1, cond = cond} or nil
    elseif kind == "camp" then
        return self:camp_remove(k)
    end
end

-- Add stack to list, merging into an existing stack of the same item so the
-- same thing never takes two cells. Returns false (list untouched) when a new
-- stack is needed and the list already holds `cap` stacks.
local function add_to_list(list, stack, cap)
    for _, s in ipairs(list) do
        if s.item == stack.item and s.cond == stack.cond then   -- (worn and new don't stack)
            s.qty = s.qty + stack.qty
            return true
        end
    end
    if cap and #list >= cap then return false end
    table.insert(list, stack)
    return true
end

-- The pockets in what you wear and the pouches on your belt (torn clothes
-- hold half).
function Game:pocket_cells()
    local n = 0
    for slot, item in pairs(self.player.equipped) do
        local def = ITEM_DB[item]
        local k = (def.pocket_cells or 0) + (def.belt_cells or 0)
        n = n + (self:torn(slot) and k // 2 or k)
    end
    return n
end

-- How the bag's cells add up, for the bag screen: "Satchel 6 + pockets 2
-- + Strength 1 = 9" (no bag: "Arms 2 + ...").
function Game:bag_sum_text()
    local p = self.player
    local back = p.equipped.back
    local bag = back and ITEM_DB[back].bag_cells or POCKET_CELLS
    if back and self:torn("back") then bag = bag // 2 end
    local parts = {(back and ITEM_DB[back].name or "Arms") .. " " .. bag}
    local pk = self:pocket_cells()
    if pk > 0 then parts[#parts + 1] = "pockets " .. pk end
    if (p.bag_bonus or 0) > 0 then parts[#parts + 1] = "Strength " .. p.bag_bonus end
    local cap = self:bag_capacity()
    local text = table.concat(parts, " + ") .. " = " .. cap
    if cap < bag + pk + (p.bag_bonus or 0) then text = text .. " (most there's room for)" end
    return text
end

-- Bag cells available now: the worn bag (else what you can carry in your
-- arms) plus your pockets, Strength and Pack Mule, within what the screen
-- can show.
function Game:bag_capacity()
    local p = self.player
    local back = p.equipped.back
    local bag = back and ITEM_DB[back].bag_cells or POCKET_CELLS
    if back and self:torn("back") then bag = bag // 2 end
    return math.max(2, math.min(BACKPACK_CAP, bag + self:pocket_cells() + (p.bag_bonus or 0)))
end

function Game:put_stack(kind, k, stack)
    if kind == "camp" then return self:camp_put(k, stack) end
    if kind == "ground" then
        add_to_list(self:ground_list(), stack)
        return true
    elseif kind == "inventory" then
        if not add_to_list(self.player.inventory, stack, self:bag_capacity()) then
            self:push_log("Bag full.")
            return false
        end
        return true
    elseif kind == "equip" then
        local def = ITEM_DB[stack.item]
        if def.slot ~= k and not HOLD_SLOTS[k] then
            self:push_log(def.name .. " can't go in " .. k .. ".")
            return false
        end
        local current = self.player.equipped[k]
        self.player.wear = self.player.wear or {}
        if current then
            local old = {item = current, qty = 1, cond = self:stack_cond(k)}
            if not add_to_list(self.player.inventory, old, self:bag_capacity()) then
                add_to_list(self:ground_list(), old)
                self:push_log("Bag full: " .. ITEM_DB[current].name .. " dropped.")
            end
        end
        self.player.equipped[k] = stack.item
        self.player.wear[k] = stack.cond
        -- equipping takes one; anything else in the stack goes to the bag
        if stack.qty > 1 then
            local rest = {item = stack.item, qty = stack.qty - 1, cond = stack.cond}
            if not add_to_list(self.player.inventory, rest, self:bag_capacity()) then
                add_to_list(self:ground_list(), rest)
            end
        end
        return true
    end
end

local function copy_stacks(list)
    local out = {}
    for i, s in ipairs(list) do out[i] = {item = s.item, qty = s.qty, cond = s.cond} end
    return out
end

-- Move a stack. Returns true when it moved. A move that would leave more
-- stacks in the bag than it can hold (e.g. taking off a full backpack) is
-- undone as a whole.
function Game:try_transfer(source, dest)
    local s_kind, s_key = source[1], source[2]
    local d_kind, d_key = dest[1], dest[2]
    if s_kind == d_kind and s_key == d_key then return false end
    local p = self.player
    local saved_inv, saved_ground = copy_stacks(p.inventory), copy_stacks(self:ground_list())
    local saved_eq, saved_wear = {}, {}
    for slot, item in pairs(p.equipped) do saved_eq[slot] = item end
    for slot, c in pairs(p.wear or {}) do saved_wear[slot] = c end
    local saved_slots = {}   -- (the camp's slots, when the move touches them)
    for id, st in pairs(self.base and self.base.slots or {}) do saved_slots[id] = st end
    local cap_before = self:bag_capacity()

    -- onto a bag cell that holds something else: they trade places (the one
    -- there goes where this came from: the ground, its bag cell, or the bag)
    local there, moving = d_kind == "inventory" and d_key and p.inventory[d_key], self:get_stack(s_kind, s_key)
    if there and moving and not (there.item == moving.item and there.cond == moving.cond) then
        if s_kind == "inventory" then
            p.inventory[s_key], p.inventory[d_key] = there, moving
            self:push_log("Moved " .. ITEM_DB[moving.item].name .. ".")
            return true
        end
        local ok = self:remove_stack(s_kind, s_key) ~= nil
        p.inventory[d_key] = moving
        if s_kind == "ground" or not add_to_list(p.inventory, there, self:bag_capacity()) then
            add_to_list(self:ground_list(), there)
        end
        local cap = self:bag_capacity()
        if #p.inventory > cap and cap < cap_before then ok = false end
        if not ok then
            p.inventory, p.equipped, p.wear = saved_inv, saved_eq, saved_wear
            self.ground[hex_key(p.q, p.r)] = saved_ground
            if self.base then self.base.slots = saved_slots end
            self:push_log("Bag too small - empty it first.")
            return false
        end
        recompute_stats(p)
        self:push_log("Swapped out " .. ITEM_DB[there.item].name .. ".")
        return true
    end
    local stack = self:remove_stack(s_kind, s_key)
    if not stack then return false end
    local ok = self:put_stack(d_kind, d_key, stack)
    -- too full only if this move made it so (more stacks, or a smaller bag):
    -- a bag that shrank on its own (torn) can still be emptied
    local cap = self:bag_capacity()
    if ok and #p.inventory > cap and (#p.inventory > #saved_inv or cap < cap_before) then
        self:push_log("Bag too small - empty it first.")
        ok = false
    end
    if not ok then
        p.inventory, p.equipped, p.wear = saved_inv, saved_eq, saved_wear
        self.ground[hex_key(p.q, p.r)] = saved_ground
        if self.base then self.base.slots = saved_slots end
        return false
    end
    recompute_stats(p)   -- held artifacts change stats
    self:push_log("Moved " .. ITEM_DB[stack.item].name .. ".")
    return true
end

function Game:try_consume(kind, k)
    local stack = self:get_stack(kind, k)
    if not stack then return end
    self:apply_item_names()
    local def = ITEM_DB[stack.item]
    if not def.consumable then
        self:push_log(def.name .. " isn't edible/drinkable.")
        return
    end
    for need, amount in pairs(def.consumable) do
        if need == "rads" then
            self.player.rads = math.max(0, (self.player.rads or 0) + amount)
        else
            self.player.needs[need] = clamp(self.player.needs[need] + amount)
        end
    end
    -- one unit per use; the stack only disappears when it runs out
    stack.qty = stack.qty - 1
    if stack.qty <= 0 then
        self:remove_stack(kind, k)
    end
    self:push_log("Consumed " .. def.name .. ".")
    self:after_consume(def, kind, k)
end

-- Use up one of the stack at kind/k (it goes when it runs out).
function Game:use_one(kind, k, stack)
    stack.qty = stack.qty - 1
    if stack.qty <= 0 then self:remove_stack(kind, k) end
end

-- Something found (a search, a body, a crate) onto the ground here; its name
-- for the log. qty: how many (else 1, or a pile's roll: ITEM_DB[..].pile).
function Game:drop_found(item, qty)
    local pile = ITEM_DB[item].pile
    qty = qty or (pile and pile[1] + self:rand(pile[2] - pile[1] + 1)) or 1
    self:put_stack("ground", nil, {item = item, qty = qty})
    return ITEM_DB[item].name .. (qty > 1 and (" x" .. qty) or "")
end

-- E on the inventory screen: the obvious thing for the item under the cursor.
-- Food/drink is eaten, gear is worn, anything else goes to a free hand; on a
-- body slot it takes the item off (held food is eaten instead).
function Game:use_item(kind, k)
    if kind == "camp" then return self:camp_action(k) end
    local stack = self:get_stack(kind, k)
    if not stack then return end
    local def = ITEM_DB[stack.item]
    local p = self.player
    if stack.item == "lore_page" then
        if self:read_lore() then self:use_one(kind, k, stack) end
        return
    end
    if self:use_churn_item(kind, k, stack) then return end   -- books, tapes, wards... (59_research)
    if def.trinket then
        if self:little_spot(hex_key(p.q, p.r)) == "cairn" then
            if kind == "inventory" then self:offer_trinket(stack.item) end
        else
            self:push_log("It's a toy. Someone small would love it. (Leave it at a cairn.)")
        end
        return
    end
    if stack.item == "medkit" then
        p.injuries.bleeding = false
        p.injuries.wounded_hours = math.max(0, p.injuries.wounded_hours - 12)
        p.health = clamp(p.health + 40)
        self:use_one(kind, k, stack)
        self:push_log("You patch yourself up properly. (+40 HP)")
        return
    end
    if stack.item == "bandage" then
        p.injuries.bleeding = false
        p.health = clamp(p.health + 15)
        self:use_one(kind, k, stack)
        self:push_log("You bandage yourself up. (+15 HP)")
        return
    end
    if stack.item == "battery_cell" and self:carrying("lora_radio") then
        if self:charge_radio() then self:use_one(kind, k, stack) end   -- a full radio keeps the cell
        return
    end
    if stack.item == "snare" then
        if self:set_snare() then
            self:use_one(kind, k, stack)
        end
        return
    end
    if stack.item == "splint" then
        if p.injuries.wounded_hours <= 0 then
            self:push_log("No wound to splint.")
            return
        end
        p.injuries.wounded_hours = math.max(0, p.injuries.wounded_hours - 12)
        self:use_one(kind, k, stack)
        self:push_log("You splint the wound. It'll mend sooner.")
        return
    end
    if stack.item == "scrawled_notes" then
        if self:read_notes() then
            self:use_one(kind, k, stack)
        end
        return
    end
    if stack.item == "cloth_scrap" and p.injuries.bleeding then
        p.injuries.bleeding = false
        self:use_one(kind, k, stack)
        self:push_log("You bind the wound. The bleeding stops.")
        return
    end
    if kind == "equip" then
        if def.consumable and HOLD_SLOTS[k] then
            self:try_consume(kind, k)
        else
            self:try_transfer({kind, k}, {"inventory"})
        end
    elseif def.consumable then
        self:try_consume(kind, k)
    elseif def.slot then
        self:try_transfer({kind, k}, {"equip", def.slot})
    else
        local hand = (not p.equipped.rhand and "rhand") or (not p.equipped.lhand and "lhand") or "rhand"
        self:try_transfer({kind, k}, {"equip", hand})
    end
end

-- ---------------------------------------------------------------------
-- Crafting and campfires
--
-- Inputs come from your bag, your hands and the ground where you stand
-- (NEO Scavenger style). A recipe's inputs are used up; its tools only have
-- to be there. Crafting takes hours, and hours drain your needs.
-- ---------------------------------------------------------------------

-- A property input ("@sharp"): its CHURN.props entry, else nil.
function Game.prop_of(item)
    return item:sub(1, 1) == "@" and CHURN.props[item:sub(2)] or nil
end

-- What the crafting screen calls an input: an item's name, or a property's.
function Game.input_name(item)
    local prop = Game.prop_of(item)
    return prop and prop.name or ITEM_DB[item].name
end

-- How many of an item (or of anything with a property) you can reach right now.
function Game:count_item(item)
    local prop = Game.prop_of(item)
    if prop then
        local n = 0
        for _, id in ipairs(prop.items) do n = n + self:count_item(id) end
        return n
    end
    local n = 0
    for _, s in ipairs(self.player.inventory) do
        if s.item == item then n = n + s.qty end
    end
    for _, s in ipairs(self:ground_list()) do
        if s.item == item then n = n + s.qty end
    end
    for _, slot in ipairs({"rhand", "lhand"}) do
        if self.player.equipped[slot] == item then n = n + 1 end
    end
    for _, id in ipairs(self:bench_tools()) do
        local s = self:camp_stack(id)
        if s.item == item then n = n + s.qty end
    end
    return n
end

-- Use up qty of an item: the ground first, then the bag, your hands last
-- (so a weapon you're holding is the last thing to go).
function Game:take_items(item, qty)
    local prop = Game.prop_of(item)
    if prop then   -- the cheapest things with the property first
        for _, id in ipairs(prop.items) do
            local take = math.min(qty, self:count_item(id))
            if take > 0 then
                self:take_items(id, take)
                qty = qty - take
            end
        end
        return qty == 0
    end
    local function from_list(list)
        local i = 1
        while qty > 0 and i <= #list do
            local s = list[i]
            if s.item == item then
                local take = math.min(qty, s.qty)
                s.qty, qty = s.qty - take, qty - take
                if s.qty <= 0 then table.remove(list, i) else i = i + 1 end
            else
                i = i + 1
            end
        end
    end
    from_list(self:ground_list())
    from_list(self.player.inventory)
    for _, slot in ipairs({"rhand", "lhand"}) do
        if qty > 0 and self.player.equipped[slot] == item then
            self.player.equipped[slot] = nil
            qty = qty - 1
        end
    end
    for _, id in ipairs(self:bench_tools()) do   -- (the workbench last)
        local s = self:camp_stack(id)
        if qty > 0 and s.item == item then
            local take = math.min(qty, s.qty)
            s.qty, qty = s.qty - take, qty - take
            if s.qty <= 0 then self.base.slots[id] = nil end
        end
    end
    return qty == 0
end

function Game:fire_here()
    return self:fire_at(self.player.hours)
end

-- Tools on the camp's workbench (they count when you craft at camp).
function Game:bench_tools()
    local out = {}
    if not (self:at_base() and self:base_has("bench")) then return out end
    for _, id in ipairs({"bench1", "bench2", "bench3"}) do
        local s = self:camp_stack(id)
        if s then out[#out + 1] = id end
    end
    return out
end

-- Any gun or bow you can reach (for Clean Guns).
function Game:guns_in_reach()
    local list = {}
    for id, def in pairs(ITEM_DB) do
        if def.shoot and not def.shoot.quiet and self:count_item(id) > 0 then list[#list + 1] = id end
    end
    table.sort(list)
    return list
end

-- The recipe's inputs in a fixed order (pairs() order isn't stable).
-- (A field, not a top-level local: the bundled file is one Lua chunk and
-- a chunk may have at most 200 locals.)
function Game.recipe_inputs(r)
    local list = {}
    for item, qty in pairs(r.inputs) do list[#list + 1] = {item, qty} end
    table.sort(list, function(a, b) return a[1] < b[1] end)
    return list
end

-- nil if you can make it now, else the reason you can't.
function Game:craft_blocker(r)
    if not (r.repair or r.study or r.cut or self.known[r.id]) then return "You don't know how to make that." end
    if r.study then return self:study_blocker(r.study) end
    if r.base then
        local why = self:base_blocker(r)
        if why then return why end
    end
    for _, iq in ipairs(Game.recipe_inputs(r)) do
        if self:count_item(iq[1]) < iq[2] then
            return "Need " .. iq[2] .. " " .. Game.input_name(iq[1]) .. "."
        end
    end
    for _, tool in ipairs(r.tools or {}) do
        if self:count_item(tool) < 1 then return "Need a " .. Game.input_name(tool) .. " to work with." end
    end
    if r.fire and not self:fire_here() then return "Needs a fire. Build a campfire here." end
    if r.place == "campfire" and self:fire_here() then return "A fire already burns here." end
    if r.mend and not self:most_worn(90) then return "Nothing you wear needs mending." end
    if r.clean and #self:guns_in_reach() == 0 then return "No gun here to clean." end
    return nil
end

function Game:craft(r)
    local why = self:craft_blocker(r)
    if why then
        self:push_log(why)
        return false
    end
    if r.repair then return self:repair(r) end
    if r.study then return self:study(r.study) end
    if r.base then return self:build_base(r) end
    local p, hours = self.player, self:craft_hours(r)
    if r.chance then   -- fiddly work (a gun): it can fail and break a part
        local chance = self:craft_chance(r)
        p.hours = p.hours + hours
        apply_awake_hours(p, hours)
        self:skill_xp("tinker", SKILLS.xp.repair)
        if not self:roll(chance) then
            local parts = {}
            for _, iq in ipairs(Game.recipe_inputs(r)) do
                if not iq[1]:find("^frame_") then parts[#parts + 1] = iq[1] end
            end
            local lost = parts[self:rand(#parts) + 1]
            self:take_items(lost, 1)
            self:sfx("miss")
            self:push_log("It won't go together. The " .. ITEM_DB[lost].name:lower() .. " is ruined.")
            return true
        end
        hours = 0
    end
    for _, iq in ipairs(Game.recipe_inputs(r)) do self:take_items(iq[1], iq[2]) end
    p.hours = p.hours + hours
    apply_awake_hours(p, hours)
    self:skill_xp("tinker", SKILLS.xp.craft)
    self:sfx("chime")
    if r.mend then
        local slot = self:most_worn(90)
        p.wear[slot] = math.min(100, p.wear[slot] + WORLD.wear.mend)
        self:push_log(("You patch your %s (%d%%)."):format(ITEM_DB[p.equipped[slot]].name:lower(), math.floor(p.wear[slot])))
    elseif r.place == "campfire" then
        local burn = r.burn or RECIPES.campfire_hours
        self.camps[hex_key(p.q, p.r)] = {until_hour = p.hours + burn}
        self:push_log("You build " .. (r.burn and "a small fire" or "a campfire") .. ". It will burn " .. burn .. "h.")
    elseif r.clean then
        self.gun_wear = self.gun_wear or {}
        for _, id in ipairs(self:guns_in_reach()) do self.gun_wear[id] = 100 end
        self:push_log("You strip, oil and wipe every gun you have. They shine.")
    else
        local stack = {item = r.out[1], qty = r.out[2]}
        if not self:put_stack("inventory", nil, stack) then
            self:put_stack("ground", nil, stack)
            self:push_log("Made " .. r.name .. " (left on the ground).")
        else
            self:push_log("Made " .. r.name .. ".")
        end
    end
    self:check_death("You bled out.")
    return true
end

-- Assembly odds (a recipe with `chance`): Perception and tinkering.
function Game:craft_chance(r)
    return math.max(5, math.min(95, r.chance + TECH.per_point * (self.player.attrs.Perception - 3)
                                    + self:skill_bonus("tinker") + self:bench_bonus()))
end

-- Scrawled Notes: learn a recipe you don't know yet (the notes are used up).
function Game:read_notes()
    local unknown = {}
    for _, r in ipairs(RECIPES) do
        if not self.known[r.id] then unknown[#unknown + 1] = r end
    end
    -- some notes (and all of them once you know every recipe) sketch the way out
    if not self.sites_known.checkpoint and (#unknown == 0 or self:rand(3) == 0) then
        return self:hear_of_exit("A sketch in the notes")
    end
    -- others mark a stash (and once you know every recipe, all of them do)
    if #unknown == 0 or self:rand(4) == 0 then
        if self:mark_stash() then return true end
    end
    if #unknown == 0 then
        self:push_log("Nothing in these notes you don't already know.")
        return false
    end
    local r = unknown[self:rand(#unknown) + 1]
    self.known[r.id] = true
    self:push_log("You puzzle out the notes: how to make " .. r.name .. ".")
    return true
end

-- "Cut up" recipes for the clothes in reach (not on your body): Cloth
-- Scraps, with any sharp edge (CHURN.cut).
function Game:cut_recipes()
    local list, seen = {}, {}
    local function add(item)
        local n = CHURN.cut.scraps[item]
        if n and not seen[item] then
            seen[item] = true
            list[#list + 1] = {id = "cut_" .. item, name = "Cut Up " .. ITEM_DB[item].name,
                               inputs = {[item] = 1}, tools = {"@sharp"}, hours = CHURN.cut.hours,
                               out = {"cloth_scrap", n}, cut = true}
        end
    end
    for _, s in ipairs(self.player.inventory) do add(s.item) end
    for _, s in ipairs(self:ground_list()) do add(s.item) end
    for _, slot in ipairs({"rhand", "lhand"}) do
        if self.player.equipped[slot] then add(self.player.equipped[slot]) end
    end
    table.sort(list, function(a, b) return a.name < b.name end)
    return list
end

-- What the crafting screen lists: what you can make right now first, then
-- the rest (each part in its usual order).
function Game:known_recipes()
    local all = {}
    for _, r in ipairs(RECIPES) do
        if self.known[r.id] then all[#all + 1] = r end
    end
    for _, r in ipairs(self:repair_recipes()) do all[#all + 1] = r end   -- broken tech you carry
    for _, r in ipairs(self:study_recipes()) do all[#all + 1] = r end    -- research (59_research)
    for _, r in ipairs(self:cut_recipes()) do all[#all + 1] = r end      -- clothes into cloth
    local ready, rest = {}, {}
    for _, r in ipairs(all) do
        local list = self:craft_blocker(r) == nil and ready or rest
        list[#list + 1] = r
    end
    for _, r in ipairs(rest) do ready[#ready + 1] = r end
    return ready
end

function Game:open_crafting()
    self.craft_ui.back = self.screen
    self.craft_ui.cursor = math.min(self.craft_ui.cursor, #self:known_recipes())
    self.screen = "craft"
end

function Game:craft_key(key)
    local list = self:known_recipes()
    local c = self.craft_ui
    if key == gfx.KEY_UP or key == KEY.W then
        c.cursor = math.max(1, c.cursor - 1)
    elseif key == gfx.KEY_DOWN or key == KEY.S then
        c.cursor = math.min(#list, c.cursor + 1)
    elseif key == KEY.ENTER or key == KEY.LF or key == KEY.SPACE then
        local r = list[c.cursor]
        if r and self:craft(r) then
            -- the list reorders (ready first): stay on the same recipe
            for i, r2 in ipairs(self:known_recipes()) do
                if r2.id == r.id then c.cursor = i end
            end
        end
    elseif key == KEY.C or key == gfx.KEY_ESCAPE or key == KEY.I then
        self.screen = c.back == "craft" and "map" or c.back
    end
end
-- ---------------------------------------------------------------------
-- Water and the survival loop
--
-- Bottles are containers (ITEM_DB[..].empty): drinking leaves an Empty
-- Bottle where the full one was. E on the map by a river or on a ford fills
-- every empty bottle you carry with Dirty Water, or with none you drink
-- straight from it. Resting in the rain fills them clean; the Boil Water
-- recipe cleans dirty water at a fire. Some food and water can make you
-- sick (ITEM_DB[..].sick), meat goes bad (perish), and at 0 thirst or
-- hunger you lose HP every hour. Numbers are in SURVIVE (05_data_world).
-- ---------------------------------------------------------------------

-- After eating/drinking one unit of def (the stack was at kind/k):
-- the empty container, and maybe sickness.
function Game:after_consume(def, kind, k)
    local p = self.player
    if def.empty then
        local empty = {item = def.empty, qty = 1}
        if kind == "equip" and p.equipped[k] == nil then
            p.equipped[k] = def.empty                       -- still in your hand
        elseif not self:put_stack("inventory", nil, empty) then
            self:put_stack("ground", nil, empty)
        end
    end
    if def.sick and self:roll(def.sick) then self:make_sick() end
    local calm = def.name == "Vodka" and CHURN.dread.vodka or def.name == "Sedative" and CHURN.dread.sedative
    if calm then self:dread(calm) end   -- (64_dread)
    if def.cures and (p.sick_hours or 0) > 0 then
        p.sick_hours = 0
        self:push_log("Your gut settles.")
    end
end

function Game:make_sick()
    local p = self.player
    local lo, hi = SURVIVE.sick_hours[1], SURVIVE.sick_hours[2]
    p.sick_hours = math.max(p.sick_hours or 0, lo + self:rand(hi - lo + 1))
    self:push_log("Your gut twists. You're sick. (" .. p.sick_hours .. "h)")
end

-- On a ford, or next to open water.
function Game:near_water()
    local p = self.player
    if self.tiles[hex_key(p.q, p.r)] == "ford" then return true end
    for _, n in ipairs(neighbors(self.tiles, p.q, p.r)) do
        if self.tiles[hex_key(n[1], n[2])] == "water" then return true end
    end
    return false
end

-- Turn every carried empty bottle into `into`. Returns how many.
function Game:fill_bottles(into)
    local p = self.player
    local n = 0
    for slot, item in pairs(p.equipped) do
        if item == "empty_bottle" then p.equipped[slot] = into; n = n + 1 end
    end
    for i = #p.inventory, 1, -1 do
        local s = p.inventory[i]
        if s.item == "empty_bottle" then
            n = n + s.qty
            local qty = s.qty
            table.remove(p.inventory, i)
            -- merges into an existing stack or takes the freed cell, so it fits
            self:put_stack("inventory", nil, {item = into, qty = qty})
        end
    end
    return n
end

-- E on the map.
function Game:water_action()
    local p = self.player
    if not self:near_water() then
        self:push_log("No water here. Find a river or a ford.")
        return
    end
    local n = self:fill_bottles("dirty_water")
    if n > 0 then
        self:push_log(("Filled %d bottle%s. Boil it before drinking."):format(n, n > 1 and "s" or ""))
        return
    end
    p.needs.thirst = clamp(p.needs.thirst + SURVIVE.drink_here)
    p.hours = p.hours + SURVIVE.drink_hours
    apply_awake_hours(p, SURVIVE.drink_hours)
    self:push_log("You drink from the river. It tastes of iron.")
    local risk = ITEM_DB.dirty_water.sick
    if risk and self:roll(risk) then self:make_sick() end
end

-- Resting in the rain: empty bottles fill clean.
function Game:rain_fill()
    local n = self:fill_bottles("water_bottle")
    if n > 0 then self:push_log(("The rain filled %d bottle%s."):format(n, n > 1 and "s" or "")) end
end

-- n units of a stack go bad.
function Game:spoil(stack, per, n)
    stack.qty = stack.qty - n
    local rot = {item = per.into, qty = n}
    if not self:put_stack("inventory", nil, rot) then self:put_stack("ground", nil, rot) end
    self.spoiled = self.spoiled or {}
    self.spoiled[ITEM_DB[stack.item].name] = true
end

-- One hour: sickness, hunger and thirst damage, food going bad.
function Game:survive_hour()
    local p = self.player
    local hurt = 0
    if (p.sick_hours or 0) > 0 then
        local s = SURVIVE.sick
        p.sick_hours = p.sick_hours - 1
        p.needs.thirst = clamp(p.needs.thirst - s.thirst)
        p.needs.hunger = clamp(p.needs.hunger - s.hunger)
        p.needs.rest = clamp(p.needs.rest - s.rest)
        hurt = hurt + s.hurt
        if p.sick_hours == 0 then self:push_log("The sickness passes.") end
    end
    if p.injuries.bleeding then
        p.injuries.bleed_hours = (p.injuries.bleed_hours or 0) + 1
        if p.injuries.bleed_hours >= SURVIVE.clot_hours then
            p.injuries.bleeding = false
            self:push_log("The bleeding slows, then stops.")
        end
    else
        p.injuries.bleed_hours = 0
    end
    if p.needs.thirst <= 0 then hurt = hurt + SURVIVE.thirst_hurt end
    if p.needs.hunger <= 0 then hurt = hurt + SURVIVE.hunger_hurt end
    p.health = clamp(p.health - hurt)

    for i = #p.inventory, 1, -1 do
        local s = p.inventory[i]
        local per = ITEM_DB[s.item].perish
        if per then
            local n = 0   -- each unit: a 1-in-hours chance
            for _ = 1, s.qty do
                if self:rand(per.hours) == 0 then n = n + 1 end
            end
            if n > 0 then
                self:spoil(s, per, n)
                if s.qty <= 0 then table.remove(p.inventory, i) end
            end
        end
    end
    for slot, item in pairs(p.equipped) do
        local per = ITEM_DB[item].perish
        if per and self:rand(per.hours) == 0 then
            p.equipped[slot] = per.into
            self.spoiled = self.spoiled or {}
            self.spoiled[ITEM_DB[item].name] = true
        end
    end
end

function Game:survive_news()
    if not self.spoiled then return end
    local names = {}
    for name in pairs(self.spoiled) do names[#names + 1] = name end
    table.sort(names)
    self:push_log(table.concat(names, ", ") .. " went bad.")
    self.spoiled = nil
end

-- What killed you, when it happened with time passing.
function Game:death_reason()
    local p = self.player
    if self.emission_caught then return "The emission took you." end
    if (p.storm_hours or 0) > WORLD.storm.grace then return "The storm took you." end
    if (p.cold_hours or 0) > WORLD.cold_grace then return "You froze to death." end
    if self:rad_stage() >= 2 then
        return self:can_measure() and "Radiation sickness took you." or "A wasting sickness took you."
    end
    if (p.sick_hours or 0) > 0 then return "The sickness took you." end
    if p.needs.thirst <= 0 then return "You died of thirst." end
    if p.needs.hunger <= 0 then return "You starved." end
    return "Your body gave out."
end
-- ---------------------------------------------------------------------
-- Time of day, weather, cold and light
--
-- The clock is derived from player.hours (see WORLD in 05_data_world). Weather is
-- rolled per WORLD.weather_block hours from the world's seed, so it needs no
-- state of its own. Game:tick() runs after every key: it walks the hours
-- that passed since the last tick and applies cold, then refreshes what you
-- can see (night shortens sight unless you hold a torch).
-- ---------------------------------------------------------------------

-- day (1..), hour (0..23) at `hours` into the run (default: now)
function Game:clock(hours)
    local total = WORLD.start_hour + (hours or self.player.hours)
    return total // 24 + 1, total % 24
end

function Game:is_night(hours)
    local _, hour = self:clock(hours)
    return hour >= WORLD.night_from or hour < WORLD.night_to
end

-- The season `hours` into the run: an entry of WORLD.seasons (from the day,
-- so nothing to save). Day 1 is late Autumn.
function Game:season(hours)
    local day = self:clock(hours)
    local i = ((day - 1) // WORLD.season_days) % #WORLD.seasons + 1
    return WORLD.seasons[i], (day - 1) % WORLD.season_days + 1
end

function Game:weather(hours)
    local block = (WORLD.start_hour + (hours or self.player.hours)) // WORLD.weather_block
    local s = (self.weather_seed + block * 7919) % 32768
    s = rand_next(rand_next(s))
    local _, kind = weighted_pick(s, self:season(hours).weather)
    -- a gentle first morning: no storm or fog while you find your feet
    if (kind == "Storm" or kind == "Fog") and (hours or self.player.hours) < WORLD.calm_start then
        kind = "Overcast"
    end
    return kind
end

-- Out in the open in a storm, with nowhere to shelter.
function Game:storm_exposed(hours)
    local p = self.player
    return self:weather(hours) == "Storm" and WORLD.storm.open[self.tiles[hex_key(p.q, p.r)]] == true
        and not self:bed_here() and not self:placed_here("tarp_shelter")
end

-- One hour of a storm (from tick): exposed, it wears you down.
function Game:storm_hour(hour)
    local p, st = self.player, WORLD.storm
    if not self:storm_exposed(hour) then
        p.storm_hours = 0
        return
    end
    p.storm_hours = (p.storm_hours or 0) + 1
    self:wear_all(WORLD.wear.storm)
    p.needs.rest = clamp(p.needs.rest - st.rest)
    if p.storm_hours > st.grace then p.health = clamp(p.health - st.hurt) end
end

-- Map panel: "Winter Storm" (season, weather), or "Win Storm" when the
-- panel's 19 columns are short of room (`extra` is said after it).
function Game:weather_text(extra)
    local s, w = self:season(), self:weather()
    local long = s.name .. " " .. w .. (extra or "")
    return #long <= 19 and long or (s.short .. " " .. w .. (extra or ""))
end

-- -- clothes wear out (numbers in WORLD.wear) ---------------------------------
-- p.wear[slot] = the condition (0-100, nil = 100) of what you wear there; off
-- your body a stack carries it as `cond` (put_stack/remove_stack move it).
-- At 0 a piece is torn: no warmth, half its pockets, until you patch it.

-- Does this item wear out? (clothes, not tools or what's in your hands)
function Game.wears(item)
    local def = ITEM_DB[item]
    return def ~= nil and def.slot ~= nil and not HOLD_SLOTS[def.slot] and not def.light
end

-- Condition of what you wear in `slot` (nil if nothing there wears out).
function Game:cond(slot)
    local item = self.player.equipped[slot]
    if HOLD_SLOTS[slot] or not (item and Game.wears(item)) then return nil end
    return (self.player.wear or {})[slot] or 100
end

function Game:torn(slot)
    local c = self:cond(slot)
    return c ~= nil and c <= 0
end

-- The piece you're wearing that is most worn (below `below`), or nil.
function Game:most_worn(below)
    local best, best_c
    for _, slot in ipairs(EQUIP_SLOTS) do
        local c = self:cond(slot)
        if c and c < (below or 100) and (not best_c or c < best_c) then best, best_c = slot, c end
    end
    return best, best_c
end

function Game:wear_out(slot, amount)
    local p, c = self.player, self:cond(slot)
    if not c or c <= 0 then return end
    local item = p.equipped[slot]
    p.wear = p.wear or {}
    p.wear[slot] = math.max(0, c - amount * (ITEM_DB[item].ragged_of and WORLD.wear.rag or 1))
    if p.wear[slot] <= 0 then
        self:push_log("Your " .. ITEM_DB[item].name:lower() .. " tears. Patch it (C).")
        self:sfx("miss")
    end
end

-- Crafting screen: what "Patch clothes" would mend.
function Game:mend_text()
    local slot, c = self:most_worn(90)
    if not slot then return "Mends your most worn clothes" end
    return ("Mends: %s%s"):format(ITEM_DB[self.player.equipped[slot]].name, Game.cond_text(c))
end

-- " 40%", " (torn)" or "" for a stack's condition (bag, ground, worn).
function Game.cond_text(cond)
    if not cond or cond >= 100 then return "" end
    if cond <= 0 then return " (torn)" end
    return (" %d%%"):format(math.floor(cond))
end

function Game:wear_all(amount)
    for _, slot in ipairs(EQUIP_SLOTS) do self:wear_out(slot, amount) end
end

-- One piece you wear, at random (an enemy's blow lands on it).
function Game:wear_hit()
    local worn = {}
    for _, slot in ipairs(EQUIP_SLOTS) do
        local c = self:cond(slot)
        if c and c > 0 then worn[#worn + 1] = slot end
    end
    if #worn > 0 then self:wear_out(worn[self:rand(#worn) + 1], WORLD.wear.hit) end
end

-- Warmth from what you wear (not what you hold); torn clothes give none.
function Game:warmth()
    local total = 0
    for slot, item in pairs(self.player.equipped) do
        if not HOLD_SLOTS[slot] and not self:torn(slot) then total = total + (ITEM_DB[item].warmth or 0) end
    end
    return total
end

function Game:cold_need(hours)
    return WORLD.need[self:weather(hours)] + self:season(hours).need
        + (self:is_night(hours) and WORLD.night_need or 0)
end

function Game:fire_at(hours)
    local camp = self.camps[hex_key(self.player.q, self.player.r)]
    if self:at_base() and self:camp_fire(hours) then return true end   -- (the camp's fire pit)
    return camp ~= nil and hours < camp.until_hour
end

function Game:is_cold(hours)
    hours = hours or self.player.hours
    return not self:fire_at(hours) and not self:bed_here() and self:warmth() < self:cold_need(hours)
end

-- A lit torch in either hand.
function Game:has_light()
    local eq = self.player.equipped
    if eq.rhand == "torch" or eq.lhand == "torch" then return true end
    for _, slot in ipairs({"rhand", "lhand"}) do   -- a black candle, a glow jar
        if eq[slot] and ITEM_DB[eq[slot]].light then return true end
    end
    for slot, item in pairs(eq) do
        if not HOLD_SLOTS[slot] and ITEM_DB[item].light then return true end   -- a headlamp
    end
    return self:at_base() and self:camp_stack("light") ~= nil   -- (the camp's lamp)
end

-- Recompute what you can see: at night sight drops by one without light.
function Game:refresh_view()
    local p = self.player
    local dark = self:is_night() and not self:has_light()
    local fog = self:weather() == "Fog"
    p.view_sight = math.max(1, p.sight - (dark and 1 or 0) - (fog and 1 or 0))
    update_visibility(p, self.tiles)
    self:apply_item_names()
end

-- Apply the hours that passed since the last tick.
function Game:tick()
    local p = self.player
    self:apply_item_names()   -- before any log line this tick names an item
    self.ticked_hour = self.ticked_hour or p.hours
    local was_cold = (p.cold_hours or 0) > 0
    local storm_before, cold_before = p.storm_hours or 0, p.cold_hours or 0
    local rad_before, dose = self:rad_stage(), 0
    for hour = self.ticked_hour, p.hours - 1 do
        if self:is_cold(hour) then
            p.cold_hours = (p.cold_hours or 0) + 1
            p.needs.rest = clamp(p.needs.rest - WORLD.cold_rest_drain)
            if p.cold_hours > WORLD.cold_grace then
                p.health = clamp(p.health - WORLD.cold_hurt)
            end
        else
            p.cold_hours = 0
        end
        dose = dose + self:rad_hour()
        self:survive_hour()
        self:storm_hour(hour)
        if self:is_night(hour) and not self:is_night(hour - 1) then self:queue_scene("first_night") end
        self:wear_all(WORLD.wear.day / 24)
        self:little_hour(hour)
        local heat = self:season(hour).thirst
        if heat > 0 then p.needs.thirst = clamp(p.needs.thirst - heat) end
        self:emission_hour(hour)
        self:dog_hour(hour)
        self:base_hour(hour)
        self:dread_hour(hour)
    end
    self.ticked_hour = p.hours
    local cold = (p.cold_hours or 0) > 0
    if cold and not was_cold then
        self:push_log("You're cold. Wear warmer clothes or build a fire.")
    elseif (p.cold_hours or 0) > WORLD.cold_grace and cold_before <= WORLD.cold_grace then
        self:push_log("The cold is getting into you. (-" .. WORLD.cold_hurt .. " HP/h)")
    end
    -- (on the change, not an exact count: a long rest jumps several hours)
    local storm = p.storm_hours or 0
    if storm > WORLD.storm.grace and storm_before <= WORLD.storm.grace then
        self:push_log("The storm is beating you down. (-" .. WORLD.storm.hurt .. " HP/h)")
    elseif storm > 0 and storm_before == 0 then
        self:push_log("The storm is on you. Get to cover: ruins, hills or trees.")
    end
    self:rad_news(dose, rad_before)
    self:survive_news()
    self:emission_log()
    self:geiger_scan()
    self:refresh_view()
    self:spot_sites()
    self:story_check()
    self:quest_tick()
    self:hint_tick()
    if not self:check_death(self:death_reason()) then self:check_achievements() end
end
-- ---------------------------------------------------------------------
-- Saving and continuing
--
-- Needs solaros.storage.write_file (SolarOS 4.15.17 and newer). On older
-- firmware the game runs exactly as before and simply can't save. Saves go
-- through SAVE.write (write `.new`, then replace), so a power cut mid-save
-- can't cost the run.
--
-- The save is a Lua table literal (read back with load() in an empty
-- environment, so it can't run code). The world itself is not stored: it is
-- regenerated from world_seed, and only what changes is saved - the player,
-- ground items, fires, searched tiles, known recipes, the clock and the log.
-- Autosave runs whenever time passes on the map/inventory/crafting screens
-- and on quit; death deletes the save (one life, like NEO Scavenger).
-- ---------------------------------------------------------------------

-- (old_dir: where saves lived before the game became The Churn; still read)
local SAVE = {version = 1, dir = "churn", old_dir = "wasteland", file = "save.lua",
              fields = {"world_seed", "seed", "weather_seed", "scavenged", "camps",
                        "known", "ground", "log", "enc_cooldown", "ticked_hour", "rad_known",
                        "trader", "sites_known", "stashes", "next_emission", "snares",
                        "karl_asked", "karl_next", "karl_gave", "muted",
                        "difficulty", "dog", "radio", "karl_hint",
                        "base", "quest", "quests_done",
                        "lore_read", "signal_page", "skills", "stats",
                        "ferry_trader", "peddler", "little", "story", "run_id", "scenes_seen",
                        "research", "books_read", "tapedeck", "gun_wear", "noise_until",
                        "placed", "crates", "vesna", "inst_chain", "rep", "karl_lure", "finds", "hints",
                        "bestiary", "scan", "radio_body", "legacy"}}

-- Where the save lives: <preferred storage>/churn/save.lua (dir: another folder)
function SAVE.path(dir)
    local storage = solaros.storage
    if not storage then return nil end
    local ok, root = pcall(function() return storage.mount_point and storage.mount_point() end)
    if not ok or type(root) ~= "string" or root == "" then root = "/flash" end
    dir = dir or SAVE.dir
    return root .. "/" .. dir, root .. "/" .. dir .. "/" .. SAVE.file
end

function SAVE.can_write()
    return solaros.storage ~= nil and solaros.storage.write_file ~= nil
end

-- Write a whole file so a power cut can't leave it half-written: the new
-- text goes to `path.new`, then replaces `path` (stock SolarOS's write_file
-- overwrites in place). Without rename, a plain write. Raises on failure
-- (callers pcall it).
function SAVE.write(path, text)
    local st = solaros.storage
    if not st.rename then return st.write_file(path, text) end
    local fresh = path .. ".new"
    st.write_file(fresh, text)
    if st.exists and st.exists(path) then st.remove(path) end
    st.rename(fresh, path)
end

-- The text of `path`, or of `path.new` if that's all a cut-short save left:
-- each candidate is handed to `accept`, and the first it returns is used.
function SAVE.read(path, max, accept)
    local st = solaros.storage
    if not (st and st.read_file) then return nil end
    for _, p in ipairs({path, path .. ".new"}) do
        local ok, text = pcall(st.read_file, p, max)
        if ok and type(text) == "string" and text ~= "" then
            local value = accept(text)
            if value ~= nil then return value end
        end
    end
    return nil
end

-- SAVE.read of `file` in the game's folder, or (a save or records from
-- before the rename) in the old one.
function SAVE.read_any(file, max, accept)
    if not SAVE.path() then return nil end
    for _, dir in ipairs({SAVE.dir, SAVE.old_dir}) do
        local folder = SAVE.path(dir)
        local value = SAVE.read(folder .. "/" .. file, max, accept)
        if value ~= nil then return value end
    end
    return nil
end

-- Plain values and nested tables of them, keys sorted so saves are stable.
function SAVE.serialize(v, out)
    local t = type(v)
    if t == "number" then
        out[#out + 1] = math.type(v) == "integer" and tostring(v) or string.format("%.17g", v)
    elseif t == "string" then
        out[#out + 1] = string.format("%q", v)
    elseif t == "boolean" then
        out[#out + 1] = tostring(v)
    elseif t == "table" then
        local keys = {}
        for k in pairs(v) do keys[#keys + 1] = k end
        table.sort(keys, function(a, b)
            if type(a) == type(b) then return a < b end
            return type(a) == "number"
        end)
        out[#out + 1] = "{"
        for _, k in ipairs(keys) do
            if type(k) == "string" and k:match("^[%a_][%w_]*$") then
                out[#out + 1] = k .. "="
            else
                out[#out + 1] = "["
                SAVE.serialize(k, out)
                out[#out + 1] = "]="
            end
            SAVE.serialize(v[k], out)
            out[#out + 1] = ","
        end
        out[#out + 1] = "}"
    else
        out[#out + 1] = "nil"
    end
    return out
end

function Game:save_state()
    local data = {version = SAVE.version, player = {}}
    for _, f in ipairs(SAVE.fields) do data[f] = self[f] end
    for k, v in pairs(self.player) do
        if k ~= "visible" then data.player[k] = v end   -- visible is recomputed
    end
    return table.concat(SAVE.serialize(data, {}))
end

-- Write the save. Returns true, or false and why (never raises).
function Game:save()
    if not SAVE.can_write() then return false, "this SolarOS can't write files" end
    local dir, path = SAVE.path()
    local ok, err = pcall(function()
        if solaros.storage.makedirs then solaros.storage.makedirs(dir) end
        SAVE.write(path, self:save_state())
    end)
    if not ok then return false, (tostring(err):gsub("^.-:%d+: ", "")) end
    self.saved_hour = self.player.hours
    return true
end

-- The saved table, or nil (no save, unreadable, or from another version).
function Game.read_save()
    return SAVE.read_any(SAVE.file, 65536, function(text)
        local chunk = load("return " .. text, "=save", "t", {})
        if not chunk then return nil end
        local good, data = pcall(chunk)
        if not good or type(data) ~= "table" or data.version ~= SAVE.version
            or type(data.player) ~= "table" or not data.world_seed then
            return nil
        end
        return data
    end)
end

function Game:load_state(data)
    local tiles, _, _, rad, sites = generate_world(data.world_seed)
    self.tiles, self.rad, self.sites = tiles, rad, sites
    self.extras = Game.place_extras(tiles, sites, rad, data.world_seed)
    for _, f in ipairs(SAVE.fields) do
        if data[f] ~= nil then self[f] = data[f] end
    end
    if data.scenes_seen == nil then self.scenes_seen = Game.all_scenes_seen() end   -- (older saves)
    -- saves from before emissions existed (or one left far behind) would
    -- otherwise never see another: schedule the next from now
    local E = RAD.emission
    if (self.next_emission or 0) + E.hours <= data.player.hours then
        self.next_emission = data.player.hours + E.every[1]
    end
    self.player = data.player
    self.player.visible = {}
    self.player.explored = self.player.explored or {}
    recompute_stats(self.player)
    self.saved_hour = self.player.hours
    self:refresh_view()
    self.screen = "map"
    local day, hour = self:clock()
    self:push_log(("Welcome back. Day %d, %02d:00."):format(day, hour))
end

function Game.delete_save()
    local storage = solaros.storage
    if not (storage and storage.remove and storage.exists) then return end
    for _, dir in ipairs({SAVE.dir, SAVE.old_dir}) do   -- (an old save too: one life)
        local _, path = SAVE.path(dir)
        for _, p in ipairs({path, path .. ".new"}) do
            pcall(function() if storage.exists(p) then storage.remove(p) end end)
        end
    end
end

-- Save after anything that took time, on the screens where a run is at rest.
function Game:autosave()
    if not SAVE.can_write() then return end
    local s = self.screen
    if s ~= "map" and s ~= "inventory" and s ~= "craft" then return end
    if self.saved_hour == self.player.hours and not self.force_save then return end
    self.force_save = nil
    local ok, why = self:save()
    if not ok and not self.save_warned then
        self.save_warned = true
        self:push_log("Couldn't save: " .. why)
    end
end
-- ---------------------------------------------------------------------
-- Radiation and anomaly fields
--
-- generate_world leaves self.rad (tile key -> level 1-3). Every hour on a
-- hot hex adds rads (Game:tick calls rad_hour); enough rads make you sick.
-- Anti-Rad and Vodka take rads off (consumable.rads). A carried Geiger
-- counter reads the hexes around you, marks them on the map (rad_known,
-- which is saved) and clicks; without one you only learn a hex was hot by
-- the dose you took there. All numbers are in RAD (05_data_world).
-- ---------------------------------------------------------------------

function Game:rad_at(q, r)
    return (self.rad and self.rad[hex_key(q, r)]) or 0
end

-- In the bag, in a hand or worn.
function Game:carrying(item)
    local p = self.player
    for _, item_here in pairs(p.equipped) do
        if item_here == item then return true end
    end
    for _, s in ipairs(p.inventory) do
        if s.item == item then return true end
    end
    return false
end

-- What worn gear lets through (1 = everything).
function Game:rad_armor()
    local through = 1
    for slot, item in pairs(self.player.equipped) do
        if not HOLD_SLOTS[slot] then through = through * (ITEM_DB[item].rad_armor or 1) end
    end
    return through
end

-- 0 = fine, else the index of the worst RAD.stages reached.
function Game:rad_stage()
    local rads, stage = self.player.rads or 0, 0
    for i, st in ipairs(RAD.stages) do
        if rads >= st.at then stage = i end
    end
    return stage
end

-- One hour at the current hex. Returns the dose taken.
function Game:rad_hour()
    local p = self.player
    local level = self:rad_at(p.q, p.r)
    local dose = 0
    if level > 0 then
        dose = RAD.dose[level] * self:rad_armor() * self:diff("rad")
        p.rads = math.min(RAD.max, (p.rads or 0) + dose)
        -- only a counter puts it on the map; otherwise you just felt something
        if self:can_measure() then self.rad_known[hex_key(p.q, p.r)] = level end
        self.dose_level = math.max(self.dose_level or 0, level)
    elseif (p.rads or 0) > 0 then
        p.rads = math.max(0, p.rads - RAD.decay)
    end
    local st = RAD.stages[self:rad_stage()]
    if st then
        p.health = clamp(p.health - st.hurt)
        p.needs.rest = clamp(p.needs.rest - st.tire)
    end
    return dose
end

-- A Geiger counter (or the Anomaly Detector) tells you what's going on.
-- Without one, radiation only shows as symptoms.
function Game:can_measure()
    return self:carrying("geiger") or self:carrying("anomaly_detector")
end

-- Items whose real name or description would give radiation away show a
-- vague one until you can measure it (vague_name / vague_desc in ITEM_DB).
-- ITEM_DB is edited in place so every screen and log line follows; runs
-- from tick (every key) and refresh_view.
function Game:apply_item_names()
    local measured = self:can_measure()
    for _, def in pairs(ITEM_DB) do
        if def.vague_name or def.vague_desc then
            def.real_name = def.real_name or def.name
            def.real_desc = def.real_desc or def.desc
            def.name = measured and def.real_name or (def.vague_name or def.real_name)
            def.desc = measured and def.real_desc or (def.vague_desc or def.real_desc)
        end
    end
end

-- The Geiger counter reads your hex and the ones next to it.
function Game:geiger_scan()
    local p = self.player
    if self:carrying("anomaly_detector") then   -- reads further than a Geiger counter
        local range = TECH.detector_range
        for dq = -range, range do
            for dr = math.max(-range, -dq - range), math.min(range, -dq + range) do
                local key = hex_key(p.q + dq, p.r + dr)
                if self.tiles[key] then self.rad_known[key] = self:rad_at(p.q + dq, p.r + dr) end
            end
        end
        return
    end
    if not self:carrying("geiger") then return end
    local here = hex_key(p.q, p.r)
    self.rad_known[here] = self:rad_at(p.q, p.r)
    local near = 0
    for _, n in ipairs(neighbors(self.tiles, p.q, p.r)) do
        local level = self:rad_at(n[1], n[2])
        self.rad_known[hex_key(n[1], n[2])] = level
        near = math.max(near, level)
    end
    -- clean here but hot next door: the counter ticks faster (once per hex)
    if self.rad_known[here] == 0 and near > 0 and self.geiger_ticked ~= here then
        self.geiger_ticked = here
        self:sfx("geiger")
        self:push_log("The Geiger ticks faster. Something hot nearby.")
    end
end

-- Log lines (and clicks) for the hours tick just applied.
function Game:rad_news(dose, stage_before)
    local p = self.player
    local measured = self:can_measure()
    local level = self.dose_level or 0
    self.dose_level = nil
    if dose > 0 then
        if measured then
            self:push_log(("%s crackles: +%d rads (%d)."):format(
                self:carrying("geiger") and "Geiger" or "Detector",
                math.floor(dose + 0.5), math.floor(p.rads)))
            self:sfx("geiger")
        else
            self:push_log(RAD.feel[math.max(1, level)])   -- a feeling, not a reading
        end
    end
    local stage = self:rad_stage()
    if stage > stage_before then
        local st = RAD.stages[stage]
        if measured then
            self:push_log(st.name .. (st.hurt > 0 and (": -" .. st.hurt .. " HP/h. Anti-Rad!") or ": you feel weak."))
        else
            self:push_log(st.onset)
        end
    elseif stage < stage_before and stage == 0 then
        self:push_log(measured and "The radiation sickness fades." or "You feel more like yourself.")
    end
end

-- Map panel line: the Geiger reading, or just how sick you are.
function Game:rad_text()
    local p = self.player
    local rads = math.floor(p.rads or 0)
    if self:can_measure() then
        return (self:carrying("geiger") and "Geiger " or "Detect ")
            .. RAD.level_name[self:rad_at(p.q, p.r)] .. " Rad " .. rads
    end
    local st = RAD.stages[self:rad_stage()]
    if not st then return nil end
    return self:can_measure() and st.name or st.feel
end

-- A search on a hot hex can turn up an artifact.
function Game:scavenge_field()
    local p = self.player
    if self:rad_at(p.q, p.r) < 2 then return end
    if not self:roll(RAD.artifact_find) then return end
    local item = ARTIFACTS[self:rand(#ARTIFACTS) + 1]
    self:put_stack("ground", nil, {item = item, qty = 1})
    self:stat("artifacts")
    self:push_log("Something glints in the hot ground: " .. ITEM_DB[item].name .. ".")
end
-- -- encounters -----------------------------------------------------------

local ENC_COLS = 55            -- mono 12 is ~7 px/char: 55 chars fit 400 px
-- the intro shares its lines with the 96 px portrait in the top-right corner
local ENC_INTRO_COLS = (400 - 12 - 104) // 7
local ENC_MSG_LINES = 4

-- 0..n-1 from the LCG's high bits
function Game:rand(n)
    self.seed = rand_next(self.seed)
    return self.seed * n // 32768
end

function Game:roll(pct)
    return self:rand(100) < pct
end

function Game:maybe_encounter(terrain_id)
    if self:at_base() and self:wall_up() then return end   -- safe at camp (while the barricade stands)
    if (self.enc_cooldown or 0) > 0 then
        self.enc_cooldown = self.enc_cooldown - 1
        return
    end
    if self:maybe_karl("move") or self:maybe_dog() or self:maybe_horror() then return end
    local chance = FIGHT.ENCOUNTER_CHANCE[terrain_id]
    if chance then chance = chance * self:diff("encounter") end
    if chance and self:is_night() then chance = chance * WORLD.night_encounters end
    if chance and self:weather() == "Storm" then chance = chance * WORLD.storm.encounters end
    if chance and self:roll(chance * self.player.encounter_mult * self:noise_mult()) then
        self:start_encounter(self:pick_encounter())
    end
end

-- A kind by ENCOUNTER_KINDS weight (skipping kinds with no entries), then
-- one of its entries at random.
function Game:pick_encounter()
    local kinds = {}
    for _, k in ipairs(ENCOUNTER_KINDS) do
        if ENCOUNTERS_BY_KIND[k[1]] then kinds[#kinds + 1] = k end
    end
    local kind
    self.seed, kind = weighted_pick(self.seed, kinds)
    local list = ENCOUNTERS_BY_KIND[kind]
    local def = list[self:rand(#list) + 1]
    if def.rare and not self:roll(def.rare) then return list[1] end
    return def
end

function Game:start_encounter(def)
    self.enc = {def = def, hp = def.hp, range = def.start or "far", msg = {},
                intro = wrap(def.intro, ENC_INTRO_COLS), cursor = 1, aim = 0,
                demanding = def.kind == "bandit"}
    if def.kind == "bandit" then self:enc_say(def.demand) end
    self:beast_seen(def)
    if (def.kind == "horror" or def.dark) and not def.phantom then self:dread(CHURN.dread.horror) end
    self:arm_enemy()
    self:maybe_parley()
    if self:placed_here("can_rattle") and self.enc.range ~= "far" then   -- the cans rang
        self.enc.range = "far"
        self:enc_say("The cans you strung up clatter. You're ready for it.")
    end
    if self:weather() == "Fog" then   -- it was on you before you saw it
        self.enc.fog = true
        if self.enc.range == "far" then self.enc.range = "near" end
    end
    self.screen = "encounter"
end

function Game:enc_say(text)
    for _, line in ipairs(wrap(text, ENC_COLS)) do table.insert(self.enc.msg, line) end
    while #self.enc.msg > ENC_MSG_LINES do table.remove(self.enc.msg, 1) end
end

function Game:end_encounter(summary)
    self.enc.over = true
    self.enc_cooldown = FIGHT.ENCOUNTER_COOLDOWN
    local d = self.enc.def
    if (d.kind == "horror" or d.dark) and not d.phantom and self.player.health > 0 then self:stat("horrors") end
    if summary then self:push_log(summary) end
end

-- The weapon in your hands (right first), its name and slot; fists if none.
function Game:weapon()
    for _, slot in ipairs({"rhand", "lhand"}) do
        local item = self.player.equipped[slot]
        if item and ITEM_DB[item].weapon then return ITEM_DB[item].weapon, ITEM_DB[item].name, slot end
    end
    return FISTS, "Fists"
end

function Game:thrown_slot()
    for _, slot in ipairs({"rhand", "lhand"}) do
        local item = self.player.equipped[slot]
        if item and ITEM_DB[item].weapon and ITEM_DB[item].weapon.thrown then return slot end
    end
end

-- First food/drink in the bag, for paying off bandits.
function Game:food_index()
    for i, stack in ipairs(self.player.inventory) do
        if ITEM_DB[stack.item].consumable then return i end
    end
end

function Game:enemy_condition()
    local f = self.enc.hp / self.enc.def.hp
    if f > 0.75 then return "unhurt" elseif f > 0.4 then return "hurt" end
    return "badly hurt"
end

-- What you can do now, as {label, action}.
function Game:encounter_options()
    local e = self.enc
    if e.over then return {{"Continue", "leave"}} end
    local kind = e.def.kind
    if kind == "helper" then return {{"Talk", "talk"}, {"Walk on", "leave_quietly"}} end
    if kind == "anomaly" then return {{"Investigate", "investigate"}, {"Walk away", "leave_quietly"}} end
    if kind == "horror" then return self:sign_options(self:horror_options(e), e) end
    if kind == "little" then return self:little_options() end
    if kind == "institute" then return self:institute_options() end
    if kind == "dog" then
        local o = {}
        if self:dog_food() then o[1] = {"Offer it food", "tame"} end
        o[#o + 1] = {"Leave it", "leave_quietly"}
        return o
    end
    if kind == "riddle" then
        local o = {}
        for i, answer in ipairs(e.riddle.answers) do
            local wink = self.karl_hint or self:rep_of("karl") >= QUESTS.rep.karl_wink
            local hint = wink and i == e.riddle.right and "  (Karl winks)" or ""
            o[i] = {answer .. hint, "answer_" .. i}
        end
        o[#o + 1] = {"Walk away", "leave_quietly"}
        return o
    end
    if e.demanding then
        local o = {}
        if self:food_index() then o[#o + 1] = {"Give them some food", "give"} end
        if self:shooter() and not e.bluffed then o[#o + 1] = {"Show them your gun", "bluff"} end
        local pa = e.parley
        if pa and self:count_item(pa.want) > 0 then
            o[#o + 1] = {("Swap your %s for their %s"):format(ITEM_DB[pa.want].name:lower(),
                                                            ITEM_DB[pa.give].name:lower()), "swap"}
        end
        o[#o + 1] = {"Refuse", "refuse"}
        o[#o + 1] = {"Run for it", "flee"}
        return o
    end
    local o = {}
    local w, wname = self:weapon()
    if e.range == "far" then
        o[#o + 1] = {"Approach", "approach"}
    elseif e.range == "near" then
        if w.reach == "near" then o[#o + 1] = {"Attack (" .. wname .. ")", "attack"} end
        o[#o + 1] = {"Close in", "approach"}
    else
        o[#o + 1] = {"Attack (" .. wname .. ")", "attack"}
    end
    local ts = self:thrown_slot()
    if ts and e.range ~= "close" then
        o[#o + 1] = {"Throw the " .. ITEM_DB[self.player.equipped[ts]].name:lower(), "throw"}
    end
    if e.range ~= "far" then o[#o + 1] = {"Back off", "back"} end
    if not e.seen then o[#o + 1] = {"Watch it", "watch"} end
    if e.range == "far" or (e.fog and e.range == "near") then o[#o + 1] = {"Hide", "hide"} end
    if kind == "mutant" and not e.talked then o[#o + 1] = {"Talk", "talk"} end
    o[#o + 1] = {"Flee", "flee"}
    return self:ranged_options(o, e)
end

function Game:enemy_dies()
    local e = self.enc
    e.outcome = "dead"            -- the portrait shows it
    local found = {}
    for _ = 1, e.def.loot_rolls or 1 do
        local item
        self.seed, item = weighted_pick(self.seed, e.def.loot)
        if item ~= "nothing" then found[#found + 1] = self:drop_found(item) end
    end
    self:drop_enemy_gun(found)
    self:beast_killed(e.def)
    if e.def.legacy then self:legacy_dies() end
    self:sfx("kill")
    self:skill_xp("fight", SKILLS.xp.kill)
    self:stat("kills")
    self:quest_kill()
    self:enc_say("The " .. e.def.who .. " goes still.")
    if #found > 0 then self:enc_say("Left behind: " .. table.concat(found, ", ") .. ".") end
    self:end_encounter("You killed the " .. e.def.who .. ".")
end

-- The other side's turn: bleed, flee when beaten, close in, or strike.
function Game:enemy_turn()
    local e, p, d = self.enc, self.player, self.enc.def
    if e.over or self.screen ~= "encounter" then return end
    if e.bleeding then
        e.hp = e.hp - FIGHT.ENEMY_BLEED_DMG
        if e.hp <= 0 then return self:enemy_dies() end
    end
    if d.flees_at and e.hp <= d.flees_at and self:roll(FIGHT.ENEMY_FLEE_CHANCE) then
        self:enc_say("The " .. d.who .. " breaks away and flees.")
        e.outcome = "fled"
        return self:end_encounter("The " .. d.who .. " fled.")
    end
    if self:little_turn() or self:dog_turn() or self:dark_flees() then return end
    if self:enemy_shoots() then return end
    if e.range ~= "close" then
        if self:roll(FIGHT.ADVANCE_CHANCE + 10 * (d.speed - p.attrs.Speed)) then
            e.range = CLOSER[e.range]
            self:enc_say("The " .. d.who .. " closes in.")
        else
            self:enc_say("The " .. d.who .. " circles, watching you.")
        end
        return
    end
    if not self:roll(d.hit - FIGHT.ENEMY_DODGE * (p.attrs.Speed - 3)) then
        self:enc_say("The " .. d.who .. " lunges and misses.")
        return
    end
    self:enemy_hits(d.dmg, d.bleed, "The " .. d.who .. " hits you")
end

-- Damage from {lo, hi} (unless the dog takes it): a bleed % and a wound
-- when it's deep, and maybe death.
function Game:enemy_hits(range, bleed, how)
    local p, d = self.player, self.enc.def
    local dmg = range[1] + self:rand(range[2] - range[1] + 1)
    if self:dog_guard(dmg) then return end
    p.health = clamp(p.health - dmg)
    self:wear_hit()
    self:sfx("hurt")
    local text = how .. " (-" .. dmg .. " HP)."
    if bleed and bleed > 0 and not p.injuries.bleeding and self:roll(bleed) then
        p.injuries.bleeding = true
        text = text .. " You're bleeding."
    end
    if dmg >= FIGHT.WOUND_DAMAGE and p.injuries.wounded_hours == 0 then
        p.injuries.wounded_hours = WOUND_REST_HOURS
        text = text .. " It leaves a deep wound."
    end
    self:enc_say(text)
    self:check_death("Killed by the " .. d.who .. ".")   -- "who", not "name": "The Fused"
end

function Game:enc_hit(dmg, bleed, how)
    local e = self.enc
    e.hp = e.hp - dmg
    if e.hp > 0 then self:sfx("hit") end
    local text = how .. " (-" .. dmg .. ")."
    if bleed and self:roll(bleed) and not e.bleeding then
        e.bleeding = true
        text = text .. " It's bleeding."
    end
    self:enc_say(text)
    if e.hp <= 0 then self:enemy_dies() end
end

function Game:helper_talk()
    local p, d = self.player, self.enc.def
    if d.help == "medic" then
        p.injuries.bleeding = false
        p.injuries.wounded_hours = p.injuries.wounded_hours // 2
        p.health = clamp(p.health + 25)
        self:put_stack("ground", nil, {item = "cloth_scrap", qty = 2})
        self:enc_say("She cleans and binds your hurts without a word, and leaves you "
            .. "two clean strips of cloth. (+25 HP)")
        self:end_encounter("The medic patched you up.")
    else
        for key in pairs(self.tiles) do
            local q, r = Game.key_qr(key)
            if axial_distance(p.q, p.r, q, r) <= 3 then p.explored[key] = true end
        end
        self:put_stack("ground", nil, {item = "water_bottle", qty = 1})
        self:enc_say("He draws the land around you in the dirt and hands you a bottle of "
            .. "clean water. 'Stay off the roads at night.'")
        self:end_encounter("The wanderer shared water and directions.")
        if not self:hear_of_exit("The wanderer") and self:learn_site("trader") then
            self:push_log("The wanderer: a trader in the town, " .. self:site_bearing("trader") .. ".")
        end
    end
end

function Game:encounter_action(action)
    local e, p = self.enc, self.player
    e.msg = {}
    if e.def.phantom then return self:phantom_gone() end   -- (it was never there: 64_dread)
    if action == "tame" then return self:dog_tame() end
    if action:find("_little$") then return self:little_action(action) end
    if action:find("_institute$") then return self:institute_action(action) end
    if action == "elder" then return self:raise_sign() end
    if action == "look_away" or action == "speak" or action == "cover" or action == "follow" then
        return self:horror_action(action)
    end
    local answer = action:match("^answer_(%d)$")
    if answer then return self:karl_answer(tonumber(answer)) end
    if action == "investigate" then
        return self:start_puzzle()
    elseif action == "leave" or action == "leave_quietly" then
        if action == "leave_quietly" then
            self.enc_cooldown = FIGHT.ENCOUNTER_COOLDOWN
            self:push_log("You nod and walk on.")
        end
        self.enc = nil
        self.screen = "map"
        return
    elseif action == "talk" then
        if e.def.kind == "helper" then return self:helper_talk() end
        e.talked = true
        self:enc_say(e.def.talk)
    elseif action == "give" then
        local i = self:food_index()
        local stack = p.inventory[i]
        local name = ITEM_DB[stack.item].name
        stack.qty = stack.qty - 1
        if stack.qty <= 0 then table.remove(p.inventory, i) end
        self:enc_say("They take the " .. name:lower() .. " and back off into the ruins.")
        return self:end_encounter("You paid the " .. e.def.who .. " off.")
    elseif action == "swap" then
        return self:parley_swap()
    elseif action == "bluff" then
        if self:bluff() then return end
    elseif action == "refuse" then
        e.demanding = false
        self:enc_say("'Wrong answer.'")
    elseif action == "approach" then
        e.range = CLOSER[e.range]
        self:enc_say("You move in. Range: " .. RANGE_NAME[e.range] .. ".")
    elseif action == "back" then
        e.range = FARTHER[e.range]
        self:enc_say("You back away. Range: " .. RANGE_NAME[e.range] .. ".")
    elseif action == "shoot" then
        self:shoot()
    elseif action == "attack" then
        local w, wname = self:weapon()
        local hit = FIGHT.PLAYER_HIT + 8 * (p.attrs.Speed - 3) + e.aim + self:skill_bonus("fight")
            + self:beast_bonus()
        e.aim = 0
        if self:roll(hit) then
            self:skill_xp("fight", SKILLS.xp.hit)
            local dmg = math.max(1, w.dmg - self:rand(w.dmg // 4 + 1) + 2 * (p.attrs.Strength - 3))
            dmg = self:dark_damage(dmg)
            self:enc_hit(dmg, w.bleed, "You hit the " .. e.def.who .. " (" .. wname:lower() .. ")")
        else
            self:sfx("miss")
            self:enc_say("You swing at the " .. e.def.who .. " and miss.")
        end
    elseif action == "throw" then
        local slot = self:thrown_slot()
        local item = p.equipped[slot]
        local w = ITEM_DB[item].weapon
        p.equipped[slot] = nil
        recompute_stats(p)
        self:put_stack("ground", nil, {item = item, qty = 1})
        if self:roll(FIGHT.THROW_HIT + 8 * (p.attrs.Perception - 3) + e.aim + self:skill_bonus("fight")
                     + self:beast_bonus()) then
            self:skill_xp("fight", SKILLS.xp.hit)
            self:enc_hit(w.dmg, w.bleed, "Your " .. ITEM_DB[item].name:lower() .. " strikes the " .. e.def.who)
        else
            self:enc_say("Your " .. ITEM_DB[item].name:lower() .. " sails wide.")
        end
        e.aim = 0
    elseif action == "watch" then
        if self:roll(FIGHT.WATCH_CHANCE + 10 * (p.attrs.Perception - 3)) then
            e.seen = true
            e.aim = FIGHT.WATCH_AIM
            self:beast_watched(e.def)
            self:enc_say("You study how it moves. It looks " .. self:enemy_condition()
                .. ", and you see an opening.")
        else
            self:enc_say("You can't make out much.")
        end
    elseif action == "hide" then
        local chance = FIGHT.HIDE_CHANCE + 10 * (p.attrs.Perception - 3) + self:dog_bonus()
            + (e.fog and WORLD.fog_hide or 0)
        if e.def.kind == "animal" then chance = chance - 10 end
        if self:roll(chance) then
            self:enc_say("You drop into cover and keep very still. It passes you by.")
            return self:end_encounter("You hid from the " .. e.def.who .. ".")
        end
        self:enc_say("It has seen where you went.")
    elseif action == "flee" then
        if self:roll(FIGHT.FLEE_CHANCE[e.range] + 10 * (p.attrs.Speed - e.def.speed) + self:dog_bonus()
                     + self:little_flee_bonus()) then
            p.mp = p.mp - 1
            self:enc_say("You run until your lungs burn. It doesn't follow. (-1 MP)")
            return self:end_encounter("You ran from the " .. e.def.who .. ".")
        end
        self:enc_say("You try to run, but it cuts you off.")
    end
    if not e.over then self:enemy_turn() end
end

function Game:encounter_key(key)
    local opts = self:encounter_options()
    local e = self.enc
    local pick
    if key >= 49 and key < 49 + #opts then          -- '1'..
        pick = key - 48
    elseif key == gfx.KEY_UP or key == KEY.W then
        e.cursor = math.max(1, e.cursor - 1)
    elseif key == gfx.KEY_DOWN or key == KEY.S then
        e.cursor = math.min(#opts, e.cursor + 1)
    elseif key == KEY.ENTER or key == KEY.LF or key == KEY.SPACE then
        pick = e.cursor
    end
    if pick and opts[pick] then
        e.cursor = 1
        self:encounter_action(opts[pick][2])
    end
end

-- ---------------------------------------------------------------------
-- Anomaly puzzles (bolt field, sequence, runes): started by an anomaly
-- encounter's Probe, keys routed here by encounter_key. Numbers in
-- 07_data_encounters (ANOMALIES, BOLT_*, SEQ_LENGTHS, RUNE_*).
-- ---------------------------------------------------------------------

local function bolt_neighbors(c)
    local out, row, col = {}, (c - 1) // BOLT_N, (c - 1) % BOLT_N
    if row > 0 then out[#out + 1] = c - BOLT_N end
    if row < BOLT_N - 1 then out[#out + 1] = c + BOLT_N end
    if col > 0 then out[#out + 1] = c - 1 end
    if col < BOLT_N - 1 then out[#out + 1] = c + 1 end
    return out
end

-- the cell one step from c in a direction (nil off the grid)
local function bolt_step(c, dir)
    local row, col = (c - 1) // BOLT_N, (c - 1) % BOLT_N
    if dir == "up" and row > 0 then return c - BOLT_N end
    if dir == "down" and row < BOLT_N - 1 then return c + BOLT_N end
    if dir == "left" and col > 0 then return c - 1 end
    if dir == "right" and col < BOLT_N - 1 then return c + 1 end
end

local function bolt_path_exists(haz)
    local seen, queue, head = {[BOLT_START] = true}, {BOLT_START}, 1
    while queue[head] do
        local c = queue[head]
        head = head + 1
        if c == BOLT_GOAL then return true end
        for _, n in ipairs(bolt_neighbors(c)) do
            if not haz[n] and not seen[n] then
                seen[n] = true
                queue[#queue + 1] = n
            end
        end
    end
    return false
end

local function bolt_count(haz, c)
    local n = 0
    for _, nb in ipairs(bolt_neighbors(c)) do if haz[nb] then n = n + 1 end end
    return n
end

function Game:start_puzzle()
    local per = self.player.attrs.Perception
    local kind = ({"bolts", "sequence", "runes"})[self:rand(3) + 1]
    local z = {kind = kind, msg = ""}
    if kind == "bolts" then
        repeat
            z.haz = {}
            local placed = 0
            while placed < BOLT_HAZARDS do
                local c = self:rand(BOLT_N * BOLT_N) + 1
                if c ~= BOLT_START and c ~= BOLT_GOAL and not z.haz[c] then
                    z.haz[c] = true
                    placed = placed + 1
                end
            end
        until bolt_path_exists(z.haz)
        z.pos, z.visited, z.revealed = BOLT_START, {[BOLT_START] = true}, {}
        z.bolts = math.max(1, BOLTS + per - 3) + (self:carrying("bolts") and RAD.bolts_bonus or 0)
    elseif kind == "sequence" then
        z.round = 1
        self:new_sequence(z)
    else
        z.target = {}
        for i = 1, RUNE_N do z.target[i] = self:rand(4) end
        repeat
            z.cur, z.scramble = {}, {}
            for i = 1, RUNE_N do z.cur[i] = z.target[i] end
            for k = 1, RUNE_SCRAMBLE do
                local i = self:rand(RUNE_N) + 1
                z.scramble[k] = i
                -- a press turns rune i and its neighbours forward; scramble backward
                for j = math.max(1, i - 1), math.min(RUNE_N, i + 1) do z.cur[j] = (z.cur[j] + 3) % 4 end
            end
            local same = true
            for i = 1, RUNE_N do if z.cur[i] ~= z.target[i] then same = false end end
        until not same
        z.moves = math.max(RUNE_SCRAMBLE, RUNE_MOVES + per - 3)
    end
    self.puz = z
    self.screen = "puzzle"
end

function Game:new_sequence(z)
    z.seq, z.typed, z.showing = {}, 0, true
    for i = 1, SEQ_LENGTHS[z.round] do z.seq[i] = self:rand(4) + 1 end
end

-- Leave the anomaly: success may leave an artifact, failure hurts.
function Game:finish_puzzle(result)
    local p, who = self.player, self.enc.def.who
    self.enc, self.puz = nil, nil
    self.enc_cooldown = FIGHT.ENCOUNTER_COOLDOWN
    self.screen = "map"
    if result == "backed_off" then
        self:push_log("You back away from the " .. who .. ".")
    elseif result == "solved" then
        if self:roll(ARTIFACT_CHANCE + 5 * (p.attrs.Perception - 3)) then
            local id = ARTIFACTS[self:rand(#ARTIFACTS) + 1]
            self:put_stack("ground", nil, {item = id, qty = 1})
            self:stat("artifacts")
            self:push_log("The " .. who .. " fades. It left something:")
            self:push_log(ITEM_DB[id].name .. ". (I to pick it up)")
        else
            self:push_log("The " .. who .. " fades. Nothing remains.")
        end
    else
        local r = self:rand(3)
        if r == 0 then
            local dmg = 10 + self:rand(16)
            p.health = clamp(p.health - dmg)
            self:push_log("The " .. who .. " tears at you. (-" .. dmg .. " HP)")
        elseif r == 1 then
            p.injuries.bleeding = true
            self:push_log("Your nose and ears begin to bleed.")
        else
            local hours = 4 + self:rand(5)
            p.hours = p.hours + hours
            apply_awake_hours(p, hours)
            self:push_log("You come to. The sun has moved. (" .. hours .. "h lost)")
        end
        self:check_death("Taken by the " .. who .. ".")
    end
end

function Game:puzzle_key(key)
    local z = self.puz
    if key == gfx.KEY_ESCAPE or key == KEY.Q then return self:finish_puzzle("backed_off") end
    local dir = (key == gfx.KEY_UP or key == KEY.W) and "up"
        or (key == gfx.KEY_DOWN or key == KEY.S) and "down"
        or (key == gfx.KEY_LEFT or key == KEY.A) and "left"
        or (key == gfx.KEY_RIGHT or key == KEY.D) and "right"
    if z.kind == "bolts" then
        if key == KEY.T then
            z.aiming = z.bolts > 0 and not z.aiming
            z.msg = z.aiming and "Throw which way?" or (z.bolts > 0 and "" or "No bolts left.")
            return
        end
        if not dir then return end
        local c = bolt_step(z.pos, dir)
        if not c then return end
        if z.aiming then
            z.aiming = false
            z.bolts = z.bolts - 1
            z.revealed[c] = true
            z.msg = z.haz[c] and "The bolt is snatched from the air and crushed."
                or "The bolt lands and lies still."
            return
        end
        if z.haz[c] then return self:finish_puzzle("failed") end
        z.pos, z.visited[c], z.msg = c, true, ""
        if c == BOLT_GOAL then return self:finish_puzzle("solved") end
    elseif z.kind == "sequence" then
        if z.showing then
            z.showing = false
            return
        end
        if key < 49 or key > 52 then return end
        if key - 48 ~= z.seq[z.typed + 1] then return self:finish_puzzle("failed") end
        z.typed = z.typed + 1
        if z.typed == #z.seq then
            z.round = z.round + 1
            if z.round > #SEQ_LENGTHS then return self:finish_puzzle("solved") end
            self:new_sequence(z)
        end
    else
        if key < 49 or key >= 49 + RUNE_N then return end
        local i = key - 48
        for j = math.max(1, i - 1), math.min(RUNE_N, i + 1) do z.cur[j] = (z.cur[j] + 1) % 4 end
        z.moves = z.moves - 1
        local done = true
        for k = 1, RUNE_N do if z.cur[k] ~= z.target[k] then done = false end end
        if done then return self:finish_puzzle("solved") end
        if z.moves <= 0 then return self:finish_puzzle("failed") end
    end
end
-- ---------------------------------------------------------------------
-- Emissions and stashes
--
-- An emission (blowout) comes every few days (RAD.emission). Game:tick calls
-- emission_hour for every hour: a warning `warn` hours ahead, then `hours`
-- of it - off shelter terrain (ruins) it costs HP and adds rads. After it,
-- field centers without an artifact grow a new one. next_emission is saved.
--
-- Stashes: some scrawled notes mark a hidden pile of supplies a few hexes
-- away (mark_stash). It's drawn on the map until you step on it.
-- ---------------------------------------------------------------------

function Game:emission_hour(hour)
    local E, p = RAD.emission, self.player
    local start = self.next_emission
    if not start then return end
    self.emission_news = self.emission_news or {}
    if hour == start - E.warn then self.emission_news.warn = true end
    if hour >= start and hour < start + E.hours then
        if E.shelter[self.tiles[hex_key(p.q, p.r)]] or self:placed_here("tarp_shelter") then
            self.emission_news.sheltered = true
        else
            local harm = self:diff("emission")
            p.health = clamp(p.health - E.hurt / E.hours * harm)
            p.rads = math.min(RAD.max, (p.rads or 0) + E.rads / E.hours * self:rad_armor() * harm)
            self.emission_news.caught = true
        end
        if hour == start + E.hours - 1 then self:emission_ends() end
    end
end

function Game:emission_ends()
    local E = RAD.emission
    for key, level in pairs(self.rad or {}) do
        if level == 3 then
            local pile = self.ground[key] or {}
            local has = false
            for _, s in ipairs(pile) do has = has or ITEM_DB[s.item].artifact ~= nil end
            if not has then
                self.ground[key] = pile
                table.insert(pile, {item = ARTIFACTS[self:rand(#ARTIFACTS) + 1], qty = 1})
            end
        end
    end
    self.next_emission = self.next_emission + E.every[1] + self:rand(E.every[2] - E.every[1] + 1)
    self.emission_news = self.emission_news or {}
    self.emission_news.ended = true
end

function Game:emission_log()
    local n = self.emission_news
    self.emission_caught = n and n.caught
    if not n then return end
    if n.warn then self:sfx("siren"); self:queue_scene("first_emission") end
    if n.caught then self:sfx("emission"); self:dread(CHURN.dread.emission)
    elseif n.sheltered then self:sfx("emission_cover"); self:dread(CHURN.dread.sheltered) end
    if n.ended then self:sfx("emission_end") end
    if n.warn then
        self:push_log(("The sky bruises purple. Emission in %dh! Ruins/hills!"):format(RAD.emission.warn))
    end
    if n.caught then
        self:push_log("The EMISSION tears through you! Find cover!")
    elseif n.sheltered then
        self:push_log("The emission howls overhead. You hold on in cover.")
    end
    if n.ended then self:push_log("The emission passes. The fields glitter.") end
    self.emission_news = nil
end

-- Panel text while one is coming or raging.
function Game:emission_text()
    local start, now = self.next_emission, self.player.hours
    if not start then return nil end
    if now >= start and now < start + RAD.emission.hours then return "EMISSION!" end
    if start - now <= RAD.emission.warn and start > now then return "EMIT " .. (start - now) .. "h" end
end

-- A scrawled note marks a stash a few hexes away. Returns false if there's
-- nowhere to put one.
function Game:mark_stash()
    local p, S = self.player, RAD.stash
    local taken = {}
    for _, key in pairs(self.sites) do taken[key] = true end
    local spots = {}
    for key, t in pairs(self.tiles) do
        local q, r = Game.key_qr(key)
        local d = axial_distance(p.q, p.r, q, r)
        if TERRAIN[t].passable and d >= S.near and d <= S.far and not self.stashes[key]
            and not taken[key] then
            spots[#spots + 1] = key
        end
    end
    if #spots == 0 then return false end
    table.sort(spots)
    local key = spots[self:rand(#spots) + 1]
    self.ground[key] = self.ground[key] or {}
    for _ = 1, S.items do
        add_to_list(self.ground[key], {item = S.loot[self:rand(#S.loot) + 1], qty = 1})
    end
    self.stashes[key] = true
    p.explored[key] = true
    self:push_log("The notes mark a stash: " .. self:bearing_to(key) .. ".")
    return true
end

-- Stepping onto a stash you were told about.
function Game:find_stash()
    local key = hex_key(self.player.q, self.player.r)
    if self.stashes[key] then
        self.stashes[key] = nil
        self:push_log("You dig up the stash. (I to look)")
        self:sfx("chime")
    end
end
-- ---------------------------------------------------------------------
-- Hunting, fishing and snares (numbers in HUNT, 05_data_world)
--
-- G on the map: by open water (or on a ford) with a Fishing Rod you fish;
-- anywhere else you track game, and finding it starts an animal encounter
-- in which you've already studied it. E on a Snare sets it on your hex
-- (self.snares, saved); stepping back onto it collects whatever it caught
-- since, worked out then from the hours that passed.
-- ---------------------------------------------------------------------

function Game:gather()
    local p = self.player
    if p.mp <= 0 then
        self:push_log("Too tired. Rest first.")
        return
    end
    if self:near_water() and self:count_item("fishing_rod") > 0 then
        -- the minigame (63_fishing); quick_fish: one roll instead (the balance bot)
        if self.quick_fish then return self:fish() end
        return self:fish_start()
    end
    local terrain = self.tiles[hex_key(p.q, p.r)]
    if not HUNT.snare_chance[terrain] then
        self:push_log(self:near_water() and "No rod to fish with. (C to make one)" or "No game here.")
        return
    end
    self:hunt()
end

-- Time passes as for a search: MP, hours, needs.
function Game:spend_hours(n)
    local p = self.player
    p.mp = p.mp - 1
    p.hours = p.hours + n
    apply_awake_hours(p, n)
end

function Game:fish()
    local p = self.player
    self:spend_hours(HUNT.fish_hours)
    if self:roll(HUNT.fish_chance + 5 * (p.attrs.Perception - 3) + self:fish_bonus()
                 + self:skill_bonus("fish")) then
        self:skill_xp("fish", SKILLS.xp.catch)
        self:stat("fish")
        local fish = {item = "raw_fish", qty = 1}
        if not self:put_stack("inventory", nil, fish) then self:put_stack("ground", nil, fish) end
        self:push_log("A pale fish, too many eyes. Got it.")
        self:sfx("chime")
    else
        self:push_log(("Fished %dh. Nothing bites."):format(HUNT.fish_hours))
    end
    self:maybe_karl("fish")
end

function Game:hunt()
    local p = self.player
    self:spend_hours(HUNT.hunt_hours)
    if not self:roll(HUNT.hunt_chance + 10 * (p.attrs.Perception - 3) + self:skill_bonus("fish")) then
        self:push_log(("Tracked %dh. Nothing but old prints."):format(HUNT.hunt_hours))
        return
    end
    self:skill_xp("fish", SKILLS.xp.hunt)   -- (only for finding it: no grinding on empty hexes)
    local animals = ENCOUNTERS_BY_KIND.animal
    self:start_encounter(animals[self:rand(#animals) + 1])
    -- you found it first: it hasn't seen you, and you've watched how it moves
    self.enc.seen, self.enc.aim = true, FIGHT.WATCH_AIM
    self:enc_say("You found its trail and crept up downwind. It hasn't seen you yet.")
end

-- E on a Snare. Returns true if it was set (the caller uses one up).
function Game:set_snare()
    local p = self.player
    local key = hex_key(p.q, p.r)
    if not HUNT.snare_chance[self.tiles[key]] then
        self:push_log("Nothing would walk into a snare here.")
        return false
    end
    if self.snares[key] then
        self:push_log("There's already a snare here.")
        return false
    end
    self.snares[key] = {set = p.hours}
    self:push_log("Snare set. Come back later.")
    return true
end

-- Stepping onto a hex with your snare.
function Game:check_snare()
    local p = self.player
    local key = hex_key(p.q, p.r)
    local snare = self.snares[key]
    if not snare then return end
    local hours = p.hours - snare.set
    local per_hour = (HUNT.snare_chance[self.tiles[key]] or 0) / 100
    local pct = math.floor(100 * (1 - (1 - per_hour) ^ hours))
    if hours > 0 and self:roll(pct) then
        self:put_stack("ground", nil, {item = HUNT.snare_catch[1], qty = HUNT.snare_catch[2]})
        snare.set = p.hours
        self:push_log("Your snare caught a two-headed hare. (I to take it)")
        self:sfx("chime")
    else
        snare.set = p.hours   -- the hours you just checked can't catch again
        self:push_log("Your snare is empty.")
    end
end
-- ---------------------------------------------------------------------
-- Karl (K-A-R-L), the riddling fisherman. Numbers and riddles in KARL.
--
-- Rare, and only by water: maybe_karl runs on moves (from maybe_encounter)
-- and after fishing. He asks a riddle he hasn't asked yet (karl_asked);
-- a right answer gets one of KARL.rewards, worn/lure gear only once
-- (karl_gave). Either way he's gone for KARL.cooldown hours (karl_next).
-- His portrait is the user's own picture (art/karl.png).
-- ---------------------------------------------------------------------

function Game:maybe_karl(how)
    local p = self.player
    if not self:near_water() or p.hours < (self.karl_next or 0) then return false end
    if not self:roll(how == "fish" and KARL.fish_chance or KARL.chance) then return false end
    self:start_karl()
    return true
end

function Game:start_karl()
    self.karl_next = self.player.hours + KARL.cooldown
    self.karl_asked = self.karl_asked or {}
    local fresh = {}
    for i in ipairs(KARL.riddles) do
        if not self.karl_asked[i] then fresh[#fresh + 1] = i end
    end
    if #fresh == 0 then   -- he's asked them all: start over
        self.karl_asked = {}
        for i in ipairs(KARL.riddles) do fresh[#fresh + 1] = i end
    end
    local i = fresh[self:rand(#fresh) + 1]
    self.karl_asked[i] = true
    local riddle = KARL.riddles[i]
    -- shuffle the answers; remember where the right one (listed first) went
    local order = {1, 2, 3}
    for j = #order, 2, -1 do
        local k = self:rand(j) + 1
        order[j], order[k] = order[k], order[j]
    end
    local answers, right = {}, nil
    for slot, idx in ipairs(order) do
        answers[slot] = riddle.a[idx]
        if idx == 1 then right = slot end
    end
    self:start_encounter({kind = "riddle", name = "Karl", art = "karl", who = "Karl",
                          intro = KARL.intro, start = "near"})
    self.enc.riddle = {answers = answers, right = right}
    self:enc_say("Karl: '" .. riddle.q .. "'")
end

-- A reward Karl hasn't already given (gear only once; Pilk and rods repeat).
function Game:karl_reward()
    self.karl_gave = self.karl_gave or {}
    local pool = {}
    for _, item in ipairs(KARL.rewards) do
        local once = ITEM_DB[item].slot or ITEM_DB[item].fish_bonus
        if not (once and self.karl_gave[item]) then pool[#pool + 1] = item end
    end
    if #pool == 0 then pool = {"pilk"} end
    local item = pool[self:rand(#pool) + 1]
    self.karl_gave[item] = true
    return item
end

function Game:karl_answer(n)
    self.karl_hint = nil   -- a radio hint is good for one riddle
    local e = self.enc
    if n == e.riddle.right then
        self:stat("riddles")
        local item = self:karl_reward()
        local stack = {item = item, qty = 1}
        if not self:put_stack("inventory", nil, stack) then self:put_stack("ground", nil, stack) end
        local name = ITEM_DB[item].name
        self:enc_say("'Ha! Sharp one.' Karl hands you " .. (item == "pilk" and "a bottle of Pilk. "
            .. "'Pepsi and milk. Trust me.'" or "his " .. name .. "."))
        self:sfx("gift")
        self:story_karl()
        self:end_encounter("Karl gave you " .. name .. ".")
        self:karl_work()
    else
        self:enc_say("Karl laughs. 'Wrong. The river keeps its secrets.' He wades off downstream.")
        self:end_encounter("Karl waded off, laughing.")
    end
end

-- Fishing bonus % from Karl's gear: worn items, and a carried lure.
function Game:fish_bonus()
    local p, bonus = self.player, 0
    for slot, item in pairs(p.equipped) do
        if not HOLD_SLOTS[slot] then bonus = bonus + (ITEM_DB[item].fish_bonus or 0) end
    end
    if self:carrying("lucky_lure") then bonus = bonus + ITEM_DB.lucky_lure.fish_bonus end
    return bonus
end
-- ---------------------------------------------------------------------
-- Traders and the way out
--
-- self.sites (from generate_world): trader = the town's center hex,
-- checkpoint = an edge hex far from it. You learn where they are from the
-- trader (who tells you about the Checkpoint), the wanderer, scrawled notes
-- or by walking there (sites_known, saved); the panel then points the way.
-- T on the trader's hex opens barter (self.trader, saved); T at the
-- Checkpoint opens the gate: a Churn Permit or GOAL.bribe artifacts get you
-- out of the Churn, which ends the run.
-- ---------------------------------------------------------------------

function Game:site_here()
    local here = hex_key(self.player.q, self.player.r)
    for name, key in pairs(self.sites) do
        if key == here then return name end
    end
end

-- Returns true the first time.
function Game:learn_site(name)
    if self.sites_known[name] then return false end
    self.sites_known[name] = true
    self.player.explored[self.sites[name]] = true
    return true
end

-- "NE 9": compass direction (up = north) and hexes from you to a site.
function Game:site_bearing(name)
    return self:bearing_to(self.sites[name])
end

function Game:bearing_to(key)
    local p = self.player
    local q, r = Game.key_qr(key)
    local d = axial_distance(p.q, p.r, q, r)
    if d == 0 then return "here" end
    local x0, y0 = axial_to_pixel(p.q, p.r, 1)
    local x1, y1 = axial_to_pixel(q, r, 1)
    local octant = math.floor(math.atan(y0 - y1, x1 - x0) / (math.pi / 4) + 0.5) % 8
    return ({"E", "NE", "N", "NW", "W", "SW", "S", "SE"})[octant + 1] .. " " .. d
end

-- Map panel line: where to go next.
function Game:goal_text()
    if self.sites_known.checkpoint then return "Exit " .. self:site_bearing("checkpoint") end
    if self.sites_known.trader then return "Trader " .. self:site_bearing("trader") end
end

-- Someone (or something) tells you where the way out is.
function Game:hear_of_exit(who)
    if self:learn_site("checkpoint") then
        self:push_log(who .. ": a checkpoint out of the Churn, " .. self:site_bearing("checkpoint") .. ".")
        return true
    end
    return false
end

-- A site you can see is a site you know (called from Game:tick).
function Game:spot_sites()
    if self:learn_site_seen("trader") then
        self:push_log("A trader's stall in the ruins, " .. self:site_bearing("trader") .. ".")
    end
    if self:learn_site_seen("checkpoint") then
        self:push_log("A guard tower on the horizon: the Checkpoint.")
    end
    if self.sites.quarry and self:learn_site_seen("quarry") then
        self:push_log("A gate in the wall of the old quarry, " .. self:site_bearing("quarry") .. ".")
    end
    if self.sites.ferry and self:learn_site_seen("ferry") then
        self:push_log("A jetty and a few huts by the water: the Ferry Post, " .. self:site_bearing("ferry") .. ".")
    end
    self:spot_peddler()
    self:spot_little()
end

function Game:learn_site_seen(name)
    return self.player.visible[self.sites[name]] and self:learn_site(name)
end

-- After a move: sites are safe (no encounters) and announce themselves.
function Game:arrive_site()
    local site = self:site_here()
    if site == "trader" then
        self:learn_site("trader")
        self:push_log("A trader's stall behind a barricade. T to trade.")
        self:hear_of_exit("Trader")
        return true
    elseif site == "checkpoint" then
        self:learn_site("checkpoint")
        self:push_log("The Checkpoint. Guards watch from the tower. T.")
        return true
    elseif site == "quarry" then
        return self:quarry_arrive()
    elseif site == "ferry" then
        self:learn_site("ferry")
        self:push_log("The Ferry Post. Mother Okun trades from the jetty. T.")
        self:hear_of_exit("Mother Okun")
        return true
    end
    return false
end

-- T on the map.
function Game:site_action()
    local site = self:site_here()
    if site == "trader" then
        self:open_trade("town")
    elseif site == "ferry" then
        self:open_trade("ferry")
    elseif site == "quarry" then
        self:open_institute()
    elseif site == "checkpoint" then
        self:open_gate()
    elseif self:peddler_key() == hex_key(self.player.q, self.player.r) then
        self:open_trade("peddler")
    elseif self:little_spot(hex_key(self.player.q, self.player.r)) == "cairn" then
        self:offer_trinket()
    elseif self:at_base() then
        self:open_camp()
    else
        self:push_log("Nobody here. (T trades at a trader)")
    end
end

-- -- barter -------------------------------------------------------------

function Game.item_value(item)
    if ITEM_DB[item] and ITEM_DB[item].trinket then return 0 end   -- toys: no use to grown-ups
    return TRADE.value[item] or 1
end

-- who: "town" (the trader), "ferry" (Mother Okun) or "peddler"
function Game:open_trade(who)
    who = who or "town"
    self:restock(who)
    self.trade_ui = {who = who, col = "mine", cursor = {mine = 1, theirs = 1}, give = {}, get = {},
                     msg = TRADE.people[who].hello or "Pick what you give and take, then T."}
    self.screen = "trade"
end

-- The one you're trading with now: their stock and their markup.
function Game:trade_partner()
    local who = self.trade_ui and self.trade_ui.who or "town"
    return self:trade_state(who), TRADE.people[who]
end

-- The two columns: your bag and the trader's stock.
function Game:trade_rows(col)
    return col == "mine" and self.player.inventory or self:trade_partner().stock
end

-- What you offer, and what the trader asks for what you picked.
-- The stacks of `item` in a list, most worn first (worn clothes are traded
-- away before good ones).
function Game.stacks_of(list, item)
    local out = {}
    for _, s in ipairs(list) do if s.item == item then out[#out + 1] = s end end
    table.sort(out, function(a, b) return (a.cond or 100) < (b.cond or 100) end)
    return out
end

-- What n units of item from a list are worth: worn clothes for less (a
-- torn piece a quarter).
function Game.units_value(list, item, n)
    local total = 0
    for _, s in ipairs(Game.stacks_of(list, item)) do
        local k = math.min(n, s.qty)
        total = total + k * math.floor(Game.item_value(item) * (25 + 0.75 * (s.cond or 100)) / 100)
        n = n - k
        if n <= 0 then break end
    end
    return total
end

function Game:trade_totals()
    local u = self.trade_ui
    local give, get = 0, 0
    for item, n in pairs(u.give) do give = give + Game.units_value(self.player.inventory, item, n) end
    -- (what you take costs at least 1 a unit: trinkets are worthless to sell)
    for item, n in pairs(u.get) do get = get + math.max(1, Game.item_value(item)) * n end
    local _, cfg = self:trade_partner()
    return give, math.ceil(get * self:markup_for(u.who or "town", cfg.markup))
end

-- Take n units of item out of a stack list (across stacks, most worn first).
local function take_units(list, item, n)
    for _, s in ipairs(Game.stacks_of(list, item)) do
        local k = math.min(n, s.qty)
        s.qty, n = s.qty - k, n - k
        if n <= 0 then break end
    end
    for i = #list, 1, -1 do
        if list[i].qty <= 0 then table.remove(list, i) end
    end
end

function Game:make_deal()
    local u, t = self.trade_ui, self:trade_partner()
    local give, ask = self:trade_totals()
    if next(u.get) == nil and next(u.give) == nil then
        u.msg = "Pick what to sell or take (Enter)."
        return false
    end
    if give < ask then   -- rubles in the bag make up the rest
        local spare = 0
        for _, s in ipairs(self.player.inventory) do
            if s.item == "rubles" then spare = spare + s.qty end
        end
        spare = spare - (u.give.rubles or 0)
        if spare < ask - give then
            u.msg = ("Not enough. They want %d, you have %d."):format(ask, give + spare)
            return false
        end
        u.give.rubles = (u.give.rubles or 0) + ask - give
        give = ask
    end
    for item, n in pairs(u.give) do
        take_units(self.player.inventory, item, n)
        add_to_list(t.stock, {item = item, qty = n})
    end
    local dropped = false
    for item, n in pairs(u.get) do
        take_units(t.stock, item, n)
        if not self:put_stack("inventory", nil, {item = item, qty = n}) then
            self:put_stack("ground", nil, {item = item, qty = n})
            dropped = true
        end
    end
    -- what they owe you back, in rubles
    local change = give - ask
    if change > 0 and not self:put_stack("inventory", nil, {item = "rubles", qty = change}) then
        self:put_stack("ground", nil, {item = "rubles", qty = change})
        dropped = true
    end
    u.give, u.get = {}, {}
    u.msg = (change > 0 and ("Deal. " .. change .. " rubles back.") or "Deal.")
        .. (dropped and " Bag full: some is on the ground." or "")
    self:push_log("You traded with " .. (u.who == "town" and "the trader" or TRADE.people[u.who].name) .. ".")
    for col, c in pairs(u.cursor) do
        u.cursor[col] = math.max(1, math.min(c, #self:trade_rows(col)))
    end
    return true
end

function Game:trade_key(key)
    local u = self.trade_ui
    local rows = self:trade_rows(u.col)
    local c = u.cursor[u.col]
    local pick = u.col == "mine" and u.give or u.get
    local row = rows[c]
    if key == KEY.Q or key == gfx.KEY_ESCAPE then
        self.trade_ui = nil
        self.screen = "map"
    elseif key == gfx.KEY_UP or key == KEY.W then
        u.cursor[u.col] = math.max(1, c - 1)
    elseif key == gfx.KEY_DOWN or key == KEY.S then
        u.cursor[u.col] = math.max(1, math.min(#rows, c + 1))
    elseif key == gfx.KEY_LEFT or key == KEY.A then
        u.col = "mine"
    elseif key == gfx.KEY_RIGHT or key == KEY.D then
        u.col = "theirs"
    elseif key == KEY.ENTER or key == KEY.LF or key == KEY.SPACE then
        local have = 0   -- (worn and new pieces of one item are separate rows)
        for _, s in ipairs(row and rows or {}) do if s.item == row.item then have = have + s.qty end end
        -- (money goes ten at a time)
        local step = row and row.item == "rubles" and 10 or 1
        if row and (pick[row.item] or 0) < have then pick[row.item] = math.min(have, (pick[row.item] or 0) + step) end
    elseif key == KEY.E then
        if row and pick[row.item] then
            pick[row.item] = pick[row.item] > 1 and pick[row.item] - 1 or nil
        end
    elseif key == KEY.T then
        self:make_deal()
    elseif key == KEY.N and u.who == "town" then   -- full bestiary pages (64_bestiary)
        u.msg = self:sell_bestiary()
    elseif key == KEY.O then   -- (W is "up" here)
        if u.who == "ferry" then self:ferry_work()
        elseif u.who == "town" then self:trader_work()
        elseif u.who == "peddler" then self:peddler_swap()
        else u.msg = "'Work? I'm a peddler. I peddle.'" end
    end
end

-- -- the Checkpoint and the end ---------------------------------------------

-- Artifacts in your bag and hands.
function Game:artifact_count()
    local p, n = self.player, 0
    for _, s in ipairs(p.inventory) do
        if ITEM_DB[s.item].artifact then n = n + s.qty end
    end
    for _, slot in ipairs({"lhand", "rhand"}) do
        local item = p.equipped[slot]
        if item and ITEM_DB[item].artifact then n = n + 1 end
    end
    return n
end

function Game:open_gate()
    local opts = {}
    if self:count_item("permit") > 0 then opts[#opts + 1] = {"Show the Churn Permit", "permit"} end
    if self:artifact_count() >= GOAL.bribe then
        opts[#opts + 1] = {("Offer %d artifacts"):format(GOAL.bribe), "bribe"}
    end
    opts[#opts + 1] = {"Walk away", "leave"}
    self.gate_ui = {cursor = 1, opts = opts}
    self.screen = "gate"
end

function Game:pay_bribe()
    self:pay_artifacts(GOAL.bribe)
end

-- Hand over n artifacts: from the bag first, then your hands.
function Game:pay_artifacts(n)
    local p, left = self.player, n
    for i = #p.inventory, 1, -1 do
        local s = p.inventory[i]
        if left > 0 and ITEM_DB[s.item].artifact then
            local n = math.min(left, s.qty)
            left = left - n
            s.qty = s.qty - n
            if s.qty <= 0 then table.remove(p.inventory, i) end
        end
    end
    for _, slot in ipairs({"lhand", "rhand"}) do
        local item = p.equipped[slot]
        if left > 0 and item and ITEM_DB[item].artifact then
            p.equipped[slot] = nil
            left = left - 1
        end
    end
    recompute_stats(p)
end

function Game:gate_key(key)
    local u = self.gate_ui
    if key == KEY.Q or key == gfx.KEY_ESCAPE then
        self.screen = "map"
    elseif key == gfx.KEY_UP or key == KEY.W then
        u.cursor = math.max(1, u.cursor - 1)
    elseif key == gfx.KEY_DOWN or key == KEY.S then
        u.cursor = math.min(#u.opts, u.cursor + 1)
    elseif key == KEY.ENTER or key == KEY.LF or key == KEY.SPACE then
        local choice = u.opts[u.cursor][2]
        if choice == "leave" then
            self:push_log("You step back from the barrier.")
            self.screen = "map"
        else
            if choice == "bribe" then self:pay_bribe() end
            self:finish_run(choice)
        end
    end
end

-- Out of the Churn: the run is over (and so is its save).
function Game:finish_run(how)
    self.ending = {how = how, day = (self:clock()), hours = self.player.hours,
                   artifacts = self:artifact_count(),
                   lore = how ~= "quiet" and self:lore_ending_line() or nil}   -- (the Quiet says it all)
    self.screen = "ending"
    self:sfx("escape")
    self:record_run(how)
    Game.delete_save()
end
-- ---------------------------------------------------------------------
-- More people to trade with: the Ferry Post and the Peddler
--
-- Game.place_extras(tiles, sites, rad, world_seed) adds the newer world
-- features AFTER generate_world, from a seed stream of their own, so a
-- world made before them (an old save) keeps every tile and site it had:
--   the Ferry Post (sites.ferry): a few ruins by the water, far from the
--     town; Mother Okun trades there (self.ferry_trader, saved).
--   the old starting clothes (extras.drops): lying a few hexes from the
--     start, since you start with nothing.
--   the Peddler's round (extras.route): TRADE.route_n stops around the map;
--     he stays TRADE.stay hours at each, so where he is comes from the
--     clock (nothing to save but his stock, self.peddler).
-- Later features add their own pieces to `extras` the same way.
-- ---------------------------------------------------------------------

function Game.place_extras(tiles, sites, rad, world_seed)
    local seed = (world_seed * 48271 + 12345) % 2147483647
    local function roll(n)
        seed = rand_next(seed)
        return seed % n
    end
    local keys = {}
    for key in pairs(tiles) do keys[#keys + 1] = key end
    table.sort(keys)
    local taken = {}
    for _, key in pairs(sites) do taken[key] = true end
    taken[hex_key(0, 0)] = true
    local extras = {}

    -- the Ferry Post: a dry, cool hex next to the water, far from the town
    local tq, tr = Game.key_qr(sites.trader)
    local F = TRADE.ferry
    local function by_water(q, r)
        for _, d in ipairs(AXIAL_DIRS) do
            if tiles[hex_key(q + d[1], r + d[2])] == "water" then return true end
        end
        return false
    end
    for _, min_town in ipairs({F.min_from_town, F.min_from_town - 3}) do
        local options = {}
        for _, key in ipairs(keys) do
            local q, r = Game.key_qr(key)
            if tiles[key] ~= "water" and not taken[key] and not rad[key]
                and axial_distance(q, r, tq, tr) >= min_town
                and axial_distance(0, 0, q, r) >= F.min_from_start and by_water(q, r) then
                options[#options + 1] = key
            end
        end
        if #options > 0 then
            local key = options[roll(#options) + 1]
            sites.ferry, taken[key] = key, true
            tiles[key] = "ruins"
            local q, r = Game.key_qr(key)
            local placed = 0
            for _, d in ipairs(AXIAL_DIRS) do
                local nk = hex_key(q + d[1], r + d[2])
                if placed < F.ruins and tiles[nk] and tiles[nk] ~= "water" and not taken[nk] then
                    tiles[nk] = "ruins"
                    placed = placed + 1
                end
            end
            break
        end
    end

    -- the Peddler's round: one stop per slice of the compass, in order
    local route = {}
    for i = 0, TRADE.route_n - 1 do
        local options = {}
        for _, key in ipairs(keys) do
            local q, r = Game.key_qr(key)
            local d = axial_distance(0, 0, q, r)
            if TERRAIN[tiles[key]].passable and not taken[key] and d >= 3 and d < GRID_RADIUS then
                local x, y = axial_to_pixel(q, r, 1)
                local slice = math.floor((math.atan(y, x) + math.pi) / (2 * math.pi) * TRADE.route_n)
                if slice % TRADE.route_n == i then options[#options + 1] = key end
            end
        end
        if #options > 0 then route[#route + 1] = options[roll(#options) + 1] end
    end
    extras.route = route

    -- the Little Ones: warrens in the woods and hills, cairns near them
    local warrens, cairns = {}, {}
    local spots = {}
    for _, key in ipairs(keys) do
        local q, r = Game.key_qr(key)
        if (tiles[key] == "forest" or tiles[key] == "hills") and not taken[key]
            and axial_distance(0, 0, q, r) >= LITTLE.min_from_start then
            spots[#spots + 1] = key
        end
    end
    for _ = 1, 60 do
        if #warrens >= LITTLE.warrens or #spots == 0 then break end
        local key = spots[roll(#spots) + 1]
        local ok = not taken[key]
        local kq, kr = Game.key_qr(key)
        for _, w in ipairs(warrens) do
            local wq, wr = Game.key_qr(w)
            if axial_distance(wq, wr, kq, kr) < 5 then ok = false end   -- spread them out
        end
        if ok then warrens[#warrens + 1], taken[key] = key, true end
    end
    for i = 1, (#warrens > 0 and LITTLE.cairns or 0) do
        local wq, wr = Game.key_qr(warrens[(i - 1) % #warrens + 1])
        local options = {}
        for _, key in ipairs(keys) do
            local q, r = Game.key_qr(key)
            local d = axial_distance(q, r, wq, wr)
            if TERRAIN[tiles[key]].passable and not taken[key] and d >= LITTLE.cairn_near and d <= LITTLE.cairn_far then
                options[#options + 1] = key
            end
        end
        if #options > 0 then
            local key = options[roll(#options) + 1]
            cairns[#cairns + 1], taken[key] = key, true
        end
    end
    extras.warrens, extras.cairns = warrens, cairns

    -- the old quarry and the Institute's gate (the storyline): hills, far
    -- from both towns
    local towns = {sites.trader, sites.ferry}
    for _, min_d in ipairs({QUESTS.story.min_from_towns, 5}) do
        local options = {}
        for _, key in ipairs(keys) do
            local q, r = Game.key_qr(key)
            local far = axial_distance(0, 0, q, r) >= 5
            for _, t in pairs(towns) do
                local a, b = Game.key_qr(t)
                if axial_distance(q, r, a, b) < min_d then far = false end
            end
            if tiles[key] == "hills" and not taken[key] and not rad[key] and far then
                options[#options + 1] = key
            end
        end
        if #options > 0 then
            local key = options[roll(#options) + 1]
            sites.quarry, taken[key] = key, true
            break
        end
    end

    -- the clothes you used to start in, left lying around instead (a new
    -- game puts them on the ground: Game.new)
    local drops, options = {}, {}
    for _, key in ipairs(keys) do
        local q, r = Game.key_qr(key)
        local d = axial_distance(0, 0, q, r)
        if TERRAIN[tiles[key]].passable and not taken[key] and d >= 2 and d <= 6 then
            options[#options + 1] = key
        end
    end
    for _, item in ipairs(START_FINDS) do
        if #options == 0 then break end
        local key = table.remove(options, roll(#options) + 1)
        drops[#drops + 1], taken[key] = {key = key, item = item}, true
    end
    extras.drops = drops
    return extras
end

-- -- the Peddler -----------------------------------------------------------

-- Where he is now (or at `hours`): a stop on his round.
function Game:peddler_key(hours)
    local route = self.extras and self.extras.route or {}
    if #route == 0 then return nil end
    return route[((hours or self.player.hours) // TRADE.stay) % #route + 1]
end

-- Seeing him puts him in the journal (called from spot_sites).
function Game:spot_peddler()
    local key = self:peddler_key()
    if key and self.player.visible[key] then
        local pd = self.peddler
        if pd.seen_key ~= key then
            self:push_log("A man pushing a rattling handcart: the Peddler, " .. self:bearing_to(key) .. ".")
        end
        pd.seen_key, pd.seen_hour = key, self.player.hours
    end
end

-- -- everyone's stock ------------------------------------------------------

-- A trader's stock and restock clock: "town", "ferry" or "peddler".
function Game:trade_state(who)
    if who == "ferry" then return self.ferry_trader end
    if who == "peddler" then return self.peddler end
    return self.trader
end

-- Fill up what sold since the last visit.
function Game:restock(who)
    local t, p = self:trade_state(who), self.player
    local cfg = TRADE.people[who] or {}
    local hours = cfg.restock_hours or TRADE.restock_hours
    local list, n = cfg.restock or TRADE.restock, cfg.restock_n or TRADE.restock_n
    while p.hours - t.restocked >= hours do
        t.restocked = t.restocked + hours
        for _ = 1, n do
            add_to_list(t.stock, {item = list[self:rand(#list) + 1], qty = 1})
        end
    end
end

-- A fresh stock list from TRADE.people[who].stock.
function Game.starting_stock(who)
    local out = {}
    for _, st in ipairs(TRADE.people[who].stock) do out[#out + 1] = {item = st[1], qty = st[2]} end
    return {stock = out, restocked = 0}
end

-- Mother Okun's job (O on her screen): three fish, any kind, or two smoked meat.
function Game:ferry_work()
    local u, q = self.trade_ui, self.quest
    if q and q.kind == "smoked" then
        local S = QUESTS.smoked
        local have = self:count_item(S.need[1])
        if have < S.need[2] then
            u.msg = ("'Two smoked. You've got %d.'"):format(have)
            return
        end
        self:take_items(S.need[1], S.need[2])
        self:give_reward(S.reward, "Mother Okun wraps them in sacking:")
        u.msg = "'That'll keep them through the week. Take these.'"
        return
    end
    local fish = self:count_item("raw_fish") + self:count_item("cooked_fish")
    if q and q.kind == "fish" then
        if fish < QUESTS.fish.need then
            u.msg = ("'Three fish. You've got %d.'"):format(fish)
            return
        end
        local left = QUESTS.fish.need
        for _, item in ipairs({"raw_fish", "cooked_fish"}) do
            local n = math.min(left, self:count_item(item))
            if n > 0 then self:take_items(item, n); left = left - n end
        end
        self:give_reward(QUESTS.fish.reward, "Mother Okun weighs them in her hands:")
        u.msg = "'They'll row tomorrow. Here.'"
        return
    end
    if q then
        u.msg = "'You've work already. Finish it.'"
        return
    end
    local kind = self:rand(2) == 0 and "smoked" or "fish"
    self:set_quest({kind = kind, giver = "Mother Okun"})
    u.msg = QUESTS[kind].offer
    self:push_log("Quest: " .. self:quest_text())
end

-- His one job (O at his cart): a tape with a voice on it for an Elder
-- Sign, once a stop. Played-out tapes are blank; he wants a voice.
function Game:peddler_swap()
    local u, S, pd = self.trade_ui, QUESTS.swap, self.peddler
    local visit = self.player.hours // TRADE.stay
    if pd.swapped == visit then
        u.msg = S.done
        return
    end
    local tape
    for _, s in ipairs(self.player.inventory) do
        if CHURN.tapes[s.item] then tape = s.item; break end
    end
    if not tape then
        u.msg = S.none
        return
    end
    self:take_items(tape, 1)
    pd.swapped = visit
    local sign = {item = S.give, qty = 1}
    if not self:put_stack("inventory", nil, sign) then self:put_stack("ground", nil, sign) end
    self:sfx("gift")
    u.msg = S.offer
    self:push_log("You swapped the " .. ITEM_DB[tape].name .. " for an Elder Sign.")
end
-- ---------------------------------------------------------------------
-- Sound effects: short melodies through solaros.audio
--
-- Game:sfx(name) plays SFX[name], a list of {Hz, ms} notes (Hz 0 = a rest).
-- tone_async queues them without stopping the game; plain tone (which
-- blocks for its length) is the fallback. M on the map mutes (self.muted,
-- saved). Never raises: a board without audio just stays quiet.
-- ---------------------------------------------------------------------

local SFX = {
    hit      = {{880, 40}, {1320, 50}},
    miss     = {{330, 60}},
    hurt     = {{220, 70}, {150, 90}},
    kill     = {{660, 60}, {880, 60}, {1320, 90}},
    geiger   = {{1800, 12}, {0, 25}, {1800, 12}},
    siren    = {{600, 150}, {900, 150}, {600, 150}, {900, 150}},
    -- (low, but not so low a small speaker can't play it)
    emission = {{196, 160}, {165, 160}, {139, 220}, {0, 60}, {196, 160}, {131, 500}},
    emission_cover = {{165, 200}, {147, 200}, {131, 400}},   -- it howls over your shelter
    emission_end = {{330, 90}, {392, 90}, {523, 160}},
    -- the title: a slow, wrong-sounding tune, once at start-up (begin_intro)
    title    = {{220, 400}, {0, 80}, {262, 300}, {330, 300}, {311, 500}, {0, 120}, {294, 300},
                {262, 300}, {247, 700}, {0, 150}, {220, 250}, {208, 900}},
    chime    = {{1047, 60}, {1568, 90}},
    gift     = {{784, 70}, {988, 70}, {1175, 120}},
    death    = {{392, 200}, {330, 200}, {262, 400}},
    escape   = {{523, 100}, {659, 100}, {784, 100}, {1047, 250}},
    bark     = {{500, 40}, {0, 40}, {450, 60}},
    whine    = {{700, 120}, {500, 200}},
    level    = {{659, 70}, {784, 70}, {988, 70}, {1319, 140}},
    achieve  = {{784, 80}, {1047, 80}, {1319, 80}, {1568, 200}},
}

function Game:sfx(name)
    if self.muted then return end
    local notes = SFX[name]
    local audio = solaros.audio
    if not (notes and audio) then return end
    local play = audio.tone_async or audio.tone
    if not play then return end
    for _, n in ipairs(notes) do
        if n[1] > 0 then
            pcall(play, n[1], n[2], 40)
        elseif audio.tone_async then
            pcall(play, 20, n[2], 0)   -- a silent step keeps the rhythm in the queue
        end
    end
    self.last_sfx = name   -- (for tests)
end

function Game:toggle_mute()
    self.muted = not self.muted or nil
    self:push_log(self.muted and "Sound off. (M)" or "Sound on. (M)")
end
-- ---------------------------------------------------------------------
-- A dog companion (numbers in DOG, 05_data_world)
--
-- A rare stray turns up on plains/forest while you have no dog. Offer it
-- food to tame it (self.dog, saved). It warns you (better hiding and
-- running), bites in fights, sometimes takes a blow meant for you, and
-- eats from your bag once a day - after DOG.leave_after hungry days it
-- leaves. If it dies, it's gone.
-- ---------------------------------------------------------------------

function Game:maybe_dog()
    local p = self.player
    if self.dog or not DOG.terrain[self.tiles[hex_key(p.q, p.r)]] then return false end
    if not self:roll(DOG.chance) then return false end
    self:start_encounter({kind = "dog", name = "Stray Dog", art = "stray", who = "dog",
                          intro = DOG.intro, start = "near"})
    self:sfx("bark")
    return true
end

-- The first food in the bag the dog would eat (DOG.eats, in order).
function Game:dog_food(list)
    list = list or self.player.inventory
    for _, item in ipairs(DOG.eats) do
        for i, s in ipairs(list) do
            if s.item == item then return i, item end
        end
    end
end

function Game:dog_tame()
    local i, item = self:dog_food()
    if not i then return end
    local s = self.player.inventory[i]
    s.qty = s.qty - 1
    if s.qty <= 0 then table.remove(self.player.inventory, i) end
    local meat = item:find("meat") or item:find("fish") or item == "jerky"
    if self:roll(DOG.tame + (meat and DOG.meat_bonus or 0)) then
        self.dog = {hp = DOG.hp, fed_hour = self.player.hours, hungry_days = 0}
        self:sfx("bark")
        self:enc_say("It wolfs down the " .. ITEM_DB[item].name:lower()
            .. ", then sits by your boot and looks up at you. You have a dog.")
        self:end_encounter("A stray dog follows you now.")
    else
        self:enc_say("It snatches the " .. ITEM_DB[item].name:lower() .. " and bolts into the grass.")
        self:end_encounter("The stray ran off with your food.")
    end
end

-- Hide/flee bonus while the dog is with you.
function Game:dog_bonus()
    return self:dog_with_you() and DOG.warn_bonus or 0
end

-- In a fight, the dog's turn: maybe a bite. Returns true if the fight ended.
function Game:dog_turn()
    local e = self.enc
    if not self:dog_with_you() or e.over or e.range ~= "close" then return false end
    if self:roll(DOG.bite_chance) then
        local dmg = DOG.bite[1] + self:rand(DOG.bite[2] - DOG.bite[1] + 1)
        self:enc_hit(dmg, nil, "Your dog bites the " .. e.def.who)
    end
    return e.over
end

-- The dog jumps in front of a blow. Returns true if it took it.
function Game:dog_guard(dmg)
    if not self:dog_with_you() or not self:roll(DOG.guard) then return false end
    local dog = self.dog
    dog.hp = dog.hp - dmg
    if dog.hp <= 0 then
        self.dog = nil
        self:sfx("whine")
        self:enc_say("Your dog throws itself in the way. It doesn't get up.")
        self:push_log("Your dog died protecting you.")
    else
        self:enc_say(("Your dog takes the blow for you (-%d)."):format(dmg))
    end
    return true
end

-- One hour passing: a slow heal, and a meal once a day.
function Game:dog_hour(hour)
    local dog = self.dog
    if not dog then return end
    if hour % 6 == 0 and dog.hp < DOG.hp then dog.hp = dog.hp + 1 end
    if hour - dog.fed_hour < DOG.meal_hours then return end
    dog.fed_hour = hour
    -- (left at camp, it eats from the stash)
    local list = dog.at_camp and self.base and self:camp_pile() or self.player.inventory
    local i, item = self:dog_food(list)
    if i then
        local s = list[i]
        s.qty = s.qty - 1
        if s.qty <= 0 then table.remove(list, i) end
        dog.hungry_days = 0
        if not dog.at_camp then self:push_log("Your dog eats the " .. ITEM_DB[item].name:lower() .. ".") end
    else
        dog.hungry_days = dog.hungry_days + 1
        local say = dog.at_camp and function(t) self:camp_news(t) end or function(t) self:push_log(t) end
        if dog.hungry_days >= DOG.leave_after then
            self.dog = nil
            self:sfx("whine")
            say(dog.at_camp and "Your dog has left the camp. Too long without food." or "Your dog is gone. Too long without food.")
        else
            say(dog.at_camp and "Your dog at camp is hungry: leave food in the stash." or "Your dog is hungry. Nothing in the bag it can eat.")
        end
    end
end
-- ---------------------------------------------------------------------
-- Broken tech and the LoRa radio (numbers in TECH, 05_data_world)
--
-- Broken devices are very rare finds. While you carry one, the crafting
-- screen lists "Repair <device>": its parts and the device itself are the
-- inputs, a Multitool the tool. A repair takes hours and can fail - then a
-- part burns out and the device stays broken.
--   LoRa Radio: R on the map; each call costs a charge (Battery Cell: E to
--     recharge) and each voice needs time before it answers again.
--   Anomaly Detector: carried, it reads rads TECH.detector_range hexes out.
--   Headlamp: worn, light at night (ITEM_DB[..].light; see has_light).
-- self.radio = {charge, next = {channel id -> hour}} is saved.
-- ---------------------------------------------------------------------

-- Repair "recipes" for the broken devices you carry (crafting screen).
function Game:repair_recipes()
    local list = {}
    for _, fix in ipairs(TECH.repairs) do
        if self:count_item(fix.broken) > 0 then
            local inputs = {[fix.broken] = 1}
            for part, n in pairs(fix.parts) do inputs[part] = n end
            list[#list + 1] = {id = "repair_" .. fix.broken, name = "Repair " .. ITEM_DB[fix.out].name,
                               inputs = inputs, tools = {TECH.tool}, hours = TECH.repair_hours,
                               out = {fix.out, 1}, repair = fix}
        end
    end
    return list
end

function Game:repair_chance(fix)
    return math.max(5, math.min(95, fix.base + TECH.per_point * (self.player.attrs.Perception - 3)
                                    + self:skill_bonus("tinker") + self:bench_bonus()))
end

-- Called by Game:craft for a repair recipe (after craft_blocker passed).
function Game:repair(r)
    local p, fix, hours = self.player, r.repair, self:craft_hours(r)
    p.hours = p.hours + hours
    apply_awake_hours(p, hours)
    local chance = self:repair_chance(fix)
    self:skill_xp("tinker", SKILLS.xp.repair)
    if self:roll(chance) then
        self:skill_xp("tinker", SKILLS.xp.repaired)
        self:stat("repairs")
        for _, iq in ipairs(Game.recipe_inputs(r)) do self:take_items(iq[1], iq[2]) end
        local stack = {item = fix.out, qty = 1}
        if not self:put_stack("inventory", nil, stack) then self:put_stack("ground", nil, stack) end
        if fix.out == "lora_radio" and not self.radio then
            self.radio = {charge = TECH.radio_start, next = {}}
        end
        self:sfx("gift")
        self:push_log("It hums back to life: " .. ITEM_DB[fix.out].name .. "!")
    else
        local parts = {}
        for part in pairs(fix.parts) do parts[#parts + 1] = part end
        table.sort(parts)
        local lost = parts[self:rand(#parts) + 1]
        self:take_items(lost, 1)
        self:sfx("miss")
        self:push_log("It sparks and dies again. Lost a " .. ITEM_DB[lost].name .. ".")
    end
    return true
end

-- E on a Battery Cell while you have the radio.
function Game:charge_radio()
    if not (self:carrying("lora_radio") and self.radio) then return false end
    if self.radio.charge >= TECH.radio_max then
        self:push_log("The radio is fully charged already.")
        return false
    end
    self.radio.charge = TECH.radio_max
    self:push_log("The radio's charge light goes green. (" .. TECH.radio_max .. " calls)")
    return true
end

-- R on the map.
function Game:open_radio()
    if not self:carrying("lora_radio") then
        self:push_log("You have no working radio.")
        return
    end
    self.radio = self.radio or {charge = TECH.radio_start, next = {}}
    self.radio_ui = {cursor = 1, msg = {"Static. Pick a frequency."}}
    self.screen = "radio"
end

function Game:radio_say(text)
    self.radio_ui.msg = wrap(text, 54)
end

-- The nearest pile with an artifact in it, as a tile key (or nil).
function Game:nearest_artifact()
    local p, best, best_d = self.player, nil, nil
    for key, pile in pairs(self.ground) do
        for _, s in ipairs(pile) do
            if ITEM_DB[s.item].artifact then
                local q, r = Game.key_qr(key)
                local d = axial_distance(p.q, p.r, q, r)
                if d > 0 and (not best or d < best_d or (d == best_d and key < best)) then
                    best, best_d = key, d
                end
            end
        end
    end
    return best
end

-- Each voice. Returns true if the call went through (it costs a charge).
local RADIO = {}
function RADIO.trader(self)
    self:learn_site("trader")
    local told = self:hear_of_exit("Trader")
    local parcel = self:mark_stash()
    if not (told or parcel) then
        self:radio_say("'Trader here. Nothing for you today, friend. Try me later.'")
        return false
    end
    self:radio_say("'Trader here. "
        .. (parcel and "Left a parcel for you, friend. Bearing's in your notes." or "")
        .. (told and " And the way out's open, if you've got paper.'" or "'"))
    return true
end
function RADIO.anna(self)
    if self:story_anna() then return true end
    local before = self.radio_ui.msg
    local spent = RADIO.anna_help(self)
    return self:story_anna_warning(before) or spent
end
function RADIO.anna_help(self)
    local work = self:anna_work()
    if work == "offered" then return false end   -- free: she only asked
    if work then return work end
    local p = self.player
    if p.health >= MAX_HEALTH and not p.injuries.bleeding and p.injuries.wounded_hours == 0 then
        self:radio_say("Anna: 'You sound fine, love. Call me when it hurts.'")
        return false
    end
    p.health = clamp(p.health + 20)
    p.injuries.bleeding = false
    p.injuries.wounded_hours = math.max(0, p.injuries.wounded_hours - 12)
    self:radio_say("Anna talks you through it, calm and slow: press here, tie that, breathe. "
        .. "(+20 HP, bleeding stopped)")
    return true
end
function RADIO.karl(self)
    if self:karl_radio_work() then return true end
    local hours = (self.next_emission or 0) - self.player.hours
    local when = hours > 0 and ("Next blowout in about " .. hours .. "h.") or "Blowout's overdue."
    self.karl_hint = true
    self:radio_say("'Karl here. With a K. Fish bite at dusk, son. " .. when
        .. " And next time we meet, I'll go easy on you.' (a hint on his next riddle)")
    return true
end
function RADIO.signal(self)
    local p = self.player
    self:dread(CHURN.dread.signal)
    if self.story then self.story.calls = (self.story.calls or 0) + 1 end
    if not self.signal_page then   -- the first time, it reads you something
        self.signal_page = true
        self:read_lore("The Signal")
    end
    p.rads = math.min(RAD.max, (p.rads or 0) + TECH.signal_rads)
    self:sfx("emission")
    local key = self:nearest_artifact()
    if not key then
        self:radio_say("Numbers, read by a voice that isn't a voice. Then your own name. Nothing else.")
        return true
    end
    p.explored[key] = true
    self:radio_say("Numbers, read by a voice that isn't a voice. You understand them: something "
        .. "waits " .. self:bearing_to(key) .. ". Your teeth ache."
        .. (self:can_measure() and (" (+" .. TECH.signal_rads .. " rads)") or ""))
    return true
end

-- Hours before a voice answers again: Anna sooner the more you've helped her.
function Game:channel_wait(ch)
    if ch.id ~= "anna" then return ch.cooldown end
    return math.max(ch.cooldown // 2, ch.cooldown - QUESTS.rep.anna_hours * self:rep_of("anna"))
end

function Game:radio_call(i)
    local ch, r = TECH.channels[i], self.radio
    if not ch then return end
    local wait = (r.next[ch.id] or 0) - self.player.hours
    if ch.id == "anna" and self:anna_ready() then wait = 0 end   -- she always takes the bandages
    if ch.id == "karl" and self:karl_ready() then wait = 0 end
    if wait > 0 then
        self:radio_say(ch.name .. ": no answer. Try again in " .. wait .. "h.")
    elseif r.charge <= 0 then
        self:radio_say("Dead air. The radio needs a Battery Cell (E on one).")
    else
        local answered = RADIO[ch.id](self)
        if answered then
            -- (free from camp with an antenna on the mast)
            if not (self:at_base() and self:camp_stack("mast")) then r.charge = r.charge - 1 end
            -- "open": the voice stays reachable (Anna after you bring her bandages)
            r.next[ch.id] = answered ~= "open" and (self.player.hours + self:channel_wait(ch)) or nil
        end
    end
end

function Game:radio_key(key)
    local u = self.radio_ui
    if u.scan then return self:scan_key(key) end   -- (64_scan)
    if key == KEY.Q or key == gfx.KEY_ESCAPE or key == KEY.R then
        self.screen = "map"
    elseif key == gfx.KEY_UP or key == KEY.W then
        u.cursor = math.max(1, u.cursor - 1)
    elseif key == gfx.KEY_DOWN or key == KEY.S then
        u.cursor = math.min(#TECH.channels + 1, u.cursor + 1)   -- (the last row: scan the band)
    elseif key == KEY.ENTER or key == KEY.LF or key == KEY.SPACE then
        if u.cursor > #TECH.channels then return self:scan_start() end
        self:radio_call(u.cursor)
    end
end

function Game:draw_radio(w, h)
    local u, r = self.radio_ui, self.radio
    if u.scan then return self:draw_scan(w, h) end
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    Game.ui_title(w, "LoRa Radio", ("Charge %d/%d"):format(r.charge, TECH.radio_max))
    for i, ch in ipairs(TECH.channels) do
        local y = 44 + (i - 1) * 18
        local wait = (r.next[ch.id] or 0) - self.player.hours
        local status = wait > 0 and (wait .. "h") or "ready"
        if i == u.cursor then
            gfx.fill_rect(4, y - 12, w - 8, 16)
            gfx.color(gfx.WHITE)
        end
        gfx.text(10, y, ch.name)
        gfx.text(300, y, status)
        gfx.color(gfx.BLACK)
    end
    local sy = 44 + #TECH.channels * 18   -- the scan row
    if u.cursor > #TECH.channels then
        gfx.fill_rect(4, sy - 12, w - 8, 16)
        gfx.color(gfx.WHITE)
    end
    gfx.text(10, sy, "Scan the band...")
    gfx.color(gfx.BLACK)
    gfx.line(6, 126, w - 6, 126)
    for i, line in ipairs(u.msg) do gfx.text(6, 132 + 14 * i, line) end
    Game.ui_keys(w, h, "Up/Dn pick  Enter call  Q back")
    gfx.refresh()
end
-- ---------------------------------------------------------------------
-- Rendering
-- ---------------------------------------------------------------------

local function shade_color(name)
    return gfx[name]
end

-- gfx draw calls appear to require integer coordinates (fill_rect at least
-- throws on a float); our hex math is full of sqrt(3)/trig-derived floats,
-- so every computed coordinate gets rounded right before it reaches gfx.*.
local function rnd(v)
    return math.floor(v + 0.5)
end

-- Draw a terrain glyph centered on (cx, cy) in the given color.
local function draw_glyph(terrain_id, cx, cy, color)
    if not draw_sprite then return end
    gfx.color(color)
    draw_sprite(rnd(cx) - GLYPH_W // 2, rnd(cy) - GLYPH_H // 2, GLYPH_W, GLYPH_H, GLYPHS[terrain_id])
end

-- Map screen (400x300 landscape): the hex map in the left MAP_W pixels
-- between MAP_TOP and MAP_BOTTOM; the HUD and the terrain legend in a panel
-- to its right (from PANEL_X); the log and key hints across the bottom.
local MAP_W, MAP_TOP, MAP_BOTTOM = 256, 4, 236
local PANEL_X = 262
local LEGEND_Y = 154
local LEGEND_ORDER = {"plains", "forest", "hills", "ruins", "ford", "water"}

-- You, your Little Ones and your dog, at your hex's center.
function Game:draw_player_mark(px, py)
    -- you: a stick figure on a white halo, so it reads on dark tiles
    if draw_sprite then
        gfx.color(gfx.WHITE)
        draw_sprite(rnd(px) - 4, rnd(py) - 6, 9, 13, GLYPHS.player_halo)
        gfx.color(gfx.BLACK)
        draw_sprite(rnd(px) - 3, rnd(py) - 5, 7, 11, GLYPHS.player)
    else   -- no bitmaps on this board: a black block on a white halo
        gfx.color(gfx.WHITE)
        gfx.fill_rect(rnd(px) - 5, rnd(py) - 5, 10, 10)
        gfx.color(gfx.BLACK)
        gfx.fill_rect(rnd(px) - 3, rnd(py) - 3, 6, 6)
    end
    local n = self.little and self.little.n or 0
    if n > 0 then   -- your Little Ones: small heads trailing behind you
        for i = 1, n do
            local lx, ly = rnd(px) - 12 + (i - 1) * 4, rnd(py) + 6 + (i % 2) * 2
            gfx.color(gfx.WHITE)
            gfx.fill_rect(lx - 1, ly - 1, 5, 5)
            gfx.color(gfx.BLACK)
            gfx.fill_rect(lx, ly, 3, 3)
        end
    end
    if self.dog then   -- your dog at your heel: a small block with an ear
        gfx.color(gfx.WHITE)
        gfx.fill_rect(rnd(px) + 5, rnd(py) + 1, 8, 6)
        gfx.color(gfx.BLACK)
        gfx.fill_rect(rnd(px) + 6, rnd(py) + 3, 6, 3)
        gfx.fill_rect(rnd(px) + 10, rnd(py) + 1, 2, 2)
    end
end

-- Rain, storm, snow or fog over the map area (nothing on boards without
-- bitmaps, or in clear weather).
function Game:draw_weather()
    local kind = self:weather()
    local W = GLYPHS.WEATHER
    if not (draw_sprite and W[kind]) then return end
    gfx.color((W[kind].flake or W[kind].veil) and gfx.WHITE or gfx.BLACK)
    local tile = GLYPHS.weather(kind, self.player.hours)
    for y = MAP_TOP, MAP_BOTTOM - W.h, W.h do
        for x = 0, MAP_W - W.w, W.w do draw_sprite(x, y, W.w, W.h, tile) end
    end
end

function Game:draw_map(w, h)
    gfx.clear(gfx.WHITE)

    local p = self.player
    -- the camera: your hex sits in the middle of the map area
    local ppx, ppy = axial_to_pixel(p.q, p.r, HEX_SIZE)
    local origin_x = MAP_W // 2 - ppx
    local origin_y = (MAP_TOP + MAP_BOTTOM) // 2 - ppy

    -- HUD: the day on a black strip; the weather; bars for health and
    -- needs; movement as pips; then conditions, radiation, where to go
    gfx.font(gfx.FONT_MONO_12)
    local day, hour = self:clock()
    local pw = w - PANEL_X + 2
    gfx.color(gfx.BLACK)
    gfx.fill_rect(PANEL_X - 2, 0, pw, 18)
    gfx.color(gfx.WHITE)
    gfx.text(PANEL_X + 2, 13, ("Day %d  %02d:00"):format(day, hour))
    if self:is_night() then gfx.text(w - 6 - 7 * 5, 13, "Night") end
    gfx.color(gfx.BLACK)
    -- an emission coming (or raging) matters more than the weather
    gfx.text(PANEL_X, 32, self:emission_text() or self:weather_text(self:fire_here() and "  Fire" or nil))
    -- (gray while fine, black when it matters: low needs, high dread)
    local dread = p.dread or 0
    local bars = {{"HP", p.health, p.health >= 30}, {"Food", p.needs.hunger, p.needs.hunger >= 30},
                  {"Drink", p.needs.thirst, p.needs.thirst >= 30}, {"Rest", p.needs.rest, p.needs.rest >= 30},
                  {"Dread", dread, dread < 60}}
    for i, b in ipairs(bars) do
        local y = 37 + (i - 1) * 12
        gfx.text(PANEL_X, y + 9, b[1])
        Game.ui_bar(PANEL_X + 38, y, 64, 10, b[2] / 100, b[3])
        gfx.text(PANEL_X + 106, y + 9, tostring(math.floor(b[2])))
    end
    -- movement points as pips, then sight
    local y = 108
    gfx.text(PANEL_X, y, "MP")
    for i = 1, p.max_mp do
        local x = PANEL_X + 18 + (i - 1) * 10
        if i <= p.mp then gfx.fill_rect(x, y - 8, 8, 8) else gfx.rect(x, y - 8, 8, 8) end
    end
    gfx.text(PANEL_X + 24 + p.max_mp * 10, y, "Sight " .. (p.view_sight or p.sight))
    local scav = SCAVENGE_LOOT[self.tiles[hex_key(p.q, p.r)]]
        and (self:scavenge_left() .. "/" .. SCAVENGE_TRIES) or "-"
    local inj = {}
    if p.injuries.bleeding then inj[#inj + 1] = "BLEEDING" end
    if p.injuries.wounded_hours > 0 then inj[#inj + 1] = "Wounded" end
    if (p.cold_hours or 0) > 0 then inj[#inj + 1] = "COLD" end
    if (p.sick_hours or 0) > 0 then inj[#inj + 1] = "SICK" end
    inj[#inj + 1] = "Scav " .. scav
    gfx.text(PANEL_X, 121, table.concat(inj, " "))
    local rad_line = self:rad_text()
    if rad_line then gfx.text(PANEL_X, 134, rad_line) end
    local goal_line = self:goal_text()
    if goal_line then gfx.text(PANEL_X, 147, goal_line) end
    local site_at = {}
    for name, key in pairs(self.sites) do site_at[key] = name end
    if self.base then site_at[self.base.key] = "camp" end   -- drawn like a site
    local peddler = self:peddler_key()
    local little_at = {}   -- warrens and cairns you've found
    for _, kind in ipairs({"warrens", "cairns"}) do
        for _, k in ipairs((self.extras or {})[kind] or {}) do
            if self.little.seen[k] then little_at[k] = kind == "warrens" and "warren" or "cairn" end
        end
    end

    local reachable = {}
    for _, n in ipairs(neighbors(self.tiles, p.q, p.r)) do
        reachable[hex_key(n[1], n[2])] = true
    end

    -- only whole hexes inside the map area (the world is far bigger than
    -- the screen): walk the axial box around you instead of every tile
    local half_w = HEX_SIZE * SQRT3 / 2
    local span = math.floor(MAP_W / (2 * half_w)) + 2   -- an integer: keys are "q,r"
    local mark_x, mark_y   -- (you're drawn last, over the weather)
    for dr = -span, span do
      for dq = -span - 1, span + 1 do
        local q, r = p.q + dq, p.r + dr
        local key = hex_key(q, r)
        local terrain_id = self.tiles[key]
        local px, py = axial_to_pixel(q, r, HEX_SIZE)
        px, py = origin_x + px, origin_y + py
        if terrain_id and px - half_w >= 1 and px + half_w <= MAP_W - 1
            and py - HEX_SIZE >= MAP_TOP and py + HEX_SIZE <= MAP_BOTTOM then
            local terrain = TERRAIN[terrain_id]
            local is_player = (q == p.q and r == p.r)
            if p.visible[key] then
                self:draw_hex(px, py, shade_color(terrain.shade), gfx.BLACK)
                if reachable[key] and terrain.passable then
                    -- second, inner outline marks tiles you can step onto
                    self:draw_hex(px, py, nil, gfx.BLACK, HEX_SIZE - 3)
                end
                if not is_player then
                    draw_glyph(terrain_id, px, py, shade_color(terrain.ink))
                end
            elseif p.explored[key] then
                -- remembered but out of sight: faded outline and faded glyph,
                -- so you still remember what kind of ground it was
                self:draw_hex(px, py, nil, gfx.LIGHT)
                draw_glyph(terrain_id, px, py, gfx.LIGHT)
            end
            local pile = self.ground[key]
            if pile and #pile > 0 and (p.visible[key] or p.explored[key]) then
                -- something lies here: small boxed dot in the hex's upper right
                local mx, my = rnd(px) + 5, rnd(py) - 11
                gfx.color(gfx.WHITE)
                gfx.fill_rect(mx - 1, my - 1, 7, 7)
                gfx.color(gfx.BLACK)
                gfx.rect(mx - 1, my - 1, 7, 7)
                gfx.fill_rect(mx + 1, my + 1, 3, 3)
            end
            local site = site_at[key]
            if site and not is_player and (p.visible[key] or p.explored[key]) then
                -- the trader's stall / the Checkpoint, on a white patch
                gfx.color(gfx.WHITE)
                gfx.fill_rect(rnd(px) - 6, rnd(py) - 6, 12, 12)
                gfx.color(gfx.BLACK)
                gfx.rect(rnd(px) - 7, rnd(py) - 7, 14, 14)
                draw_glyph(site, px, py, gfx.BLACK)
            end
            local spot = little_at[key]
            if spot and not is_player and (p.visible[key] or p.explored[key]) then
                gfx.color(gfx.WHITE)
                gfx.fill_rect(rnd(px) - 6, rnd(py) - 6, 12, 12)
                draw_glyph(spot, px, py, gfx.BLACK)
            end
            if key == peddler and p.visible[key] and not is_player then
                -- the Peddler and his cart, on a white patch
                gfx.color(gfx.WHITE)
                gfx.fill_rect(rnd(px) - 6, rnd(py) - 6, 12, 12)
                draw_glyph("cart", px, py, gfx.BLACK)
            end
            if self.stashes[key] and (p.visible[key] or p.explored[key]) then
                -- a stash from the notes: an X in the lower right
                local sx, sy = rnd(px) + 4, rnd(py) + 3
                gfx.color(gfx.WHITE)
                gfx.fill_rect(sx - 1, sy - 1, 9, 9)
                gfx.color(gfx.BLACK)
                gfx.rect(sx - 1, sy - 1, 9, 9)
                gfx.line(sx + 1, sy + 1, sx + 5, sy + 5)
                gfx.line(sx + 5, sy + 1, sx + 1, sy + 5)
            end
            if self.snares[key] and (p.visible[key] or p.explored[key]) then
                -- your snare: a small loop at the bottom of the hex
                local sx, sy = rnd(px) - 3, rnd(py) + 6
                gfx.color(gfx.WHITE)
                gfx.fill_rect(sx - 1, sy - 1, 8, 8)
                gfx.color(gfx.BLACK)
                gfx.rect(sx, sy, 6, 6)
                gfx.line(sx + 3, sy + 6, sx + 3, sy + 8)
            end
            if self.quest and self.quest.target == key and (p.visible[key] or p.explored[key]) then
                -- a quest target: "!" in a box, lower right
                local qx, qy = rnd(px) + 4, rnd(py) + 2
                gfx.color(gfx.WHITE)
                gfx.fill_rect(qx - 1, qy - 1, 8, 10)
                gfx.color(gfx.BLACK)
                gfx.rect(qx - 1, qy - 1, 8, 10)
                gfx.fill_rect(qx + 2, qy + 1, 2, 4)
                gfx.fill_rect(qx + 2, qy + 6, 2, 2)
            end
            local hot = self.rad_known[key]
            if hot and hot > 0 and (p.visible[key] or p.explored[key]) then
                -- measured radiation: a trefoil in the upper left, inverted
                -- (white on black) when deadly
                local rx, ry = rnd(px) - 11, rnd(py) - 11
                gfx.color(hot >= 3 and gfx.BLACK or gfx.WHITE)
                gfx.fill_rect(rx - 1, ry - 1, 9, 9)
                gfx.color(gfx.BLACK)
                gfx.rect(rx - 1, ry - 1, 9, 9)
                gfx.color(hot >= 3 and gfx.WHITE or gfx.BLACK)
                draw_sprite(rx, ry, 7, 7, GLYPHS.rad)
            end
            local find = self.finds and self.finds[key]
            if find and (p.visible[key] or p.explored[key]) then
                -- a find (F in the journal): upper right; a grave cross for a
                -- dead churner, an open box for a crate
                -- (the crate is solid black with its lid open, unlike the other boxes)
                local fx, fy = rnd(px) + 4, rnd(py) - 11
                local crate = find.kind ~= "corpse"
                gfx.color(gfx.WHITE)
                gfx.rect(fx - 2, fy - 2, 11, 11)   -- (a white rim: it shows on dark hexes too)
                gfx.color(crate and gfx.BLACK or gfx.WHITE)
                gfx.fill_rect(fx - 1, fy - 1, 9, 9)
                gfx.color(gfx.BLACK)
                gfx.rect(fx - 1, fy - 1, 9, 9)
                if crate then
                    gfx.color(gfx.WHITE)
                    gfx.fill_rect(fx + 1, fy + 4, 5, 1)
                    gfx.line(fx + 1, fy + 2, fx + 5, fy)
                else
                    gfx.fill_rect(fx + 3, fy + 1, 1, 6)
                    gfx.fill_rect(fx + 1, fy + 2, 5, 1)
                end
            end
            local camp = self.camps[key]
            if camp and p.hours < camp.until_hour and (p.visible[key] or p.explored[key]) then
                -- a burning campfire, in the hex's lower left, on a white patch
                local fx, fy = rnd(px) - 12, rnd(py) + 1
                gfx.color(gfx.WHITE)
                gfx.fill_rect(fx - 1, fy - 1, GLYPH_W + 2, GLYPH_H + 2)
                gfx.color(gfx.BLACK)
                draw_sprite(fx, fy, GLYPH_W, GLYPH_H, GLYPHS.campfire)
            end
            if is_player then mark_x, mark_y = px, py end
        end
      end
    end
    self:draw_weather()
    if mark_x then self:draw_player_mark(mark_x, mark_y) end
    gfx.color(gfx.BLACK)
    gfx.rect(0, MAP_TOP - 2, MAP_W, MAP_BOTTOM - MAP_TOP + 4)   -- the map's frame

    self:draw_legend()

    -- log
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_MONO_12)
    local ly = h - 52
    for _, line in ipairs(self.log) do
        gfx.text(6, ly, line)
        ly = ly + 14
    end
    Game.ui_keys(w, h, self.move_lean
        and ((self.move_lean < 0 and "Up" or "Down") .. ": now Left or Right picks the side")
        or "Arrows Spc:rest F:search E:water I:bag H:help")

    gfx.refresh()
end

-- Terrain key: swatch (same fill + glyph as on the map), name, and what it
-- costs to cross. The tile you're standing on gets a second box.
function Game:draw_legend()
    local here = self.tiles[hex_key(self.player.q, self.player.r)]
    gfx.font(gfx.FONT_MONO_12)
    for i, terrain_id in ipairs(LEGEND_ORDER) do
        local t = TERRAIN[terrain_id]
        local x, y = PANEL_X + 2, LEGEND_Y + (i - 1) * 14

        local fill = shade_color(t.shade)
        if fill ~= gfx.WHITE then
            gfx.color(fill)
            gfx.fill_rect(x, y, 14, 14)
        end
        gfx.color(gfx.BLACK)
        gfx.rect(x, y, 14, 14)
        draw_glyph(terrain_id, x + 7, y + 7, shade_color(t.ink))

        gfx.color(gfx.BLACK)
        if terrain_id == here then
            gfx.rect(x - 2, y - 2, 18, 18)
        end
        local detail = t.passable and (t.cost .. " MP") or "impassable"
        gfx.text(x + 20, y + 11, t.name .. " " .. detail)
    end
end

-- Fill a pointy-top hexagon with horizontal 2px bands whose width follows the
-- hex outline (gfx has no polygon fill). Inset by 1px so the fill never spills
-- past the outline. Skipped for WHITE since the background is already white.
local function fill_hex(cx, cy, size, color)
    if color == gfx.WHITE then return end
    gfx.color(color)
    local half_w = size * SQRT3 / 2
    local step = 2
    for y0 = -size, size - step, step do
        local a = math.abs(y0 + step / 2)
        local hw
        if a <= size / 2 then
            hw = half_w
        else
            hw = half_w * (size - a) / (size / 2)
        end
        hw = hw - 1
        if hw >= 1 then
            gfx.fill_rect(rnd(cx - hw), rnd(cy + y0), rnd(2 * hw), step)
        end
    end
end

-- Unit hex corners (cos, sin of 60i-30 degrees), worked out once: the map
-- draws hundreds of hexes a frame and each new table is garbage to collect.
local HEX_CORNERS = {}
for i = 0, 6 do
    local angle = math.rad(60 * (i % 6) - 30)
    HEX_CORNERS[2 * i + 1], HEX_CORNERS[2 * i + 2] = math.cos(angle), math.sin(angle)
end

-- fill_color may be nil (outline only). size defaults to HEX_SIZE.
-- The hex drawn with rects and lines (the original way, kept for boards
-- without gfx.bitmap and as the source of the masks below).
local function draw_hex_lines(cx, cy, fill_color, outline_color, size)
    if fill_color then
        fill_hex(cx, cy, size, fill_color)
    end
    gfx.color(outline_color)
    local c = HEX_CORNERS
    for i = 0, 5 do
        gfx.line(rnd(cx + size * c[2 * i + 1]), rnd(cy + size * c[2 * i + 2]),
                 rnd(cx + size * c[2 * i + 3]), rnd(cy + size * c[2 * i + 4]))
    end
end

-- Hex masks: draw_hex_lines replayed once per size, at a whole-pixel
-- center, into 1-bit bitmaps of at most 128 bytes (gfx.bitmap's limit), so
-- a hex is ~5 draw calls instead of ~24 (16 fill bands + 6 lines). The
-- firmware dithers a bitmap like a fill_rect of the same color. Each mask
-- is a list of chunks {dx, dy, w, h, data} relative to the center.
HEX_MASKS = {}   -- (a global: the bundle's 200-local limit)
function Game.hex_mask(size)
    if HEX_MASKS[size] then return HEX_MASKS[size] end
    local layers, pen = {}, nil
    local function plot(x, y)
        local layer = layers[pen]
        layer.px[y * 1000 + x] = true
        layer.x0, layer.x1 = math.min(layer.x0, x), math.max(layer.x1, x)
        layer.y0, layer.y1 = math.min(layer.y0, y), math.max(layer.y1, y)
    end
    local real = {color = gfx.color, fill_rect = gfx.fill_rect, line = gfx.line}
    gfx.color = function(c)
        pen = c
        layers[c] = layers[c] or {px = {}, x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9}
    end
    gfx.fill_rect = function(x, y, w, h)
        for yy = y, y + h - 1 do for xx = x, x + w - 1 do plot(xx, yy) end end
    end
    gfx.line = function(x0, y0, x1, y1)   -- Bresenham, both ends included
        local dx, dy = math.abs(x1 - x0), -math.abs(y1 - y0)
        local sx, sy = x0 < x1 and 1 or -1, y0 < y1 and 1 or -1
        local err = dx + dy
        while true do
            plot(x0, y0)
            if x0 == x1 and y0 == y1 then break end
            local e2 = 2 * err
            if e2 >= dy then err = err + dy; x0 = x0 + sx end
            if e2 <= dx then err = err + dx; y0 = y0 + sy end
        end
    end
    -- the fill in BLACK, the outline in WHITE, just to tell them apart
    local ok, err = pcall(draw_hex_lines, 0, 0, gfx.BLACK, gfx.WHITE, size)
    gfx.color, gfx.fill_rect, gfx.line = real.color, real.fill_rect, real.line
    if not ok then error(err) end
    local function pack(layer)
        local chunks = {}
        if not layer or layer.x1 < layer.x0 then return chunks end   -- (nothing plotted)
        local w = layer.x1 - layer.x0 + 1
        local bpr = (w + 7) // 8
        local rows = 128 // bpr
        for top = layer.y0, layer.y1, rows do
            local h = math.min(rows, layer.y1 - top + 1)
            local bytes = {}
            for y = top, top + h - 1 do
                for b = 0, bpr - 1 do
                    local v = 0
                    for bit = 0, 7 do
                        local x = layer.x0 + b * 8 + bit
                        if b * 8 + bit < w and layer.px[y * 1000 + x] then v = v | (1 << bit) end
                    end
                    bytes[#bytes + 1] = string.char(v)
                end
            end
            chunks[#chunks + 1] = {layer.x0, top, w, h, table.concat(bytes)}
        end
        return chunks
    end
    HEX_MASKS[size] = {fill = pack(layers[gfx.BLACK]), outline = pack(layers[gfx.WHITE])}
    return HEX_MASKS[size]
end

local function draw_mask(chunks, cx, cy)
    for _, c in ipairs(chunks) do draw_sprite(cx + c[1], cy + c[2], c[3], c[4], c[5]) end
end

function Game:draw_hex(cx, cy, fill_color, outline_color, size)
    size = size or HEX_SIZE
    if not draw_sprite then return draw_hex_lines(cx, cy, fill_color, outline_color, size) end
    local mask, x, y = Game.hex_mask(size), rnd(cx), rnd(cy)
    if fill_color and fill_color ~= gfx.WHITE then
        gfx.color(fill_color)
        draw_mask(mask.fill, x, y)
    end
    gfx.color(outline_color)
    draw_mask(mask.outline, x, y)
end

local INV_ROWS = {}  -- rebuilt each draw: {kind, key, label} - only selectable item rows
local INV_POS = {}   -- rebuilt each draw: row_index -> {x, y, w, h} - where that row draws
-- ---------------------------------------------------------------------
-- A base: claim a ruin, then build on it (recipes with `base`, in RECIPES)
--
-- self.base = {key, built = {box, bedroll, barrel, barricade}} (saved).
-- The base hex's ground is your Stash box; the Bedroll keeps you warm and
-- rests you better there; the Rain Barrel fills water bottles into the box;
-- the Barricade stops encounters starting on the hex. Numbers in BASE.
-- ---------------------------------------------------------------------

function Game:at_base()
    return self.base ~= nil and self.base.key == hex_key(self.player.q, self.player.r)
end

function Game:base_has(part)
    return self.base ~= nil and self.base.built[part] == true
end

-- Why a base recipe can't be built here (nil if it can).
function Game:base_blocker(r)
    if r.base == "claim" then
        if self.tiles[hex_key(self.player.q, self.player.r)] ~= "ruins" then
            return "Only a ruin will do for a camp."
        end
        if self:at_base() then return "This is already your camp." end
        return nil
    end
    if not self:at_base() then return "Build it at your camp." end
    if self:base_has(r.base) then return "Already built." end
    if r.needs and not self:base_has(r.needs) then
        return "Needs a " .. BASE.names[r.needs] .. " first."
    end
    return nil
end

-- Called by Game:craft for a base recipe (after craft_blocker passed).
function Game:build_base(r)
    local p, hours = self.player, self:craft_hours(r)
    for _, iq in ipairs(Game.recipe_inputs(r)) do self:take_items(iq[1], iq[2]) end
    p.hours = p.hours + hours
    apply_awake_hours(p, hours)
    self:skill_xp("tinker", SKILLS.xp.craft)
    self:sfx("chime")
    if r.base == "claim" then
        local old = self.base
        if old then   -- one camp: what was in the old one's slots stays in its stash
            local pile = self:camp_pile()
            for _, st in pairs(old.slots or {}) do add_to_list(pile, {item = st.item, qty = st.qty}) end
            if self.dog then self.dog.at_camp = nil end
        end
        self.base = {key = hex_key(p.q, p.r), built = {}, barrel_hour = p.hours, slots = {}}
        self:push_log(old and "You move your camp here. The old one's things stay behind."
            or "You make this ruin your camp. T: the camp.")
    else
        self.base.built[r.base] = true
        if r.base == "barricade" then self.base.wall = BASE.wall_hp end
        self:push_log("Built: " .. BASE.names[r.base] .. ".")
    end
    return true
end

-- Your bedroll, here: warm, and better rest.
function Game:bed_here()
    return self:at_base() and (self:base_has("bedroll") or self:camp_stack("bed") ~= nil)
end

-- One hour: the rain barrel fills a bottle every BASE.barrel_hours (two in
-- rain) into the stash box, up to BASE.barrel_max.
function Game:base_hour(hour)
    local b = self.base
    if not b then return end
    self:camp_hour(hour)
    if not (b.built.barrel and b.built.box) then return end
    if hour - (b.barrel_hour or hour) < BASE.barrel_hours then return end
    b.barrel_hour = hour
    local pile = self.ground[b.key] or {}
    self.ground[b.key] = pile
    local have = 0
    for _, s in ipairs(pile) do if s.item == "water_bottle" then have = have + s.qty end end
    local add = math.min(self:weather(hour) == "Rain" and 2 or 1, BASE.barrel_max - have)
    if add > 0 then add_to_list(pile, {item = "water_bottle", qty = add}) end
end

-- What the journal says about it.
function Game:base_text()
    if not self.base then return nil end
    local parts = {}
    for _, part in ipairs(BASE.order) do
        if self.base.built[part] then parts[#parts + 1] = BASE.names[part] end
    end
    local where = self:at_base() and "here" or self:bearing_to(self.base.key)
    return "Camp: " .. where .. (#parts > 0 and (". " .. table.concat(parts, ", ") .. ".") or ".")
end

-- ---------------------------------------------------------------------
-- The camp screen: slots (BASE.slots) that hold things and work while you
-- are away. self.base.slots = {slot id -> stack}; a stack in the pot or on
-- the rack keeps its hours in .t, a ward its days left in .left. Other
-- camp state on self.base: fire_until (hour the fire pit burns to), wall
-- (barricade condition), news (what happened while you were away),
-- day (last day ticked). All saved with self.base.
-- ---------------------------------------------------------------------

function Game.camp_slot(id)
    for _, s in ipairs(BASE.slots) do
        if s[1] == id then return s end
    end
end

-- Things that are tools somewhere in the recipes (the workbench takes them).
function Game.is_tool(item)
    if not Game.tool_set then
        local set = {[TECH.tool] = true}
        for _, r in ipairs(RECIPES) do
            for _, t in ipairs(r.tools or {}) do
                local prop = Game.prop_of(t)
                for _, id in ipairs(prop and prop.items or {t}) do set[id] = true end
            end
        end
        Game.tool_set = set
    end
    return Game.tool_set[item] == true
end

-- Does camp slot `slot` (a BASE.slots row) take this item?
function Game.camp_takes(slot, item)
    local kind, def = slot[4], ITEM_DB[item]
    if kind == "info" then return false end
    if kind == "light" then return def.light == true or item == "torch" end
    if kind == "tool" then return Game.is_tool(item) end
    if kind == "shelf" then return def.artifact ~= nil or def.trinket ~= nil end
    return BASE.takes[kind] ~= nil and BASE.takes[kind][item] ~= nil
end

-- nil if the slot can be used now, else why not.
function Game:camp_slot_blocker(slot)
    if slot[5] and not self:base_has(slot[5]) then
        return "Build a " .. BASE.names[slot[5]]:lower() .. " first (C)."
    end
    if slot[1] == "dog" and not self.dog then return "No dog to bed down." end
    return nil
end

function Game:camp_stack(id)
    local b = self.base
    return b and b.slots and b.slots[id] or nil
end

-- Put a stack in a camp slot (the camp side of put_stack): what was there
-- (another thing) and anything over the slot's limit go to the bag, or the
-- ground when it's full. False when it doesn't belong there.
function Game:camp_put(id, stack)
    local slot = Game.camp_slot(id)
    local why = slot and (self:camp_slot_blocker(slot)
        or (not Game.camp_takes(slot, stack.item) and (ITEM_DB[stack.item].name .. " doesn't go there.")))
    if not slot or why then
        self:push_log(why or "Not here.")
        return false
    end
    local b = self.base
    b.slots = b.slots or {}
    local spill = {}
    local here = b.slots[id]
    if here and here.item ~= stack.item then
        spill[#spill + 1] = here
        here = nil
    end
    local qty = stack.qty + (here and here.qty or 0)
    local max = slot[6] or qty
    b.slots[id] = {item = stack.item, qty = math.min(qty, max), t = here and here.t,
                   left = here and here.left or BASE.takes.ward[stack.item]}
    if qty > max then spill[#spill + 1] = {item = stack.item, qty = qty - max, cond = stack.cond} end
    for _, s in ipairs(spill) do
        s = {item = s.item, qty = s.qty, cond = s.cond}
        if not add_to_list(self.player.inventory, s, self:bag_capacity()) then add_to_list(self:ground_list(), s) end
    end
    if slot[4] == "ward" and not here then self:push_log("You set the " .. ITEM_DB[stack.item].name:lower() .. " at the edge of camp.") end
    return true
end

function Game:camp_remove(id)
    local b = self.base
    local s = b and b.slots and b.slots[id]
    if not s then return nil end
    b.slots[id] = nil
    return {item = s.item, qty = s.qty}
end

-- -- what the slots do ---------------------------------------------------

-- The fire pit: lit while it has fuel or a piece is still burning.
function Game:camp_fire(hours)
    local b = self.base
    if not (b and b.built.firepit) then return false end
    return (b.fire_until or 0) > hours or self:camp_stack("fire") ~= nil
end

function Game:camp_wards()
    local n = 0
    for _, id in ipairs({"ward1", "ward2", "ward3"}) do
        if self:camp_stack(id) then n = n + 1 end
    end
    return n
end

function Game:camp_count(kind)   -- trinkets or artifacts on the shelf
    local n = 0
    for _, id in ipairs({"shelf1", "shelf2", "shelf3"}) do
        local s = self:camp_stack(id)
        if s and ITEM_DB[s.item][kind] then n = n + 1 end
    end
    return n
end

function Game:dog_at_camp()
    return self.dog ~= nil and self.dog.at_camp == true
end

-- The dog is with you (not left at camp).
function Game:dog_with_you()
    return self.dog ~= nil and not self.dog.at_camp
end

-- The barricade stands (built and not broken down).
function Game:wall_up()
    local b = self.base
    return b ~= nil and b.built.barricade == true and (b.wall or BASE.wall_hp) > 0
end

-- Something that happened at camp: in the log if you're there, else kept
-- for when you come back.
function Game:camp_news(text)
    if self:at_base() then
        self:push_log(text)
        return
    end
    local b = self.base
    b.news = b.news or {}
    if #b.news < BASE.news_max then b.news[#b.news + 1] = text end
end

-- Back at camp: what happened while you were away.
function Game:camp_arrive()
    local b = self.base
    if not (b and self:at_base()) then return end
    if b.news then
        for _, line in ipairs(b.news) do self:push_log(line) end
        b.news = nil
    end
    if self:dog_at_camp() then self:push_log("Your dog runs out to meet you.") end
end

-- The camp's stash (its ground, the stash box).
function Game:camp_pile()
    local b = self.base
    self.ground[b.key] = self.ground[b.key] or {}
    return self.ground[b.key]
end

-- One hour at camp (from base_hour).
function Game:camp_hour(hour)
    local b = self.base
    b.slots = b.slots or {}
    local sl = b.slots
    -- the fire pit eats its fuel a piece at a time
    if b.built.firepit and sl.fire and (b.fire_until or 0) <= hour then
        b.fire_until = hour + BASE.takes.fuel[sl.fire.item]
        sl.fire.qty = sl.fire.qty - 1
        if sl.fire.qty <= 0 then sl.fire = nil end
    end
    -- the pot cooks over it; the rack smokes, fire or not
    local pot = sl.pot
    if pot and BASE.takes.cook[pot.item] and self:camp_fire(hour) then
        pot.t = (pot.t or 0) + 1
        if pot.t >= BASE.cook_hours then
            sl.pot = {item = BASE.takes.cook[pot.item], qty = pot.qty}
            self:camp_news("The pot at camp is done: " .. ITEM_DB[sl.pot.item].name:lower() .. ".")
        end
    end
    local rack = sl.rack
    if rack and BASE.takes.smoke[rack.item] then
        rack.t = (rack.t or 0) + 1
        if rack.t >= BASE.smoke_hours then
            sl.rack = {item = BASE.takes.smoke[rack.item], qty = rack.qty}
            self:camp_news("On the rack at camp: " .. rack.qty .. " smoked meat.")
        end
    end
    -- the radio mast tops up a radio you have with you at camp
    if sl.mast and self.radio and self:at_base() and self:carrying("lora_radio")
        and hour % BASE.mast_charge_hours == 0 and self.radio.charge < TECH.radio_max then
        self.radio.charge = self.radio.charge + 1
    end
    if hour % 24 == 6 then self:camp_day(hour) end
end

-- Once a day at dawn: wards wear, snares, the berry patch, the Little Ones,
-- the weather on the barricade, and a raid while you're away.
function Game:camp_day(hour)
    local b, sl = self.base, self.base.slots
    local pile = self:camp_pile()
    for _, id in ipairs({"ward1", "ward2", "ward3"}) do
        local w = sl[id]
        if w then
            w.left = (w.left or 1) - 1
            if w.left <= 0 then
                sl[id] = nil
                self:camp_news("A ward at camp has worn out: " .. ITEM_DB[w.item].name:lower() .. ".")
            end
        end
    end
    if sl.trap then
        local caught, broke = 0, 0
        for _ = 1, sl.trap.qty do
            if self:roll(BASE.trap_catch) then caught = caught + 1 end
            if self:roll(BASE.trap_break) then broke = broke + 1 end
        end
        if caught > 0 then
            add_to_list(pile, {item = "strange_meat", qty = caught})
            self:camp_news("The snare line caught something: " .. caught .. " meat in the stash.")
        end
        sl.trap.qty = sl.trap.qty - broke
        if sl.trap.qty <= 0 then sl.trap = nil end
    end
    if sl.plot and b.built.garden then
        add_to_list(pile, {item = "berries", qty = math.max(1, sl.plot.qty // BASE.plot_per)})
    end
    if self:camp_count("trinket") > 0 and self:roll(BASE.gift) then
        local item = LITTLE.trinkets[self:rand(#LITTLE.trinkets) + 1]
        if self:roll(50) then item = ({"berries", "cloth_scrap", "stick", "button"})[self:rand(4) + 1] end
        add_to_list(pile, {item = item, qty = 1})
        self:camp_news("Small footprints round the shelf. The Little Ones left a " .. ITEM_DB[item].name:lower() .. ".")
    end
    if b.built.barricade and self:weather(hour) == "Storm" then self:wall_hit(BASE.wall_storm, "The storm battered") end
    if not self:at_base() then self:camp_raid() end
end

function Game:wall_hit(n, how)
    local b = self.base
    b.wall = math.max(0, (b.wall or BASE.wall_hp) - n)
    self:camp_news(how .. " the barricade" .. (b.wall == 0 and ": it's down." or (" (" .. b.wall .. "%).")))
end

-- % a raid comes today (you away).
function Game:raid_chance()
    if self:dog_at_camp() then return 0 end
    local c = BASE.raid - BASE.raid_ward * self:camp_wards() - BASE.raid_shelf * self:camp_count("artifact")
    if self:camp_stack("light") then c = c - BASE.raid_light end
    return math.max(0, c)
end

function Game:camp_raid()
    if not self:roll(self:raid_chance()) then return end
    if self:wall_up() then
        local w = BASE.wall_raid
        return self:wall_hit(w[1] + self:rand(w[2] - w[1] + 1), "Someone tried")
    end
    local b, sl = self.base, self.base.slots
    local gone = {}
    for _, id in ipairs({"pot", "rack"}) do   -- (food left out goes first)
        if sl[id] then gone[#gone + 1] = ITEM_DB[sl[id].item].name:lower(); sl[id] = nil end
    end
    local pile = self:camp_pile()
    local take = b.built.lockbox and 0 or b.built.box and 1 or 2
    for _ = 1, take do
        if #pile == 0 then break end
        local i = self:rand(#pile) + 1
        gone[#gone + 1] = ITEM_DB[pile[i].item].name:lower()
        pile[i].qty = pile[i].qty - 1
        if pile[i].qty <= 0 then table.remove(pile, i) end
    end
    self:camp_news(#gone > 0 and ("Someone's been through your camp. Gone: " .. table.concat(gone, ", ") .. ".")
        or "Someone's been through your camp, and found nothing worth taking.")
end

-- After a night's rest at camp: something may come to the edge of the light.
function Game:camp_visit_chance()
    local c = BASE.visit
    c = c * BASE.ward_mult ^ self:camp_wards()
    if self:camp_stack("light") then c = c * BASE.light_mult end
    if self:camp_stack("bed") then c = c * BASE.pelt_mult end
    c = c * BASE.shelf_mult ^ self:camp_count("artifact")
    if self:dog_at_camp() or self:dog_with_you() then c = c / 2 end
    return c
end

function Game:camp_night()
    if not (self:at_base() and self:is_night()) then return false end
    if not self:roll(self:camp_visit_chance()) then return false end
    local def = NIGHT.horrors[self:rand(#NIGHT.horrors) + 1]
    self:start_encounter(def)
    self:sfx("emission")
    self:enc_say("You wake. Something stands at the edge of the camp's light.")
    return true
end

-- E on a camp slot.
function Game:camp_action(id)
    local b = self.base
    if id == "wall" then
        if not b.built.barricade then return self:push_log("Build a barricade first (C).") end
        if (b.wall or BASE.wall_hp) >= BASE.wall_hp then return self:push_log("The barricade is sound.") end
        local fix = self:count_item("scrap_metal") > 0 and {"scrap_metal", 1} or self:count_item("stick") >= 2 and {"stick", 2}
        if not fix then return self:push_log("Mending needs scrap metal, or 2 sticks.") end
        self:take_items(fix[1], fix[2])
        self.player.hours = self.player.hours + 1
        apply_awake_hours(self.player, 1)
        b.wall = math.min(BASE.wall_hp, (b.wall or BASE.wall_hp) + BASE.mend)
        return self:push_log("You shore up the barricade (" .. b.wall .. "%).")
    elseif id == "dog" then
        if not self.dog then return self:push_log("No dog to bed down.") end
        if self:dog_at_camp() then
            self.dog.at_camp = nil
            return self:push_log("You whistle. Your dog comes along.")
        end
        if not self:camp_stack("dog") then return self:push_log("Give it something to lie on first.") end
        self.dog.at_camp = true
        return self:push_log("Your dog circles its bed and lies down. It'll guard the camp.")
    elseif id == "map" then
        if not b.built.mapwall then return self:push_log("Build a map wall first (C).") end
        self.skills_off, self.page = 0, "map"
        self.skills_back = "inventory"
        self.screen = "skills"
        return
    end
    local s = self:camp_stack(id)
    if s then return self:push_log(self:camp_slot_text(id)) end
    local slot = Game.camp_slot(id)
    self:push_log(slot and (self:camp_slot_blocker(slot) or (slot[3] .. ": empty.")) or "")
end

-- One line on what a slot is doing (the screen, under the cursor).
function Game:camp_slot_text(id)
    local b, s = self.base, self:camp_stack(id)
    local slot = Game.camp_slot(id)
    local why = self:camp_slot_blocker(slot)
    if id == "barrel" then
        if why then return why end
        local n = 0
        for _, st in ipairs(self:camp_pile()) do if st.item == "water_bottle" then n = n + st.qty end end
        return n .. " bottles in the stash. Fills one a " .. BASE.barrel_hours .. "h, two in rain."
    elseif id == "wall" then
        if why then return why end
        local hp = b.wall or BASE.wall_hp
        if hp <= 0 then return "Down. E: mend it (scrap metal, or 2 sticks)." end
        return ("Holding at %d%%: stops raids.%s"):format(hp, hp < BASE.wall_hp and " E: mend." or "")
    elseif id == "box" then
        return b.built.lockbox and "Lockbox: raiders can't touch the stash."
            or b.built.box and "Stash box: a raid takes 1 thing at most. A lockbox: none."
            or "No box: a raid takes 2 things. Build one (C)."
    elseif id == "map" then
        return why or "E: the map wall - every place you know."
    end
    if why then return why end
    local kind = slot[4]
    if not s then
        return ({fuel = "Sticks, branches, newspaper, charcoal: it burns while fed.",
                 cook = "Raw meat, fish or dirty water: cooks over the fire.",
                 bedding = "A pelt or tarp: better rest, a warmer night.",
                 dogbed = "Cloth or hide. Then E: the dog stays and guards.",
                 light = "A glow jar, candle or torch: keeps the dark back.",
                 mast = "An antenna: free calls here, and a slow recharge.",
                 ward = "Salt circle, candle, rattle, charm, sign: wards the camp.",
                 smoke = "Meat or fish: smoked in a day, keeps for ever.",
                 trap = "Snares (3): meat in the stash most mornings.",
                 plot = "Berries to plant: more berries every morning.",
                 tool = "A tool left here counts when you craft at camp.",
                 shelf = "An artifact (wards) or a toy (the Little Ones)."})[kind] or ""
    end
    if kind == "fuel" then
        local left = math.max(0, (b.fire_until or 0) - self.player.hours)
        return ("Burning: %dh, and %d %s to go."):format(left, s.qty, ITEM_DB[s.item].name:lower())
    elseif kind == "cook" then return ("Cooking: %d of %dh."):format(s.t or 0, BASE.cook_hours)
    elseif kind == "smoke" then return ("Smoking: %d of %dh."):format(s.t or 0, BASE.smoke_hours)
    elseif kind == "ward" then return ("Holds %d more day%s."):format(s.left or 1, (s.left or 1) == 1 and "" or "s")
    elseif kind == "dogbed" then return self:dog_at_camp() and "Your dog guards the camp. E: call it." or "E: tell your dog to stay."
    end
    return ""
end

-- The line under the camp screen.
function Game:camp_summary()
    local b, p = self.base, self.player
    local parts = {}
    if b.built.firepit then
        parts[#parts + 1] = self:camp_fire(p.hours) and ("Fire " .. math.max(0, (b.fire_until or 0) - p.hours) .. "h") or "Fire out"
    end
    parts[#parts + 1] = "Wards " .. self:camp_wards()
    if b.built.barricade then parts[#parts + 1] = "Wall " .. (b.wall or BASE.wall_hp) .. "%" end
    if self:dog_at_camp() then parts[#parts + 1] = "Dog" end
    return table.concat(parts, "  ")
end

-- Every place you know, for the map wall.
function Game:map_wall_lines()
    local lines = {}
    local function add(s) lines[#lines + 1] = s end
    add("Camp: here.")
    for _, site in ipairs({{"trader", "Trader"}, {"ferry", "Ferry Post"}, {"checkpoint", "Checkpoint"},
                           {"quarry", "The quarry (Institute)"}}) do
        if self.sites_known[site[1]] and self.sites[site[1]] then add(site[2] .. ": " .. self:site_bearing(site[1]) .. ".") end
    end
    local pd = self.peddler
    if pd and pd.seen_key then add("Peddler, last seen: " .. self:bearing_to(pd.seen_key) .. ".") end
    for key in pairs(self.stashes or {}) do add("Stash: " .. self:bearing_to(key) .. ".") end
    for key in pairs(self.snares or {}) do add("Snare: " .. self:bearing_to(key) .. ".") end
    for _, l in ipairs(self:little_lines()) do add(l) end
    if next(self.finds or {}) then
        add("")
        for _, l in ipairs(self:finds_lines()) do add(l) end
    end
    local out = {}
    for _, l in ipairs(lines) do
        for _, w in ipairs(#l > 55 and wrap(l, 55) or {l}) do out[#out + 1] = w end
    end
    return out
end

-- T on the map at camp, or T on the bag screen there: the camp screen.
function Game:open_camp()
    self.screen = "inventory"
    self.camp_view = true
    self.inv_cursor = 1
    self.inv_selected = nil
end
-- ---------------------------------------------------------------------
-- Quests: small jobs from the people of the Churn (texts and numbers in
-- QUESTS). One at a time: self.quest = {kind, giver, target, ...} (saved).
--   fetch  (the trader, O on the trade screen): bring an artifact back.
--   den    (the trader): kill the beast in a den a few hexes away.
--   drive  (the trader): bring a USB drive back.
--   supply (Anna, on the radio): have bandages on you when you call her.
--   notes  (Anna): the Surgeon's Notes, the same way.
--   crate  (a USB drive's map): an Institute crate; Lockpicks open it.
--   smoked (Mother Okun), sinew (Karl, on the radio): the new loot.
-- Some jobs have a deadline (QUESTS.due); each job done or lapsed moves your
-- standing with its giver (self.rep, QUESTS.rep), which changes prices,
-- Anna's wait and Karl's riddles.
--   dog    (Karl, after a right answer): find his lost dog by the river.
-- Targets get a "!" on the map and a line in the journal.
-- ---------------------------------------------------------------------

function Game:give_reward(list, why)
    local names = {}
    for _, it in ipairs(list) do
        local stack = {item = it[1], qty = it[2] or 1}
        if not self:put_stack("inventory", nil, stack) then self:put_stack("ground", nil, stack) end
        names[#names + 1] = ITEM_DB[it[1]].name .. ((it[2] or 1) > 1 and (" x" .. it[2]) or "")
    end
    self:sfx("gift")
    self:push_log(why .. " " .. table.concat(names, ", ") .. ".")
    self:rep_change(self.quest and self.quest.giver, 1)
    self.quest = nil
    self.quests_done = (self.quests_done or 0) + 1
end

-- A passable, non-site hex at distance near..far from you (or from the hex
-- `around`), optionally by water.
function Game:quest_spot(near, far, by_water, around)
    local p, taken, spots = self.player, {}, {}
    local oq, orr = p.q, p.r
    if around then oq, orr = Game.key_qr(around) end
    for _, k in pairs(self.sites) do taken[k] = true end
    if self.base then taken[self.base.key] = true end
    for key, t in pairs(self.tiles) do
        local q, r = Game.key_qr(key)
        local d = axial_distance(oq, orr, q, r)
        if TERRAIN[t].passable and d >= near and d <= far and not taken[key]
            and (self.rad[key] or 0) == 0 then
            if not by_water then
                spots[#spots + 1] = key
            else
                for _, n in ipairs(neighbors(self.tiles, q, r)) do
                    if self.tiles[hex_key(n[1], n[2])] == "water" then spots[#spots + 1] = key; break end
                end
            end
        end
    end
    if #spots == 0 then return nil end
    table.sort(spots)
    return spots[self:rand(#spots) + 1]
end

-- W on the trade screen: ask for work, or hand it in.
function Game:trader_work()
    local u, q = self.trade_ui, self.quest
    if q and q.kind == "drive" then
        if self:count_item("usb_drive") == 0 then
            u.msg = "'No drive, no deal.'"
            return
        end
        self:take_items("usb_drive", 1)
        local D = QUESTS.drive
        local reward = {D.reward[1], {D.part[self:rand(#D.part) + 1], 1}, D.reward[2]}
        self:give_reward(reward, "The trader pockets the drive. He pays:")
        u.msg = "'Bring me more if the Churn coughs them up.'"
        return
    end
    if q and q.kind == "fetch" then
        if self:artifact_count() == 0 then
            u.msg = "'Still waiting on that artifact.'"
            return
        end
        self:pay_artifacts(1)
        self:give_reward(QUESTS.fetch.reward, "The trader turns it over in his gloves. He pays:")
        u.msg = "'Good. Come back if you want more work.'"
        return
    end
    if q then
        u.msg = "'Finish the job you've got first.'"
        return
    end
    local pick = self:rand(3)
    if pick == 0 then
        self:set_quest({kind = "fetch", giver = "Trader"})
        u.msg = QUESTS.fetch.offer
    elseif pick == 1 then
        self:set_quest({kind = "drive", giver = "Trader"})
        u.msg = QUESTS.drive.offer
    else
        local key = self:quest_spot(QUESTS.den.near, QUESTS.den.far)
        if not key then u.msg = "'Nothing today.'"; return end
        self:set_quest({kind = "den", giver = "Trader", target = key})
        self.player.explored[key] = true
        u.msg = QUESTS.den.offer .. " (" .. self:bearing_to(key) .. ")"
    end
    self:push_log("Quest: " .. self:quest_text())
end

-- Her job (bandages or the notes) is done and in your bag (she answers
-- even while busy).
function Game:anna_ready()
    local q = self.quest
    if not (q and (q.kind == "supply" or q.kind == "notes")) then return false end
    local need = QUESTS[q.kind].need
    return self:count_item(need[1]) >= need[2]
end

-- Anna's channel: hands in her supply job (true: the call is spent), or
-- offers one when you're not hurt (free, like any call she doesn't answer).
function Game:anna_work()
    local q = self.quest
    if q and (q.kind == "supply" or q.kind == "notes") then
        if not self:anna_ready() then return false end
        local need = QUESTS[q.kind].need
        self:take_items(need[1], need[2])
        if self.story then self.story.anna = true end   -- (she'll help you at the gate)
        self:give_reward(QUESTS[q.kind].reward, "Anna: 'Bless you.' A runner leaves a parcel:")
        self:radio_say(q.kind == "notes"
            and "Anna: 'His hand. I knew him. Now somebody here can learn it. I've sent you something.'"
            or "Anna: 'Bless you. The children here will sleep tonight. I've sent you something.'")
        return "open"   -- her channel stays open afterwards
    end
    local p = self.player
    local hurt = p.health < MAX_HEALTH or p.injuries.bleeding or p.injuries.wounded_hours > 0
    if not q and not hurt then
        local kind = self:rand(2) == 0 and "notes" or "supply"
        self.quest = {kind = kind, giver = "Anna"}
        self:radio_say(QUESTS[kind].offer)
        self:push_log("Quest: " .. self:quest_text())
        return "offered"
    end
    return false
end

-- Karl, after a right answer: his dog ran off.
function Game:karl_work()
    if self.quest then return end
    local key = self:quest_spot(QUESTS.dog.near, QUESTS.dog.far, true)
    if not key then return end
    self.quest = {kind = "dog", giver = "Karl", target = key}
    self.player.explored[key] = true
    self:enc_say(QUESTS.dog.offer .. " (" .. self:bearing_to(key) .. ")")
    self:push_log("Quest: " .. self:quest_text())
end

-- Stepping onto a quest target (from try_move). True if it started a fight.
function Game:quest_arrive()
    local q = self.quest
    if not (q and q.target == hex_key(self.player.q, self.player.r)) then return false end
    if q.kind == "dog" then
        local reward = {{"pilk", 2}}
        for _, item in ipairs({"karls_waders", "karls_hat"}) do
            if not (self.karl_gave and self.karl_gave[item]) and not self:carrying(item) then
                reward = {{item, 1}}
                self.karl_gave = self.karl_gave or {}
                self.karl_gave[item] = true
                break
            end
        end
        self:sfx("bark")
        self:give_reward(reward, "Karl's old dog limps out of the reeds and licks your hand. "
            .. "Karl will be glad. Tied to its collar:")
        return false
    end
    if q.kind == "crate" or q.kind == "deep_crate" then return self:open_quest_crate() end
    if q.kind == "den" then
        local animals = ENCOUNTERS_BY_KIND.animal
        local base = animals[self:rand(#animals) + 1]
        local def = {}
        for k, v in pairs(base) do def[k] = v end
        def.hp = math.floor(base.hp * QUESTS.den.hp_mult)
        def.flees_at = nil
        def.den = true
        def.intro = "The den stinks of old blood. Something big is home. " .. base.intro
        self:start_encounter(def)
        return true
    end
    return false
end

-- When a den beast dies (from enemy_dies).
function Game:quest_kill()
    local q = self.quest
    if q and q.kind == "den" and self.enc and self.enc.def.den then
        local reward = {}
        for _, it in ipairs(QUESTS.den.reward) do
            if not self:carrying(it[1]) then reward[#reward + 1] = it end
        end
        if #reward == 0 then reward = {{"antirad", 2}} end
        self:give_reward({reward[1], {"canned_beans", 2}}, "The den is clear. The trader's payment:")
    end
end

function Game:quest_text()
    local q = self.quest
    if not q then return nil end
    local where = q.target and (" " .. self:bearing_to(q.target) .. ".") or ""
    local due = ""
    if q.due then
        local left = math.max(0, q.due - self.player.hours)
        due = left >= 24 and (" (%dd left)"):format(left // 24) or (" (%dh left)"):format(left)
    end
    return q.giver .. ": " .. QUESTS[q.kind].journal .. where .. due
end

-- A new job, with its deadline if the kind has one.
function Game:set_quest(q)
    local hours = QUESTS.due[q.kind]
    if hours then q.due = self.player.hours + hours end
    self.quest = q
    return q
end

-- From tick: a job past its deadline lapses (and the giver remembers).
function Game:quest_tick()
    local q = self.quest
    if not (q and q.due and self.player.hours > q.due) then return end
    self.quest = nil
    self:rep_change(q.giver, -1)
    self:push_log(QUESTS.lapsed[q.giver] or (q.giver .. " stopped waiting for you."))
end

-- -- standing --------------------------------------------------------------

function Game:rep_of(id)
    return (self.rep or {})[id] or 0
end

function Game:rep_change(giver, d)
    local R = QUESTS.rep
    local id = giver and R.giver[giver]
    if not id then return end
    self.rep = self.rep or {}
    self.rep[id] = math.max(R.min, math.min(R.max, self:rep_of(id) + d))
end

-- A trader's markup after your standing with them (who: "town", "ferry"...).
function Game:markup_for(who, markup)
    local R = QUESTS.rep
    local id = R.trade[who]
    if not id then return markup end
    return math.max(R.floor, markup * (1 - R.price * self:rep_of(id)))
end

-- "Standing: Trader +2  Okun -1" for the journal (nil while all are 0).
function Game:rep_text()
    local R, parts = QUESTS.rep, {}
    for _, id in ipairs(R.order) do
        local n = self:rep_of(id)
        if n ~= 0 then parts[#parts + 1] = ("%s %+d"):format(R.names[id], n) end
    end
    return #parts > 0 and ("Standing: " .. table.concat(parts, "  ")) or nil
end

-- -- Karl's job, on the radio ----------------------------------------------

-- His sinew is in your bag (he answers even before his wait is up).
function Game:karl_ready()
    local q, need = self.quest, QUESTS.sinew.need
    return q ~= nil and q.kind == "sinew" and self:count_item(need[1]) >= need[2]
end

-- A call to Karl: hands in his job, or now and then offers it. True if
-- that was the call (the forecast is skipped).
function Game:karl_radio_work()
    local S = QUESTS.sinew
    if self:karl_ready() then
        self:take_items(S.need[1], S.need[2])
        local first = not self.karl_lure
        self.karl_lure = true
        self:give_reward(first and S.reward or S.again, "A runner from Karl:")
        self:radio_say(S.thanks)
        return true
    end
    if not self.quest and self:rand(2) == 0 then
        self:set_quest({kind = "sinew", giver = "Karl"})
        self:radio_say(S.offer)
        self:push_log("Quest: " .. self:quest_text())
        return true
    end
    return false
end

-- A drive's map (pair_usb): a locked Institute crate a few hexes off.
function Game:mark_crate()
    if self.quest then return false end
    local C = QUESTS.crate
    local key = self:quest_spot(C.near, C.far)
    if not key then return false end
    self.quest = {kind = "crate", giver = "A USB drive", target = key}
    self.player.explored[key] = true
    self:push_log("A map on the drive: an Institute crate, " .. self:bearing_to(key) .. ".")
    return true
end

-- Standing on the marked crate: Lockpicks open it (the job stays till then).
-- The first one holds a map to a CLEARANCE crate by the quarry; that one an
-- Institute Pass (self.inst_chain: 1 = map found, 2 = opened).
function Game:open_quest_crate()
    local C, kind = QUESTS.crate, self.quest.kind
    if self:count_item("lockpicks") == 0 then
        self:push_log(C.locked)
        return false
    end
    self:lock_start(kind == "deep_crate" and CHURN.pick.deep_pins or CHURN.pick.pins,
                    function(g) g:quest_crate_opened() end)
    return true
end

-- The lock gave (64_lockpick): the Institute crate's contents, and what comes next.
function Game:quest_crate_opened()
    local C, kind = QUESTS.crate, self.quest.kind
    local found = {}
    for _ = 1, C.rolls do
        local item
        self.seed, item = weighted_pick(self.seed, CHURN.crate_loot)
        found[#found + 1] = self:drop_found(item)
    end
    self.quest = nil
    self.quests_done = (self.quests_done or 0) + 1
    self:sfx("gift")
    self:push_log("The lock gives. Inside: " .. table.concat(found, ", ") .. ". (I to pick up)")
    self:note_find(hex_key(self.player.q, self.player.r), "crate",
                   kind == "deep_crate" and "The CLEARANCE crate" or "An Institute crate", found)
    if kind == "deep_crate" then
        self.inst_chain = 2
        if not self:give_pass(nil, QUESTS.deep_crate.pass) then
            self:put_stack("ground", nil, {item = "antirad", qty = 2})
        end
    elseif (self.inst_chain or 0) == 0 and self.sites.quarry then
        local D = QUESTS.deep_crate
        local key = self:quest_spot(D.near, D.far, false, self.sites.quarry)
        if key then
            self.inst_chain = 1
            self.quest = {kind = "deep_crate", giver = "A second map", target = key}
            self.player.explored[key] = true
            self:push_log(D.found .. " (" .. self:bearing_to(key) .. ")")
        end
    end
    return false
end
-- ---------------------------------------------------------------------
-- Lore: torn pages that tell what happened here (LORE.pages, in order)
--
-- E on a Torn Page reads the next unread page (self.lore_read, saved);
-- the Signal on the radio gives one the first time. J then L opens the
-- reader. How much you've read changes the ending (lore_ending_line).
-- ---------------------------------------------------------------------

LORE = {
    pages = {
        {title = "Institute memo, day 0",
         text = "Instrument readings over the old quarry are 'within tolerance'. Staff are "
             .. "reminded that the hum is a transformer fault. Do not discuss the birds."},
        {title = "A driver's notebook",
         text = "Third run out to the Institute this week. They load crates at night now. "
             .. "One was warm. One was singing, I swear on my mother."},
        {title = "Radio log, 03:12",
         text = "- Say again, the sky over the quarry is what?\n- Purple. It's purple and "
             .. "it's breathing.\n- Breathing.\n- Get everyone inside. Everyone. Now."},
        {title = "The first emission",
         text = "Nobody outside lived. The ones in the cellars came up two days later and "
             .. "the fields had changed. The grass grew in spirals. The dogs came back wrong."},
        {title = "Evacuation order 14",
         text = "All residents will assemble at the school. Bring nothing. Do not bring pets. "
             .. "Do not bring anything that is warm to the touch."},
        {title = "Anna's diary",
         text = "They told the doctors to go. I stayed. Somebody has to sew up the fools who "
             .. "come back for the money. I keep a candle in the window. Nobody asks why."},
        {title = "Karl, written on a tackle box lid",
         text = "Fished this river forty years. Fish came back with too many eyes. Still bite "
             .. "at dusk. A river doesn't care what happened. That's the comfort of it."},
        {title = "The Checkpoint's standing orders",
         text = "No one leaves without paper. Confiscate all objects. Do not hold any object "
             .. "longer than necessary. If an object speaks, report to the sergeant."},
        {title = "A churner's last note",
         text = "Third artifact today. They're easy if you don't mind the dreams. I dream "
             .. "of a door in a field. Every night it's open a little wider."},
        {title = "Institute memo, day 400",
         text = "The broadcast on the old military band is not ours. It began the night of "
             .. "the first emission. It reads numbers. Lately it reads names."},
        {title = "The numbers",
         text = "We decoded it. They aren't coordinates. They're a count. It counts us, the "
             .. "ones still here, and every time it reads the list, it is shorter."},
        {title = "Unsigned, in the Checkpoint's tower",
         text = "The Churn isn't a wound. It's an eye opening. Everything we take out of it "
             .. "is something it lets us carry, so it can see where we go."},
    },
    -- the ending's last line, by pages read (first match from the top)
    ending = {
        {at = 9, text = "You know what the Signal counts now. As the barrier drops you "
            .. "hear it begin again, one name shorter. It doesn't say yours. Not yet."},
        {at = 4, text = "You've read enough to wonder what you're carrying out, and who "
            .. "is looking through it."},
    },
}

function Game:lore_count()
    return #(self.lore_read or {})
end

-- Read the next page. Returns false if there are none left.
function Game:read_lore(how)
    self.lore_read = self.lore_read or {}
    local n = #self.lore_read + 1
    local page = LORE.pages[n]
    if not page then
        self:push_log("Nothing new on it. You've read them all.")
        return false
    end
    self.lore_read[n] = true
    self:sfx("chime")
    self:push_log(("%s: '%s' (%d/%d, J then L)"):format(how or "A torn page", page.title, n, #LORE.pages))
    return true
end

function Game:lore_ending_line()
    local n = self:lore_count()
    for _, e in ipairs(LORE.ending) do
        if n >= e.at then return e.text end
    end
end

function Game:open_lore()
    if self:lore_count() == 0 then return end
    self.lore_page = math.min(self.lore_page or 1, self:lore_count())
    self.screen = "lore"
end

function Game:lore_key(key)
    local n = self:lore_count()
    if key == gfx.KEY_UP or key == KEY.W or key == gfx.KEY_LEFT or key == KEY.A then
        self.lore_page = math.max(1, self.lore_page - 1)
    elseif key == gfx.KEY_DOWN or key == KEY.S or key == gfx.KEY_RIGHT or key == KEY.D then
        self.lore_page = math.min(n, self.lore_page + 1)
    else
        self.screen = "journal"
    end
end

function Game:draw_lore(w, h)
    local page = LORE.pages[self.lore_page]
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    Game.ui_title(w, page.title)
    gfx.text(w - 60, 18, self.lore_page .. "/" .. self:lore_count())
    gfx.line(6, 26, w - 6, 26)
    local y = 48
    for para in (page.text .. "\n"):gmatch("(.-)\n") do   -- "\n" starts a new line
        for _, line in ipairs(wrap(para, 54)) do
            gfx.text(6, y, line)
            y = y + 16
        end
    end
    Game.ui_keys(w, h, "Up/Dn page  any key: back")
    gfx.refresh()
end
-- ---------------------------------------------------------------------
-- Night horrors (NIGHT in 05_data_world). Only after dark, never in the normal
-- encounter pick: maybe_horror runs on each move at night with its own
-- chance, halved by light in your hand or a fire on the hex, and never at a
-- camp with a bedroll.
--   The Long Man: look away (safe, costs rest), run, or speak to it.
--   The Crawler: a fight; without light your blows only half land, and a
--     torch at close range can drive it off.
--   The Whisperers: cover your ears, or follow the voice.
-- ---------------------------------------------------------------------

function Game:horror_chance()
    if not self:is_night() or self:bed_here() then return 0 end
    local chance = NIGHT.chance
    if self:has_light() then chance = chance / 2 end
    if self:fire_here() then chance = chance / 2 end
    if self:placed_here("salt_circle") then chance = chance / 4 end   -- the circle holds
    if self:carrying("black_candle") then chance = chance / 2 end
    return chance
end

function Game:maybe_horror()
    if not self:roll(self:horror_chance()) then return false end
    local def = NIGHT.horrors[self:rand(#NIGHT.horrors) + 1]
    self:start_encounter(def)
    self:sfx("emission")
    if self.little and self.little.n > 0 then
        self:enc_say("Your Little Ones go silent and stare into the dark.")
    end
    return true
end

-- Options for the two that don't fight.
function Game:horror_options(e)
    if e.def.horror == "long_man" then
        return {{"Look away", "look_away"}, {"Run", "flee"}, {"Speak to it", "speak"}}
    end
    return {{"Cover your ears", "cover"}, {"Follow the voice", "follow"}}
end

function Game:horror_action(action)
    local p, e = self.player, self.enc
    if action == "look_away" then
        p.needs.rest = clamp(p.needs.rest - NIGHT.dread_rest)
        self:enc_say("You stare at your boots until your eyes water. When you look up, the "
            .. "edge of the light is empty. You don't sleep well after that.")
        return self:end_encounter("It was gone when you looked up.")
    elseif action == "speak" then
        if self:roll(50) then
            local item = ARTIFACTS[self:rand(#ARTIFACTS) + 1]
            self:put_stack("ground", nil, {item = item, qty = 1})
            self:stat("artifacts")
            self:enc_say("It bends down, and down, and puts something in the grass at your feet. "
                .. "Then it isn't there.")
            return self:end_encounter("It left you a " .. ITEM_DB[item].name .. ".")
        end
        p.health = clamp(p.health - NIGHT.madness_hurt)
        self:enc_say("It answers. You don't remember what it said. Your nose is bleeding and "
            .. "your hands won't stop shaking. (-" .. NIGHT.madness_hurt .. " HP)")
        self:end_encounter("You spoke to it. You wish you hadn't.")
        return self:check_death("Something answered you in the dark.")
    elseif action == "cover" then
        p.needs.rest = clamp(p.needs.rest - NIGHT.whisper_rest)
        self:enc_say("You press your hands over your ears and hum until dawn. They know your "
            .. "name. They'll know it tomorrow too.")
        return self:end_encounter("You didn't listen to the river.")
    elseif action == "follow" then
        if self:roll(40 + 10 * (p.attrs.Perception - 3)) then
            self:mark_stash()
            self:enc_say("The voice leads you along the bank to a drowned man's pack. When you "
                .. "turn, the water is just water.")
            return self:end_encounter("The voices showed you something.")
        end
        p.health = clamp(p.health - NIGHT.follow_hurt)
        self:enc_say("You're waist-deep before you wake. Cold hands let go of your ankles. "
            .. "(-" .. NIGHT.follow_hurt .. " HP)")
        self:end_encounter("You nearly walked into the river.")
        return self:check_death("The river kept you.")
    end
end

-- The Crawler: blows in the dark only half land.
function Game:dark_damage(dmg)
    local e = self.enc
    if e and e.def.dark and not self:has_light() then return math.max(1, dmg // 2) end
    return dmg
end

-- The Crawler hates light: a torch at close range may drive it off.
function Game:dark_flees()
    local e = self.enc
    if not (e and e.def.dark and self:has_light() and e.range == "close") then return false end
    if not self:roll(NIGHT.light_drives_off) then return false end
    self:enc_say("You thrust the light at it. It shrieks and pours away into the dark.")
    e.outcome = "fled"
    self:end_encounter("The light drove it off.")
    return true
end
-- ---------------------------------------------------------------------
-- Skills that grow with use (numbers in SKILLS, 05_data_world)
--
-- self.skills = {skill -> XP} (saved). Doing a thing earns XP in its
-- skill (search, fish and hunt, fight, craft and repair); every threshold
-- in SKILLS.levels is a level, up to 5. Each level gives a small bonus
-- through skill_bonus at the place the roll is made: scavenge (fewer
-- duds), fish / hunt, attack / throw, repair_chance, and craft_hours.
-- ---------------------------------------------------------------------

function Game:skill_level(name)
    local xp, level = (self.skills or {})[name] or 0, 0
    for i, need in ipairs(SKILLS.levels) do
        if xp >= need then level = i end
    end
    return level
end

-- The skill's bonus in percent points (0 at level 0).
function Game:skill_bonus(name)
    return self:skill_level(name) * SKILLS.bonus[name]
end

function Game:skill_xp(name, n)
    self.skills = self.skills or {}
    local before = self:skill_level(name)
    self.skills[name] = (self.skills[name] or 0) + n
    local after = self:skill_level(name)
    if after > before then
        self:push_log(("%s improves to %d."):format(SKILLS.long[name], after))
        self:sfx("level")
    end
end

-- Hours a recipe takes: practised tinkerers are an hour quicker.
function Game:craft_hours(r)
    local h = r.hours
    if self:skill_level("tinker") >= SKILLS.fast_craft then h = h - 1 end
    if self:at_base() and self:base_has("bench") and not r.base then h = h - BASE.bench_hours end
    return math.max(1, h)
end

-- +% on fiddly work (guns, repairs) at the camp's workbench.
function Game:bench_bonus()
    return self:at_base() and self:base_has("bench") and BASE.bench_chance or 0
end

-- "Scav 2  Fish 1  Fight 3  Tinker 0" (journal).
function Game:skills_line()
    local parts = {}
    for _, name in ipairs(SKILLS.order) do
        parts[#parts + 1] = SKILLS.name[name] .. " " .. self:skill_level(name)
    end
    return "Skills: " .. table.concat(parts, "  ")
end

-- ---------------------------------------------------------------------
-- The skills page (K in the journal): each skill's level, XP and bonus,
-- then the recipes you know. Up/Down scroll when it's longer than the
-- screen; any other key goes back to the journal.
-- ---------------------------------------------------------------------

function Game:skills_page_lines()
    if self.page == "finds" then return self:finds_lines() end
    if self.page == "map" then return self:map_wall_lines() end
    if self.page == "bestiary" then return self:bestiary_lines() end
    local lines = {"Skill               Lv  XP       Bonus"}
    for _, name in ipairs(SKILLS.order) do
        local level, xp = self:skill_level(name), (self.skills or {})[name] or 0
        local next_xp = SKILLS.levels[level + 1]
        local bonus = SKILLS.what[name]:format(self:skill_bonus(name))
        if name == "tinker" and level >= SKILLS.fast_craft then bonus = bonus .. ", -1h craft" end
        lines[#lines + 1] = ("%-19s %d   %-8s %s"):format(SKILLS.long[name], level,
            next_xp and (xp .. "/" .. next_xp) or (xp .. " max"), bonus)
    end
    lines[#lines + 1] = ("Levels: %s XP. Tinker %d: craft 1h faster."):format(
        table.concat(SKILLS.levels, "/"), SKILLS.fast_craft)
    lines[#lines + 1] = ""
    local names = {}
    for _, r in ipairs(RECIPES) do
        if self.known[r.id] then names[#names + 1] = r.name end
    end
    lines[#lines + 1] = ("Recipes known: %d of %d"):format(#names, #RECIPES)
    for _, l in ipairs(wrap(#names > 0 and table.concat(names, ", ") or "None yet.", 55)) do
        lines[#lines + 1] = l
    end
    if #names < #RECIPES then lines[#lines + 1] = "Learn more: study, read notes, listen to tapes." end
    return lines
end

function Game:open_skills()
    self.skills_off, self.page = 0, nil
    self.screen = "skills"
end

function Game.skills_fit(h) return (h - 24 - 40) // 14 + 1 end

function Game:skills_key(key, h)
    local max_off = math.max(0, #self:skills_page_lines() - Game.skills_fit(h or 300))
    if key == gfx.KEY_UP or key == KEY.W then
        self.skills_off = math.max(0, (self.skills_off or 0) - 3)
    elseif key == gfx.KEY_DOWN or key == KEY.S then
        self.skills_off = math.min(max_off, (self.skills_off or 0) + 3)
    else
        self.screen = self.skills_back or "journal"
        self.skills_back = nil
    end
end

function Game:draw_skills(w, h)
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    Game.ui_title(w, ({finds = "Finds", map = "Map wall", bestiary = "Bestiary"})[self.page] or "Skills and recipes")
    local lines, fit = self:skills_page_lines(), Game.skills_fit(h)
    local off = math.max(0, math.min(self.skills_off or 0, #lines - fit))
    local y = 40
    for i = off + 1, math.min(#lines, off + fit) do
        gfx.text(6, y, lines[i])
        y = y + 14
    end
    Game.ui_keys(w, h, #lines > fit and "Up/Dn scroll  any key: back" or "Any key: back")
    gfx.refresh()
end
-- ---------------------------------------------------------------------
-- Run stats, lifetime records and achievements
--
-- self.stats counts this run (saved with it): kills, searches, artifacts
-- found, fish caught, riddles answered, repairs, night horrors lived
-- through. The lifetime records live in their own file next to the save,
-- <mount>/churn/records.lua, written whenever a run ends or an
-- achievement unlocks, so deleting a save (death, escape) keeps them.
-- Without write_file they last until the app is closed.
-- R on the title, creator, death and ending screens shows them.
-- ---------------------------------------------------------------------

local RECORDS = {
    file = "records.lua",
    data = nil,   -- the loaded records (Game.records)
    -- id, name, what it takes, test(game, how): how = "permit"/"bribe" when escaping
    list = {
        {"first_steps", "First Steps", "Live to see day 2",
         function(g) return (g:clock()) >= 2 end},
        {"week", "Week in the Churn", "Live to see day 8",
         function(g) return (g:clock()) >= 8 end},
        {"out", "Out", "Leave the Churn alive", function(_, how) return how ~= nil end},
        {"paper", "Paper Trail", "Leave with a Churn Permit",
         function(_, how) return how == "permit" end},
        {"bribed", "Bribed", "Buy your way out", function(_, how) return how == "bribe" end},
        {"hardened", "Churn-Hardened", "Leave on Churn-Hardened",
         function(g, how) return how ~= nil and g.difficulty == "hard" end},
        {"dog", "Dog's Best Friend", "Tame a stray", function(g) return g.dog ~= nil end},
        {"karl", "Karl's Friend", "Answer Karl 3 riddles in a run",
         function(g) return g:stat_of("riddles") >= 3 end},
        {"archivist", "Archivist", "Read every torn page",
         function(g) return g:lore_count() >= #LORE.pages end},
        {"fixer", "Fixer", "Repair a broken device", function(g) return g:stat_of("repairs") >= 1 end},
        {"homeowner", "Homeowner", "Build all four camp parts",
         function(g)
             if not g.base then return false end
             for _, part in ipairs({"box", "bedroll", "barrel", "barricade"}) do   -- (the first four)
                 if not g.base.built[part] then return false end
             end
             return true
         end},
        {"quiet", "The Quiet", "Silence the Signal", function(_, how) return how == "quiet" end},
        {"night_owl", "Night Owl", "Live through 3 night horrors",
         function(g) return g:stat_of("horrors") >= 3 end},
    },
}

function Game:stat(name, n)
    self.stats = self.stats or {}
    self.stats[name] = (self.stats[name] or 0) + (n or 1)
end

function Game:stat_of(name)
    return (self.stats or {})[name] or 0
end

local function records_path()
    local dir = SAVE.path()
    return dir, dir and (dir .. "/" .. RECORDS.file)
end

-- The lifetime records, read from storage the first time.
function Game.records()
    if RECORDS.data then return RECORDS.data end
    local rec
    local storage = solaros.storage
    local _, path = records_path()
    if path and storage and storage.read_file then
        -- (or the old folder's, or the `.new` copy a cut-short save left)
        local text = SAVE.read_any(RECORDS.file, 16384, function(t) return t end)
        local ok = text ~= nil
        local chunk = ok and type(text) == "string" and text ~= "" and load("return " .. text, "=records", "t", {})
        local good, data = false, nil
        if chunk then good, data = pcall(chunk) end
        if good and type(data) == "table" then
            rec = data
        elseif ok and type(text) == "string" and text ~= "" then
            -- unreadable (cut short by a power loss?): keep a copy before the
            -- next write replaces it
            RECORDS.bad_text = text
        end
    end
    RECORDS.data = Game.clean_records(rec or {})
    return RECORDS.data
end

-- Whatever the file held, a records table the game can use: counts are
-- whole numbers >= 0, tables are tables, the best escape a real difficulty.
function Game.clean_records(rec)
    local function count(v)
        v = math.tointeger(tonumber(v) or 0) or 0
        return v > 0 and v or 0
    end
    local out = {runs = count(rec.runs), escapes = count(rec.escapes), kills = count(rec.kills),
                 longest = count(rec.longest), most_out = count(rec.most_out),
                 deaths = {}, achieved = {}, counted = {}}
    if type(rec.deaths) == "table" then
        for why, n in pairs(rec.deaths) do
            if type(why) == "string" and count(n) > 0 then out.deaths[why] = count(n) end
        end
    end
    if type(rec.achieved) == "table" then
        for id, on in pairs(rec.achieved) do
            if type(id) == "string" and on == true then out.achieved[id] = true end
        end
    end
    if type(rec.counted) == "table" then
        for _, id in ipairs(rec.counted) do
            if type(id) == "string" then out.counted[#out.counted + 1] = id end
        end
    end
    if type(rec.best_escape) == "string" and DIFFICULTY[rec.best_escape] then
        out.best_escape = rec.best_escape
    end
    -- what's left of your last body (64_legacy): stacks of real items only
    local leg = rec.legacy
    if type(leg) == "table" and type(leg.items) == "table" then
        local items = {}
        for _, s in ipairs(leg.items) do
            if type(s) == "table" and type(s.item) == "string" and ITEM_DB[s.item] and count(s.qty) > 0 then
                items[#items + 1] = {item = s.item, qty = count(s.qty)}
            end
        end
        if #items > 0 then
            out.legacy = {items = items, cause = type(leg.cause) == "string" and leg.cause or "You died.",
                          day = count(leg.day)}
        end
    end
    return out
end

-- Forget the loaded records (tests: read them back from storage).
function Game.reload_records()
    RECORDS.data = nil
end

function Game.write_records()
    if not SAVE.can_write() then return false end
    local dir, path = records_path()
    return pcall(function()
        if solaros.storage.makedirs then solaros.storage.makedirs(dir) end
        if RECORDS.bad_text then   -- the unreadable old file, kept once
            solaros.storage.write_file(dir .. "/records.bad.lua", RECORDS.bad_text)
            RECORDS.bad_text = nil
        end
        SAVE.write(path, table.concat(SAVE.serialize(Game.records(), {})))
    end)
end

-- Unlock what this run has earned (from tick, and when the run ends).
function Game:check_achievements(how, no_write)
    local rec, new = Game.records(), false
    for _, a in ipairs(RECORDS.list) do
        if not rec.achieved[a[1]] and a[4](self, how) then
            rec.achieved[a[1]] = true
            self.run_unlocked = (self.run_unlocked or 0) + 1
            self:push_log("Achievement: " .. a[2] .. "!")
            self:sfx("achieve")
            new = true
        end
    end
    if new and not no_write then Game.write_records() end
end

-- A run is over: how = "permit"/"bribe" for an escape, nil for a death.
function Game:record_run(how, cause)
    if self.run_recorded then return end
    self.run_recorded = true
    local rec, p, best = Game.records(), self.player, {}
    -- a run is counted once, even if its save survives and is continued
    local id = self.run_id or tostring(self.world_seed)   -- (saves from before run ids)
    for _, seen in ipairs(rec.counted) do
        if seen == id then return end
    end
    table.insert(rec.counted, id)
    while #rec.counted > 20 do table.remove(rec.counted, 1) end
    rec.runs = rec.runs + 1
    rec.kills = rec.kills + self:stat_of("kills")
    if p.hours > rec.longest then
        if rec.runs > 1 then best[#best + 1] = "longest run" end
        rec.longest = p.hours
    end
    if how then
        rec.escapes = rec.escapes + 1
        local out = self:artifact_count()
        if out > rec.most_out then
            if rec.most_out > 0 then best[#best + 1] = "most artifacts out" end
            rec.most_out = out
        end
        local order = {easy = 1, normal = 2, hard = 3}
        if (order[self.difficulty] or 0) > (order[rec.best_escape] or 0) then
            rec.best_escape = self.difficulty
        end
    else
        local why = cause or "Unknown"
        rec.deaths[why] = (rec.deaths[why] or 0) + 1
    end
    self.run_best = best
    self:check_achievements(how, true)
    Game.write_records()
end

-- A few lines for the death and ending screens.
function Game:run_summary()
    local p = self.player
    local day = self:clock()
    local seen = 0
    for _ in pairs(p.explored or {}) do seen = seen + 1 end
    local lines = {
        ("Day %d, %d hours. Kills %d. Hexes seen %d."):format(day, p.hours, self:stat_of("kills"), seen),
        ("Searches %d. Artifacts found %d. Fish %d. Pages %d."):format(self:stat_of("searches"),
            self:stat_of("artifacts"), self:stat_of("fish"), self:lore_count()),
    }
    if self.run_best and #self.run_best > 0 then
        lines[#lines + 1] = "New record: " .. table.concat(self.run_best, ", ") .. "!"
    end
    if (self.run_unlocked or 0) > 0 then
        lines[#lines + 1] = ("Achievements this run: %d. (R to see them)"):format(self.run_unlocked)
    end
    return lines
end

-- -- the records screen ---------------------------------------------------

function Game:open_records()
    self.records_back = self.screen
    self.screen = "records"
end

function Game:records_key()
    self.screen = self.records_back or "title"
end

function Game:records_lines()
    local rec = Game.records()
    local deaths, worst, worst_n = 0, nil, 0
    for why, n in pairs(rec.deaths) do
        deaths = deaths + n
        if n > worst_n or (n == worst_n and worst and why < worst) then worst, worst_n = why, n end
    end
    local lines = {
        ("Runs %d   Escapes %d   Deaths %d"):format(rec.runs, rec.escapes, deaths),
        ("Longest run %dh   Most artifacts out %d"):format(rec.longest, rec.most_out),
        ("Kills, all runs %d   Best escape: %s"):format(rec.kills,
            rec.best_escape and DIFFICULTY[rec.best_escape].short or "none"),
    }
    if worst then lines[#lines + 1] = "Most deaths: " .. worst end
    return lines
end

function Game:draw_records(w, h)
    local rec = Game.records()
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    Game.ui_title(w, "Records")
    local y = 40
    for _, line in ipairs(self:records_lines()) do
        gfx.text(6, y, line:sub(1, 56))
        y = y + 14
    end
    local got = 0
    for _, a in ipairs(RECORDS.list) do
        if rec.achieved[a[1]] then got = got + 1 end
    end
    y = y + 8
    gfx.font(gfx.FONT_BOLD_14)
    gfx.text(6, y, ("Achievements %d/%d"):format(got, #RECORDS.list))
    gfx.font(gfx.FONT_MONO_12)
    y = y + 18
    -- only the ones you've earned: the rest stay a surprise
    for _, a in ipairs(RECORDS.list) do
        if rec.achieved[a[1]] then
            gfx.text(6, y, a[2])
            gfx.text(170, y, a[3])
            y = y + 12
        end
    end
    if got == 0 then
        gfx.text(6, y, "None yet.")
        y = y + 12
    end
    if got < #RECORDS.list then
        gfx.text(6, y + 2, ("%d more to find."):format(#RECORDS.list - got))
    end
    if not SAVE.can_write() then gfx.text(6, h - 22, "(not saved: this SolarOS can't write files)") end
    Game.ui_keys(w, h, "Any key: back")
    gfx.refresh()
end
-- ---------------------------------------------------------------------
-- The Little Ones (numbers in LITTLE, 05_data_world)
--
-- The Churn's children, grown small, pale and huge-eyed (art/little.jpg). They live in
-- warrens in the woods and hills and are never hostile, only mischievous.
-- Trinkets (toys, crayons, buttons: worth nothing to anyone else) left at
-- their cairns befriend them; with enough gifts a troupe follows you from
-- a warren. self.little = {friend, n, mood, mood_hour, hidden, seen}
-- (saved). Warrens and cairns come from Game.place_extras (extras.warrens,
-- extras.cairns).
-- ---------------------------------------------------------------------

LITTLE.def = {kind = "little", name = "The Little Ones", art = "little",
              who = "little ones", intro = LITTLE.intro, start = "near", speed = 6}

function Game.new_little()
    return {friend = 0, n = 0, mood = 0, mood_hour = 0, seen = {}}
end

-- "warren", "cairn" or nil for a hex.
function Game:little_spot(key)
    local x = self.extras or {}
    for _, k in ipairs(x.warrens or {}) do if k == key then return "warren" end end
    for _, k in ipairs(x.cairns or {}) do if k == key then return "cairn" end end
    return nil
end

function Game:first_trinket()
    for _, s in ipairs(self.player.inventory) do
        if ITEM_DB[s.item].trinket then return s.item end
    end
    return nil
end

-- How many follow for this many gifts (0 before join_at).
function Game.troupe_size(friend)
    if friend < LITTLE.join_at then return 0 end
    return math.min(LITTLE.max, 1 + (friend - LITTLE.join_at) // LITTLE.per_extra)
end

-- One unit out of your bag (not the ground or your hands, unlike take_items).
function Game:take_from_bag(item)
    local inv = self.player.inventory
    for i, s in ipairs(inv) do
        if s.item == item then
            s.qty = s.qty - 1
            if s.qty <= 0 then table.remove(inv, i) end
            return true
        end
    end
    return false
end

-- A trinket given (at a cairn, or to them at a warren).
function Game:gift_little(item, points)
    local l = self.little
    self:take_from_bag(item)
    l.friend = l.friend + (points or 1)
    if l.n > 0 then
        l.mood = math.min(LITTLE.mood_max, l.mood + LITTLE.mood_per_gift)
        l.mood_hour = self.player.hours
        local more = Game.troupe_size(l.friend)
        if more > l.n then
            l.n = more
            self:push_log("Another Little One falls in behind you, staring.")
        end
    end
end

-- E (or T) at a cairn: leave a trinket on the stones.
function Game:offer_trinket(item)
    item = item or self:first_trinket()
    if not item then
        self:push_log("Nothing to leave. They like toys.")
        return false
    end
    local name = ITEM_DB[item].name:lower()
    self:gift_little(item)
    self:push_log(("You set the %s on the stones. Something giggles in the grass."):format(name))
    self:sfx("chime")
    return true
end

function Game:little_join()
    local l = self.little
    l.n = Game.troupe_size(l.friend)
    l.mood, l.mood_hour = LITTLE.mood_start, self.player.hours
    self:sfx("gift")
    self:push_log(l.n == 1 and "A Little One creeps out of the burrow and follows you, giggling."
        or ("%d Little Ones tumble out of the burrow and follow you."):format(l.n))
end

-- Warrens and cairns in sight are remembered (from spot_sites).
function Game:spot_little()
    local l, vis = self.little, self.player.visible
    for _, kind in ipairs({"warrens", "cairns"}) do
        for _, k in ipairs((self.extras or {})[kind] or {}) do
            if vis[k] and not l.seen[k] then
                l.seen[k] = true
                if kind == "warrens" then self:queue_scene("little_ones") end
                self:push_log(kind == "warrens" and ("A burrow under a mound, " .. self:bearing_to(k) .. ". Giggling.")
                    or ("A little cairn of stones, " .. self:bearing_to(k) .. "."))
            end
        end
    end
end

-- After a move (from try_move). True if it started an encounter.
function Game:little_arrive()
    local key = hex_key(self.player.q, self.player.r)
    local spot = self:little_spot(key)
    if not spot then return false end
    local l = self.little
    l.seen[key] = true
    if spot == "warren" then self:queue_scene("little_ones") end
    if spot == "cairn" then
        self:push_log("A little cairn of stones, a shell on top. Toys left here are gone.")
        return false
    end
    if l.n > 0 then
        self:push_log("Your Little Ones dive into the burrow and tumble out again.")
        return false
    end
    if Game.troupe_size(l.friend) > 0 then
        self:little_join()
        return false
    end
    self:start_encounter(LITTLE.def)
    return true
end

-- -- what a following troupe gets up to ----------------------------------------

function Game:little_find(hour)
    local p = self.player
    local item
    if self:roll(LITTLE.find_trinket) then
        item = LITTLE.trinkets[self:rand(#LITTLE.trinkets) + 1]
    else
        local loot = SCAVENGE_LOOT[self.tiles[hex_key(p.q, p.r)]] or SCAVENGE_LOOT.plains
        local table_ = {}
        for _, e in ipairs(loot) do
            if e[1] ~= "nothing" then table_[#table_ + 1] = e end
        end
        self.seed, item = weighted_pick(self.seed, table_)
    end
    self:put_stack("ground", nil, {item = item, qty = 1})
    self:push_log("A Little One drops " .. ITEM_DB[item].name:lower() .. " at your feet and runs off giggling.")
end

-- Hide one small thing: only odds and ends - never what you eat or drink,
-- wear, heal with, work with, or what gets you out of the Churn.
function Game:little_mischief(hour)
    local p, l = self.player, self.little
    local options = {}
    for _, s in ipairs(p.inventory) do
        local def = ITEM_DB[s.item]
        if not def.artifact and not def.consumable and not def.slot and not LITTLE.keep[s.item] then
            options[#options + 1] = s.item
        end
    end
    if #options == 0 or l.hidden then return end
    local item = options[self:rand(#options) + 1]
    self:take_from_bag(item)
    if self:roll(LITTLE.back_chance) then
        local b = LITTLE.back_hours
        l.hidden = {item = item, back = hour + b[1] + self:rand(b[2] - b[1] + 1)}
    end
    self:push_log("Your " .. ITEM_DB[item].name:lower() .. " is gone. Giggling, somewhere close.")
end

-- One hour with the troupe (from tick).
function Game:little_hour(hour)
    local l, p = self.little, self.player
    if not l then return end
    if l.hidden and hour >= l.hidden.back then
        self:put_stack("ground", nil, {item = l.hidden.item, qty = 1})
        self:push_log("Your " .. ITEM_DB[l.hidden.item].name:lower() .. " is back, on the ground at your feet.")
        l.hidden = nil
    end
    if l.n <= 0 then return end
    if hour - l.mood_hour >= LITTLE.decay_hours then
        l.mood, l.mood_hour = l.mood - 1, hour
        if l.mood <= 0 then
            l.n, l.friend = 0, LITTLE.join_at - 1   -- one more gift wins them back
            self:push_log("Your Little Ones get bored of you and wander home.")
            return
        end
    end
    if hour % LITTLE.act_every ~= 0 then return end
    if self:roll(LITTLE.find) then
        self:little_find(hour)
    elseif self:roll(LITTLE.mischief) then
        self:little_mischief(hour)
    elseif self:is_night(hour) and self:roll(LITTLE.keep_awake) then
        p.needs.rest = clamp(p.needs.rest - LITTLE.awake_rest)
        self:push_log("The Little Ones giggle half the night away.")
    end
end

-- In a fight: they pelt it with stones (true if that killed it).
function Game:little_turn()
    local l, e = self.little, self.enc
    if not l or l.n <= 0 or e.over or e.def.kind == "horror" then return false end
    if not self:roll(LITTLE.pebble) then return false end
    local d, dmg = LITTLE.pebble_dmg, 0
    for _ = 1, l.n do dmg = dmg + d[1] + self:rand(d[2] - d[1] + 1) end
    e.hp = e.hp - dmg
    self:enc_say(("The Little Ones pelt the %s with stones (-%d)."):format(e.def.who, dmg))
    if e.hp <= 0 then
        self:enemy_dies()
        return true
    end
    return false
end

-- % added to running away: they make a racket; horrors they flee from with you.
function Game:little_flee_bonus()
    local l, e = self.little, self.enc
    if not l or l.n <= 0 then return 0 end
    return (e and e.def.kind == "horror") and LITTLE.horror_run or LITTLE.flee_bonus
end

-- -- meeting them at a warren (kind "little") --------------------------------

function Game:little_options()
    local o = {{"Watch them", "watch_little"}}
    if self:first_trinket() then o[#o + 1] = {"Offer a trinket", "offer_little"} end
    o[#o + 1] = {"Shoo them away", "shoo_little"}
    return o
end

function Game:little_action(action)
    local l = self.little
    if action == "watch_little" then
        self:enc_say("They watch you back. One waves. Another picks its teeth with a bird bone. "
            .. "Then they're gone.")
        return self:end_encounter("The Little Ones went back underground.")
    elseif action == "offer_little" then
        local item = self:first_trinket()
        self:gift_little(item, 2)
        self:enc_say("A small blotched hand snatches the " .. ITEM_DB[item].name:lower()
            .. ". Delighted shrieking under the ground.")
        if l.n == 0 and Game.troupe_size(l.friend) > 0 then
            self:end_encounter()
            self:little_join()
            return
        end
        return self:end_encounter("The Little Ones liked that.")
    else   -- shoo: they take something and vanish
        local before = #self.player.inventory
        self:little_mischief(self.player.hours)
        self:enc_say(#self.player.inventory ~= before and "They scatter, and something of yours goes with them."
            or "They scatter, giggling.")
        return self:end_encounter("The Little Ones scattered.")
    end
end

-- Journal lines.
function Game:little_lines()
    local l, out = self.little, {}
    if not l then return out end
    local moods = {"sulky", "sulky", "restless", "restless", "content", "content", "happy",
                   "happy", "delighted", "delighted"}
    if l.n > 0 then
        out[1] = ("Little Ones: %d following, %s."):format(l.n, moods[math.max(1, math.min(10, l.mood))])
    elseif l.friend > 0 then
        out[1] = ("Little Ones: %d trinket%s given (%d befriends them)."):format(
            l.friend, l.friend == 1 and "" or "s", LITTLE.join_at)
    end
    local p, best, best_d = self.player, nil, nil
    for key in pairs(l.seen) do
        if self:little_spot(key) == "cairn" then
            local q, r = Game.key_qr(key)
            local d = axial_distance(p.q, p.r, q, r)
            if not best_d or d < best_d then best, best_d = key, d end
        end
    end
    if best then out[#out + 1] = "Nearest cairn: " .. self:bearing_to(best) .. "." end
    return out
end
-- ---------------------------------------------------------------------
-- The storyline: what the Signal counts (numbers and texts in QUESTS.story)
--
-- self.story = {step, calls, anna, warned, pass, retry_at, lab_searched,
-- read_count} (saved). Inside: QUESTS.story.rooms, walked in order (enc.room).
--   step nil      -> "quarry": read QUESTS.story.pages torn pages, or call the
--                    Signal signal_calls times. The quarry (sites.quarry,
--                    from Game.place_extras) goes in the journal.
--   "quarry"      -> "gate": walk to the quarry; the gate needs a pass.
--   "gate"        -> "source": Karl gives his son's old pass for a right
--                    answer, or Anna sends it if you did her bandage job.
--   "source"      -> T at the gate: the Institute (kind "institute"):
--                    shut it down (a Multitool, a Tinker/Perception roll)
--                    and walk out into "the Quiet" (an escape, how =
--                    "quiet"); listen to it (every page, then you join the
--                    count); or leave.
-- ---------------------------------------------------------------------

function Game.new_story()
    return {calls = 0}
end

-- Starts the story when enough is known (from tick).
function Game:story_check()
    local st = self.story
    if not st or st.step or not self.sites.quarry then return end
    if self:lore_count() >= QUESTS.story.pages or st.calls >= QUESTS.story.signal_calls then
        st.step = "quarry"
        self:learn_site("quarry")
        self:push_log("It all points one way: the old quarry, " .. self:site_bearing("quarry") .. ".")
        self:sfx("emission")
    end
end

-- Arriving at the quarry (from arrive_site).
function Game:quarry_arrive()
    local st = self.story
    self:learn_site("quarry")
    self:queue_scene("the_gate")
    if st.step == "quarry" then st.step = "gate" end
    if self:count_item("institute_pass") > 0 and st.step == "gate" then st.step = "source" end
    if st.step == "source" then
        self:push_log("The Institute's gate. Your pass fits the slot. T.")
    elseif st.step == "gate" then
        self:push_log("Chained steel door: INSTITUTE. A card slot. Wants a pass.")
    else
        self:push_log("A chained steel door in the quarry wall. It hums.")
    end
    return true
end

-- Karl or Anna hands over the pass (once); or `text` says where it was found.
function Game:give_pass(who, text)
    local st = self.story
    if st.pass then return false end
    st.pass = true
    if not self:put_stack("inventory", nil, {item = "institute_pass", qty = 1}) then
        self:put_stack("ground", nil, {item = "institute_pass", qty = 1})
    end
    if st.step == "gate" then st.step = "source" end
    self:sfx("gift")
    self:push_log(text or (who .. " gave you an Institute Pass."))
    return true
end

-- Karl, after a right answer while the gate is shut.
function Game:story_karl()
    local st = self.story
    if st and st.step == "gate" and not st.pass then
        self:enc_say("Karl goes quiet. He takes a laminated card from his tackle box. "
            .. "'My boy's. He worked there. Didn't come back. You might.'")
        return self:give_pass("Karl")
    end
    return false
end

-- Anna on the radio, if you helped her: the pass (that's the whole call).
function Game:story_anna()
    local st = self.story
    if st and st.step == "gate" and st.anna and not st.pass then
        self:radio_say("Anna: 'You're going anyway. My brother's pass. A runner's bringing it. "
            .. "Come back out, love.'")
        return self:give_pass("Anna's runner")
    end
    return false
end

-- Her warning, once the story has begun: said after whatever else she said
-- on this call (so it never costs you her help). True if she said it.
function Game:story_anna_warning(said_before)
    local st = self.story
    if not st or not st.step or st.warned then return false end
    st.warned = true
    local text = "Anna: 'My brother worked at the Institute. Don't go.'"
    local u = self.radio_ui
    if said_before and u.msg ~= said_before then
        for _, line in ipairs(wrap(text, 54)) do u.msg[#u.msg + 1] = line end
    else
        self:radio_say(text)
    end
    return true
end

-- T at the quarry.
function Game:open_institute()
    local st = self.story
    if self:count_item("institute_pass") == 0 then
        self:push_log("The gate is sealed. It wants a pass.")
        return
    end
    if st.retry_at and self.player.hours < st.retry_at then
        self:push_log(("Your hands still shake. Try again in %dh."):format(st.retry_at - self.player.hours))
        return
    end
    self:start_encounter({kind = "institute", name = "The Institute", art = "institute",
                          who = "institute", intro = QUESTS.story.intro, start = "close", speed = 0})
    self:institute_room(1)
end

-- Into room i (QUESTS.story.rooms): its name and text replace the screen's.
function Game:institute_room(i)
    local e, room = self.enc, QUESTS.story.rooms[i]
    e.room = i
    e.def.name = room.name
    e.intro = wrap(room.text, ENC_INTRO_COLS)
    e.msg, e.cursor = {}, 1
end

function Game:shutdown_chance()
    return math.max(5, math.min(95, QUESTS.story.shut_base + QUESTS.story.shut_per_point * (self.player.attrs.Perception - 3)
        + 2 * self:skill_bonus("tinker")))
end

function Game:institute_options()
    local rooms, e = QUESTS.story.rooms, self.enc
    local i = e.room or #rooms
    if i < #rooms then
        local o = {{i == 1 and "Go down" or "Go deeper", "deeper_institute"}}
        if rooms[i].loot and not self.story.lab_searched then o[#o + 1] = {"Search the lab", "search_institute"} end
        if rooms[i].read and not e.read then o[#o + 1] = {"Read the count", "read_institute"} end
        o[#o + 1] = {"Leave", "leave_quietly"}
        return o
    end
    local tool = self:carrying(TECH.tool)
    return {{tool and ("Shut it down (" .. self:shutdown_chance() .. "%)") or "Shut it down (needs a Multitool)",
             "shut_institute"},
            {"Listen to it", "listen_institute"},
            {"Leave", "leave_quietly"}}
end

function Game:institute_action(action)
    local p, st = self.player, self.story
    local rooms, e = QUESTS.story.rooms, self.enc
    if action == "deeper_institute" then
        self:institute_room((e.room or 1) + 1)
        p.rads = math.min(RAD.max, (p.rads or 0) + QUESTS.story.room_rads)
        return
    elseif action == "search_institute" then
        local room = rooms[e.room]
        st.lab_searched = true
        for _, it in ipairs(room.loot) do self:put_stack("ground", nil, {item = it[1], qty = it[2]}) end
        self:enc_say(room.search)
        self:enc_say("(On the floor: a lab book, chemicals, Anti-Rad. I to pick up, after.)")
        return
    elseif action == "read_institute" then
        local room = rooms[e.room]
        e.read = true
        p.needs.rest = math.max(0, p.needs.rest - room.cost)
        self:enc_say(room.read .. (self.vesna == "found" and room.vesna or ""))
        if not st.read_count then
            st.read_count = true
            self.research = self.research or {}
            self.research.warding = (self.research.warding or 0) + CHURN.study.base * 2
        end
        return
    elseif action == "shut_institute" then
        if not self:carrying(TECH.tool) then
            self:enc_say("The panel is all screws and fused wire. Not with your bare hands.")
            return
        end
        if self:roll(self:shutdown_chance()) then
            self:skill_xp("tinker", SKILLS.xp.repaired)
            st.step = "done"
            self.enc = nil
            return self:finish_run("quiet")
        end
        p.rads = math.min(RAD.max, (p.rads or 0) + QUESTS.story.fail_rads)
        st.retry_at = p.hours + QUESTS.story.retry_hours
        self:enc_say("A spark, a smell of hot copper, and the light swells. You're thrown back "
            .. "up the stair, teeth aching." .. (self:can_measure() and (" (+" .. QUESTS.story.fail_rads .. " rads)") or ""))
        return self:end_encounter("The Institute threw you out.")
    elseif action == "listen_institute" then
        self.lore_read = {}
        for i = 1, #LORE.pages do self.lore_read[i] = true end
        self.death_note = "You listen. You understand all of it at once: the pages, the count, the eye. "
            .. "And then you hear your own name, and it doesn't stop."
        p.health = 0
        self.enc = nil
        self:check_death("You joined the count.")
    end
end

-- Journal line.
function Game:story_text()
    local st = self.story
    if not st or not st.step or st.step == "done" or not self.sites.quarry then return nil end
    local j = QUESTS.story.journal
    if st.step == "quarry" then return j.quarry:format(self:site_bearing("quarry")) end
    if st.step == "gate" then return j.gate end
    return j.source:format(self:site_bearing("quarry"))
end
-- ---------------------------------------------------------------------
-- Research: how the Churn's recipes are learned (numbers in CHURN, 08).
--
-- Almost nothing is known at the start. Each recipe belongs to a topic
-- (Tailoring, Bushcraft, Medicine, Tinkering, Chemistry, Gunsmithing,
-- Warding) and a topic's recipes are learned in RECIPES order, by:
--   * studying at a fire or your camp (crafting screen, "Study: <topic>"):
--     hours for points, more with the topic's book in reach;
--   * reading a book (E): its topic's next recipe, the first time;
--   * playing a cassette (E, with a charged Cassette Player): one recipe
--     and a dead churner's voice;
--   * pairing a USB drive with the LoRa Radio (E): one or two recipes from
--     what's on it, sometimes a stash or the way out;
--   * Scrawled Notes, as before: a random recipe.
-- self.research = {topic -> points}, self.books_read = {book -> true},
-- self.tapedeck = {charge} (saved).
-- Also here: the other new things you use with E, and lockpicked crates.
-- ---------------------------------------------------------------------

function Game.topic_def(id)
    for _, t in ipairs(CHURN.topics) do if t.id == id then return t end end
end

-- The next recipe the topic would teach, and how many of it you know.
function Game:topic_next(topic)
    local known = 0
    for _, r in ipairs(RECIPES) do
        if r.topic == topic then
            if self.known[r.id] then known = known + 1 else return r, known end
        end
    end
    return nil, known
end

-- Points a topic needs for its next recipe.
function Game:topic_need(topic)
    local _, known = self:topic_next(topic)
    return CHURN.study.need + CHURN.study.need_step * known
end

-- Learn the topic's next recipe (nil if there's none left).
function Game:learn_next(topic, how)
    local r = self:topic_next(topic)
    if not r then return nil end
    self.known[r.id] = true
    self:stat("learned")
    self:push_log((how or "You work it out") .. ": " .. r.name .. ".")
    return r
end

-- "Study: <topic>" entries for the crafting screen (topics with something left).
function Game:study_recipes()
    local list = {}
    for _, t in ipairs(CHURN.topics) do
        if self:topic_next(t.id) then
            list[#list + 1] = {id = "study_" .. t.id, name = "Study: " .. t.name, inputs = {},
                               hours = CHURN.study.hours, study = t.id}
        end
    end
    return list
end

function Game:study_text(topic)
    self.research = self.research or {}
    local r = self:topic_next(topic)
    return ("Research %d/%d%s"):format(self.research[topic] or 0, self:topic_need(topic),
                                       r and "" or " (done)")
end

function Game:study_blocker(topic)
    if not (self:fire_here() or self:at_base()) then return "Study by a fire or at your camp." end
    local t = Game.topic_def(topic)
    if t.needs then
        local have = false
        for _, id in ipairs(t.needs) do if self:count_item(id) > 0 then have = true end end
        if not have then
            local names = {}
            for i = 1, math.min(2, #t.needs) do names[i] = ITEM_DB[t.needs[i]].name end
            return "Nothing to study it from (" .. table.concat(names, ", ") .. "...)."
        end
    end
    return nil
end

-- Study points for one session.
function Game:study_points(topic)
    local S, t = CHURN.study, Game.topic_def(topic)
    local pts = math.max(1, S.base + S.per_point * (self.player.attrs.Perception - 3)
                            + self:skill_bonus("tinker") // 5)
    if t.book and self:count_item(t.book) > 0 then pts = pts * S.book_mult end
    return pts
end

function Game:study(topic)
    local p, t = self.player, Game.topic_def(topic)
    self.research = self.research or {}
    local hours = CHURN.study.hours
    p.hours = p.hours + hours
    apply_awake_hours(p, hours)
    if t.cost then p.needs.rest = math.max(0, p.needs.rest - t.cost) end
    local pts = self:study_points(topic)
    self.research[topic] = (self.research[topic] or 0) + pts
    self:skill_xp("tinker", SKILLS.xp.craft)
    local need = self:topic_need(topic)
    if self.research[topic] >= need then
        self.research[topic] = self.research[topic] - need
        self:sfx("gift")
        self:learn_next(topic, "Hours of " .. t.name:lower() .. " pay off")
    else
        self:push_log(("You study %s for %dh. (%d/%d)"):format(t.name:lower(), hours,
                                                              self.research[topic], need))
    end
    if t.cost then self:push_log("It leaves you hollow. (-" .. t.cost .. " rest)") end
    return true
end

-- E on a book: the first read of each book teaches its topic's next recipe
-- (later reads still give study points, at a fire or not).
function Game:read_book(item)
    local p, def = self.player, ITEM_DB[item]
    local topic, t = def.book, Game.topic_def(def.book)
    self.books_read = self.books_read or {}
    self.research = self.research or {}
    p.hours = p.hours + CHURN.study.read_hours
    apply_awake_hours(p, CHURN.study.read_hours)
    if t.cost then p.needs.rest = math.max(0, p.needs.rest - t.cost) end
    if not self.books_read[item] then
        self.books_read[item] = true
        if self:learn_next(topic, "From the " .. def.name) then return end
    end
    if not self:topic_next(topic) then
        self:push_log("You know everything in the " .. def.name .. ".")
        return
    end
    self.research[topic] = (self.research[topic] or 0) + CHURN.study.base
    self:push_log(("You reread the %s. (%s %d/%d)"):format(def.name, t.name, self.research[topic],
                                                         self:topic_need(topic)))
end

-- E on a cassette: needs a charged player in reach. The tape plays once.
function Game:play_tape(item)
    local tape = CHURN.tapes[item]
    if self:count_item("cassette_player") == 0 then
        self:push_log("You need a Cassette Player to hear it.")
        return false
    end
    self.tapedeck = self.tapedeck or {charge = 0}
    if self.tapedeck.charge <= 0 then
        self:push_log("The player is dead. A Battery Cell (E) would wake it.")
        return false
    end
    self:dread(CHURN.dread.tape)   -- (a human voice in the dark: it helps)
    self.tapedeck.charge = self.tapedeck.charge - 1
    if item == "tape_vesna" and not self.vesna then self.vesna = "heard" end   -- (find_corpse)
    local p = self.player
    p.hours = p.hours + CHURN.study.tape_hours
    apply_awake_hours(p, CHURN.study.tape_hours)
    self:push_log(tape.voice:sub(1, 60) .. "...")
    self.last_tape = tape.voice   -- (the journal shows it whole)
    if not self:learn_next(tape.topic, "From the tape") then
        self:push_log("Nothing on it you didn't know.")
    end
    if self:rand(3) == 0 then self:mark_stash() end
    return true
end

-- E on a USB drive: the radio reads it (a charge). Sometimes it fails.
function Game:pair_usb()
    if not (self:carrying("lora_radio") and self.radio) then
        self:push_log("Nothing to read it with. A LoRa Radio could.")
        return false
    end
    if self.radio.charge <= 0 then
        self:push_log("The radio has no charge to read it.")
        return false
    end
    self.radio.charge = self.radio.charge - 1
    local p = self.player
    p.hours = p.hours + CHURN.study.usb_hours
    apply_awake_hours(p, CHURN.study.usb_hours)
    if self:roll(CHURN.study.usb_fail - self:skill_bonus("tinker")) then
        self:push_log("The radio chokes on it: corrupt. Try again later.")
        return false
    end
    local topics = CHURN.usb_topics
    local learned = 0
    for _ = 1, 1 + self:rand(2) do
        local topic = topics[self:rand(#topics) + 1]
        if self:learn_next(topic, "Off the drive") then learned = learned + 1 end
    end
    if not self.sites_known.checkpoint and self:rand(3) == 0 then
        self:hear_of_exit("A map on the drive")
    elseif self:roll(QUESTS.crate.chance) and self:mark_crate() then
        -- (the crate is the job now)
    elseif self:rand(3) == 0 then
        self:mark_stash()
    elseif learned == 0 then
        self:push_log("Photos of a family. A field that isn't there any more.")
    end
    return true
end

-- E on a Battery Cell or Choir Cell: the radio first, then the tape player.
function Game:charge_tapedeck(full)
    if self:count_item("cassette_player") == 0 then return false end
    self.tapedeck = self.tapedeck or {charge = 0}
    if self.tapedeck.charge >= CHURN.study.tape_max then
        self:push_log("The cassette player is charged.")
        return false
    end
    self.tapedeck.charge = CHURN.study.tape_max
    self:push_log("The cassette player clicks and whirs. (" .. CHURN.study.tape_max .. " tapes)")
    return true
end

-- The new things E does; true if it handled the item.
function Game:use_churn_item(kind, k, stack)
    local p, item, def = self.player, stack.item, ITEM_DB[stack.item]
    local key = hex_key(p.q, p.r)
    if def.book then
        self:read_book(item)
    elseif CHURN.tapes[item] then
        if self:play_tape(item) then
            self:use_one(kind, k, stack)
            local blank = {item = "blank_tape", qty = 1}
            if not self:put_stack("inventory", nil, blank) then self:put_stack("ground", nil, blank) end
        end
    elseif item == "usb_drive" then
        if self:pair_usb() then self:use_one(kind, k, stack) end
    elseif item == "battery_cell" and self:count_item("cassette_player") > 0
           and not (self:carrying("lora_radio") and self.radio and self.radio.charge < TECH.radio_max) then
        if self:charge_tapedeck() then self:use_one(kind, k, stack) end
    elseif item == "choir_cell" then
        local any = false
        if self:carrying("lora_radio") and self.radio then self.radio.charge = TECH.radio_max; any = true end
        if self:charge_tapedeck() then any = true end
        if any then
            self:use_one(kind, k, stack)
            self:push_log("The Choir Cell sings, and everything you carry wakes.")
        else
            self:push_log("Nothing here to charge.")
        end
    elseif item == "stitches" then
        if not p.injuries.bleeding and p.injuries.wounded_hours <= 0 then
            self:push_log("No wound to stitch.")
            return true
        end
        p.injuries.bleeding = false
        p.injuries.wounded_hours = math.max(0, p.injuries.wounded_hours // 2 - 6)
        p.health = math.min(MAX_HEALTH, p.health + 10)
        self:use_one(kind, k, stack)
        self:push_log("You stitch it shut, teeth gritted. (+10 HP)")
    elseif item == "painkillers" then
        p.health = math.min(MAX_HEALTH, p.health + 12)
        self:use_one(kind, k, stack)
        self:push_log("The edges go soft. (+12 HP)")
    elseif item == "can_rattle" or item == "tarp_shelter" or item == "salt_circle" then
        self.placed = self.placed or {}
        self.placed[key] = self.placed[key] or {}
        if self.placed[key][item] then
            self:push_log("There's one here already.")
            return true
        end
        self.placed[key][item] = true
        self:use_one(kind, k, stack)
        self:push_log(({can_rattle = "You string the cans round the camp. Anything coming will ring them.",
                        tarp_shelter = "You pitch the lean-to. Cover from the weather, here.",
                        salt_circle = "You pour the circle unbroken. Here, the dark has to knock."})[item])
    else
        return false
    end
    return true
end

-- Something placed on this hex (E on a can rattle, lean-to, salt circle).
function Game:placed_here(item)
    local here = self.placed and self.placed[hex_key(self.player.q, self.player.r)]
    return here ~= nil and here[item] == true
end

-- F in ruins with Lockpicks: some hexes hide a locked crate (once a hex).
function Game:pick_crate(key)
    if self.tiles[key] ~= "ruins" or self:count_item("lockpicks") == 0 then return end
    self.crates = self.crates or {}
    if self.crates[key] == "locked" then   -- (one you left, or broke a pick on)
        return self:lock_start(CHURN.pick.pins, function(g) g:open_crate(key) end)
    end
    if self.crates[key] then return end
    self.crates[key] = true
    if not self:roll(CHURN.crate_chance + self:skill_bonus("scav")) then return end
    self.crates[key] = "locked"
    self:push_log("Under the rubble: a locked crate. You get out the picks.")
    self:lock_start(CHURN.pick.pins, function(g) g:open_crate(key) end)
end

-- The lock gave (64_lockpick): what's inside.
function Game:open_crate(key)
    self.crates[key] = true
    local found = {}
    for _ = 1, 2 do
        local item
        self.seed, item = weighted_pick(self.seed, CHURN.crate_loot)
        found[#found + 1] = self:drop_found(item)
    end
    self:push_log("You pick a locked crate: " .. table.concat(found, ", ") .. ".")
    self:note_find(key, "crate", "A locked crate", found)
end

-- F in ruins: now and then (CHURN.corpse.chance %, once a hex) a dead churner,
-- with what they carried for the Churn: tapes, books, drives, gun parts.
function Game:find_corpse(key)
    local C = CHURN.corpse
    if self.tiles[key] ~= "ruins" then return end
    self.crates = self.crates or {}
    local mark = C.prefix .. key
    if self.crates[mark] then return end
    local seeking = self.vesna == "heard"   -- (her tape: she's out there, up some stair)
    if not self:roll(C.chance * (seeking and CHURN.vesna.mult or 1)) then return end
    self.crates[mark] = true
    if seeking then return self:find_vesna(key) end
    local found = {}
    for _ = 1, 1 + self:rand(2) do
        local item
        self.seed, item = weighted_pick(self.seed, C.loot)
        found[#found + 1] = self:drop_found(item, C.rounds[item] and C.rounds[item] + self:rand(3))
    end
    self:dread(CHURN.dread.corpse)
    self:push_log(C.epitaphs[self:rand(#C.epitaphs) + 1])
    self:push_log("On them: " .. table.concat(found, ", ") .. ".")
    self:note_find(key, "corpse", "A dead churner", found)
end

-- The churner from the tape: what she took up the stairs.
function Game:find_vesna(key)
    self.vesna = "found"
    self:dread(CHURN.dread.vesna)
    self:queue_scene("vesna")
    local names = {}
    for _, it in ipairs(CHURN.vesna.loot) do
        self:put_stack("ground", nil, {item = it[1], qty = it[2]})
        names[#names + 1] = ITEM_DB[it[1]].name
    end
    self:push_log(CHURN.vesna.epitaph)
    self:push_log("On her: " .. table.concat(names, ", ") .. ".")
    self:note_find(key, "corpse", "Vesna, from the tape", names)
end

-- -- finds: dead churners and opened crates, on the map and the Finds page --
-- self.finds = {key -> {kind = "corpse"/"crate", label, day, what}} (saved).

function Game:note_find(key, kind, label, what)
    self.finds = self.finds or {}
    self.finds[key] = {kind = kind, label = label, day = (self:clock(self.player.hours)),
                       what = table.concat(what or {}, ", ")}
end

-- The Finds page (F in the journal): oldest first, where, and what was there.
function Game:finds_lines()
    local list = {}
    for key, f in pairs(self.finds or {}) do list[#list + 1] = {key = key, f = f} end
    table.sort(list, function(a, b)
        if a.f.day ~= b.f.day then return a.f.day < b.f.day end
        return a.key < b.key
    end)
    -- (every line wrapped to the page: 55 columns)
    if #list == 0 then return wrap("Nothing yet. Dead churners and the crates you open go here.", 55) end
    local lines = {}
    for _, e in ipairs(list) do
        local head = ("Day %d  %s, %s"):format(e.f.day, e.f.label, self:bearing_to(e.key))
        for _, l in ipairs(#head > 55 and wrap(head, 55) or {head}) do lines[#lines + 1] = l end
        if e.f.what ~= "" then
            for _, l in ipairs(wrap(e.f.what, 52)) do lines[#lines + 1] = "   " .. l end
        end
    end
    return lines
end

function Game:open_finds()
    self.skills_off, self.page = 0, "finds"
    self.screen = "skills"   -- (the same scrolling page)
end

-- Equip slots sit ON the body part they dress, NEO Scavenger style: a box over
-- the head, the face, the torso, the legs, a hand... sized to that part, with
-- the worn item painted onto the body and its icon drawn inside the box.
-- {x, y, w, h} authored against the figure at center x 150 / head top y 72,
-- then shifted with it (BODY_DX/BODY_DY below). Boxes never touch each other.
local EQUIP_RECT = {
    head   = {139,  64, 22, 18},   -- top of the head (a hat sits here)
    ears   = {118,  84, 20, 18},   -- against the side of the head
    eyes   = {140,  84, 20, 18},   -- the face
    neck   = {140, 105, 20, 18},   -- throat / collar
    jacket = {116, 126, 68, 38},   -- chest and shoulders
    shirt  = {124, 167, 52, 22},   -- belly
    belt   = {124, 192, 52, 17},   -- the waist
    hands  = { 73, 212, 22, 22},   -- gloves: the left forearm and hand
    wrists = {205, 212, 22, 22},   -- the right wrist
    lhand  = { 70, 236, 24, 24},   -- held in the left hand (anything)
    rhand  = {206, 236, 24, 24},   -- held in the right hand (anything)
    back   = {230, 118, 40, 40},   -- worn on the back, drawn beside the shoulder
    pants  = {122, 212, 56, 52},   -- hips and legs
    feet   = {120, 267, 60, 20},   -- both feet
}
-- shown inside an empty slot; the long form when it fits the box
local EQUIP_NAME = {head = "Head", ears = "Ears", eyes = "Eyes", neck = "Neck",
                    jacket = "Jacket", shirt = "Shirt", hands = "Gloves",
                    wrists = "Wrists", pants = "Pants", feet = "Feet",
                    lhand = "L Hand", rhand = "R Hand", back = "Back", belt = "Belt"}
local EQUIP_ABBR = {head = "Hd", ears = "Ea", eyes = "Ey", neck = "Nk", jacket = "Jk",
                    shirt = "Sh", hands = "Gl", wrists = "Wr", pants = "Pt", feet = "Ft",
                    lhand = "LH", rhand = "RH", back = "Bk", belt = "Bt"}
-- where the doll sits on the 400x300 screen: the left column, head at the top
local BODY_DX, BODY_DY = -66, -46
for _, r in pairs(EQUIP_RECT) do r[1], r[2] = r[1] + BODY_DX, r[2] + BODY_DY end

-- right column (from INV_COL_X): ground grid, bag grid with its name and
-- fill count above it, then what the cursor is on
local INV_COL_X = 212
local GROUND_GRID_COLS = 5
local GROUND_GRID_ROWS = 2   -- visible rows; the grid scrolls to follow the cursor
local GROUND_CELL, GROUND_GAP = 30, 2
local GROUND_Y = 32
-- bag: up to BACKPACK_CAP cells, all visible (with a bag on, your pockets
-- start a row of their own, framed in gray)
local BACKPACK_COLS = 8
local BACKPACK_CELL, BACKPACK_GAP = 20, 2
local BACKPACK_Y = 114
local BAG_LABEL_Y = BACKPACK_Y - 5
local CURSOR_DESC_Y = 210
local CONDITIONS_Y = 264     -- full width, under the doll
-- log lines sit on the last lines of the reported screen height
local INV_LOG_LINES = 2
-- the camp screen's slots (BASE.slots, 6 a row) in the doll's place:
-- {x0, y0, cell, column step, row step}, a label under each cell
local CAMP_GRID = {6, 26, 30, 34, 48}

local function item_abbr(item_id)
    return ITEM_DB[item_id].name:sub(1, 1)
end

function Game:current_conditions()
    -- Only conditions we actually track - nothing fabricated (no injury/
    -- temperature model exists yet, so none are listed here).
    local list = {}
    if self.player.equipped.feet == nil then table.insert(list, "Barefoot") end
    if (self.player.cold_hours or 0) > 0 then table.insert(list, "Cold") end
    if self.player.needs.hunger <= 0 then table.insert(list, "Starving") end
    if self.player.needs.thirst <= 0 then table.insert(list, "Dehydrated") end
    if self.player.needs.rest <= 0 then table.insert(list, "Exhausted") end
    if self.player.injuries.bleeding then table.insert(list, "Bleeding") end
    if self.player.injuries.wounded_hours > 0 then table.insert(list, "Wounded") end
    if self.player.health < 50 then table.insert(list, "Hurt") end
    local _, worst = self:most_worn(1)
    if worst and worst <= 0 then table.insert(list, "Torn clothes") end
    if (self.player.sick_hours or 0) > 0 then table.insert(list, "Sick") end
    local rad_stage = RAD.stages[self:rad_stage()]
    if rad_stage then table.insert(list, self:can_measure() and rad_stage.name or rad_stage.feel) end
    local dread = self:dread_name()
    if dread then table.insert(list, dread) end
    if #list == 0 then return "Conditions: none" end
    local text = table.concat(list, ", ")
    -- all four at once don't fit after the prefix (mono 12 is ~7px/char)
    if (12 + #text) * 7 > 392 then return text end
    return "Conditions: " .. text
end

function Game:draw_slot_box(x, y, w, h, stack, is_cursor, is_selected, pocket)
    if stack and stack.item then
        gfx.color(gfx.LIGHT)
        gfx.fill_rect(x, y, w, h)
        gfx.color(gfx.BLACK)
        local sprite = SPRITES[stack.item]
        if sprite and draw_sprite then
            -- center the 16x16 icon in the slot (// keeps coordinates integers)
            draw_sprite(x + (w - SPRITE_W) // 2, y + (h - SPRITE_H) // 2,
                        SPRITE_W, SPRITE_H, sprite)
        else
            gfx.font(gfx.FONT_MONO_12)
            gfx.text(x + 3, y + h - 5, item_abbr(stack.item))
        end
        if stack.qty and stack.qty > 1 then
            gfx.font(gfx.FONT_MONO_12)
            -- bottom-right corner, right-aligned (mono 12 is ~7px per char), so
            -- it stays clear of the centered 16x16 icon and inside the box
            local qty_text = tostring(stack.qty)
            if #qty_text > 2 or (#qty_text > 1 and w < 24) then   -- (on paper, so it reads over the icon)
                gfx.color(gfx.WHITE)
                gfx.fill_rect(x + w - 3 - 7 * #qty_text, y + h - 11, 7 * #qty_text + 2, 10)
                gfx.color(gfx.BLACK)
            end
            gfx.text(x + w - 2 - 7 * #qty_text, y + h - 2, qty_text)
        end
    end
    gfx.color(pocket and gfx.DARK or gfx.BLACK)   -- (a pocket: a gray frame)
    gfx.rect(x, y, w, h)
    gfx.color(gfx.BLACK)
    if is_selected then
        gfx.rect(x - 2, y - 2, w + 4, h + 4)
    elseif is_cursor then
        gfx.rect(x - 1, y - 1, w + 2, h + 2)
    end
end

-- ---------------------------------------------------------------------
-- Paperdoll silhouette
--
-- gfx has no polygon fill, so the body is described as polygons (points are
-- offsets from the body's center line), rasterized ONCE at load into
-- horizontal blocks (runs of identical rows merged into one tall rect), and
-- drawn with fill_rect. Drawing the union in black expanded by 1px and then in
-- gray at true size gives a clean 1px outline around the whole figure, so
-- overlapping parts (arm meeting torso) don't leave internal seams.
-- ---------------------------------------------------------------------

local BODY_CX = 150 + BODY_DX
-- The figure is authored in the coordinates below (head top at y 117, feet at
-- 289) and scaled by BODY_SCALE about its top, landing at BODY_Y0.
local BODY_SCALE, BODY_SRC_Y0, BODY_Y0 = 1.25, 117, 72 + BODY_DY
local BODY_TOP = BODY_Y0
local BODY_BOTTOM = BODY_Y0 + math.ceil((289 - BODY_SRC_Y0) * BODY_SCALE)   -- exclusive

-- The polygons and the rasterizer only run here, once, so they live in a
-- do-block: the bundle is one Lua chunk with a 200-local limit, and only
-- the finished blocks are needed afterwards.
local BODY_BLOCKS, PART_BLOCKS = nil, {}
do
    local function mirror_x(pts)
        local out = {}
        for i = 1, #pts, 2 do
            out[i] = -pts[i]
            out[i + 1] = pts[i + 1]
        end
        return out
    end

    -- Build a full polygon from its right half (listed top to bottom, starting and
    -- ending on the center line) by appending the mirrored points in reverse.
    local function symmetric(right)
        local pts = {}
        for i = 1, #right do pts[i] = right[i] end
        for i = #right - 1, 1, -2 do
            pts[#pts + 1] = -right[i]
            pts[#pts + 1] = right[i + 1]
        end
        return pts
    end

    local function ellipse_points(cy, rx, ry, n)
        local pts = {}
        for i = 0, n - 1 do
            local a = 2 * math.pi * i / n
            pts[#pts + 1] = rx * math.cos(a)
            pts[#pts + 1] = cy + ry * math.sin(a)
        end
        return pts
    end

    local BODY_POLYGONS = {}
    local BODY_PART
    local function add_body_polygon(pts)
        local out = {}
        for i = 1, #pts, 2 do
            out[i] = pts[i] * BODY_SCALE
            out[i + 1] = BODY_Y0 + (pts[i + 1] - BODY_SRC_Y0) * BODY_SCALE
        end
        BODY_POLYGONS[#BODY_POLYGONS + 1] = out
    end

    -- head (which part each polygon is: BODY_PART[i], used to paint worn clothes)
    BODY_PART = {}
    local function add_part(part, pts)
        add_body_polygon(pts)
        BODY_PART[#BODY_POLYGONS] = part
    end
    add_part("head", ellipse_points(130, 11, 13, 28))
    -- neck, sloped shoulders, tapered torso down to the hips
    add_part("torso", symmetric({
        0, 139,  4, 139,  4, 146,  14, 148,  27, 151,  31, 156,  30, 164,
        25, 170,  22, 182,  19, 200,  21, 214,  23, 226,  0, 226,
    }))
    -- arms hang slightly away from the body and end in hands
    local ARM = {
        30, 151,  38, 154,  42, 175,  46, 195,  50, 215,  53, 230,
        56, 238,  56, 246,  52, 250,  48, 246,  47, 238,  47, 230,
        43, 215,  37, 195,  31, 178,  27, 166,  28, 158,
    }
    add_part("arms", ARM)
    add_part("arms", mirror_x(ARM))
    -- legs: thigh, knee, calf, ankle, and a foot angled outward
    local LEG = {
        1, 224,  23, 224,  22, 240,  20, 254,  18, 266,  15, 278,
        20, 284,  21, 288,  3, 288,  3, 282,  5, 270,  4, 254,  2, 240,
    }
    add_part("legs", LEG)
    add_part("legs", mirror_x(LEG))

    -- x-intervals [a, b) covered by one polygon on the pixel row whose center is yc
    local function polygon_row_spans(pts, yc)
        local xs = {}
        local n = #pts // 2
        for i = 1, n do
            local j = i % n + 1
            local x1, y1 = pts[2 * i - 1], pts[2 * i]
            local x2, y2 = pts[2 * j - 1], pts[2 * j]
            if y1 ~= y2 and ((y1 <= yc and yc < y2) or (y2 <= yc and yc < y1)) then
                xs[#xs + 1] = x1 + (yc - y1) * (x2 - x1) / (y2 - y1)
            end
        end
        table.sort(xs)
        local spans = {}
        for k = 1, #xs - 1, 2 do
            -- Pixel i is covered when its center (i + 0.5) lies strictly inside the
            -- edges. Strict on BOTH sides so an edge landing exactly on a pixel
            -- center is treated the same left and right - keeps the figure symmetric.
            local a = math.floor(BODY_CX + xs[k] - 0.5) + 1
            local b = math.ceil(BODY_CX + xs[k + 1] - 0.5)
            if b > a then spans[#spans + 1] = {a, b} end
        end
        return spans
    end

    -- part: only that body part's polygons (nil = the whole figure)
    local function build_body_blocks(part)
        local blocks, prev_key = {}, nil
        for y = BODY_TOP, BODY_BOTTOM - 1 do
            local all = {}
            for i, poly in ipairs(BODY_POLYGONS) do
                if part == nil or BODY_PART[i] == part then
                    for _, sp in ipairs(polygon_row_spans(poly, y + 0.5)) do
                        all[#all + 1] = sp
                    end
                end
            end
            table.sort(all, function(p, q) return p[1] < q[1] end)
            local merged = {}
            for _, sp in ipairs(all) do
                local last = merged[#merged]
                if last and sp[1] <= last[2] then
                    if sp[2] > last[2] then last[2] = sp[2] end
                else
                    merged[#merged + 1] = {sp[1], sp[2]}
                end
            end
            local parts = {}
            for _, m in ipairs(merged) do parts[#parts + 1] = m[1] .. "," .. m[2] end
            local key = table.concat(parts, ";")
            if key ~= "" and key == prev_key then
                blocks[#blocks].h = blocks[#blocks].h + 1
            elseif key ~= "" then
                blocks[#blocks + 1] = {y = y, h = 1, spans = merged}
            end
            prev_key = key
        end
        return blocks
    end

    BODY_BLOCKS = build_body_blocks()
    for _, part in ipairs({"head", "torso", "arms", "legs"}) do
        PART_BLOCKS[part] = build_body_blocks(part)
    end
end

local function body_row(src_y)
    return BODY_Y0 + math.floor((src_y - BODY_SRC_Y0) * BODY_SCALE + 0.5)
end

-- fill_rect cut to clip = {x0, y0, x1, y1} (exclusive), or plain without one:
-- the cursor-only redraw repaints just the doll under one slot.
local function fill_clipped(clip, x, y, w, h)
    if clip then
        local x0, y0 = math.max(x, clip[1]), math.max(y, clip[2])
        local x1, y1 = math.min(x + w, clip[3]), math.min(y + h, clip[4])
        if x1 <= x0 or y1 <= y0 then return end
        x, y, w, h = x0, y0, x1 - x0, y1 - y0
    end
    gfx.fill_rect(x, y, w, h)
end

-- Holes in a torn piece: 2x2 spots on a staggered grid (every 5 rows, 6
-- columns, alternate rows shifted 3), fixed to the screen so the holes line
-- up across body parts; in `hole_color` (the body shows through).
function Game.punch_holes(clip, x, y, w, h, hole_color, color)
    gfx.color(hole_color)
    local row = (y + 4) // 5
    for yy = row * 5, y + h - 2, 5 do
        local shift = (yy // 5) % 2 * 3
        local first = x + (shift - x) % 6
        for xx = first, x + w - 2, 6 do fill_clipped(clip, xx, yy, 2, 2) end
    end
    gfx.color(color)
end

-- Paint one body part between two authored rows (clothing on the doll).
-- inner/outer (optional, authored units) keep only the pixels whose distance
-- from the center line is in [inner, outer), on both sides. torn: with holes.
local function paint_part(part, src_y0, src_y1, color, inner, outer, clip, torn)
    local y0, y1 = body_row(src_y0), body_row(src_y1)
    local hole = color == gfx.LIGHT and gfx.WHITE or gfx.LIGHT
    local bands
    if outer then
        local i = math.floor(inner * BODY_SCALE + 0.5)
        local o = math.floor(outer * BODY_SCALE + 0.5)
        bands = {{BODY_CX - o, BODY_CX - i}, {BODY_CX + i, BODY_CX + o}}
    end
    gfx.color(color)
    for _, b in ipairs(PART_BLOCKS[part]) do
        local top, bottom = math.max(b.y, y0), math.min(b.y + b.h, y1)
        if bottom > top then
            for _, sp in ipairs(b.spans) do
                if bands then
                    for _, band in ipairs(bands) do
                        local a, z = math.max(sp[1], band[1]), math.min(sp[2], band[2])
                        if z > a then
                            fill_clipped(clip, a, top, z - a, bottom - top)
                            if torn then Game.punch_holes(clip, a, top, z - a, bottom - top, hole, color) end
                        end
                    end
                else
                    fill_clipped(clip, sp[1], top, sp[2] - sp[1], bottom - top)
                    if torn then Game.punch_holes(clip, sp[1], top, sp[2] - sp[1], bottom - top, hole, color) end
                end
            end
        end
    end
end

-- Draw order for painting worn items: under-layers before over-layers.
-- Held items (lhand/rhand) are never painted on, only shown in their box.
local WEAR_ORDER = {"shirt", "pants", "belt", "jacket", "back", "feet", "hands", "head", "neck",
                    "wrists", "eyes", "ears"}

-- clip (optional): only repaint inside {x0, y0, x1, y1}, on white.
function Game:draw_silhouette(clip)
    if clip then
        gfx.color(gfx.WHITE)
        gfx.fill_rect(clip[1], clip[2], clip[3] - clip[1], clip[4] - clip[2])
    end
    -- pass 1: outline (every block grown by 1px, black)
    gfx.color(gfx.BLACK)
    for _, b in ipairs(BODY_BLOCKS) do
        for _, sp in ipairs(b.spans) do
            fill_clipped(clip, sp[1] - 1, b.y - 1, sp[2] - sp[1] + 2, b.h + 2)
        end
    end
    -- pass 2: body fill at true size
    gfx.color(gfx.LIGHT)
    for _, b in ipairs(BODY_BLOCKS) do
        for _, sp in ipairs(b.spans) do
            fill_clipped(clip, sp[1], b.y, sp[2] - sp[1], b.h)
        end
    end
    -- pass 3: worn clothes painted onto the body, inner layers first
    for _, slot in ipairs(WEAR_ORDER) do
        local item = self.player.equipped[slot]
        local wear = item and ITEM_DB[item].wear
        if wear then
            local torn = self:torn(slot)
            for _, w in ipairs(wear) do
                paint_part(w[1], w[2], w[3], gfx[w[4]], w[5], w[6], clip, torn)
            end
        end
    end
end

-- A slot's frame on the doll (the cursor gets a solid one): one rect in
-- dark gray, which the 1-bit panel dithers into a broken line. (It was
-- drawn as 2px dashes - ~30 line calls a slot, most of the bag screen's
-- draw time on the device.)
local function dashed_rect(x, y, w, h)
    gfx.color(gfx.DARK)
    gfx.rect(x, y, w, h)
    gfx.color(gfx.BLACK)
end

local HALO = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}}

-- One paperdoll slot, framed by a dashed outline over the body part. Worn:
-- the clothes are already painted on the doll (draw_silhouette); the item's
-- icon sits on top. Empty: the slot's name on a small white tag so it reads
-- on the dithered gray.
function Game:draw_equip_slot(slot, x, y, w, h, is_cursor, is_selected)
    local item = self.player.equipped[slot]
    gfx.font(gfx.FONT_MONO_12)
    if item then
        -- the item sits on the (painted) body: black icon with a 1px white
        -- halo so it reads on any fill, inside the slot's dashed frame
        local sprite = SPRITES[item]
        local sx, sy = x + (w - SPRITE_W) // 2, y + (h - SPRITE_H) // 2
        if sprite and draw_sprite then
            gfx.color(gfx.WHITE)
            for _, d in ipairs(HALO) do
                draw_sprite(sx + d[1], sy + d[2], SPRITE_W, SPRITE_H, sprite)
            end
            gfx.color(gfx.BLACK)
            draw_sprite(sx, sy, SPRITE_W, SPRITE_H, sprite)
        else
            gfx.color(gfx.WHITE)
            gfx.fill_rect(sx + 3, sy + 2, 11, 13)
            gfx.color(gfx.BLACK)
            gfx.text(sx + 5, sy + 12, item_abbr(item))
        end
        gfx.color(gfx.BLACK)
        dashed_rect(x, y, w, h)
    else
        local label = EQUIP_NAME[slot]
        if 7 * #label + 4 > w then label = EQUIP_ABBR[slot] end
        local tw = 7 * #label
        local tx, ty = x + (w - tw) // 2, y + h // 2 + 4
        gfx.color(gfx.WHITE)
        gfx.fill_rect(tx - 1, ty - 9, tw + 2, 11)
        gfx.color(gfx.BLACK)
        gfx.text(tx, ty, label)
        dashed_rect(x, y, w, h)
    end
    if is_selected or is_cursor then
        -- white inner line keeps the cursor visible over black clothes
        gfx.color(gfx.WHITE)
        gfx.rect(x, y, w, h)
    end
    gfx.color(gfx.BLACK)
    if is_selected then
        gfx.rect(x - 2, y - 2, w + 4, h + 4)
        gfx.rect(x - 1, y - 1, w + 2, h + 2)
    elseif is_cursor then
        gfx.rect(x - 1, y - 1, w + 2, h + 2)
    end
end

-- One camp slot (the camp screen): its cell, and its label under it.
-- A slot that isn't built yet is a gray frame with "--"; the four info
-- slots show their state in words.
function Game:draw_camp_slot(id, x, y, w, h, is_cursor, is_selected)
    local slot = Game.camp_slot(id)
    local b = self.base
    gfx.font(gfx.FONT_MONO_12)
    local blocked = self:camp_slot_blocker(slot)
    local word
    if slot[4] == "info" and not blocked then
        if id == "barrel" then
            local n = 0
            for _, st in ipairs(self:camp_pile()) do if st.item == "water_bottle" then n = n + st.qty end end
            word = tostring(n)
        elseif id == "wall" then word = tostring(b.wall or BASE.wall_hp)
        elseif id == "box" then word = b.built.lockbox and "Lck" or "Box"
        else word = "Map" end
    elseif blocked then
        word = "--"
    end
    if word then
        gfx.color(gfx.WHITE)
        gfx.fill_rect(x, y, w, h)
        gfx.color(gfx.BLACK)
        gfx.text(x + (w - 7 * #word) // 2, y + h // 2 + 4, word)
        gfx.color(blocked and gfx.DARK or gfx.BLACK)
        gfx.rect(x, y, w, h)
        gfx.color(gfx.BLACK)
        if is_selected then gfx.rect(x - 2, y - 2, w + 4, h + 4)
        elseif is_cursor then gfx.rect(x - 1, y - 1, w + 2, h + 2) end
    else
        self:draw_slot_box(x, y, w, h, self:camp_stack(id), is_cursor, is_selected)
    end
    gfx.color(gfx.BLACK)
    gfx.text(x + (w - 7 * #slot[2]) // 2, y + h + 12, slot[2])
end

-- What the cursor is on, e.g. "Head: Cap" or "Bag: Rock x3".
function Game:cursor_description()
    local row = INV_ROWS[self.inv_cursor]
    if not row then return "" end
    local kind, key = row[1], row[2]
    local stack = self:get_stack(kind, key)
    local where = kind == "ground" and ((self:at_base() and self:base_has("box")) and "Box" or "Ground") or kind == "inventory" and "Bag"
        or kind == "camp" and Game.camp_slot(key)[3] or EQUIP_NAME[key]
    if not stack then return where .. ": empty" end
    local text = where .. ": " .. ITEM_DB[stack.item].name
    if stack.qty > 1 then text = text .. " x" .. stack.qty end
    return text .. Game.cond_text(stack.cond)
end

-- Which ground stack starts the visible window: scrolled so the cursor is
-- in view when it is on the ground grid.
function Game:ground_scroll(n_ground)
    local off = self.ground_off or 0
    if self.inv_cursor <= n_ground then
        local crow = (self.inv_cursor - 1) // GROUND_GRID_COLS
        local first = off // GROUND_GRID_COLS
        if crow < first then
            off = crow * GROUND_GRID_COLS
        elseif crow >= first + GROUND_GRID_ROWS then
            off = (crow - GROUND_GRID_ROWS + 1) * GROUND_GRID_COLS
        end
    end
    local total_rows = (n_ground + GROUND_GRID_COLS - 1) // GROUND_GRID_COLS
    return math.max(0, math.min(off, (total_rows - GROUND_GRID_ROWS) * GROUND_GRID_COLS))
end

-- Where cursor row i sits on screen ({x, y, w, h}). A ground cell scrolled
-- out of view has none drawn: it gets the spot it would have in the grid.
function Game:inv_row_pos(i)
    local pos, row = INV_POS[i], INV_ROWS[i]
    if pos or not row or row[1] ~= "ground" then return pos end
    local k = row[2] - (self.ground_off or 0) - 1
    return {x = INV_COL_X + 2 + k % GROUND_GRID_COLS * (GROUND_CELL + GROUND_GAP),
            y = GROUND_Y + k // GROUND_GRID_COLS * (GROUND_CELL + GROUND_GAP), w = GROUND_CELL, h = GROUND_CELL}
end

-- Arrow keys on the bag screen: the cursor goes to the nearest cell or slot
-- that way (dx, dy = -1/0/1), across the ground, the doll and the bag.
-- Nothing further that way: it wraps round to the far side.
function Game:inv_move(dx, dy)
    local cur = self.inv_cursor
    local row = INV_ROWS[cur]
    if not row then return end
    -- the ground grid scrolls: step through it by index first
    if row[1] == "ground" then
        local n, cols, i = 0, GROUND_GRID_COLS, row[2]
        for _, r in ipairs(INV_ROWS) do if r[1] == "ground" then n = n + 1 end end
        local t = i + dx + dy * cols
        if dx ~= 0 and (t - 1) // cols ~= (i - 1) // cols then t = nil end
        if dy > 0 and t and t > n and (n - 1) // cols > (i - 1) // cols then t = n end
        if t and t >= 1 and t <= n then
            self.inv_cursor = t   -- (ground rows come first: row index == ground index)
            return
        end
    end
    local p = self:inv_row_pos(cur)
    if not p then return end
    local cx, cy = p.x + p.w / 2, p.y + p.h / 2
    local best, best_score, wrap, wrap_score
    for i = 1, #INV_ROWS do
        local q = i ~= cur and INV_POS[i]
        if q then
            local vx, vy = q.x + q.w / 2 - cx, q.y + q.h / 2 - cy
            local along, across = vx * dx + vy * dy, math.abs(dx ~= 0 and vy or vx)
            if along > 0 and across <= 2 * along then   -- (roughly that way: within ~63 degrees)
                local score = along + 2 * across
                if not best_score or score < best_score then best, best_score = i, score end
            elseif along <= 0 then   -- the far side, as level as can be
                local score = 2 * across + along
                if not wrap_score or score < wrap_score then wrap, wrap_score = i, score end
            end
        end
    end
    self.inv_cursor = best or wrap or cur
end

-- X on the bag screen: what the cursor is on goes on the ground.
function Game:inv_drop()
    local row = INV_ROWS[self.inv_cursor]
    if not row or row[1] == "ground" or not self:get_stack(row[1], row[2]) then return false end
    self.inv_selected = nil
    return self:try_transfer({row[1], row[2]}, {"ground"})
end

-- Everything the bag screen shows except where the cursor is: when only the
-- cursor moved, the screen is patched instead of redrawn.
function Game:inv_signature()
    local camp = {}
    if self.camp_view and self.base then   -- (the camp's slots and state)
        camp[1] = self:camp_summary()
        for _, slot in ipairs(BASE.slots) do
            local st = self:camp_stack(slot[1])
            camp[#camp + 1] = st and (st.item .. st.qty) or "-"
        end
        for part in pairs(self.base.built) do camp[#camp + 1] = part end
    end
    local p, out = self.player, {self:current_conditions(), table.concat(self:inv_stats_lines(), "|"),
                                 table.concat(camp, ","),
                                 self.ground_off or 0, self:bag_capacity(),
                                 (self:at_base() and self:base_has("box")) and "box" or "ground"}
    for _, list in ipairs({self:ground_list(), p.inventory}) do
        for _, s in ipairs(list) do out[#out + 1] = s.item .. "x" .. s.qty end
        out[#out + 1] = "|"
    end
    for _, slot in ipairs(EQUIP_SLOTS) do out[#out + 1] = p.equipped[slot] or "-" end
    local sel = self.inv_selected
    out[#out + 1] = sel and (sel[1] .. ":" .. sel[2]) or "-"
    for _, line in ipairs(self.log) do out[#out + 1] = line end
    return table.concat(out, "\n")
end

-- Your numbers, under the cursor's lines: "Hunger 70 Thirst 60" and
-- "HP 85 Rest 80 Warm 3/5". Warmth is what you wear / what the weather,
-- season and night ask for (cold_need); by a fire or in your bedroll it
-- reads "fire" or "bed". Both lines fit the column at 3-digit values.
function Game:inv_stats_lines()
    local p = self.player
    local warm = self:fire_at(p.hours) and "fire" or self:bed_here() and "bed"
        or (self:warmth() .. "/" .. self:cold_need())
    return {("Hunger %d Thirst %d"):format(math.floor(p.needs.hunger), math.floor(p.needs.thirst)),
            ("HP %d Rest %d Warm %s"):format(math.floor(p.health), math.floor(p.needs.rest), warm)}
end

-- An item's numbers, short: "Warm 3, +2 cells", "12 dmg, close, bleed 30%",
-- "Hunger +40". nil when it has none. (Radiation only shows as a number
-- once you can measure it.)
function Game:item_stats(item)
    local d, out = ITEM_DB[item], {}
    local function add(s) out[#out + 1] = s end
    if (d.warmth or 0) > 0 then add("Warm " .. d.warmth) end
    if d.bag_cells then add(d.bag_cells .. " bag cells") end
    local cells = (d.pocket_cells or 0) + (d.belt_cells or 0)
    if cells > 0 then add("+" .. cells .. (cells > 1 and " cells" or " cell")) end
    if d.rad_armor then add(self:can_measure() and ("rads x" .. d.rad_armor) or "filters air") end
    if d.fx and d.fx.mp then add(d.fx.mp .. " MP") end
    if d.light then add("light") end
    if d.fish_bonus then add("fish +" .. d.fish_bonus .. "%") end
    if d.shoot then
        add("shot " .. d.shoot.dmg .. " dmg")
    elseif d.weapon then
        add(d.weapon.dmg .. " dmg, " .. (d.weapon.thrown and "thrown" or d.weapon.reach))
        if (d.weapon.bleed or 0) > 0 then add("bleed " .. d.weapon.bleed .. "%") end
    end
    for _, need in ipairs({"hunger", "thirst", "rest", "rads"}) do
        local v = d.consumable and d.consumable[need]
        if v and (need ~= "rads" or self:can_measure()) then
            add(need:sub(1, 1):upper() .. need:sub(2) .. " " .. (v > 0 and "+" or "") .. v)
        end
    end
    if #out == 0 then return nil end
    return table.concat(out, ", ")
end

-- What the cursor is on, its numbers and what it does, under the bag (at
-- most three lines), then your own numbers.
function Game:draw_inv_desc(w, clear)
    local top = CURSOR_DESC_Y - 7
    if clear then
        gfx.color(gfx.WHITE)
        gfx.fill_rect(INV_COL_X, top - 10, w - INV_COL_X, CONDITIONS_Y - top)
    end
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_MONO_12)
    local max_chars = (w - INV_COL_X - 2) // 7
    local row = INV_ROWS[self.inv_cursor]
    local stack = row and self:get_stack(row[1], row[2])
    local lines = wrap(self:cursor_description(), max_chars)
    if row and row[1] == "camp" then   -- (what the slot does, or is doing)
        for _, l in ipairs(wrap(self:camp_slot_text(row[2]), max_chars)) do lines[#lines + 1] = l end
    elseif row and row[1] == "inventory" and not stack then   -- (an empty cell: where the cells come from)
        for _, l in ipairs(wrap(self:bag_sum_text(), max_chars)) do lines[#lines + 1] = l end
    elseif stack then
        for _, text in ipairs({self:item_stats(stack.item) or false, ITEM_DB[stack.item].desc or false}) do
            if text then
                for _, l in ipairs(wrap(text, max_chars)) do lines[#lines + 1] = l end
            end
        end
    end
    for i = 1, math.min(3, #lines) do
        gfx.text(INV_COL_X, top + 12 * (i - 1), lines[i]:sub(1, max_chars))
    end
    -- your numbers, above the conditions (here because the erase above reaches them)
    for i, line in ipairs(self:inv_stats_lines()) do
        gfx.text(INV_COL_X, CONDITIONS_Y - 25 + 12 * (i - 1), line:sub(1, max_chars))
    end
end

-- The doll's pixels on the 1px ring just outside a slot, as runs
-- {color, x, y, w, h}: draw_silhouette is run once into a recorder (so it is
-- exactly what a full redraw paints there) and cached until the clothes change.
-- Cached drawings of the doll for what you wear now (reset when it changes).
function Game:doll_cache()
    local worn = {}   -- (only what is painted on the doll: not what's in your hands)
    for _, s in ipairs(WEAR_ORDER) do   -- (a torn piece looks different: "!")
        worn[#worn + 1] = (self.player.equipped[s] or "-") .. (self:torn(s) and "!" or "")
    end
    worn = table.concat(worn, ",")
    if not (self.ring_cache and self.ring_cache.worn == worn) then self.ring_cache = {worn = worn} end
    return self.ring_cache
end

-- The whole doll as 1-bit bitmap tiles, one set per color: {color, x, y,
-- w, h, data}. draw_silhouette's ~500-800 rects are replayed once into bit
-- planes and cut into 32x32 tiles (128 bytes, gfx.bitmap's limit); the
-- firmware dithers a bitmap exactly like a fill_rect of the same color, so
-- ~60-80 calls draw the same picture.
function Game:doll_tiles()
    local cache = self:doll_cache()
    if cache.tiles then return cache.tiles end
    local x0, y0, x1, y1 = 1e9, BODY_TOP - 1, -1e9, BODY_BOTTOM + 1
    for _, b in ipairs(BODY_BLOCKS) do
        for _, sp in ipairs(b.spans) do
            x0, x1 = math.min(x0, sp[1] - 1), math.max(x1, sp[2] + 1)
        end
    end
    local bw, rows = x1 - x0, y1 - y0
    -- The doll is painted into one bit plane per color: per row, (bw + 63)
    -- // 64 integers of 64 pixels (bit 0 = leftmost). A later color clears
    -- the others' bits, as paint would. A few KB, where a table per pixel
    -- made ~0.6 MB of garbage on every change of clothes.
    local words = (bw + 63) // 64
    local planes = {}
    local real_color, real_fill, pen = gfx.color, gfx.fill_rect, gfx.WHITE
    gfx.color = function(c) pen = c end
    gfx.fill_rect = function(x, y, w, h)
        local a, z = math.max(x, x0) - x0, math.min(x + w, x1) - x0   -- columns [a, z)
        local top, bottom = math.max(y, y0) - y0, math.min(y + h, y1) - y0
        if z <= a or bottom <= top then return end
        if pen ~= gfx.WHITE and not planes[pen] then
            local p = {}
            for i = 1, rows * words do p[i] = 0 end
            planes[pen] = p
        end
        for k = a // 64, (z - 1) // 64 do
            local lo, hi = math.max(a, k * 64) - k * 64, math.min(z, k * 64 + 64) - k * 64
            local mask = (hi - lo == 64) and -1 or (((1 << (hi - lo)) - 1) << lo)
            for r = top, bottom - 1 do
                local i = r * words + k + 1
                for c, p in pairs(planes) do
                    if c == pen then p[i] = p[i] | mask else p[i] = p[i] & ~mask end
                end
            end
        end
    end
    local ok, err = pcall(self.draw_silhouette, self)
    gfx.color, gfx.fill_rect = real_color, real_fill
    if not ok then error(err) end
    local tiles, bytes = {}, {}   -- (one byte buffer for every tile)
    for _, c in ipairs({gfx.BLACK, gfx.DARK, gfx.LIGHT}) do
        local p = planes[c]
        if p then
            for ty = y0, y1 - 1, 32 do
                for tx = x0, x1 - 1, 32 do
                    local w, h = math.min(32, x1 - tx), math.min(32, y1 - ty)
                    local n, any = 0, false
                    for yy = ty, ty + h - 1 do
                        local base = (yy - y0) * words + 1
                        for bx = 0, (w + 7) // 8 - 1 do
                            local b = tx - x0 + bx * 8          -- first column of this byte
                            local k, off = b // 64, b % 64
                            local v = (p[base + k] >> off) & 0xFF
                            if off > 56 and k + 1 < words then v = v | ((p[base + k + 1] << (64 - off)) & 0xFF) end
                            local left = w - bx * 8               -- columns of the tile still in this byte
                            if left < 8 then v = v & ((1 << left) - 1) end
                            if v ~= 0 then any = true end
                            n = n + 1
                            bytes[n] = v
                        end
                    end
                    if any then tiles[#tiles + 1] = {c, tx, ty, w, h, string.char(table.unpack(bytes, 1, n))} end
                end
            end
        end
    end
    cache.tiles = tiles
    return tiles
end

-- The doll: bitmap tiles when the firmware has them, else the rects.
function Game:draw_doll()
    if not draw_sprite then return self:draw_silhouette() end
    local pen
    for _, t in ipairs(self:doll_tiles()) do
        if t[1] ~= pen then
            pen = t[1]
            gfx.color(pen)
        end
        draw_sprite(t[2], t[3], t[4], t[5], t[6])
    end
end

function Game:doll_ring(slot, pos)
    local cache = self:doll_cache()
    if cache[slot] then return cache[slot] end
    local x0, y0, x1, y1 = pos.x - 1, pos.y - 1, pos.x + pos.w, pos.y + pos.h
    -- the ring as four lines of pixels: {x, y, dx, dy, length}
    local lines = {{x0, y0, 1, 0, x1 - x0 + 1}, {x0, y1, 1, 0, x1 - x0 + 1},
                   {x0, y0 + 1, 0, 1, y1 - y0 - 1}, {x1, y0 + 1, 0, 1, y1 - y0 - 1}}
    local px = {{}, {}, {}, {}}
    local real_color, real_fill, pen = gfx.color, gfx.fill_rect, gfx.WHITE
    gfx.color = function(c) pen = c end
    gfx.fill_rect = function(x, y, w, h)
        for i, l in ipairs(lines) do
            local lx, ly = l[1], l[2]
            if l[3] == 1 then      -- a row: the part of [x, x+w) on it
                if ly >= y and ly < y + h then
                    for xx = math.max(x, lx), math.min(x + w, lx + l[5]) - 1 do px[i][xx - lx + 1] = pen end
                end
            elseif lx >= x and lx < x + w then
                for yy = math.max(y, ly), math.min(y + h, ly + l[5]) - 1 do px[i][yy - ly + 1] = pen end
            end
        end
    end
    local ok, err = pcall(self.draw_silhouette, self, {x0, y0, x1 + 1, y1 + 1})
    gfx.color, gfx.fill_rect = real_color, real_fill
    if not ok then error(err) end
    -- run-length: one rect per stretch of one color
    local runs = {}
    for i, l in ipairs(lines) do
        local start, color = 1, px[i][1]
        for k = 2, l[5] + 1 do
            if k > l[5] or px[i][k] ~= color then
                local n = k - start
                local x, y = l[1] + l[3] * (start - 1), l[2] + l[4] * (start - 1)
                runs[#runs + 1] = {color, x, y, l[3] == 1 and n or 1, l[3] == 1 and 1 or n}
                start, color = k, px[i][k]
            end
        end
    end
    cache[slot] = runs
    return runs
end

-- One cell or slot again (on top of what is there), with the cursor or not.
function Game:redraw_inv_row(i, erase)
    local row, pos = INV_ROWS[i], INV_POS[i]
    if not (row and pos) then return end
    local sel = self.inv_selected
    sel = sel ~= nil and sel[1] == row[1] and sel[2] == row[2]
    if row[1] == "camp" then
        if erase then
            gfx.color(gfx.WHITE)
            gfx.fill_rect(pos.x - 2, pos.y - 2, pos.w + 4, pos.h + 4)
        end
        self:draw_camp_slot(row[2], pos.x, pos.y, pos.w, pos.h, i == self.inv_cursor, sel)
    elseif row[1] == "equip" then
        if erase then
            -- the cursor's rect is the 1px ring just outside the slot (its
            -- own frame is redrawn below): put the doll's pixels back there
            for _, run in ipairs(self:doll_ring(row[2], pos)) do
                gfx.color(run[1])
                gfx.fill_rect(run[2], run[3], run[4], run[5])
            end
        end
        self:draw_equip_slot(row[2], pos.x, pos.y, pos.w, pos.h, i == self.inv_cursor, sel)
    else
        if erase then
            gfx.color(gfx.WHITE)
            gfx.fill_rect(pos.x - 2, pos.y - 2, pos.w + 4, pos.h + 4)
        end
        self:draw_slot_box(pos.x, pos.y, pos.w, pos.h, self:get_stack(row[1], row[2]),
                           i == self.inv_cursor, sel, pos.pocket)
    end
end

-- Only the cursor moved: redraw the cell it left, the one it's on, and the
-- description (~50 draw calls instead of ~850 for the whole screen).
function Game:move_inv_cursor_drawn(old, w)
    self:redraw_inv_row(old, true)
    self:redraw_inv_row(self.inv_cursor, true)
    -- an erase can clip the selected cell's outline (it may be the cell just
    -- left): draw it again on top, last
    local sel = self.inv_selected
    if sel then
        for i, row in ipairs(INV_ROWS) do
            if row[1] == sel[1] and row[2] == sel[2] then
                self:redraw_inv_row(i, false)
            end
        end
    end
    self:draw_inv_desc(w, true)
    -- the cells' erase boxes reach the labels' descenders: write them again
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_MONO_12)
    for _, l in ipairs(self.inv_labels or {}) do Game.ui_tag(INV_COL_X + 2, l[1], l[2]) end
    self.inv_drawn.cursor = self.inv_cursor
    gfx.refresh()
end

function Game:draw_inventory(w, h)
    -- cursor-only change (the screen on the panel is this one, unchanged)
    local drawn = self.inv_drawn
    if drawn and INV_ROWS and #INV_ROWS > 0 then
        self.inv_cursor = math.max(1, math.min(self.inv_cursor, #INV_ROWS))
        if self:ground_scroll(#self:ground_list() + 1) == (self.ground_off or 0)
            and self:inv_signature() == drawn.sig then
            if drawn.cursor ~= self.inv_cursor then self:move_inv_cursor_drawn(drawn.cursor, w) end
            return
        end
    end
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_MONO_12)
    local camp = self.camp_view and self.base and self:at_base()
    self.camp_view = camp or nil
    Game.ui_title(w, camp and "Camp" or "Bag", camp and "Enter move  E use  T bag  I map"
        or ("Enter move E use X drop C craft I map " .. (self:at_base() and "T camp" or "H help")), 16)

    INV_ROWS = {}
    INV_POS = {}

    local function add_row(kind, key, x, y, w2, h2)
        table.insert(INV_ROWS, {kind, key})
        -- no x: selectable but scrolled out of view, so it gets no position
        INV_POS[#INV_ROWS] = x and {x = x, y = y, w = w2, h = h2} or nil
    end

    -- ground items grid. Every ground stack is a cursor row (ground rows come
    -- first, so cursor index == ground index), but only GROUND_GRID_ROWS rows
    -- of cells fit above the paperdoll: scroll the window to keep the cursor
    -- in view and give off-screen stacks no position.
    local ground = self:ground_list()
    -- one extra, empty cell after the last stack: somewhere to drop things
    local n_ground = #ground + 1
    local per_page = GROUND_GRID_COLS * GROUND_GRID_ROWS
    local off = self:ground_scroll(n_ground)
    self.ground_off = off
    local label = camp and "Camp stash" or (self:at_base() and self:base_has("box")) and "Stash box" or "Ground"
    if #ground > per_page then
        label = label .. " " .. (off + 1) .. "-" .. math.min(#ground, off + per_page)
            .. "/" .. #ground
    end
    Game.ui_tag(INV_COL_X + 2, GROUND_Y - 5, label)
    self.inv_labels = {{GROUND_Y - 5, label}}
    for i = 1, n_ground do
        if i > off and i <= off + per_page then
            local col = (i - off - 1) % GROUND_GRID_COLS
            local row = (i - off - 1) // GROUND_GRID_COLS
            local x = INV_COL_X + 2 + col * (GROUND_CELL + GROUND_GAP)
            local y = GROUND_Y + row * (GROUND_CELL + GROUND_GAP)
            add_row("ground", i, x, y, GROUND_CELL, GROUND_CELL)
        else
            add_row("ground", i)
        end
    end

    -- equipped slots (positioned near the body, not listed), or on the camp
    -- screen the camp's slots in their grid
    if camp then
        local g = CAMP_GRID
        for i, slot in ipairs(BASE.slots) do
            add_row("camp", slot[1], g[1] + (i - 1) % 6 * g[4], g[2] + (i - 1) // 6 * g[5], g[3], g[3])
        end
    else
        for _, slot in ipairs(EQUIP_SLOTS) do
            local r = EQUIP_RECT[slot]
            add_row("equip", slot, r[1], r[2], r[3], r[4])
        end
    end

    -- bag: one cell per unit of capacity. Every stack is a row, plus the
    -- first empty cell (a drop target); the other empty cells are just drawn.
    local capacity = self:bag_capacity()
    local n_inv = #self.player.inventory
    -- with a bag on, the last `pockets` cells are your clothes' pockets: they
    -- start a row of their own when the rows allow
    local back = self.player.equipped.back
    local pockets = back and math.min(self:pocket_cells(), capacity) or 0
    local n_bag = capacity - pockets
    local rows_of = function(n) return (n + BACKPACK_COLS - 1) // BACKPACK_COLS end
    local skip = 0
    if pockets > 0 and n_inv <= capacity and rows_of(n_bag) + rows_of(pockets) <= BACKPACK_CAP // BACKPACK_COLS then
        skip = rows_of(n_bag) * BACKPACK_COLS - n_bag
    end
    local function bag_cell(i)
        local k = i > n_bag and i - 1 + skip or i - 1
        return INV_COL_X + 2 + k % BACKPACK_COLS * (BACKPACK_CELL + BACKPACK_GAP),
               BACKPACK_Y + k // BACKPACK_COLS * (BACKPACK_CELL + BACKPACK_GAP)
    end
    -- (every cell is a row: the cursor can reach any pocket, and an empty
    -- one takes what you drop on it)
    for i = 1, math.min(math.max(n_inv, capacity), BACKPACK_CAP) do
        local x, y = bag_cell(i)
        add_row("inventory", i, x, y, BACKPACK_CELL, BACKPACK_CELL)
        INV_POS[#INV_ROWS].pocket = i > n_bag and i <= capacity
    end

    self.inv_cursor = math.max(1, math.min(self.inv_cursor, #INV_ROWS))

    -- draw ground + backpack cells
    for i, row in ipairs(INV_ROWS) do
        if (row[1] == "ground" or row[1] == "inventory") and INV_POS[i] then
            local pos = INV_POS[i]
            local stack = self:get_stack(row[1], row[2])
            self:draw_slot_box(pos.x, pos.y, pos.w, pos.h, stack,
                i == self.inv_cursor,
                self.inv_selected and self.inv_selected[1] == row[1] and self.inv_selected[2] == row[2],
                pos.pocket)
        end
    end

    gfx.color(gfx.BLACK)
    gfx.text(4, CONDITIONS_Y, camp and self:camp_summary() or self:current_conditions())

    -- silhouette + equip slots (the camp screen: its slots)
    if not camp then self:draw_doll() end
    for i, row in ipairs(INV_ROWS) do
        if row[1] == "camp" then
            local pos = INV_POS[i]
            self:draw_camp_slot(row[2], pos.x, pos.y, pos.w, pos.h, i == self.inv_cursor,
                self.inv_selected and self.inv_selected[1] == row[1] and self.inv_selected[2] == row[2])
        elseif row[1] == "equip" then
            local pos = INV_POS[i]
            self:draw_equip_slot(row[2], pos.x, pos.y, pos.w, pos.h,
                i == self.inv_cursor,
                self.inv_selected and self.inv_selected[1] == row[1] and self.inv_selected[2] == row[2])
        end
    end

    -- what the cursor is on, under the bag
    self:draw_inv_desc(w, false)

    local bag_label = (back and ITEM_DB[back].name or "Pockets") .. " " .. n_inv .. "/" .. capacity
        .. (pockets > 0 and (" " .. pockets .. " pocket" .. (pockets > 1 and "s" or "")) or "")
    Game.ui_tag(INV_COL_X + 2, BAG_LABEL_Y, bag_label)
    self.inv_labels[2] = {BAG_LABEL_Y, bag_label}

    -- log: the newest INV_LOG_LINES lines, the last one at h - 8
    local ly = h - 8 - 12 * (INV_LOG_LINES - 1)
    local start_i = math.max(1, #self.log - INV_LOG_LINES + 1)
    for i = start_i, #self.log do
        gfx.text(4, ly, self.log[i])
        ly = ly + 12
    end

    self.inv_drawn = {sig = self:inv_signature(), cursor = self.inv_cursor}
    gfx.refresh()
end

-- ---------------------------------------------------------------------
-- First-day hints: the first time a situation comes up in a run, one
-- "Tip:" line in the log (at most one a tick, from tick). self.hints =
-- {id -> true} (saved), so each shows once a run. Every line fits the
-- map's log (57 characters).
-- ---------------------------------------------------------------------

Game.HINTS = {
    {"bleeding", "Tip: bleeding. E on a bandage or a rag stops it.",
     function(g, p) return p.injuries.bleeding end},
    {"cold", "Tip: cold hurts. Wear more, or C: a fire (matches).",
     function(g, p) return (p.cold_hours or 0) > 0 end},
    {"thirsty", "Tip: thirsty. E drinks; boil dirty water by a fire (C).",
     function(g, p) return p.needs.thirst < 45 end},
    {"hungry", "Tip: hungry. E eats; F searches; G hunts or fishes.",
     function(g, p) return p.needs.hunger < 45 end},
    {"tired", "Tip: tired. Space rests; it's safer by a fire.",
     function(g, p) return p.needs.rest < 35 end},
    {"night", "Tip: nights are cold and worse. Rest by a fire.",
     function(g, p) return g:is_night() end},
    {"fire", "Tip: by a fire, C has Study: work out a recipe.",
     function(g, p) return g:fire_here() end},
    {"book", "Tip: E on a book: its first read teaches a recipe.",
     function(g, p)
         for _, s in ipairs(p.inventory) do
             if ITEM_DB[s.item].book and not (g.books_read or {})[s.item] then return true end
         end
     end},
    {"radio", "Tip: R calls on the radio. Anna heals; Karl tells.",
     function(g, p) return g:carrying("lora_radio") end},
}

function Game:hint_tick()
    if self.no_hints then return end
    self.hints = self.hints or {}
    local p = self.player
    for _, h in ipairs(Game.HINTS) do
        if not self.hints[h[1]] and h[3](self, p) then
            self.hints[h[1]] = true
            self:push_log(h[2])
            return
        end
    end
end
-- ---------------------------------------------------------------------
-- Ranged weapons: the rare handguns (and the quiet bow and sling), plus
-- the Elder Sign (numbers in CHURN.guns, items in 08_data_churn).
--
-- A gun or bow in a hand, with its rounds anywhere in reach, adds "Shoot"
-- to a fight at any range; each shot uses one. Guns are loud (more
-- encounters for a few hours; animals may bolt), they wear a little each
-- shot and a worn gun jams more (Clean Guns: gunsmithing). The Marsh
-- Revolver hits hardest and takes something from you every time.
-- self.gun_wear = {gun -> %}, self.noise_until = hour (saved).
-- ---------------------------------------------------------------------

-- The ranged weapon in your hands with ammo for it: item, its shoot table.
function Game:shooter()
    for _, slot in ipairs({"rhand", "lhand"}) do
        local item = self.player.equipped[slot]
        local sh = item and ITEM_DB[item].shoot
        if sh and self:count_item(sh.ammo) > 0 then return item, sh end
    end
end

function Game:gun_wear_of(item)
    return (self.gun_wear or {})[item] or 100
end

-- Jam chance: the gun's own, plus more as it wears.
function Game:jam_chance(item)
    local sh = ITEM_DB[item].shoot
    if sh.jam == 0 then return 0 end
    return sh.jam + (100 - self:gun_wear_of(item)) // CHURN.guns.jam_per_wear
end

function Game:shoot_chance(item)
    local p, e, G = self.player, self.enc, CHURN.guns
    return G.shoot_hit + 8 * (p.attrs.Perception - 3) + (e.aim or 0) + self:skill_bonus("fight") + self:beast_bonus()
        + ITEM_DB[item].shoot.hit - (e.range == "far" and G.far_penalty or 0)
end

-- Extra fight options: Shoot, and the Elder Sign against what walks at night.
function Game:ranged_options(o, e)
    local item = self:shooter()
    if item then
        local ammo = ITEM_DB[item].shoot.ammo
        table.insert(o, 1, {("Shoot (%s, %d)"):format(ITEM_DB[item].name, math.min(99, self:count_item(ammo))),
                            "shoot"})
    end
    return self:sign_options(o, e)
end

function Game:sign_options(o, e)
    if (e.def.kind == "horror" or e.def.dark) and self:count_item("elder_sign") > 0 then
        table.insert(o, 1, {"Raise the Elder Sign", "elder"})
    end
    return o
end

function Game:shoot()
    local p, e, G = self.player, self.enc, CHURN.guns
    local item, sh = self:shooter()
    if not item then return end
    local name = ITEM_DB[item].name
    self:take_items(sh.ammo, 1)
    if not sh.quiet then
        self.gun_wear = self.gun_wear or {}
        self.gun_wear[item] = math.max(0, self:gun_wear_of(item) - G.wear_per_shot)
        self.noise_until = p.hours + G.noise_hours
    end
    if sh.curse then
        p.needs.rest = math.max(0, p.needs.rest - sh.curse)
    end
    if self:roll(self:jam_chance(item)) then
        self:sfx("miss")
        self:enc_say("Click. The " .. name .. " jams, and you lose the round clearing it.")
        return
    end
    if self:roll(self:shoot_chance(item)) then
        self:skill_xp("fight", SKILLS.xp.hit)
        local dmg = math.max(1, sh.dmg - self:rand(sh.dmg // 4 + 1))
        e.aim = 0
        local how = sh.quiet and ("Your shot from the " .. name .. " strikes the " .. e.def.who)
                              or ("The " .. name .. " cracks. You hit the " .. e.def.who)
        self:enc_hit(dmg, sh.quiet and 15 or G.bleed, how)
        if sh.curse and not e.over then self:enc_say("Something in the dark counts the shot.") end
    else
        self:sfx("miss")
        e.aim = 0
        self:enc_say(sh.quiet and "Your shot goes wide." or ("The " .. name .. " cracks. You miss."))
    end
    if not e.over and not sh.quiet and e.def.kind == "animal" and self:roll(G.animal_flee) then
        self:enc_say("The noise is too much for the " .. e.def.who .. ". It bolts.")
        e.outcome = "fled"
        self:end_encounter("The " .. e.def.who .. " ran from the gunshot.")
    end
end

-- The Elder Sign: whatever it is, it can't stay where the sign is shown.
-- The sign crumbles.
function Game:raise_sign()
    self:take_items("elder_sign", 1)
    self:sfx("emission")
    self:enc_say("You hold up the scratched bone. The air folds around it, and the "
        .. Game.e_name(self.enc.def) .. " is simply not there any more. The bone crumbles to salt.")
    self.enc.outcome = "fled"
    return self:end_encounter("The Elder Sign sent it away.")
end

-- (a horror has no `who` sometimes; its name will do)
function Game.e_name(def)
    return def.who or def.name:lower()
end

-- Gunshots carry: encounters are likelier for a while after.
function Game:noise_mult()
    if self.noise_until and self.player.hours < self.noise_until then return CHURN.guns.noise_mult end
    return 1
end

-- -- armed enemies (CHURN.armed) -------------------------------------------

-- Some people carry a gun: e.gun = {item, rounds}.
function Game:arm_enemy()
    local e = self.enc
    local a = CHURN.armed[e.def.who]
    if not a or not self:roll(a.chance) then return end
    e.gun = {item = a.item, rounds = a.rounds[1] + self:rand(a.rounds[2] - a.rounds[1] + 1)}
    self:enc_say("The " .. e.def.who .. " carries a " .. ITEM_DB[a.item].name .. ".")
end

-- "PM", "Nagant", "Tokarev": for the fight's status line.
function Game:enemy_gun_name()
    local g = self.enc.gun
    return g and g.rounds > 0 and ITEM_DB[g.item].name:match("^%S+")
end

-- An armed enemy short of arm's reach shoots instead of closing in, while
-- its rounds last. Loud, like yours. True when it took its turn.
function Game:enemy_shoots()
    local e, p, A = self.enc, self.player, CHURN.armed
    local g = e.gun
    if not g or e.range == "close" or e.demanding then return false end
    if g.rounds <= 0 then
        if not g.empty then
            g.empty = true
            self:enc_say("The " .. e.def.who .. "'s gun clicks empty. It comes for you instead.")
            return true
        end
        return false
    end
    local a = A[e.def.who]
    g.rounds = g.rounds - 1
    self.noise_until = p.hours + CHURN.guns.noise_hours
    local hit = a.hit - FIGHT.ENEMY_DODGE * (p.attrs.Speed - 3)
        - (e.range == "far" and A.far_penalty or 0) - (e.fog and A.fog or 0)
    local gun = ITEM_DB[g.item].name
    if not self:roll(hit) then
        self:sfx("miss")
        self:enc_say("The " .. e.def.who .. "'s " .. gun .. " cracks. The shot goes past you.")
        return true
    end
    self:enemy_hits(a.dmg, CHURN.guns.bleed, "The " .. e.def.who .. " shoots you")
    return true
end

-- Your loaded gun against their demand: they back off (an end), or call it.
function Game:bluff()
    local e, A = self.enc, CHURN.armed
    e.bluffed = true
    if self:roll(e.gun and A.bluff or A.bluff_unarmed) then
        self:enc_say("You let them see the gun. A long look, then they back away into the ruins.")
        e.outcome = "fled"
        self:end_encounter("The " .. e.def.who .. " backed off from your gun.")
        return true
    end
    e.demanding = false
    self:enc_say("'You won't,' they say, and spread out.")
end

-- On a kill: its gun, and whatever it hadn't fired.
function Game:drop_enemy_gun(found)
    local g = self.enc.gun
    if not g then return end
    self:put_stack("ground", nil, {item = g.item, qty = 1})
    found[#found + 1] = ITEM_DB[g.item].name
    if g.rounds > 0 then
        local ammo = ITEM_DB[g.item].shoot.ammo
        self:put_stack("ground", nil, {item = ammo, qty = g.rounds})
        found[#found + 1] = g.rounds .. " " .. ITEM_DB[ammo].name:lower()
    end
end

-- Rival Churners who'd rather trade (CHURN.parley): one thing you carry that
-- they want, for one of theirs.
function Game:maybe_parley()
    local e, P = self.enc, CHURN.parley
    if e.def.who ~= "rival churner" or not self:roll(P.chance) then return end
    local want
    for _, id in ipairs(P.want) do
        if not want and self:count_item(id) > 0 then want = id end
    end
    if not want then return end
    local give
    self.seed, give = weighted_pick(self.seed, P.give)
    e.parley = {want = want, give = give}
    self:enc_say(P.say)
end

function Game:parley_swap()
    local e, P = self.enc, CHURN.parley
    local pa = e.parley
    self:take_items(pa.want, 1)
    local qty = (ITEM_DB[pa.give].desc or ""):find("^Ammo") and P.rounds or 1   -- (rounds come by the handful)
    self:put_stack("ground", nil, {item = pa.give, qty = qty})
    self:enc_say(P.done)
    e.outcome = "fled"
    return self:end_encounter("You traded with the rival churners: their "
        .. ITEM_DB[pa.give].name:lower() .. " is on the ground.")
end
-- ---------------------------------------------------------------------
-- The fishing minigame (G by water with a Fishing Rod; numbers in
-- HUNT.game, 05_data_world). Turn-based, so it plays the same on the
-- device as on a PC.
--
-- Bite: Space waits a beat and watches the float. It lies still, twitches
-- (a nibble), and at last goes under for one beat. Enter strikes: on the
-- plunge it hooks the fish; too early spooks them (a fresh wait, `spooks`
-- times at most), and waiting past the plunge loses the bait.
-- Fight: each turn the fish shows what it's doing, and you answer it:
--   pulls left/right: lean the other way (Right/Left) - it tires
--   dives:            give line (Down) - it tires, the line eases
--   rests:            reel (Up) - it comes in two lengths
-- Up reels any time (it comes in, but the line tightens); Down gives line
-- (it eases, but the fish gets further). A pull tightens the line each turn,
-- a rest eases it. Over the snap point the line breaks; slack too long and
-- it shakes the hook. Bring it in to the bank (distance 0) to land it.
-- self.fishing holds a session; it isn't saved (a quit mid-cast loses it).
-- ---------------------------------------------------------------------

function Game:fish_start()
    self:spend_hours(HUNT.fish_hours)
    self.fishing = {phase = "wait", spooked = 0, turn = 0, msg = "You cast. The float settles. (Space: wait)"}
    self:fish_new_wait()
    self.screen = "fishing"
end

-- A fresh run of beats before the bite: a few still or twitching, then the plunge.
function Game:fish_new_wait()
    local G, f = HUNT.game, self.fishing
    local n = G.wait[1] + self:rand(G.wait[2] - G.wait[1] + 1)
    f.beats, f.beat = {}, 1
    for i = 1, n - 1 do f.beats[i] = self:roll(G.twitch) and "twitch" or "still" end
    f.beats[n] = "plunge"
    f.float = "still"
end

-- Line strength: where it snaps (Perception, Karl's gear).
function Game:fish_snap()
    local G = HUNT.game
    return G.snap + G.snap_per * (self.player.attrs.Perception - 3) + self:fish_bonus() // 2
end

-- The fish takes the hook: which one, and its fight.
function Game:fish_hook()
    local G, f = HUNT.game, self.fishing
    local pick = {}
    for i, d in ipairs(G.fish) do pick[i] = {i, d[3]} end
    local i
    self.seed, i = weighted_pick(self.seed, pick)
    local d = G.fish[i]
    -- skill: a tired fish from the start
    f.kind, f.phase = d, "fight"
    f.stamina = math.max(1, d[4] - self:skill_bonus("fish") // 5)
    f.dist, f.tension, f.slack, f.turn = d[5], G.tension, 0, 0
    f.act = self:fish_act()
    f.msg = "Hooked! " .. self:fish_act_text()
    self:sfx("hit")
end

function Game:fish_act()
    local f = self.fishing
    if f.stamina <= 0 then return "rest" end   -- worn out: it only drifts
    local act
    self.seed, act = weighted_pick(self.seed, HUNT.game.acts)
    return act
end

function Game:fish_act_text()
    local f = self.fishing
    return ({left = "It pulls hard to the left!", right = "It pulls hard to the right!",
             dive = "It dives for the bottom!", lunge = "It LUNGES! Give it line!",
             rest = f.stamina <= 0 and "It's spent. It drifts on the line." or "It rests, finning."})[f.act]
end

-- One key in a session. Returns nothing; self.fishing ends with fish_end.
function Game:fishing_key(key)
    local f = self.fishing
    if not f then self.screen = "map" return end
    if key == KEY.Q or key == gfx.KEY_ESCAPE then
        return self:fish_end(nil, "You reel in and pack up the rod.")
    end
    if f.phase == "done" then
        self.fishing = nil
        self.screen = "map"
        return
    end
    if f.phase == "wait" then return self:fish_wait_key(key) end
    self:fish_fight_key(key)
end

function Game:fish_wait_key(key)
    local G, f = HUNT.game, self.fishing
    local now = f.beats[f.beat]
    if key == KEY.ENTER or key == KEY.LF then
        if now == "plunge" then return self:fish_hook() end
        f.spooked = f.spooked + 1
        if f.spooked > G.spooks then
            return self:fish_end(nil, "You yank at nothing again. Every fish here has gone.")
        end
        self:fish_new_wait()
        f.msg = "You yank at nothing. The ripples spread. Wait..."
        return
    end
    if key ~= KEY.SPACE and key ~= gfx.KEY_DOWN and key ~= KEY.S then return end
    if now == "plunge" then
        return self:fish_end(nil, "The float pops back up. The bait's gone.")
    end
    f.beat = f.beat + 1
    f.float = f.beats[f.beat]
    f.msg = ({still = "The float rides the current.", twitch = "The float twitches...",
              plunge = "The float goes UNDER! (Enter: strike)"})[f.float]
end

function Game:fish_fight_key(key)
    local G, f = HUNT.game, self.fishing
    local act = f.act
    local move = (key == gfx.KEY_LEFT or key == KEY.A) and "left" or (key == gfx.KEY_RIGHT or key == KEY.D) and "right"
        or (key == gfx.KEY_UP or key == KEY.W) and "up" or (key == gfx.KEY_DOWN or key == KEY.S) and "down" or nil
    if not move then return end
    local said
    local pull = act == "left" or act == "right"
    if pull and move ~= "up" and move ~= "down" then
        if move ~= act then   -- leaning against it
            f.tension, f.stamina = f.tension + G.lean.tension, f.stamina - G.lean.tire
            said = "You lean into it. It's tiring."
        else                  -- with it: it runs
            f.tension, f.dist = f.tension + G.wrong.tension, f.dist + G.wrong.dist
            said = "Wrong way! It runs with the line."
        end
    elseif move == "up" then
        local r = act == "rest" and G.reel_rest or G.reel
        f.tension, f.dist = f.tension + r.tension, math.max(0, f.dist - r.dist)
        said = act == "rest" and "You reel it in while it rests." or "You reel against it. The line sings."
    elseif move == "down" then
        if act == "dive" or act == "lunge" then
            f.tension, f.stamina = f.tension + G.give_dive.tension, f.stamina - G.give_dive.tire
            said = "You give it line. It wears itself out going down."
        else
            f.tension, f.dist = f.tension + G.give.tension, f.dist + G.give.dist
            said = "You give it line. It eases, and it gets further away."
        end
    else
        said = "You hold the rod."
    end
    -- the fish's own pull (or a rest): never quite the same twice
    if act == "rest" then
        f.tension = f.tension - G.rest_ease
    elseif act == "lunge" then
        f.tension = f.tension + G.lunge
    else
        f.tension = f.tension + G.pull + G.pull_var[1] + self:rand(G.pull_var[2] - G.pull_var[1] + 1)
    end
    f.tension = math.max(0, f.tension)
    f.stamina = math.max(0, f.stamina)
    f.turn = f.turn + 1
    if f.tension >= self:fish_snap() then
        return self:fish_end(nil, "SNAP. The line parts and it's gone.")
    end
    f.slack = f.tension < G.slack and f.slack + 1 or 0
    if f.slack >= G.slack_turns then
        return self:fish_end(nil, "The line goes slack. It shook the hook.")
    end
    if f.dist <= 0 then return self:fish_land() end
    f.act = self:fish_act()
    f.msg = said .. " " .. self:fish_act_text()
end

-- On the bank: what it was.
function Game:fish_land()
    local G, f = HUNT.game, self.fishing
    local d = f.kind
    local item, qty
    if d[6] == "junk" then
        self.seed, item = weighted_pick(self.seed, G.junk)
        qty = 1
    else
        item, qty = d[6][1], d[6][2]
    end
    local stack = {item = item, qty = qty}
    if not self:put_stack("inventory", nil, stack) then self:put_stack("ground", nil, stack) end
    if d[6] ~= "junk" then
        self:skill_xp("fish", SKILLS.xp.catch * qty)
        self:stat("fish", qty)
    end
    self:sfx("chime")
    local got = ITEM_DB[item].name .. (qty > 1 and (" x" .. qty) or "")
    self:fish_end(true, ("Landed %s! (%s)"):format(d[2], got))
end

-- The session is over: the result line stays up until a key.
function Game:fish_end(caught, text)
    local f = self.fishing
    f.phase, f.msg, f.caught = "done", text, caught
    self:push_log(text:sub(1, 57))
    self:maybe_karl("fish")
    if self.screen ~= "fishing" then self.fishing = nil end   -- (Karl came up the bank)
end

-- -- the screen -----------------------------------------------------------

function Game:draw_fishing(w, h)
    local f = self.fishing
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    Game.ui_title(w, "Fishing")
    -- the water and the bank
    local top, bank_x = 60, 40
    gfx.color(gfx.LIGHT)
    gfx.fill_rect(bank_x, top, w - bank_x - 6, 140)
    gfx.color(gfx.DARK)
    gfx.fill_rect(bank_x, top + 100, w - bank_x - 6, 40)   -- the deep
    gfx.color(gfx.BLACK)
    gfx.line(bank_x, top, w - 6, top)
    gfx.fill_rect(6, top - 10, bank_x - 6, 150)             -- the bank
    -- the rod and the line to the float
    local rod_x, rod_y = bank_x - 4, top - 34
    gfx.line(14, top - 10, rod_x, rod_y)
    local G = HUNT.game
    local fx
    if f.phase == "fight" or (f.phase == "done" and f.kind) then
        local d = f.kind
        fx = bank_x + 10 + math.floor((w - bank_x - 40) * math.min(1, (f.dist or 0) / d[5]))
    else
        fx = w - 60
    end
    local fy = top + (f.float == "plunge" and 14 or f.float == "twitch" and 3 or 0)
    if f.phase == "fight" then fy = top + 30 end
    gfx.line(rod_x, rod_y, fx, fy)
    if f.phase ~= "fight" then   -- the float: a white ring with a black cap
        gfx.color(gfx.WHITE)
        gfx.fill_rect(fx - 4, fy - 4, 8, 8)
        gfx.color(gfx.BLACK)
        gfx.rect(fx - 4, fy - 4, 8, 8)
        gfx.fill_rect(fx - 2, fy - 10, 4, 6)
        if f.float == "twitch" then
            gfx.rect(fx - 9, fy + 2, 18, 3)
        elseif f.float == "plunge" then
            gfx.rect(fx - 14, top - 1, 28, 4)
            gfx.rect(fx - 20, top - 2, 40, 6)
        end
    else                         -- the fish on the line, and which way it goes
        gfx.fill_rect(fx - 10, fy - 3, 20, 7)
        gfx.fill_rect(f.act == "right" and fx - 13 or fx + 8, fy - 6, 5, 13)   -- (the tail: away from where it goes)
        local ax = f.act == "left" and -1 or f.act == "right" and 1 or 0
        if f.act == "lunge" then gfx.rect(fx - 16, fy - 10, 32, 20) end   -- (thrashing)
        if ax ~= 0 then
            local x0 = fx + ax * 18
            gfx.line(x0, fy, x0 + ax * 22, fy)
            gfx.line(x0 + ax * 22, fy, x0 + ax * 16, fy - 5)
            gfx.line(x0 + ax * 22, fy, x0 + ax * 16, fy + 5)
        elseif f.act == "dive" or f.act == "lunge" then
            gfx.line(fx, fy + 8, fx, fy + 40)
            gfx.line(fx, fy + 40, fx - 5, fy + 34)
            gfx.line(fx, fy + 40, fx + 5, fy + 34)
        end
    end
    -- the tension bar (the snap point marked), under the water
    local y = top + 152
    if f.phase == "fight" or (f.phase == "done" and f.tension) then
        local snap = self:fish_snap()
        local bw = w - 70
        gfx.text(6, y + 9, "Line")
        gfx.rect(50, y, bw, 12)
        gfx.fill_rect(50, y, math.floor(bw * math.min(1, f.tension / snap)), 12)
        gfx.color(gfx.DARK)
        gfx.fill_rect(50 + math.floor(bw * G.slack / snap), y - 3, 2, 18)   -- slack below this
        gfx.color(gfx.BLACK)
        gfx.text(50 + bw + 4, y + 9, "!")
        if f.phase == "fight" then
            gfx.text(6, y + 26, ("%d lengths out%s"):format(f.dist, f.stamina <= 0 and ", worn out" or ""))
        end
    end
    -- what's happening, and the keys
    local ly = y + 44
    for i, line in ipairs(wrap(f.msg or "", 55)) do
        if i <= 2 then gfx.text(6, ly + 13 * (i - 1), line) end
    end
    Game.ui_keys(w, h, f.phase == "wait" and "Space wait  Enter strike  Q stop"
        or f.phase == "fight" and "Lt/Rt lean  Up reel  Dn give line  Q cut"
        or "Any key: back")
    gfx.refresh()
end
-- ---------------------------------------------------------------------
-- The bestiary (numbers in CHURN.bestiary): a page for every creature you
-- meet, kept by who it is (def.who). self.bestiary[who] = {name, seen,
-- watched, killed, sold} (saved). Watching one (Watch it, in a fight) finds
-- its weak spot for good: + bonus % to hit that kind ever after. A full
-- page - seen, watched and killed - sells to the Trader (N on his screen).
-- B in the journal shows the pages.
-- ---------------------------------------------------------------------

function Game:beast_page(def, make)
    if not def or CHURN.bestiary.skip[def.kind] or def.phantom or def.legacy then return nil end
    self.bestiary = self.bestiary or {}
    local page = self.bestiary[def.who]
    if not page and make then
        page = {name = def.name, seen = 0, killed = 0}
        self.bestiary[def.who] = page
    end
    return page
end

function Game:beast_seen(def)
    local page = self:beast_page(def, true)
    if page then page.seen = page.seen + 1 end
end

function Game:beast_watched(def)
    local page = self:beast_page(def, true)
    if page and not page.watched then
        page.watched = true
        self:enc_say("You note how it moves, where it's soft. (Bestiary: weak spot)")
    end
end

function Game:beast_killed(def)
    local page = self:beast_page(def, true)
    if page then page.killed = page.killed + 1 end
end

-- +% to hit what you're fighting, if you know its weak spot.
function Game:beast_bonus()
    local page = self.enc and self:beast_page(self.enc.def)
    return page and page.watched and CHURN.bestiary.bonus or 0
end

function Game.beast_full(page)
    return page.seen > 0 and page.watched and page.killed > 0
end

-- The journal page (B).
function Game:bestiary_lines()
    local names = {}
    for who, page in pairs(self.bestiary or {}) do names[#names + 1] = who end
    table.sort(names, function(a, b) return self.bestiary[a].name < self.bestiary[b].name end)
    if #names == 0 then return wrap("Nothing yet. Every creature you meet gets a page.", 55) end
    local lines, full = {}, 0
    for _, who in ipairs(names) do
        local pg = self.bestiary[who]
        if Game.beast_full(pg) then full = full + 1 end
        lines[#lines + 1] = ("%s%s"):format(pg.name, Game.beast_full(pg) and (pg.sold and "  (sold)" or "  (full page)") or "")
        lines[#lines + 1] = ("   seen %d, killed %d, weak spot: %s"):format(pg.seen, pg.killed,
            pg.watched and ("+" .. CHURN.bestiary.bonus .. "% to hit") or "watch it")
    end
    table.insert(lines, 1, ("%d pages, %d full. The Trader buys full ones (N)."):format(#names, full))
    table.insert(lines, 2, "")
    return lines
end

function Game:open_bestiary()
    self.skills_off, self.page = 0, "bestiary"
    self.screen = "skills"
end

-- N on the Trader's screen: full pages for rubles.
function Game:sell_bestiary()
    local n = 0
    for _, pg in pairs(self.bestiary or {}) do
        if Game.beast_full(pg) and not pg.sold then
            pg.sold, n = true, n + 1
        end
    end
    if n == 0 then return "'Bring me a full page. Seen it, studied it, killed it.'" end
    local pay = n * CHURN.bestiary.price
    if not self:put_stack("inventory", nil, {item = "rubles", qty = pay}) then
        self:put_stack("ground", nil, {item = "rubles", qty = pay})
    end
    return ("'Good notes.' He pays %d rubles for %d page%s."):format(pay, n, n > 1 and "s" or "")
end
-- ---------------------------------------------------------------------
-- Dread (numbers in CHURN.dread): what the Churn does to your mind, 0..100
-- on the player (p.dread, saved with the player). Horrors, emissions, the
-- dead, the dark and the wrong voices on the radio raise it; a fire, your
-- own bed, the dog at your side, a tape, vodka and a sedative ease it.
--   Uneasy (35+): only the label.
--   Dread (60+): the Churn whispers in the log as you walk.
--   70+: now and then something is there that isn't - one action and it's gone.
--   Terror (85+): sleep does you half the good.
-- ---------------------------------------------------------------------

function Game:dread(n)
    local p = self.player
    p.dread = math.max(0, math.min(100, (p.dread or 0) + n))
end

-- The tier's name ("Uneasy"...), or nil below the first.
function Game:dread_name()
    local name
    for _, t in ipairs(CHURN.dread.tiers) do
        if (self.player.dread or 0) >= t[1] then name = t[2] end
    end
    return name
end

-- One hour (from tick): the dark gets in; the dog and a camp by day ease it.
function Game:dread_hour(hour)
    local D = CHURN.dread
    if self:is_night(hour) and not self:has_light() and not self:fire_at(hour) and not self:at_base() then
        self:dread(D.dark_hour)
    end
    if self:dog_with_you() and hour % D.dog_hours == 0 then self:dread(-1) end
    if self:at_base() and not self:is_night(hour) then self:dread(D.camp_day / 12) end
end

-- After a move (from try_move): a whisper, or a phantom. True if a phantom
-- encounter started.
function Game:dread_move()
    local D, d = CHURN.dread, self.player.dread or 0
    if d >= 70 and self:roll(D.phantom) then
        local base = NIGHT.horrors[self:rand(#NIGHT.horrors) + 1]
        local def = {}
        for k, v in pairs(base) do def[k] = v end
        def.phantom = true
        self:start_encounter(def)
        return true
    end
    if d >= 60 and self:roll(D.whisper) then
        self:push_log(D.lines[self:rand(#D.lines) + 1])
    end
    return false
end

-- Any action against a phantom: there's nothing there.
function Game:phantom_gone()
    self:dread(-5)
    self:enc_say("You blink. There's nothing there. There was never anything there.")
    self:end_encounter("It was nothing. Was it?")
end
-- ---------------------------------------------------------------------
-- What's left of you (numbers in CHURN.legacy). When you die, what you
-- carried and wore is written to the records (rec.legacy: the stacks, the
-- cause, the day), so it outlives the save. In your next world something
-- wears it: The Risen waits CHURN.legacy.near..far hexes from where you
-- start, on the map from the first day, and fights with the best weapon you
-- had. Kill it and everything drops at your feet; the records forget it.
-- Run from it and it waits. A newer death replaces an older one.
-- self.legacy = {key} (saved): where it waits in this world.
-- ---------------------------------------------------------------------

-- At death (check_death): keep what you had for next time.
function Game:save_legacy(cause)
    local p, items = self.player, {}
    local function add(item, qty)
        if #items < CHURN.legacy.max_stacks then items[#items + 1] = {item = item, qty = qty} end
    end
    for _, s in ipairs(p.inventory) do add(s.item, s.qty) end
    for _, slot in ipairs(EQUIP_SLOTS) do
        if p.equipped[slot] then add(p.equipped[slot], 1) end
    end
    if #items == 0 then return end
    local rec = Game.records()
    rec.legacy = {items = items, cause = cause or "You died.", day = (self:clock())}
end

-- A new run: if a body is waiting, put it somewhere near.
function Game:place_legacy()
    local leg = Game.records().legacy
    if not leg then return end
    local key = self:quest_spot(CHURN.legacy.near, CHURN.legacy.far, false)
    if not key then return end
    self.legacy = {key = key}
    self.player.explored[key] = true
    self:note_find(key, "corpse", "What's left of you", {})
end

-- Its fight: your gear, your best weapon.
function Game:legacy_def()
    local L, leg = CHURN.legacy, Game.records().legacy
    local best = 8
    for _, s in ipairs(leg.items) do
        local def = ITEM_DB[s.item]
        local w = def and (def.shoot and def.shoot.dmg or def.weapon and def.weapon.dmg)
        if w and w > best then best = w end
    end
    return {kind = "mutant", legacy = true, name = "The Risen", who = L.who, art = L.art,
            intro = L.intro:format(leg.cause:gsub("%.$", "")), talk = L.talk,
            hp = math.min(L.hp_max, L.hp + L.hp_per * #leg.items), dmg = {best - 2, best + 6},
            hit = 55, speed = 2, bleed = 20, start = "near", loot = {{"nothing", 1}}, loot_rolls = 0}
end

-- Stepping onto its hex (from try_move).
function Game:legacy_arrive()
    local leg = self.legacy
    if not (leg and leg.key == hex_key(self.player.q, self.player.r) and Game.records().legacy) then
        return false
    end
    self:start_encounter(self:legacy_def())
    self:dread(CHURN.dread.risen)
    self:sfx("emission")
    return true
end

-- It's down (from enemy_dies): your things, back.
function Game:legacy_dies()
    local rec = Game.records()
    local found = {}
    for _, s in ipairs(rec.legacy and rec.legacy.items or {}) do
        if ITEM_DB[s.item] then
            self:put_stack("ground", nil, {item = s.item, qty = s.qty})
            found[#found + 1] = ITEM_DB[s.item].name
        end
    end
    rec.legacy = nil
    self.legacy = nil
    Game.write_records()
    self:enc_say("It folds up like an empty coat. Everything you had is here.")
    if #found > 0 then self:enc_say("Yours again: " .. table.concat(found, ", ") .. ".") end
    if self.finds then self.finds[hex_key(self.player.q, self.player.r)] = nil end
end

-- The journal line.
function Game:legacy_text()
    if not (self.legacy and Game.records().legacy) then return nil end
    return "What's left of you walks the Churn: " .. self:bearing_to(self.legacy.key) .. "."
end
-- ---------------------------------------------------------------------
-- Lockpicking (numbers in CHURN.pick, 08_data_churn): every locked crate is
-- a small game now. Pins, one at a time, left to right. Up raises the pin a
-- notch, Down lowers it, Enter tries to set it. At the right height you
-- may feel it give - or feel nothing. One notch too far, or Enter at the
-- wrong height, strains the pick and drops the pin; strain it too often and
-- it snaps. Q backs off and leaves the crate locked for another try.
-- self.lock = {pins, i, h, strain, set, msg, done} (not saved).
-- done(game) runs when the last pin sets.
-- ---------------------------------------------------------------------

function Game:lock_start(npins, done, back)
    local P = CHURN.pick
    local pins = {}
    for i = 1, npins do pins[i] = 1 + self:rand(P.height) end
    self.lock = {pins = pins, i = 1, h = 0, strain = 0, done = done, back = back or "map",
                 msg = "You slide the pick in. Up raises the first pin."}
    self.screen = "lockpick"
end

function Game:lock_hint_chance()
    local P = CHURN.pick
    return P.hint + P.hint_per * (self.player.attrs.Perception - 3) + self:skill_bonus("tinker")
end

function Game:lock_strain(text)
    local L = self.lock
    L.strain, L.h = L.strain + 1, 0
    if L.strain >= CHURN.pick.strain_max then
        self:take_items("lockpicks", 1)
        self:sfx("miss")
        self:push_log("The pick snaps in the lock. The crate stays shut.")
        L.msg, L.over = "SNAP. The pick breaks off in the lock. (any key)", true
        return
    end
    L.msg = text .. " The pin drops."
end

function Game:lockpick_key(key)
    local L = self.lock
    if not L then self.screen = "map" return end
    if L.over then
        self.lock = nil
        self.screen = L.back
        return
    end
    if key == KEY.Q or key == gfx.KEY_ESCAPE then
        self:push_log("You leave the lock for now. Come back to try again.")
        self.lock = nil
        self.screen = L.back
        return
    end
    local target = L.pins[L.i]
    if key == gfx.KEY_UP or key == KEY.W then
        L.h = L.h + 1
        if L.h > target then
            return self:lock_strain("Too far - the spring bites back.")
        end
        L.msg = (L.h == target and self:roll(self:lock_hint_chance())) and "Something gives, just slightly."
            or ("Notch " .. L.h .. ". Nothing.")
    elseif key == gfx.KEY_DOWN or key == KEY.S then
        L.h = math.max(0, L.h - 1)
        L.msg = "You ease it down. Notch " .. L.h .. "."
    elseif key == KEY.ENTER or key == KEY.LF or key == KEY.SPACE then
        if L.h ~= target then return self:lock_strain("It slips.") end
        self:sfx("hit")
        L.i, L.h = L.i + 1, 0
        if L.i > #L.pins then
            self:skill_xp("tinker", SKILLS.xp.repair)
            self:sfx("gift")
            L.msg, L.over = "Click. The lock turns. (any key)", true
            L.done(self)
            return
        end
        L.msg = "Click. Pin " .. (L.i - 1) .. " is set. On to the next."
    end
end

function Game:draw_lockpick(w, h)
    local L, P = self.lock, CHURN.pick
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    Game.ui_title(w, "Picking the lock", ("Strain %d/%d"):format(L.strain, P.strain_max))
    -- the lock: a shear line across, a column per pin
    local x0, base, notch, col = 60, 200, 22, 46
    local top = base - P.height * notch
    gfx.rect(x0 - 10, top - 30, col * #L.pins + 10, P.height * notch + 50)
    for i = 1, #L.pins do
        local x = x0 + (i - 1) * col
        local hh = i < L.i and L.pins[i] or i == L.i and L.h or 0
        gfx.color(gfx.LIGHT)
        gfx.fill_rect(x, top, 24, P.height * notch)
        gfx.color(gfx.BLACK)
        gfx.fill_rect(x + 4, base - hh * notch - 30, 16, 30)   -- the pin
        if i < L.i then gfx.text(x + 4, base + 13, "set") end  -- (under its column)
        if i == L.i then gfx.rect(x - 3, top - 3, 30, P.height * notch + 6) end
    end
    -- the pick, under the current pin
    local px = x0 + (L.i - 1) * col + 12
    if L.i <= #L.pins then gfx.line(20, base + 12, px, base - L.h * notch + 2) end
    for i, line in ipairs(wrap(L.msg or "", 55)) do
        if i <= 3 then gfx.text(6, 250 + 13 * (i - 1), line) end
    end
    Game.ui_keys(w, h, L.over and "Any key: back" or "Up/Dn move pin  Enter set  Q leave it")
    gfx.refresh()
end
-- ---------------------------------------------------------------------
-- Scanning the band (the LoRa radio's last row; numbers in CHURN.scan).
-- A dial from low to high MHz: Left/Right turn it one MHz, Up/Down five.
-- Each day a few stations sit somewhere on it; the signal bar rises as you
-- come close, and Enter on the strongest listens (a charge). What they are:
--   stash - numbers that mark a stash on the map
--   body  - a churner calling for help from a ruin (you'll find them there)
--   site  - morse naming a place you didn't know yet
--   voice - something that shouldn't be on the air (dread)
-- A station heard is gone until tomorrow. self.scan = {day, stations} (saved).
-- ---------------------------------------------------------------------

-- Today's stations (made fresh each day).
function Game:scan_stations()
    local S, day = CHURN.scan, (self:clock())
    if self.scan and self.scan.day == day then return self.scan.stations end
    local list, used = {}, {}
    for _, f in ipairs(S.avoid) do used[f] = true end
    for _ = 1, S.n[1] + self:rand(S.n[2] - S.n[1] + 1) do
        local f
        repeat f = S.low + 2 + self:rand(S.high - S.low - 3) until not used[f]
        for d = -S.near, S.near do used[f + d] = true end   -- (never two on top of each other)
        local kind
        self.seed, kind = weighted_pick(self.seed, S.kinds)
        list[#list + 1] = {f = f, kind = kind}
    end
    self.scan = {day = day, stations = list}
    return list
end

-- How strong the nearest station is at frequency f: 0..near+1, and which.
function Game:scan_signal(f)
    local best, which = 0, nil
    for _, st in ipairs(self:scan_stations()) do
        local s = CHURN.scan.near + 1 - math.abs(st.f - f)
        if not st.heard and s > best then best, which = s, st end
    end
    return best, which
end

function Game:scan_start()
    self.radio_ui.scan = {f = CHURN.scan.low + (CHURN.scan.high - CHURN.scan.low) // 2,
                          msg = "Left/Right tune. Enter on a signal listens."}
end

function Game:scan_key(key)
    local u, S = self.radio_ui.scan, CHURN.scan
    if key == KEY.Q or key == gfx.KEY_ESCAPE then
        self.radio_ui.scan = nil
        return
    end
    local step = (key == gfx.KEY_LEFT or key == KEY.A) and -1 or (key == gfx.KEY_RIGHT or key == KEY.D) and 1
        or (key == gfx.KEY_DOWN or key == KEY.S) and -5 or (key == gfx.KEY_UP or key == KEY.W) and 5 or nil
    if step then
        u.f = math.max(S.low, math.min(S.high, u.f + step))
        local s = self:scan_signal(u.f)
        u.msg = s == 0 and S.static[self:rand(#S.static) + 1]
            or s > S.near and "A clear signal! (Enter: listen)" or "Something, faint. Closer..."
        return
    end
    if key ~= KEY.ENTER and key ~= KEY.LF and key ~= KEY.SPACE then return end
    local s, st = self:scan_signal(u.f)
    if s <= S.near then
        u.msg = "Nothing clear enough to listen to."
        return
    end
    if self.radio.charge <= 0 then
        u.msg = "Dead air. The radio needs a Battery Cell."
        return
    end
    if not (self:at_base() and self:camp_stack("mast")) then self.radio.charge = self.radio.charge - 1 end
    st.heard = true
    u.msg = self:scan_listen(st.kind)
end

-- What a station turns out to be.
function Game:scan_listen(kind)
    local S, p = CHURN.scan, self.player
    if kind == "site" then
        for _, site in ipairs({"quarry", "checkpoint", "ferry", "trader"}) do
            if self.sites[site] and self:learn_site(site) then
                self:push_log("Morse on the radio: a place, " .. self:site_bearing(site) .. ".")
                return S.site .. " (" .. site .. ", " .. self:site_bearing(site) .. ")"
            end
        end
        kind = "stash"   -- (you know them all: it's numbers after all)
    end
    if kind == "stash" then
        if self:mark_stash() then return S.numbers end
        return "Numbers, then a long tone. Whatever it marks, you've found."
    elseif kind == "body" then
        local key = self:quest_spot(3, 8, false)
        if not key then return "A voice, breaking up. Too far to make out." end
        self.radio_body = key
        p.explored[key] = true
        self:push_log("A call for help on the radio: " .. self:bearing_to(key) .. ".")
        return S.body .. " (" .. self:bearing_to(key) .. ")"
    end
    self:dread(CHURN.dread.voice)
    self:sfx("emission")
    return S.voice[self:rand(#S.voice) + 1]
end

function Game:draw_scan(w, h)
    local u, S = self.radio_ui.scan, CHURN.scan
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    Game.ui_title(w, "Scanning the band", ("Charge %d/%d"):format(self.radio.charge, TECH.radio_max))
    -- the dial: ticks every 5 MHz, the needle at f
    local x0, x1, y = 20, w - 20, 90
    gfx.line(x0, y, x1, y)
    for f = S.low, S.high, 5 do
        local x = x0 + (x1 - x0) * (f - S.low) // (S.high - S.low)
        gfx.line(x, y - (f % 10 == 0 and 8 or 4), x, y)
        if f % 10 == 0 then gfx.text(x - 10, y + 16, tostring(f)) end
    end
    local nx = x0 + (x1 - x0) * (u.f - S.low) // (S.high - S.low)
    gfx.fill_rect(nx - 1, y - 24, 3, 30)
    gfx.font(gfx.FONT_BOLD_14)
    gfx.text(w // 2 - 40, 50, u.f .. " MHz")
    gfx.font(gfx.FONT_MONO_12)
    -- the signal: a bar of five
    local s = self:scan_signal(u.f)
    gfx.text(20, 140, "Signal")
    for i = 1, S.near + 1 do
        local bx = 80 + (i - 1) * 22
        if i <= s then gfx.fill_rect(bx, 140 - 4 * i, 16, 4 * i) else gfx.rect(bx, 140 - 4 * i, 16, 4 * i) end
    end
    for i, line in ipairs(wrap(u.msg or "", 55)) do
        if i <= 4 then gfx.text(6, 180 + 14 * (i - 1), line) end
    end
    Game.ui_keys(w, h, "Lt/Rt tune  Up/Dn x5  Enter listen  Q back")
    gfx.refresh()
end

-- Stepping onto the hex a voice called from: too late, but what they had is yours.
function Game:scan_arrive()
    local key = hex_key(self.player.q, self.player.r)
    if self.radio_body ~= key then return false end
    self.radio_body = nil
    local C, found = CHURN.corpse, {}
    for _ = 1, 2 do
        local item
        self.seed, item = weighted_pick(self.seed, C.loot)
        found[#found + 1] = self:drop_found(item, C.rounds[item] and C.rounds[item] + self:rand(3))
    end
    self:dread(CHURN.dread.corpse)
    self:push_log("The one who called. The radio in their hand is still on.")
    self:push_log("On them: " .. table.concat(found, ", ") .. ".")
    self:note_find(key, "corpse", "The voice on the radio", found)
    return false
end
