-- ---------------------------------------------------------------------
-- Encounter portraits
--
-- Painted by tools/paint_portraits.py and baked into PORTRAIT_DATA (the
-- part before this one) as 1-bit 32x32 sprite tiles, raw bytes. Only the
-- creature on screen is cut into tiles, and only once: PORTRAIT_CACHE holds one
-- subject, so memory stays at a few KB whatever the roster grows to.
--
-- The picture reacts to the fight: far away it is small, near it fills the
-- frame, close up you see its face; wounds show as it gets hurt; dead or
-- fled changes it again.
-- ---------------------------------------------------------------------

local PORTRAIT_SIZE = 96

local PORTRAIT_CACHE = {who = nil, views = {}, empty = string.rep("\0", 128)}

-- The tiles of one view ({x, y, data} per non-empty 32x32 tile), decoded on
-- first use. Returns nil for a subject with no art.
local function portrait_view(who, view)
    local entry = PORTRAIT_DATA[who]
    if not entry or not entry[view] then return nil end
    if PORTRAIT_CACHE.who ~= who then
        PORTRAIT_CACHE.who, PORTRAIT_CACHE.views = who, {}
    end
    local cached = PORTRAIT_CACHE.views[view]
    if cached then return cached end
    local v = entry[view]
    local bytes = v.data
    local tiles = {}
    for ty = 0, v.th - 1 do
        for tx = 0, v.tw - 1 do
            local k = (ty * v.tw + tx) * 128
            local tile = bytes:sub(k + 1, k + 128)
            if tile ~= PORTRAIT_CACHE.empty then
                tiles[#tiles + 1] = {x = tx * 32, y = ty * 32, data = tile}
            end
        end
    end
    cached = {w = v.w, h = v.h, th = v.th, tiles = tiles, marks = v.marks}
    PORTRAIT_CACHE.views[view] = cached
    return cached
end

-- How many wound marks to show for a fraction of health left (the same
-- bands as Game:enemy_condition: unhurt > 0.75, hurt > 0.4, else badly).
function Game.wound_count(frac)
    if frac > 0.75 then return 0 elseif frac > 0.4 then return 5 end
    return 11
end

-- Draw the portrait for encounter e in a 96x96 frame at (x, y).
function Game:draw_portrait(e, x, y)
    local size = PORTRAIT_SIZE
    gfx.color(gfx.WHITE)
    gfx.fill_rect(x, y, size, size)
    gfx.color(gfx.BLACK)
    local who = e.def.art
    local fights = e.def.hp ~= nil
    if e.outcome == "fled" then
        gfx.rect(x, y, size, size)
        gfx.font(gfx.FONT_MONO_12)
        gfx.text(x + size // 2 - 14, y + size // 2 + 4, "gone")
        return
    end
    -- far: the small view low in the frame, as if across the field;
    -- close: the face fills it; near (and everything that doesn't fight): all of it
    local view = "near"
    if fights and e.outcome ~= "dead" then
        if e.range == "far" then view = "far" elseif e.range == "close" then view = "close" end
    end
    local v = who and portrait_view(who, view)
    if v then
        -- tiles are 32x32, so a 48 px view is padded to 64: place by the
        -- padded size so no tile hangs outside the frame (far sits low-ish)
        local ox = x + (size - v.w) // 2
        local oy = y + size - v.th * 32
        for _, t in ipairs(v.tiles) do
            draw_sprite(ox + t.x, oy + t.y, 32, 32, t.data)
        end
        -- wounds: small dark blots on the creature, more as it weakens
        local frac = fights and math.max(0, e.hp / e.def.hp) or 1
        local n = e.outcome == "dead" and #v.marks // 2 or Game.wound_count(frac)
        local r = view == "far" and 1 or 2
        for i = 1, math.min(n, #v.marks // 2) do
            local mx, my = v.marks[2 * i - 1], v.marks[2 * i]
            gfx.fill_rect(ox + mx - r, oy + my - r, 2 * r + 1, 2 * r)
            gfx.fill_rect(ox + mx - r + 1, oy + my + r, 2 * r - 1, r + 1)   -- a drip
        end
    end
    if e.outcome == "dead" then
        -- dead: a dark hatch across the picture
        gfx.color(gfx.DARK)
        for k = -size, size, 6 do
            local x0, x1 = math.max(0, k), math.min(size - 1, k + size - 1)
            if x1 > x0 then gfx.line(x + x0, y + x0 - k, x + x1, y + x1 - k) end
        end
        gfx.color(gfx.BLACK)
    end
    gfx.rect(x, y, size, size)
end
-- ---------------------------------------------------------------------
-- Story moments (texts in QUESTS.scenes): a short full-screen scene, once a
-- run, at a few turning points. Game:queue_scene(id) from the moment's own
-- code; the main loop shows queued scenes only from the map screen (so the
-- tests and the balance sim, which call methods directly, never see one).
-- self.scenes_seen = {id = true} (saved; an old save counts all as seen).
-- ---------------------------------------------------------------------

function Game:queue_scene(id)
    self.scenes_seen = self.scenes_seen or {}
    if self.scenes_seen[id] or not QUESTS.scenes[id] then return false end
    self.scenes_seen[id] = true
    self.scene_queue = self.scene_queue or {}
    table.insert(self.scene_queue, id)
    return true
end

-- From the main loop: true if a scene is now on screen.
function Game:show_queued_scene()
    local q = self.scene_queue
    if self.screen ~= "map" or not q or #q == 0 then return false end
    self.scene = table.remove(q, 1)
    self.screen = "scene"
    return true
end

function Game:scene_key()
    self.scene = nil
    self.screen = "map"
end

-- Every scene counted as seen (old saves: nothing replays).
function Game.all_scenes_seen()
    local seen = {}
    for _, id in ipairs(QUESTS.scenes.order) do seen[id] = true end
    return seen
end

function Game:draw_scene(w, h)
    local sc = QUESTS.scenes[self.scene] or QUESTS.scenes.wake
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    Game.ui_title(w, sc.title)
    local cols = 54
    if sc.art and PORTRAIT_DATA[sc.art] and draw_sprite then   -- (no picture yet: text only)
        self:draw_portrait({def = {art = sc.art}}, w - PORTRAIT_SIZE - 10, 34)
        gfx.color(gfx.BLACK)
        gfx.rect(w - PORTRAIT_SIZE - 11, 33, PORTRAIT_SIZE + 2, PORTRAIT_SIZE + 2)
        cols = (w - PORTRAIT_SIZE - 30) // 7
    end
    local y = 50
    for _, line in ipairs(wrap(sc.text, cols)) do
        gfx.text(10, y, line)
        y = y + 16
    end
    Game.ui_keys(w, h, "any key: go on")
end
-- ---------------------------------------------------------------------
-- The intro: a splash on every launch (its picture, "THE CHURN" in
-- big block letters, an epigraph), then the title menu, then - for a
-- new survivor - a short story crawl before the creator.
--   screen "intro" -> "title" -> "crawl" -> "creator"
-- The tests and the balance sim build games with Game.new() and never
-- pass through here; only the main loop does (Game:begin_intro).
-- ---------------------------------------------------------------------

Game.INTRO = {
    -- 5x7 block letters, "#" = filled
    glyphs = {
        T = {"#####", "..#..", "..#..", "..#..", "..#..", "..#..", "..#.."},
        H = {"#...#", "#...#", "#...#", "#####", "#...#", "#...#", "#...#"},
        E = {"#####", "#....", "#....", "####.", "#....", "#....", "#####"},
        C = {".####", "#....", "#....", "#....", "#....", "#....", ".####"},
        U = {"#...#", "#...#", "#...#", "#...#", "#...#", "#...#", ".###."},
        R = {"####.", "#...#", "#...#", "####.", "#.#..", "#..#.", "#...#"},
        N = {"#...#", "##..#", "#.#.#", "#.#.#", "#..##", "#...#", "#...#"},
    },
    title = "THE CHURN", cell = 5,
    epigraph = {"The land does not lie still. It turns over in its",
                "sleep, and what it turns up, it remembers."},
    -- New survivor: the story so far, a page at a time
    crawl = {
        {"THE INSTITUTE",
         "There was an Institute out by the old quarry. The town was told the hum "
         .. "was a transformer fault, and not to talk about the birds. Lorries came "
         .. "at night with crates that were warm to the touch. One of them, a "
         .. "driver swore, was singing."},
        {"THE FIRST EMISSION",
         "Then the sky over the quarry turned purple and breathed. Nobody outside "
         .. "lived. Those in the cellars came up two days later into fields that "
         .. "had changed: grass in spirals, dogs that came back wrong, roads that "
         .. "no longer went where they had gone."},
        {"THE CHURN",
         "The land began to turn. Not fast; the way a sleeper turns. Hills fold, "
         .. "rivers drift a field to the left, and what was buried comes up again: "
         .. "tins, tapes, guns, bones. The soldiers fenced it off and called it "
         .. "the Churn. They let no one out without paper."},
        {"YOU",
         "You wake in the grass with nothing. Not even shoes. Somewhere there is "
         .. "a Trader, and past him a Checkpoint. Learn what the dead knew - their "
         .. "books, their tapes, their drives - and walk out. Or stay, and be "
         .. "turned over with the rest."},
    },
}

-- Start-up from the main loop: the splash first, then the title menu.
function Game:begin_intro(saved)
    self.title_save = saved
    self.title_cursor = 1
    self.intro_phase = 0
    self.screen = "intro"
    self.muted = saved and saved.muted or nil   -- (sound off last time: still off)
    self:sfx("title")
end

-- Big letters from runs of filled cells (one fill_rect per run).
function Game.draw_big_text(text, x, y, cell)
    local G = Game.INTRO.glyphs
    for i = 1, #text do
        local rows = G[text:sub(i, i)]
        if rows then
            for ry, row in ipairs(rows) do
                local start
                for cx = 1, #row + 1 do
                    local on = row:sub(cx, cx) == "#"
                    if on and not start then start = cx end
                    if not on and start then
                        gfx.fill_rect(x + (start - 1) * cell, y + (ry - 1) * cell, (cx - start) * cell, cell)
                        start = nil
                    end
                end
            end
        end
        x = x + 6 * cell
    end
end

-- The title screens' pictures (art/splash.png -> Game.SPLASH_ART on the
-- start screen, art/title.png -> Game.TITLE_ART on the title menu; baked
-- into 69_title_art by tools/paint_title.py): non-blank tiles, decoded once.
Game.ART_TILES = {}
function Game.art_tiles(name)
    if Game.ART_TILES[name] then return Game.ART_TILES[name] end
    local A, tiles = Game[name], {}
    if A then
        local bytes, empty = A.data, string.rep("\0", 128)
        for ty = 0, A.th - 1 do
            for tx = 0, A.tw - 1 do
                local k = (ty * A.tw + tx) * 128
                local tile = bytes:sub(k + 1, k + 128)
                if tile ~= empty then tiles[#tiles + 1] = {x = tx * 32, y = ty * 32, data = tile} end
            end
        end
    end
    Game.ART_TILES[name] = tiles
    return tiles
end

function Game.draw_art(name, x, y)
    if not (draw_sprite and Game[name]) then return end   -- (no bitmaps: text only)
    gfx.color(gfx.BLACK)
    for _, t in ipairs(Game.art_tiles(name)) do draw_sprite(x + t.x, y + t.y, 32, 32, t.data) end
    gfx.rect(x - 1, y - 1, Game[name].w + 2, Game[name].h + 2)
end

-- The picture on the left; the right panel starts here.
Game.INTRO.panel = 204

function Game:draw_intro(w, h)
    local I, px = Game.INTRO, Game.INTRO.panel
    local mid = px + (w - px) // 2
    gfx.clear(gfx.WHITE)
    Game.draw_art("SPLASH_ART", 4, 6)
    gfx.color(gfx.BLACK)
    for i, word in ipairs({"THE", "CHURN"}) do
        Game.draw_big_text(word, mid - ((#word * 6 - 1) * I.cell) // 2, 28 + (i - 1) * 48, I.cell)
    end
    gfx.font(gfx.FONT_MONO_12)
    local y = 150
    for _, line in ipairs(wrap(table.concat(I.epigraph, " "), (w - px - 6) // 7)) do
        gfx.text(mid - (#line * 7) // 2, y, line)
        y = y + 16
    end
    self:draw_intro_prompt(w, h)
    gfx.refresh()
end

function Game:draw_intro_prompt(w, h)
    local text, px = "- press any key -", Game.INTRO.panel
    gfx.color(gfx.WHITE)
    gfx.fill_rect(px, h - 40, w - px, 20)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_MONO_12)
    if (self.intro_phase or 0) % 4 ~= 3 then
        gfx.text(px + (w - px - #text * 7) // 2, h - 26, text)
    end
end

-- An idle poll on the splash: the prompt blinks (only it is redrawn).
function Game:intro_tick(w, h)
    self.intro_phase = (self.intro_phase or 0) + 1
    self:draw_intro_prompt(w, h)
    gfx.refresh()
end

function Game:intro_key(key)
    if key == KEY.Q then
        self.quit = true
    else
        self.screen = "title"
    end
end

-- The title menu: Continue (with a save), New survivor.
function Game:title_rows()
    local rows = {}
    local d = self.title_save
    if d then
        rows[#rows + 1] = {("Continue (day %d, %d HP)"):format(
            (WORLD.start_hour + d.player.hours) // 24 + 1, math.floor(d.player.health or 0)), "continue"}
    end
    rows[#rows + 1] = {"New survivor", "new"}
    return rows
end

function Game:draw_title(w, h)
    local I, px = Game.INTRO, Game.INTRO.panel
    local mid = px + (w - px) // 2
    gfx.clear(gfx.WHITE)
    Game.draw_art("TITLE_ART", 4, 6)
    gfx.color(gfx.BLACK)
    local tw = (#I.title * 6 - 1) * 3
    Game.draw_big_text(I.title, mid - tw // 2, 30, 3)
    gfx.font(gfx.FONT_MONO_12)
    local sub = "a survival game"
    gfx.text(mid - (#sub * 7) // 2, 70, sub)
    for i, row in ipairs(self:title_rows()) do
        local y = 120 + (i - 1) * 24
        if i == self.title_cursor then
            gfx.fill_rect(px, y - 13, w - px - 4, 18)
            gfx.color(gfx.WHITE)
        end
        gfx.text(px + 6, y, row[1])
        gfx.color(gfx.BLACK)
    end
    gfx.text(px + 6, h - 22, "Up/Dn pick  Enter go")
    gfx.text(px + 6, h - 8, "R records   Q quit")
    gfx.refresh()
end

function Game:title_key(key)
    local rows = self:title_rows()
    if key == gfx.KEY_UP or key == KEY.W then
        self.title_cursor = math.max(1, self.title_cursor - 1)
    elseif key == gfx.KEY_DOWN or key == KEY.S then
        self.title_cursor = math.min(#rows, self.title_cursor + 1)
    elseif key == KEY.ENTER or key == KEY.LF or key == KEY.SPACE then
        local pick = rows[self.title_cursor] or rows[#rows]
        if pick[2] == "continue" then
            self:load_state(self.title_save)
        else
            self.crawl_page = 1
            self.screen = "crawl"
        end
        self.title_save = nil
    end
end

function Game:draw_crawl(w, h)
    local page = Game.INTRO.crawl[self.crawl_page or 1]
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    gfx.font(gfx.FONT_BOLD_14)
    gfx.text(14, 40, page[1])
    gfx.font(gfx.FONT_MONO_12)
    local y = 74
    for _, line in ipairs(wrap(page[2], 52)) do
        gfx.text(14, y, line)
        y = y + 18
    end
    gfx.text(w - 60, 22, ("%d/%d"):format(self.crawl_page or 1, #Game.INTRO.crawl))
    gfx.text(6, h - 8, "Enter: on   Esc: skip")
    gfx.refresh()
end

function Game:crawl_key(key)
    if key == gfx.KEY_ESCAPE or key == KEY.Q then
        self.screen = "creator"
    elseif key == KEY.ENTER or key == KEY.LF or key == KEY.SPACE or key == gfx.KEY_RIGHT or key == KEY.D then
        self.crawl_page = (self.crawl_page or 1) + 1
        if self.crawl_page > #Game.INTRO.crawl then self.screen = "creator" end
    end
end
-- ---------------------------------------------------------------------
-- The look every screen shares (a few gfx calls each, so cheap on the
-- device): a black title bar with the screen's name and, at its right, a
-- status; a footer of key chips - the key in a black box, then what it
-- does; bars for a value out of a maximum.
-- ---------------------------------------------------------------------

Game.UI = {bar_h = 22, chip_h = 13, gap = 8}

-- The title bar. right (optional): status text at the bar's right end.
-- Leaves the pen black and the font mono 12.
-- bh (optional): a slimmer bar (the bag screen's, 16).
function Game.ui_title(w, title, right, bh)
    bh = bh or Game.UI.bar_h
    gfx.color(gfx.BLACK)
    gfx.fill_rect(0, 0, w, bh)
    gfx.color(gfx.WHITE)
    gfx.font(gfx.FONT_BOLD_14)
    gfx.text(6, bh - 6 + (bh < Game.UI.bar_h and 2 or 0), title)
    gfx.font(gfx.FONT_MONO_12)
    if right then gfx.text(w - 6 - 7 * #right, bh - 7 + (bh < Game.UI.bar_h and 2 or 0), right) end
    gfx.color(gfx.BLACK)
end

-- "Up/Dn pick  Enter make  Q quit", "Arrows Spc:rest F:search", "any key:
-- back": the footer's text as {key, what it does} pairs.
function Game.ui_key_pairs(text)
    local pairs_ = {}
    local function add(group)
        group = group:gsub("^%s+", ""):gsub("%s+$", "")
        if group == "" then return end
        local k, v = group:match("^(.-):%s*(.*)$")
        if k and not k:find(" ") or (k and k:lower() == "any key") then
            pairs_[#pairs_ + 1] = {k, v}
            return
        end
        local first, rest = group:match("^(%S+)%s+(.+)$")
        pairs_[#pairs_ + 1] = first and {first, rest} or {group, ""}
    end
    for group in (text .. "  "):gmatch("(.-)%s%s+") do
        -- one group of single-spaced "K:label" tokens: split them
        if select(2, group:gsub(":", "")) > 1 then
            for tok in group:gmatch("%S+") do add(tok) end
        else
            add(group)
        end
    end
    return pairs_
end

-- The key footer along the bottom. Squeezes the gaps (then drops what
-- won't fit) to stay on the screen.
function Game.ui_keys(w, h, text)
    local U, list = Game.UI, Game.ui_key_pairs(text)
    local total = 0
    for _, kv in ipairs(list) do
        total = total + 7 * #kv[1] + 4 + (kv[2] ~= "" and 7 * #kv[2] + 3 or 0)
    end
    local gap = math.max(2, math.min(U.gap, (w - 8 - total) // math.max(1, #list - 1)))
    local x, y = 4, h - 4 - U.chip_h
    gfx.font(gfx.FONT_MONO_12)
    for _, kv in ipairs(list) do
        local kw, lw = 7 * #kv[1] + 4, kv[2] ~= "" and 7 * #kv[2] + 3 or 0
        if x + kw + lw > w - 2 then break end
        gfx.color(gfx.BLACK)
        gfx.fill_rect(x, y, kw, U.chip_h)
        gfx.color(gfx.WHITE)
        gfx.text(x + 2, y + 10, kv[1])
        gfx.color(gfx.BLACK)
        if lw > 0 then gfx.text(x + kw + 3, y + 10, kv[2]) end
        x = x + kw + lw + gap
    end
end

-- A bar: frame, filled to frac (0..1). dark: fill in dark gray (it dithers).
function Game.ui_bar(x, y, bw, bh, frac, dark)
    gfx.color(gfx.BLACK)
    gfx.rect(x, y, bw, bh)
    local fw = math.floor((bw - 2) * math.max(0, math.min(1, frac)) + 0.5)
    if fw > 0 then
        gfx.color(dark and gfx.DARK or gfx.BLACK)
        gfx.fill_rect(x + 1, y + 1, fw, bh - 2)
    end
    gfx.color(gfx.BLACK)
end

-- A small label on a black tag (section headings on busy screens).
function Game.ui_tag(x, y, text)
    gfx.color(gfx.BLACK)
    gfx.fill_rect(x - 2, y - 10, 7 * #text + 4, 13)
    gfx.color(gfx.WHITE)
    gfx.text(x, y, text)
    gfx.color(gfx.BLACK)
end
