        end
        gfx.text(10, y, opt[1])
        gfx.color(gfx.BLACK)
        y = y + 20
    end
    if #u.opts == 1 then
        gfx.text(6, y + 10, ("You need a Churn Permit or %d artifacts."):format(GOAL.bribe))
    end
