end

function Game:draw_ending(w, h)
    local e = self.ending
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    Game.ui_title(w, "You left the Churn.")
    local y, cols = 60, 54
    local art = CHURN.ending_art[e.how]
    if art and PORTRAIT_DATA[art] then   -- (a picture for this ending, once there is one)
