function Game:open_help()
    self.help_back = self.screen
    self.help_page = 1
    self.screen = "help"
end

-- The help rows on page n: the keys (1), the tips (2). They don't fit one screen.
function Game.help_rows(n)
    local out, tips = {}, false
    for _, row in ipairs(HELP) do
        if row[1] == "TIPS" then tips = true end
        if tips == (n == 2) then out[#out + 1] = row end
    end
    return out
end

function Game:help_key(key)   -- help, info and journal: any key goes back
    if self.screen == "journal" and key == KEY.L and self:lore_count() > 0 then
        return self:open_lore()
    end
    if self.screen == "journal" and key == KEY.K then return self:open_skills() end
    if self.screen == "journal" and key == KEY.F then return self:open_finds() end
    if self.screen == "journal" and key == KEY.B then return self:open_bestiary() end
    if self.screen == "help" and key == KEY.V then
        self.screen = "info"
    elseif self.screen == "help" and (self.help_page or 1) == 1
        and (key == gfx.KEY_DOWN or key == gfx.KEY_RIGHT or key == KEY.S or key == KEY.D) then
        self.help_page = 2
    elseif self.screen == "help" and self.help_page == 2
        and (key == gfx.KEY_UP or key == gfx.KEY_LEFT or key == KEY.W or key == KEY.A) then
        self.help_page = 1
    else
        self.screen = self.help_back or "map"
    end
end

function Game:draw_help(w, h)
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    local page = self.help_page or 1
    Game.ui_title(w, page == 1 and "Keys" or "Tips", "The Churn " .. Game.VERSION:match("^%S+"))
    local y = 36
    for _, row in ipairs(Game.help_rows(page)) do
        if page == 2 then   -- (no label column: the tips are long)
            gfx.text(6, y, row[2])
        else
            if row[1] ~= "" then y = y + 3 end
            gfx.text(6, y, row[1])
            gfx.text(62, y, row[2])
        end
        y = y + 15
    end
    Game.ui_keys(w, h, (page == 1 and "Dn: tips" or "Up: keys") .. "  any key: back  V: device info")
    gfx.refresh()
end

-- Every gfx call is an event the firmware drains 24 at a time, once per app
-- tick (25 ms by default): ~960 calls a second, so a 900-call screen took
-- most of a second to appear. solaros.tick_interval asks for faster ticks;
-- the main loop turns them on only while a frame is being drawn, so the
-- board idles as before. Firmware without it keeps the old speed.
Game.DRAW_TICK_MS = 2

function Game.draw_pump(on)
    local set = solaros.tick_interval
    if not set then return false end
    return (pcall(set, on and Game.DRAW_TICK_MS or 0))
end

-- What the game sees of the device, one line each.
function Game:device_lines()
    local st = solaros.storage
    local lines = {
        "Game " .. Game.VERSION,
        (_VERSION or "Lua ?") .. ", memory " .. math.floor(collectgarbage("count")) .. " KB",
        ("Screen %dx%d"):format(gfx.size()),
    }
    local clock = solaros.time and solaros.time.uptime_ms
    lines[#lines + 1] = "Uptime " .. (clock and (math.floor(clock() / 1000) .. " s") or "unknown")
    if st then
        local ok, root = pcall(function() return st.mount_point and st.mount_point() end)
        lines[#lines + 1] = "Storage " .. (ok and tostring(root) or "error: " .. tostring(root))
    else
        lines[#lines + 1] = "Storage: no solaros.storage"
    end
    lines[#lines + 1] = "Can save: " .. (SAVE.can_write() and "yes (write_file)" or "no (needs SolarOS 4.15.17+)")
    local _, path = SAVE.path()
    if path and st and st.exists then
        local ok, there = pcall(st.exists, path)
        lines[#lines + 1] = "Save " .. path .. ": " .. (ok and (there and "found" or "none") or "error")
    end
    lines[#lines + 1] = ("World seed %d, hour %d, %s"):format(self.world_seed or 0, self.player.hours,
        DIFFICULTY[self.difficulty or "normal"].name)
    lines[#lines + 1] = "Fast drawing: " .. (solaros.tick_interval
        and ("yes (" .. Game.DRAW_TICK_MS .. " ms ticks while drawing)") or "no (older firmware)")
    lines[#lines + 1] = "Audio: " .. ((solaros.audio and solaros.audio.tone) and "tone ok" or "none")
    return lines
end

function Game:draw_info(w, h)
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    Game.ui_title(w, "Device info")
    local y = 40
    for _, line in ipairs(self:device_lines()) do
        gfx.text(6, y, line:sub(1, 56))
        y = y + 16
    end
    Game.ui_keys(w, h, "Any key: back")
    gfx.refresh()
end
-- ---------------------------------------------------------------------
-- Journal (J): one page of what you know, so you don't have to remember it.
-- ---------------------------------------------------------------------

function Game:open_journal()
    self.help_back = self.screen   -- shares help's "any key: back" (help_key)
    self.screen = "journal"
end

function Game:journal_lines()
    local p, lines = self.player, {}
    local function add(s) lines[#lines + 1] = s end
    local day, hour = self:clock()
    add(("Day %d, %02d:00. %d hours in the Churn. %s."):format(day, hour, p.hours,
        DIFFICULTY[self.difficulty or "normal"].name))
    add(self:skills_line())
    local worn, c = self:most_worn(100)
    if worn then
        add(("Most worn: %s,%s. C: Patch clothes."):format(ITEM_DB[self.player.equipped[worn]].name:lower(),
            Game.cond_text(c)))
    end
    local season, sday = self:season()
    local weather = self:weather()
    local advice = {Storm = " Find shelter: ruins, hills, trees.", Fog = " Sight is short.",
                    Snow = " Dress warm.", ["Cold snap"] = " Dress warm."}
    add(("%s, day %d of %d. %s.%s"):format(season.name, sday, WORLD.season_days, weather,
        advice[weather] or ""))
    -- the way out
    if self.sites_known.checkpoint then
        add("Checkpoint: " .. self:site_bearing("checkpoint") .. ". Needs a permit or "
            .. GOAL.bribe .. " artifacts.")
    else
        add("The way out: unknown. Find the trader, or read notes.")
    end
    if self.sites_known.trader then add("Trader: " .. self:site_bearing("trader") .. ".") end
    if self.sites_known.ferry then add("Ferry Post (Mother Okun): " .. self:site_bearing("ferry") .. ".") end
    for _, l in ipairs(self:little_lines()) do add(l) end
    local pd = self.peddler
    if pd and pd.seen_key then
        add(("Peddler: last seen %s, day %d."):format(self:bearing_to(pd.seen_key), (self:clock(pd.seen_hour))))
    end
    if self:lore_count() > 0 then
        add(("Pages read: %d/%d. L to reread them."):format(self:lore_count(), #LORE.pages))
    end
    local n_known = 0
    for _, r in ipairs(RECIPES) do if self.known[r.id] then n_known = n_known + 1 end end
    add(("Recipes known: %d of %d. K: see them, and your skills."):format(n_known, #RECIPES))
    if self.last_tape then add("Last tape: " .. self.last_tape) end
    local story = self:story_text()
    if story then add(story) end
    local quest = self:quest_text()
    if quest then add("Quest - " .. quest) end
    local standing = self:rep_text()
    if standing then add(standing) end
    local camp = self:base_text()
    if camp then add(camp) end
    local risen = self:legacy_text()
    if risen then add(risen) end
    if self:dread_name() then
        add(("Dread: %d (%s). A fire, your bed, the dog, a tape ease it."):format(math.floor(p.dread), self:dread_name()))
    end
    local permit = self:count_item("permit") > 0
    add(("Artifacts: %d of %d.%s"):format(self:artifact_count(), GOAL.bribe,
        permit and " You have a Churn Permit." or ""))
    -- places
    for key in pairs(self.stashes) do add("Stash: " .. self:bearing_to(key) .. ".") end
    for key, snare in pairs(self.snares) do
        add(("Snare: %s, set %dh ago."):format(self:bearing_to(key), p.hours - snare.set))
    end
    local hot, nearest, nearest_d = 0, nil, nil
    for key, level in pairs(self.rad_known) do
        if level > 0 then
            hot = hot + 1
            local q, r = Game.key_qr(key)
            local d = axial_distance(p.q, p.r, q, r)
            if not nearest or d < nearest_d then nearest, nearest_d = key, d end
        end
    end
    if hot > 0 then
        add(("Hot hexes known: %d. Nearest: %s."):format(hot, nearest_d == 0 and "here"
            or self:bearing_to(nearest)))
    end
    -- you, and who's with you
    if self:can_measure() and (p.rads or 0) > 0 then
        add(("Radiation: %d rads."):format(math.floor(p.rads)))
    elseif self:rad_stage() > 0 then
        add("You feel " .. RAD.stages[self:rad_stage()].feel:lower() .. ". Something is making you sick.")
    end
    local emit = self:emission_text()
    if emit then add("Emission: " .. emit .. ". Get to ruins or hills.") end
    if self.dog then
        local hungry = self.dog.hungry_days > 0 and (", hungry " .. self.dog.hungry_days .. "d") or ", fed"
        add(("Your dog: %d/%d HP%s."):format(self.dog.hp, DOG.hp, hungry))
    end
    if self.radio and self:carrying("lora_radio") then
        add(("Radio: %d/%d charge."):format(self.radio.charge, TECH.radio_max))
    end
    return lines
end

function Game:draw_journal(w, h)
    gfx.clear(gfx.WHITE)
    gfx.color(gfx.BLACK)
    Game.ui_title(w, "Journal")
    local y, max_y = 40, h - 24
    local all = {}
    for _, line in ipairs(self:journal_lines()) do
        for _, part in ipairs(wrap(line, 55)) do all[#all + 1] = part end
    end
    local fit = (max_y - y) // 14 + 1
    for i, line in ipairs(all) do
        if i == fit and #all > fit then
            gfx.text(6, y, ("+%d more"):format(#all - fit + 1))
            break
        end
        gfx.text(6, y, line)
        y = y + 14
    end
    Game.ui_keys(w, h, (self:lore_count() > 0 and "L: pages  " or "") .. "K: skills  F: finds  B: beasts  any key: back")
    gfx.refresh()
end
-- ---------------------------------------------------------------------
-- Main loop
-- ---------------------------------------------------------------------

-- Everything built at load is in place: clear out the garbage the build left
-- (the collector setting is at the top of the file, 00_header).
collectgarbage("collect")

gfx.begin()

local ok, err = pcall(function()
    local game = Game.new()
    local w, h = gfx.size()
    game:begin_intro(Game.read_save())   -- the splash, then the title menu

    local function handle_map_key(key)
        if game:map_dir_key(key) then
            return   -- (a step, or Up/Down leaning for the next one)
        elseif key == gfx.KEY_ESCAPE or key == KEY.Q then
            game:ask_quit()   -- (asks first: a run is under way)
        elseif key == KEY.SPACE then
            game:rest()
        elseif key == KEY.F then
            game:scavenge()
        elseif key == KEY.E then
            game:water_action()
        elseif key == KEY.T then
            game:site_action()
        elseif key == KEY.H then
            game:open_help()
        elseif key == KEY.G then
            game:gather()
        elseif key == KEY.M then
            game:toggle_mute()
        elseif key == KEY.R then
            game:open_radio()
        elseif key == KEY.J then
            game:open_journal()
        elseif key == KEY.C then
            game:open_crafting()
        elseif key == KEY.I then
            game.screen = "inventory"
            game.camp_view = nil
            game.inv_cursor = 1
            game.inv_selected = nil
        end
    end

    local function handle_inventory_key(key)
        if key == gfx.KEY_ESCAPE or key == KEY.Q then
            game:ask_quit()
        elseif key == KEY.I then
            game.screen = "map"
            game.camp_view = nil
        elseif key == KEY.T and game:at_base() then   -- the bag <-> the camp
            game.camp_view = not game.camp_view or nil
            game.inv_cursor, game.inv_selected = 1, nil
        elseif key == KEY.H then
            game:open_help()
        elseif key == KEY.J then
            game:open_journal()
        elseif key == KEY.C then
            game.inv_selected = nil
            game:open_crafting()
        elseif key == gfx.KEY_UP or key == KEY.W then
            game:inv_move(0, -1)
        elseif key == gfx.KEY_DOWN or key == KEY.S then
            game:inv_move(0, 1)
        elseif key == gfx.KEY_LEFT or key == KEY.A then
            game:inv_move(-1, 0)
        elseif key == gfx.KEY_RIGHT or key == KEY.D then
            game:inv_move(1, 0)
        elseif key == KEY.X or key == KEY.BACKSPACE then
            game:inv_drop()
        elseif key == KEY.E then
            local row = INV_ROWS[game.inv_cursor]
            if row then
                game:use_item(row[1], row[2])
                -- the stack may be gone or shifted; don't keep a stale pick
                game.inv_selected = nil
            end
        elseif key == KEY.ENTER or key == KEY.LF or key == KEY.SPACE then
            local row = INV_ROWS[game.inv_cursor]
            if row then
                if game.inv_selected == nil then
                    if game:get_stack(row[1], row[2]) ~= nil then
                        game.inv_selected = {row[1], row[2]}
                    end
                else
                    game:try_transfer(game.inv_selected, {row[1], row[2]})
                    game.inv_selected = nil
                end
            end
        end
    end

    -- Redraw only after a key was handled: nothing changes on its own, and a
    -- full frame is hundreds of gfx calls plus a panel refresh.
    local dirty = true
    while not game.quit and not solaros.should_exit() do
        if game:show_queued_scene() then dirty = true end   -- (a story moment)
        if dirty then
            -- the bag screen patches itself when only its cursor moved; any
            -- other screen in between means it has to be drawn whole again
            if game.screen ~= "inventory" then game.inv_drawn = nil end
            if game.screen ~= "map" then game.move_lean = nil end   -- (no stale Up/Down)
            Game.draw_pump(true)
            if game.screen == "intro" then
                game:draw_intro(w, h)
            elseif game.screen == "title" then
                game:draw_title(w, h)
            elseif game.screen == "crawl" then
                game:draw_crawl(w, h)
            elseif game.screen == "creator" then
                game:draw_creator(w, h)
            elseif game.screen == "dead" then
                game:draw_dead(w, h)
            elseif game.screen == "ending" then
                game:draw_ending(w, h)
            elseif game.screen == "help" then
                game:draw_help(w, h)
            elseif game.screen == "radio" then
                game:draw_radio(w, h)
            elseif game.screen == "journal" then
                game:draw_journal(w, h)
            elseif game.screen == "lore" then
                game:draw_lore(w, h)
            elseif game.screen == "skills" then
                game:draw_skills(w, h)
            elseif game.screen == "info" then
                game:draw_info(w, h)
            elseif game.screen == "records" then
                game:draw_records(w, h)
            elseif game.screen == "trade" then
                game:draw_trade(w, h)
            elseif game.screen == "gate" then
                game:draw_gate(w, h)
            elseif game.screen == "encounter" then
                game:draw_encounter(w, h)
            elseif game.screen == "puzzle" then
                game:draw_puzzle(w, h)
            elseif game.screen == "fishing" then
                game:draw_fishing(w, h)
            elseif game.screen == "lockpick" then
                game:draw_lockpick(w, h)
            elseif game.screen == "craft" then
                game:draw_craft(w, h)
            elseif game.screen == "scene" then
                game:draw_scene(w, h)
            elseif game.screen == "map" then
                game:draw_map(w, h)
            else
                game:draw_inventory(w, h)
            end
            if game.confirm_quit then game:draw_quit_confirm(w, h) end
            Game.draw_pump(false)
            dirty = false
        end

        local key = gfx.getch(POLL_MS)
        if key == nil and game.screen == "intro" then game:intro_tick(w, h) end   -- (the eye turns)
        if key == KEY.CLOSE then
            game:close_requested()
            dirty = true
        elseif key ~= nil and game.confirm_quit then
            game:quit_confirm_key(key)   -- (no time passes while it asks)
            dirty = true
        elseif key ~= nil then
            if game.screen == "records" then
                game:records_key(key)
            elseif key == KEY.R and (game.screen == "title" or game.screen == "creator"
                                     or game.screen == "dead" or game.screen == "ending") then
                game:open_records()
            elseif game.screen == "intro" then
                game:intro_key(key)
            elseif game.screen == "crawl" then
                game:crawl_key(key)
            elseif game.screen == "title" then
                if key == gfx.KEY_ESCAPE or key == KEY.Q then
                    game.quit = true
                else
                    game:title_key(key)
                end
            elseif game.screen == "creator" then
                if key == gfx.KEY_ESCAPE or key == KEY.Q then
                    game.quit = true
                else
                    game:creator_key(key)
                end
            elseif game.screen == "encounter" then
                game:encounter_key(key)
            elseif game.screen == "puzzle" then
                game:puzzle_key(key)
            elseif game.screen == "fishing" then
                game:fishing_key(key)
            elseif game.screen == "lockpick" then
                game:lockpick_key(key)
            elseif game.screen == "craft" then
                if key == KEY.Q then game:ask_quit() else game:craft_key(key) end
            elseif game.screen == "trade" then
                game:trade_key(key)
            elseif game.screen == "help" or game.screen == "info" or game.screen == "journal" then
                game:help_key(key)
            elseif game.screen == "radio" then
                game:radio_key(key)
            elseif game.screen == "lore" then
                game:lore_key(key)
            elseif game.screen == "skills" then
                game:skills_key(key, h)
            elseif game.screen == "gate" then
                game:gate_key(key)
            elseif game.screen == "dead" or game.screen == "ending" then
                if key == gfx.KEY_ESCAPE or key == KEY.Q then
                    game.quit = true
                elseif key == KEY.ENTER or key == KEY.LF then
                    game = Game.new()   -- a fresh world and the creator
                end
            elseif game.screen == "scene" then
                game:scene_key(key)
            elseif game.screen == "map" then
                handle_map_key(key)
            else
                handle_inventory_key(key)
            end
            -- time may have passed (moving, resting, crafting...): apply cold,
            -- night and light before the next frame
            if game.screen ~= "creator" and game.screen ~= "dead" and game.screen ~= "title"
                and game.screen ~= "intro" and game.screen ~= "crawl"
                and game.screen ~= "ending" and game.screen ~= "records" then
                game:tick()
            end
            game:autosave()
            dirty = true
        end
    end
    -- quitting mid-run keeps it (a run on the title or creator isn't started yet)
    game.force_save = true
    game:autosave()
end)

-- Per SolarOS convention: cleanup must run even when drawing/logic fails,
-- and the error is re-raised afterward so it still surfaces (with a real
-- traceback) instead of being silently swallowed. (A draw that failed
-- mid-frame left the fast event pump on: turn it off first.)
Game.draw_pump(false)
gfx["end"]()
if not ok then
    error(err)
end
